import { GoogleGenAI, Type } from "@google/genai";
import { AspectRatio, ImageSize, AIModel } from "../types";

const fileToPart = async (file: File): Promise<{ inlineData: { data: string; mimeType: string } }> => {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onloadend = () => {
      if (typeof reader.result === 'string') {
        const base64Data = reader.result.split(',')[1];
        const mimeType = (file.type && file.type.startsWith('image/')) ? file.type : 'image/png';
        resolve({
          inlineData: {
            data: base64Data,
            mimeType: mimeType,
          },
        });
      } else {
        reject(new Error("读取文件失败"));
      }
    };
    reader.onerror = reject;
    reader.readAsDataURL(file);
  });
};

/**
 * 将扩展比例或自定义像素比例映射到 Gemini API 原生支持的比例
 * 支持的值: "1:1", "4:3", "3:4", "16:9", "9:16"
 */
const mapToSupportedRatio = (ratio: AspectRatio, width?: number, height?: number): string => {
  if (ratio === AspectRatio.Custom && width && height) {
    const r = width / height;
    if (r >= 1.5) return "16:9";
    if (r >= 1.2) return "4:3";
    if (r > 0.8) return "1:1";
    if (r > 0.6) return "3:4";
    return "9:16";
  }

  const mapping: Record<string, string> = {
    [AspectRatio.Square]: "1:1",
    [AspectRatio.Landscape_4_3]: "4:3",
    [AspectRatio.Portrait_3_4]: "3:4",
    [AspectRatio.Landscape_16_9]: "16:9",
    [AspectRatio.Portrait_9_16]: "9:16",
    [AspectRatio.Landscape_21_9]: "16:9",
    [AspectRatio.Portrait_9_21]: "9:16",
    [AspectRatio.Portrait_4_5]: "3:4",
    [AspectRatio.Landscape_5_4]: "4:3",
  };
  return mapping[ratio] || "1:1";
};

export const analyzeAndName = async (
  prompt: string, 
  files: File[], 
  isSmartAnalysis: boolean
): Promise<{ refinedPrompt: string; fileName: string }> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  try {
    const parts: any[] = [];
    if (files.length > 0) {
      const imageParts = await Promise.all(files.map(fileToPart));
      parts.push(...imageParts);
    }

    const systemInstruction = isSmartAnalysis 
      ? "你是一个顶尖的AI绘画提示词专家。请分析用户的原始提示词和参考图，生成一个更专业的、包含艺术细节和构图描述的英文提示词(refinedPrompt)，以及一个简洁生动的中文描述作为文件名(fileName)。"
      : "请根据提示词生成一个简洁生动的中文描述作为文件名(fileName)。";

    const userContent = `用户提示词: ${prompt || "（仅参考图）"}`;
    parts.push({ text: userContent });

    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: { parts },
      config: {
        systemInstruction,
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            refinedPrompt: { 
              type: Type.STRING, 
              description: "优化后的详细英文绘画提示词" 
            },
            fileName: { 
              type: Type.STRING, 
              description: "简洁的中文描述，适合做文件名" 
            }
          },
          required: ["fileName"]
        }
      }
    });

    const result = JSON.parse(response.text);
    return {
      refinedPrompt: isSmartAnalysis ? (result.refinedPrompt || prompt) : prompt,
      fileName: (result.fileName || "创意作品").replace(/[\\/:*?"<>|]/g, '')
    };
  } catch (e) {
    console.error("Smart analysis failed:", e);
    return {
      refinedPrompt: prompt,
      fileName: (prompt.substring(0, 10) || "创意作品").replace(/[\\/:*?"<>|]/g, '')
    };
  }
};

export const generateSingleImage = async (
  prompt: string,
  inputFiles: File[],
  aspectRatio: AspectRatio,
  imageSize: ImageSize,
  model: AIModel,
  customWidth?: number,
  customHeight?: number
): Promise<string[]> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  const parts: any[] = [];

  if (inputFiles.length > 0) {
    const imageParts = await Promise.all(inputFiles.map(fileToPart));
    parts.push(...imageParts);
  }

  let finalPrompt = prompt.trim() || (inputFiles.length > 0 ? "Enhance this image professionally" : "");
  if (!finalPrompt) throw new Error("请输入提示词");

  // 如果是自定义像素，在提示词中加入尺寸暗示，增强模型对构图的理解
  if (aspectRatio === AspectRatio.Custom && customWidth && customHeight) {
    finalPrompt = `${finalPrompt}. Composition aspect ratio strictly ${customWidth}:${customHeight}, ultra-detailed production.`;
  }

  parts.push({ text: finalPrompt });

  const config: any = {
    imageConfig: {
      aspectRatio: mapToSupportedRatio(aspectRatio, customWidth, customHeight),
    }
  };

  if (model === AIModel.Pro) {
    config.imageConfig.imageSize = imageSize;
  }

  const response = await ai.models.generateContent({
    model: model,
    contents: { parts: parts },
    config: config,
  });

  const urls: string[] = [];
  if (response.candidates?.[0]?.content?.parts) {
    for (const part of response.candidates[0].content.parts) {
      if (part.inlineData?.data) {
        urls.push(`data:${part.inlineData.mimeType || 'image/png'};base64,${part.inlineData.data}`);
      }
    }
  }

  if (urls.length === 0) {
    const textRes = response.text;
    if (textRes) throw new Error(`模型反馈: ${textRes}`);
    throw new Error("未能生成图像");
  }

  return urls;
};

import React, { useMemo } from 'react';
import { AspectRatio, ImageSize, AIModel } from '../types';
import { Settings2, Maximize, Layers, Cpu, BrainCircuit, RefreshCw, Layout, Smartphone } from 'lucide-react';

interface SettingsPanelProps {
  aspectRatio: AspectRatio;
  imageSize: ImageSize;
  batchSize: number;
  model: AIModel;
  isSmartAnalysis: boolean;
  customWidth?: number;
  customHeight?: number;
  onAspectRatioChange: (ratio: AspectRatio) => void;
  onImageSizeChange: (size: ImageSize) => void;
  onBatchSizeChange: (size: number) => void;
  onModelChange: (model: AIModel) => void;
  onSmartAnalysisChange: (enabled: boolean) => void;
  onCustomPixelsChange?: (width: number, height: number) => void;
  disabled: boolean;
}

const SettingsPanel: React.FC<SettingsPanelProps> = ({
  aspectRatio,
  imageSize,
  batchSize,
  model,
  isSmartAnalysis,
  customWidth = 1024,
  customHeight = 1024,
  onAspectRatioChange,
  onImageSizeChange,
  onBatchSizeChange,
  onModelChange,
  onSmartAnalysisChange,
  onCustomPixelsChange,
  disabled
}) => {

  const isPortrait = useMemo(() => {
    return [
      AspectRatio.Portrait_3_4, 
      AspectRatio.Portrait_9_16, 
      AspectRatio.Portrait_9_21,
      AspectRatio.Portrait_4_5
    ].includes(aspectRatio);
  }, [aspectRatio]);

  const baseRatio = useMemo(() => {
    if (aspectRatio === AspectRatio.Custom) return "custom";
    if (aspectRatio === AspectRatio.Square) return "1:1";
    if (aspectRatio === AspectRatio.Landscape_4_3 || aspectRatio === AspectRatio.Portrait_3_4) return "4:3";
    if (aspectRatio === AspectRatio.Landscape_16_9 || aspectRatio === AspectRatio.Portrait_9_16) return "16:9";
    if (aspectRatio === AspectRatio.Landscape_21_9 || aspectRatio === AspectRatio.Portrait_9_21) return "21:9";
    if (aspectRatio === AspectRatio.Landscape_5_4 || aspectRatio === AspectRatio.Portrait_4_5) return "4:5";
    return "1:1";
  }, [aspectRatio]);

  const toggleOrientation = () => {
    if (baseRatio === "1:1" || baseRatio === "custom") return;

    let newRatio = aspectRatio;
    if (baseRatio === "4:3") newRatio = isPortrait ? AspectRatio.Landscape_4_3 : AspectRatio.Portrait_3_4;
    if (baseRatio === "16:9") newRatio = isPortrait ? AspectRatio.Landscape_16_9 : AspectRatio.Portrait_9_16;
    if (baseRatio === "21:9") newRatio = isPortrait ? AspectRatio.Landscape_21_9 : AspectRatio.Portrait_9_21;
    if (baseRatio === "4:5") newRatio = isPortrait ? AspectRatio.Landscape_5_4 : AspectRatio.Portrait_4_5;

    onAspectRatioChange(newRatio);
  };

  const handleBaseRatioChange = (base: string) => {
    if (base === "custom") {
      onAspectRatioChange(AspectRatio.Custom);
      return;
    }
    let newRatio = AspectRatio.Square;
    if (base === "4:3") newRatio = isPortrait ? AspectRatio.Portrait_3_4 : AspectRatio.Landscape_4_3;
    if (base === "16:9") newRatio = isPortrait ? AspectRatio.Portrait_9_16 : AspectRatio.Landscape_16_9;
    if (base === "21:9") newRatio = isPortrait ? AspectRatio.Portrait_9_21 : AspectRatio.Landscape_21_9;
    if (base === "4:5") newRatio = isPortrait ? AspectRatio.Portrait_4_5 : AspectRatio.Landscape_5_4;
    onAspectRatioChange(newRatio);
  };

  const baseRatioOptions = [
    { value: "1:1", label: "1:1", desc: "社交" },
    { value: "4:5", label: "4:5", desc: "人像" },
    { value: "4:3", label: "4:3", desc: "经典" },
    { value: "16:9", label: "16:9", desc: "高清" },
    { value: "21:9", label: "21:9", desc: "宽屏" },
    { value: "custom", label: "自定义", desc: "像素" },
  ];

  return (
    <div className="bg-slate-800/50 rounded-xl p-4 border border-slate-700 space-y-5">
      <div className="flex items-center gap-2 text-banana-400 font-medium mb-1">
        <Settings2 size={18} />
        <h2>生成参数</h2>
      </div>

      <div className="grid grid-cols-1 gap-4">
        <div>
          <label className="text-[10px] text-slate-500 block mb-2 font-bold uppercase tracking-wider flex items-center gap-1">
            <Cpu size={12} /> 生成引擎
          </label>
          <div className="grid grid-cols-2 gap-2">
            {[AIModel.Standard, AIModel.Pro].map(m => (
              <button
                key={m}
                disabled={disabled}
                onClick={() => onModelChange(m)}
                className={`py-1.5 rounded-lg border text-[10px] font-bold transition-all ${
                  model === m ? 'bg-banana-500/20 border-banana-500 text-banana-400' : 'bg-slate-900 border-slate-700 text-slate-500'
                }`}
              >
                {m === AIModel.Pro ? 'Nano Pro' : 'Nano Std'}
              </button>
            ))}
          </div>
        </div>

        <div className="flex items-center justify-between bg-slate-900/50 p-2.5 rounded-xl border border-slate-700/50">
          <div className="flex items-center gap-2">
            <BrainCircuit size={14} className={isSmartAnalysis ? "text-banana-400" : "text-slate-500"} />
            <span className="text-[10px] font-bold text-slate-300">AI 语义增强</span>
          </div>
          <button
            disabled={disabled}
            onClick={() => onSmartAnalysisChange(!isSmartAnalysis)}
            className={`w-8 h-4 rounded-full transition-colors relative ${isSmartAnalysis ? 'bg-banana-500' : 'bg-slate-700'}`}
          >
            <div className={`absolute top-0.5 w-3 h-3 bg-white rounded-full transition-all ${isSmartAnalysis ? 'left-4.5' : 'left-0.5'}`} />
          </button>
        </div>
      </div>

      <div className="space-y-3">
        <div className="flex items-center justify-between">
           <label className="text-[10px] text-slate-500 font-bold uppercase tracking-wider flex items-center gap-1">
             <Layout size={12} /> 画幅比例
           </label>
           <button 
             disabled={disabled || baseRatio === "1:1" || baseRatio === "custom"}
             onClick={toggleOrientation}
             className={`flex items-center gap-1.5 px-2.5 py-1 rounded-md border text-[10px] font-bold transition-all ${
               (baseRatio === "1:1" || baseRatio === "custom") ? 'opacity-20 cursor-not-allowed' : 'bg-slate-900 border-slate-700 text-banana-400'
             }`}
           >
             <RefreshCw size={10} className={isPortrait ? "rotate-90 transition-transform" : "transition-transform"} />
             {isPortrait ? '纵' : '横'}
           </button>
        </div>

        <div className="grid grid-cols-3 sm:grid-cols-6 gap-1.5">
          {baseRatioOptions.map((opt) => (
            <button
              key={opt.value}
              disabled={disabled}
              onClick={() => handleBaseRatioChange(opt.value)}
              className={`flex flex-col items-center justify-center py-2 px-1 rounded-lg border transition-all ${
                baseRatio === opt.value
                  ? 'bg-banana-500/10 border-banana-500 text-banana-400'
                  : 'bg-slate-900 border-slate-800 text-slate-600 hover:border-slate-700'
              }`}
            >
              <div className={`mb-1 border transition-all duration-300 ${
                baseRatio === opt.value ? 'border-banana-500 bg-banana-500/20' : 'border-slate-700'
              }`} style={{
                width: opt.value === "custom" ? "12px" : (opt.value === "1:1" ? "10px" : isPortrait ? "8px" : "14px"),
                height: opt.value === "custom" ? "12px" : (opt.value === "1:1" ? "10px" : isPortrait ? "14px" : "8px"),
                borderRadius: opt.value === "custom" ? "2px" : "1px",
                borderStyle: opt.value === "custom" ? "dashed" : "solid",
                aspectRatio: opt.value === "custom" ? "1" : (opt.value === "1:1" ? "1" : isPortrait ? (opt.value === "4:3" ? "0.75" : opt.value === "16:9" ? "0.56" : opt.value === "21:9" ? "0.42" : "0.8") : (opt.value === "4:3" ? "1.33" : opt.value === "16:9" ? "1.77" : opt.value === "21:9" ? "2.33" : "1.25"))
              }} />
              <span className="text-[9px] font-bold">{opt.label}</span>
            </button>
          ))}
        </div>

        {/* Custom Pixel Inputs */}
        {baseRatio === "custom" && (
          <div className="bg-slate-900/50 p-3 rounded-xl border border-slate-700 flex gap-3 animate-in fade-in slide-in-from-top-2">
            <div className="flex-1 space-y-1.5">
              <label className="text-[8px] text-slate-500 uppercase font-bold">宽度 (Width)</label>
              <input 
                type="number" 
                value={customWidth}
                min={256}
                max={4096}
                onChange={(e) => onCustomPixelsChange?.(parseInt(e.target.value) || 1024, customHeight)}
                className="w-full bg-slate-800 border border-slate-700 rounded px-2 py-1.5 text-xs text-banana-400 outline-none focus:border-banana-500"
              />
            </div>
            <div className="flex items-center pt-4 text-slate-600">
               <X size={10} />
            </div>
            <div className="flex-1 space-y-1.5">
              <label className="text-[8px] text-slate-500 uppercase font-bold">高度 (Height)</label>
              <input 
                type="number" 
                value={customHeight}
                min={256}
                max={4096}
                onChange={(e) => onCustomPixelsChange?.(customWidth, parseInt(e.target.value) || 1024)}
                className="w-full bg-slate-800 border border-slate-700 rounded px-2 py-1.5 text-xs text-banana-400 outline-none focus:border-banana-500"
              />
            </div>
          </div>
        )}
      </div>

      <div className="grid grid-cols-2 gap-3">
        <div>
          <label className="text-[10px] text-slate-500 block mb-1.5 font-bold uppercase tracking-wider">生成数量</label>
          <div className="flex bg-slate-900 rounded-lg p-1 border border-slate-700">
            {[1, 2, 4].map(num => (
              <button
                key={num}
                disabled={disabled}
                onClick={() => onBatchSizeChange(num)}
                className={`flex-1 py-1 rounded-md text-[10px] font-bold ${batchSize === num ? 'bg-banana-500 text-slate-900' : 'text-slate-500'}`}
              >
                {num}
              </button>
            ))}
          </div>
        </div>
        <div>
          <label className="text-[10px] text-slate-500 block mb-1.5 font-bold uppercase tracking-wider">分辨率档位</label>
          <select 
            disabled={disabled || model === AIModel.Standard}
            value={imageSize}
            onChange={(e) => onImageSizeChange(e.target.value as ImageSize)}
            className="w-full bg-slate-900 border border-slate-700 rounded-lg py-1 px-2 text-[10px] text-slate-300 outline-none"
