export default SettingsPanel;

import React, { useState, useEffect, useCallback, useRef } from 'react';
import { Sparkles, Download, Trash2, Loader2, Image as ImageIcon, Key, Copy, Check, Timer, Tag, BrainCircuit, Activity } from 'lucide-react';
import { generateSingleImage, analyzeAndName } from './services/geminiService';
import SettingsPanel from './components/SettingsPanel';
import ImageUploader from './components/ImageUploader';
import ImageViewer from './components/ImageViewer';
import { AspectRatio, ImageSize, GeneratedImage, AIModel, GenerationStep } from './types';

interface AIStudio {
  hasSelectedApiKey: () => Promise<boolean>;
  openSelectKey: () => Promise<void>;
}

const App: React.FC = () => {
  const [prompt, setPrompt] = useState('');
  const [inputImages, setInputImages] = useState<File[]>([]);
  const [aspectRatio, setAspectRatio] = useState<AspectRatio>(AspectRatio.Square);
  const [imageSize, setImageSize] = useState<ImageSize>(ImageSize.Size_1K);
  const [batchSize, setBatchSize] = useState<number>(1);
  const [model, setModel] = useState<AIModel>(AIModel.Pro);
  const [isSmartAnalysis, setIsSmartAnalysis] = useState<boolean>(true);

  const [customWidth, setCustomWidth] = useState(1024);
  const [customHeight, setCustomHeight] = useState(1024);

  const [isGenerating, setIsGenerating] = useState(false);
  const [progress, setProgress] = useState(0);
  const [elapsedTime, setElapsedTime] = useState(0);
  const [steps, setSteps] = useState<GenerationStep[]>([]);

  const [generatedImages, setGeneratedImages] = useState<GeneratedImage[]>([]);
  const [selectedImage, setSelectedImage] = useState<GeneratedImage | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [copyStatus, setCopyStatus] = useState<Record<string, boolean>>({});

  const [hasApiKey, setHasApiKey] = useState<boolean>(false);
  const [checkingKey, setCheckingKey] = useState<boolean>(true);

  const galleryEndRef = useRef<HTMLDivElement>(null);
  const startTimeRef = useRef<number>(0);
  const stepStartTimeRef = useRef<number>(0);

  useEffect(() => {
    const checkKey = async () => {
      const aistudio = (window as any).aistudio as AIStudio | undefined;
      if (aistudio && aistudio.hasSelectedApiKey) {
        const hasKey = await aistudio.hasSelectedApiKey();
        setHasApiKey(hasKey);
      } else {
        setHasApiKey(true); 
      }
      setCheckingKey(false);
    };
    checkKey();
  }, []);

  const handleSelectKey = async () => {
    const aistudio = (window as any).aistudio as AIStudio | undefined;
    if (aistudio && aistudio.openSelectKey) {
      await aistudio.openSelectKey();
      setHasApiKey(true);
      setError(null);
    }
  };

  const updateCurrentStep = (stepId: string, status: 'active' | 'done') => {
    const now = performance.now();
    setSteps(prev => prev.map(s => {
      if (s.id === stepId) {
        const duration = status === 'done' ? (now - stepStartTimeRef.current) / 1000 : null;
        if (status === 'done') stepStartTimeRef.current = now;
        return { ...s, status, duration };
      }
      return s;
    }));
  };

  const handleGenerate = async () => {
    if (!prompt.trim() && inputImages.length === 0) {
      setError("请输入提示词或上传参考图片");
      return;
    }

    if (model === AIModel.Pro) {
      const aistudio = (window as any).aistudio as AIStudio | undefined;
      if (aistudio && aistudio.hasSelectedApiKey) {
          const hasKey = await aistudio.hasSelectedApiKey();
          if (!hasKey) {
               setHasApiKey(false);
               return;
          }
      }
    }

    setIsGenerating(true);
    setError(null);
    setProgress(0);
    setElapsedTime(0);

    startTimeRef.current = performance.now();
    stepStartTimeRef.current = startTimeRef.current;

    const initialSteps: GenerationStep[] = [
      { id: 'prep', name: isSmartAnalysis ? 'AI 语义分析与增强' : '素材整理与命名', duration: null, status: 'active' },
      { id: 'inference', name: `${model === AIModel.Pro ? 'Pro' : '标准'} 引擎推理渲染`, duration: null, status: 'pending' },
      { id: 'finalize', name: '作品质检与归档', duration: null, status: 'pending' },
    ];
    setSteps(initialSteps);

    const timerInterval = setInterval(() => {
      setElapsedTime((performance.now() - startTimeRef.current) / 1000);
      setProgress(prev => (prev < 90 ? prev + 0.3 : prev));
    }, 100);

    try {
      const analysisResult = await analyzeAndName(prompt, inputImages, isSmartAnalysis);
      const { refinedPrompt, fileName } = analysisResult;

      updateCurrentStep('prep', 'done');
      setSteps(prev => prev.map(s => s.id === 'inference' ? { ...s, status: 'active' } : s));

      const generationTasks = Array.from({ length: batchSize }).map(() => 
        generateSingleImage(
            refinedPrompt, 
            inputImages, 
            aspectRatio, 
            imageSize, 
            model,
            aspectRatio === AspectRatio.Custom ? customWidth : undefined,
            aspectRatio === AspectRatio.Custom ? customHeight : undefined
        )
      );

      const results = await Promise.all(generationTasks);

      updateCurrentStep('inference', 'done');
      setSteps(prev => prev.map(s => s.id === 'finalize' ? { ...s, status: 'active' } : s));

      const finalTotalTime = (performance.now() - startTimeRef.current) / 1000;

      const finalStepsState: GenerationStep[] = [
        ...initialSteps.map(s => {
          if (s.id === 'prep') return { ...s, status: 'done', duration: steps.find(st => st.id === 'prep')?.duration || 0 } as GenerationStep;
          if (s.id === 'inference') return { ...s, status: 'done', duration: steps.find(st => st.id === 'inference')?.duration || 0 } as GenerationStep;
          return s;
        }),
        { id: 'finalize', name: '作品质检与归档', duration: finalTotalTime - (steps.reduce((acc, curr) => acc + (curr.duration || 0), 0)), status: 'done' } as GenerationStep
      ];

      const newImages: GeneratedImage[] = results.flatMap((urls, idx) => 
        urls.map((url, uIdx) => ({
          id: Date.now().toString() + Math.random().toString(),
          url,
          prompt: prompt || "参考图变体",
          refinedPrompt: isSmartAnalysis ? refinedPrompt : undefined,
          filename: batchSize > 1 ? `${fileName}-${idx + 1}` : fileName,
          timestamp: Date.now(),
          totalDuration: finalTotalTime,
          thoughtLog: JSON.parse(JSON.stringify(finalStepsState))
        }))
      );

      setTimeout(() => {
        updateCurrentStep('finalize', 'done');
        setProgress(100);
        clearInterval(timerInterval);

        setTimeout(() => {
            setGeneratedImages(prev => [...newImages, ...prev]);
            setIsGenerating(false);
            setTimeout(() => {
                galleryEndRef.current?.scrollIntoView({ behavior: 'smooth' });
            }, 100);
        }, 300);
      }, 300);

    } catch (err: any) {
      clearInterval(timerInterval);
      if (err.message && err.message.includes("Requested entity was not found")) {
         if (model === AIModel.Pro) setHasApiKey(false);
         setError("API Key 权限异常，请检查配置。");
      } else {
         setError(err.message || "生成过程出现异常。");
      }
      setIsGenerating(false);
    }
  };

  const handleCopyPrompt = async (text: string, id: string) => {
    try {
      await navigator.clipboard.writeText(text);
      setCopyStatus({ ...copyStatus, [id]: true });
      setTimeout(() => {
        setCopyStatus(prev => ({ ...prev, [id]: false }));
      }, 2000);
    } catch (err) {
      console.error("复制失败", err);
    }
  };

  const handleGlobalPaste = useCallback((e: ClipboardEvent) => {
    if (e.clipboardData && e.clipboardData.files.length > 0) {
        const files = Array.from(e.clipboardData.files).filter(f => f.type.startsWith('image/'));
        if (files.length > 0) {
            setInputImages(prev => [...prev, ...files]);
        }
    }
  }, []);

  useEffect(() => {
    window.addEventListener('paste', handleGlobalPaste);
    return () => window.removeEventListener('paste', handleGlobalPaste);
  }, [handleGlobalPaste]);

  if (checkingKey) return <div className="min-h-screen flex items-center justify-center bg-slate-900 text-banana-400 font-bold"><Loader2 className="animate-spin mr-3" /> 艺术引擎初始化...</div>;

  if (model === AIModel.Pro && !hasApiKey) {
      return (
          <div className="min-h-screen flex flex-col items-center justify-center bg-slate-900 p-4">
              <div className="max-w-md w-full bg-slate-800 p-8 rounded-2xl shadow-2xl text-center border border-slate-700">
                  <div className="w-16 h-16 bg-banana-500/10 rounded-full flex items-center justify-center mx-auto mb-6 text-banana-500 border border-banana-500/20">
                      <Key size={32} />
                  </div>
                  <h1 className="text-2xl font-bold text-white mb-2">Pro 版引擎已锁定</h1>
                  <p className="text-slate-400 mb-8 leading-relaxed">
                      nano bannan pro 需要您绑定一个已开启付费的 API 项目。该版本支持 4K 分辨率及更高精度的推理能力。
                  </p>
                  <div className="space-y-3">
                      <button onClick={handleSelectKey} className="w-full py-4 px-6 bg-banana-500 hover:bg-banana-400 text-slate-900 font-black rounded-xl transition-all shadow-lg shadow-banana-500/10">绑定 Pro 密钥</button>
                      <button onClick={() => setModel(AIModel.Standard)} className="w-full py-3 px-6 bg-slate-700 hover:bg-slate-600 text-white font-bold rounded-xl transition-all">返回标准版</button>
                  </div>
              </div>
          </div>
      );
  }

  return (
    <div className="min-h-screen bg-slate-900 text-slate-100 flex flex-col lg:flex-row">
      <div className="w-full lg:w-[420px] p-6 flex flex-col gap-6 lg:h-screen lg:overflow-y-auto border-b lg:border-b-0 lg:border-r border-slate-800 bg-slate-900/95 sticky top-0 z-30">
        <div className="flex items-center gap-4">
          <div className="w-12 h-12 bg-gradient-to-br from-banana-400 to-banana-600 rounded-2xl flex items-center justify-center shadow-xl text-slate-900">
            <Sparkles size={28} />
          </div>
          <div>
            <h1 className="text-xl font-black text-white leading-tight">nano bannan pro<br/><span className="text-banana-400 italic text-sm">图像编辑器</span></h1>
            <p className="text-[10px] text-slate-500 font-mono tracking-widest uppercase opacity-70">AI Smart Image Lab</p>
          </div>
        </div>

        <div className="space-y-3">
          <div className="flex justify-between items-end">
            <label className="text-xs font-bold text-slate-400 uppercase tracking-widest">创意提示词</label>
            <span className="text-[10px] bg-slate-800 px-2 py-0.5 rounded text-slate-500">{prompt.length}</span>
          </div>
          <textarea
            value={prompt}
            onChange={(e) => setPrompt(e.target.value)}
            placeholder="输入画面描述，例如：麋鹿载着圣诞老人在雪地飞驰..."
            className="w-full h-36 bg-slate-800/80 border border-slate-700 rounded-2xl p-4 text-sm focus:ring-2 focus:ring-banana-500/50 focus:border-banana-500 outline-none resize-none transition-all"
          />
        </div>

        <ImageUploader files={inputImages} onFilesChange={setInputImages} disabled={isGenerating} />

        <SettingsPanel 
          aspectRatio={aspectRatio} 
          imageSize={imageSize} 
          batchSize={batchSize}
          model={model}
          isSmartAnalysis={isSmartAnalysis}
          customWidth={customWidth}
          customHeight={customHeight}
          onAspectRatioChange={setAspectRatio}
          onImageSizeChange={setImageSize}
          onBatchSizeChange={setBatchSize}
          onModelChange={setModel}
          onSmartAnalysisChange={setIsSmartAnalysis}
          onCustomPixelsChange={(w, h) => { setCustomWidth(w); setCustomHeight(h); }}
          disabled={isGenerating}
        />

        {error && <div className="bg-red-500/10 border border-red-500/50 text-red-400 p-4 rounded-xl text-xs font-medium animate-in slide-in-from-top-4">{error}</div>}

        <button
          onClick={handleGenerate}
          disabled={isGenerating || (!prompt && inputImages.length === 0)}
          className="w-full py-5 bg-gradient-to-r from-banana-500 to-banana-600 hover:from-banana-400 hover:to-banana-500 text-slate-900 font-black rounded-2xl shadow-xl shadow-banana-500/20 disabled:opacity-50 transition-all transform active:scale-95 flex items-center justify-center gap-3 overflow-hidden relative"
        >
          {isGenerating ? (
            <div className="flex items-center gap-3 z-10">
                <Loader2 className="animate-spin" size={24} /> 
                <span>渲染中... ({Math.round(progress)}%)</span>
            </div>
          ) : (
            <><Sparkles size={24} /> <span>开启艺术之旅</span></>
          )}
          {isGenerating && (
            <div className="absolute left-0 bottom-0 top-0 bg-white/10 transition-all duration-300 pointer-events-none" style={{ width: `${progress}%` }} />
          )}
        </button>

        {isGenerating && (
            <div className="bg-slate-800/60 rounded-2xl border border-slate-700/50 p-5 space-y-4 animate-in fade-in slide-in-from-bottom-2 duration-300 shadow-inner">
                <div className="flex justify-between items-center pb-2 border-b border-slate-700/50">
                    <div className="flex items-center gap-2 text-banana-400 text-xs font-bold uppercase tracking-wider">
                        <Activity size={14} className="animate-pulse" /> 实时链路监测
                    </div>
                    <div className="flex items-center gap-1.5 text-slate-400 font-mono text-[10px]">
                        <Timer size={12} /> {elapsedTime.toFixed(1)}s
                    </div>
                </div>

                <div className="space-y-3">
                    {steps.map((step) => (
                        <div key={step.id} className="flex items-center justify-between group">
                            <div className="flex items-center gap-3">
                                {step.status === 'done' ? <div className="w-4 h-4 rounded-full bg-green-500/20 flex items-center justify-center text-green-500"><Check size={10} strokeWidth={4} /></div> : step.status === 'active' ? <Loader2 size={12} className="animate-spin text-banana-400" /> : <div className="w-4 h-4 rounded-full border border-slate-700" />}
                                <span className={`text-xs ${step.status === 'active' ? 'text-banana-400 font-bold' : step.status === 'done' ? 'text-slate-300' : 'text-slate-600'}`}>{step.name}</span>
                            </div>
                            {step.duration !== null && <span className="text-[10px] font-mono text-slate-500">{step.duration.toFixed(2)}s</span>}
                        </div>
                    ))}
                </div>

                <div className="space-y-1.5">
                    <div className="h-1.5 w-full bg-slate-900 rounded-full overflow-hidden border border-slate-700">
                        <div className="h-full bg-gradient-to-r from-banana-600 via-banana-400 to-banana-500 transition-all duration-300" style={{ width: `${progress}%` }} />
                    </div>
                </div>
            </div>
        )}
      </div>

      <div className="flex-1 bg-slate-950 p-6 lg:p-12 overflow-y-auto lg:h-screen relative">
        <div className="max-w-7xl mx-auto">
            <div className="flex items-center justify-between mb-8">
            <h2 className="text-xl font-bold text-slate-200 flex items-center gap-3">
                <ImageIcon className="text-banana-500" size={24} /> 创作库
                <span className="bg-slate-800 text-slate-400 text-xs px-3 py-1 rounded-full font-mono">{generatedImages.length}</span>
            </h2>
            {generatedImages.length > 0 && <button onClick={() => setGeneratedImages([])} className="text-xs text-red-400 hover:bg-red-500/10 px-4 py-2 rounded-xl border border-red-500/20 transition-colors flex items-center gap-2"><Trash2 size={14} /> 清空记录</button>}
            </div>

            <div className="grid grid-cols-1 sm:grid-cols-2 xl:grid-cols-3 2xl:grid-cols-4 gap-8" ref={galleryEndRef}>
            {generatedImages.length === 0 && !isGenerating ? (
                <div className="col-span-full h-[500px] flex flex-col items-center justify-center text-slate-700 border-2 border-dashed border-slate-800 rounded-[3rem] bg-slate-900/20">
                    <div className="relative mb-6">
                        <Sparkles size={64} className="opacity-10" />
                        <BrainCircuit size={24} className="absolute -top-2 -right-2 opacity-20 animate-pulse text-banana-400" />
                    </div>
                    <p className="text-xl font-bold opacity-30">画卷正待铺展</p>
                    <p className="text-xs opacity-20 mt-2">支持多图参考及 AI 智能增强</p>
                </div>
            ) : (
                <>
                {isGenerating && (
                    <div className="aspect-square rounded-[2rem] bg-slate-900/50 border border-slate-800 flex flex-col items-center justify-center animate-pulse relative overflow-hidden group">
                        <div className="relative">
                            <Loader2 className="animate-spin text-banana-500/50" size={48} />
                            {isSmartAnalysis && <BrainCircuit className="absolute -top-4 -right-4 text-banana-400/30 animate-bounce" size={20} />}
                        </div>
                        <div className="mt-8 flex flex-col items-center px-6 text-center">
                            <p className="text-xs font-bold text-banana-400 uppercase tracking-widest mb-2">
                                {isSmartAnalysis ? '智能神经网络构建中' : '正在执行推理任务'}
                            </p>
                            <p className="text-[10px] text-slate-500 font-mono italic">正在将创意转化为像素...</p>
                        </div>
                    </div>
                )}
                {generatedImages.map((img) => (
                    <div key={img.id} className="group relative rounded-[2rem] overflow-hidden bg-slate-900 border border-slate-800 shadow-2xl transition-all hover:border-banana-500/40 hover:scale-[1.02] duration-500 cursor-pointer" onClick={() => setSelectedImage(img)}>
                    <img src={img.url} alt={img.prompt} className="w-full h-full object-cover aspect-square bg-slate-800 transition-transform duration-700 group-hover:scale-110" />

                    <div className="absolute top-4 right-4 z-10">
                        <span className="bg-slate-950/80 backdrop-blur-md text-[9px] font-mono text-banana-400 px-2.5 py-1 rounded-full border border-banana-500/20 flex items-center gap-1.5 shadow-xl">
                            <Timer size={10} /> {img.totalDuration.toFixed(1)}s
                        </span>
                    </div>

                    <div className="absolute top-4 left-4 flex gap-2">
                        <span className="bg-slate-950/70 backdrop-blur-md text-[10px] font-bold text-banana-400 px-3 py-1.5 rounded-full border border-banana-500/20 flex items-center gap-2 shadow-lg">
                            <Tag size={10} /> {img.filename}
                        </span>
                        {img.refinedPrompt && (
                             <span className="bg-banana-500/80 backdrop-blur-md text-[8px] font-black text-slate-950 px-2 py-1.5 rounded-full flex items-center gap-1 shadow-lg uppercase">
                                <BrainCircuit size={8} /> AI 增强
                             </span>
                        )}
                    </div>
                    <div className="absolute inset-0 bg-gradient-to-t from-slate-950 via-slate-950/40 to-transparent opacity-0 group-hover:opacity-100 transition-all duration-300 flex flex-col justify-end p-6">
                        <div className="flex gap-2 translate-y-2 group-hover:translate-y-0 transition-transform duration-300">
                            <button 
                                onClick={(e) => { e.stopPropagation(); handleCopyPrompt(img.prompt, img.id); }}
                                className="flex-1 bg-white/10 hover:bg-white/20 text-white backdrop-blur-md py-2.5 rounded-xl text-[10px] font-bold flex items-center justify-center gap-2 transition-all border border-white/10"
                            >
                                {copyStatus[img.id] ? <><Check size={14} className="text-green-400" /> <span>已复制</span></> : <><Copy size={14} className="opacity-60" /> <span>提示词</span></>}
                            </button>
                            <a href={img.url} download={`${img.filename}.png`} onClick={(e) => e.stopPropagation()} className="bg-banana-500 hover:bg-banana-400 text-slate-900 w-10 h-10 rounded-xl flex items-center justify-center transition-colors shadow-lg shadow-banana-500/20">
                                <Download size={18} />
                            </a>
                        </div>
                    </div>
                    </div>
                ))}
                </>
            )}
            </div>
        </div>
      </div>

      {selectedImage && (
        <ImageViewer 
          image={selectedImage} 
          onClose={() => setSelectedImage(null)} 
          onCopy={() => handleCopyPrompt(selectedImage.prompt, selectedImage.id)}
          isCopied={copyStatus[selectedImage.id]}
        />
      )}
    </div>
  );
};

export default App;

import React, { useMemo } from 'react';
import { AspectRatio, ImageSize, AIModel } from '../types';
import { Settings2, Maximize, Layers, Cpu, BrainCircuit, RefreshCw, Layout, Smartphone, X } from 'lucide-react';

interface SettingsPanelProps {
  aspectRatio: AspectRatio;
  imageSize: ImageSize;
  batchSize: number;
  model: AIModel;
  isSmartAnalysis: boolean;
  customWidth?: number;
  customHeight?: number;
  onAspectRatioChange: (ratio: AspectRatio) => void;
  onImageSizeChange: (size: ImageSize) => void;
  onBatchSizeChange: (size: number) => void;
  onModelChange: (model: AIModel) => void;
  onSmartAnalysisChange: (enabled: boolean) => void;
  onCustomPixelsChange?: (width: number, height: number) => void;
  disabled: boolean;
}

const SettingsPanel: React.FC<SettingsPanelProps> = ({
  aspectRatio,
  imageSize,
  batchSize,
  model,
  isSmartAnalysis,
  customWidth = 1024,
  customHeight = 1024,
  onAspectRatioChange,
  onImageSizeChange,
  onBatchSizeChange,
  onModelChange,
  onSmartAnalysisChange,
  onCustomPixelsChange,
  disabled
}) => {

  const isPortrait = useMemo(() => {
    return [
      AspectRatio.Portrait_3_4, 
      AspectRatio.Portrait_9_16, 
      AspectRatio.Portrait_9_21,
      AspectRatio.Portrait_4_5
    ].includes(aspectRatio);
  }, [aspectRatio]);

  const baseRatio = useMemo(() => {
    if (aspectRatio === AspectRatio.Custom) return "custom";
    if (aspectRatio === AspectRatio.Square) return "1:1";
    if (aspectRatio === AspectRatio.Landscape_4_3 || aspectRatio === AspectRatio.Portrait_3_4) return "4:3";
    if (aspectRatio === AspectRatio.Landscape_16_9 || aspectRatio === AspectRatio.Portrait_9_16) return "16:9";
    if (aspectRatio === AspectRatio.Landscape_21_9 || aspectRatio === AspectRatio.Portrait_9_21) return "21:9";
    if (aspectRatio === AspectRatio.Landscape_5_4 || aspectRatio === AspectRatio.Portrait_4_5) return "4:5";
    return "1:1";
  }, [aspectRatio]);

  const toggleOrientation = () => {
    if (baseRatio === "1:1" || baseRatio === "custom") return;

    let newRatio = aspectRatio;
    if (baseRatio === "4:3") newRatio = isPortrait ? AspectRatio.Landscape_4_3 : AspectRatio.Portrait_3_4;
    if (baseRatio === "16:9") newRatio = isPortrait ? AspectRatio.Landscape_16_9 : AspectRatio.Portrait_9_16;
    if (baseRatio === "21:9") newRatio = isPortrait ? AspectRatio.Landscape_21_9 : AspectRatio.Portrait_9_21;
    if (baseRatio === "4:5") newRatio = isPortrait ? AspectRatio.Landscape_5_4 : AspectRatio.Portrait_4_5;

    onAspectRatioChange(newRatio);
  };

  const handleBaseRatioChange = (base: string) => {
    if (base === "custom") {
      onAspectRatioChange(AspectRatio.Custom);
      return;
    }
    let newRatio = AspectRatio.Square;
    if (base === "4:3") newRatio = isPortrait ? AspectRatio.Portrait_3_4 : AspectRatio.Landscape_4_3;
    if (base === "16:9") newRatio = isPortrait ? AspectRatio.Portrait_9_16 : AspectRatio.Landscape_16_9;
    if (base === "21:9") newRatio = isPortrait ? AspectRatio.Portrait_9_21 : AspectRatio.Landscape_21_9;
    if (base === "4:5") newRatio = isPortrait ? AspectRatio.Portrait_4_5 : AspectRatio.Landscape_5_4;
    onAspectRatioChange(newRatio);
  };

  const baseRatioOptions = [
    { value: "1:1", label: "1:1", desc: "社交" },
    { value: "4:5", label: "4:5", desc: "人像" },
