import { GoogleGenAI, Type } from "@google/genai";
import { AspectRatio, ImageSize, AIModel } from "../types";

const fileToPart = async (file: File | Blob): Promise<{ inlineData: { data: string; mimeType: string } }> => {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onloadend = () => {
      if (typeof reader.result === 'string') {
        const base64Data = reader.result.split(',')[1];
        const mimeType = file.type || 'image/png';
        resolve({
          inlineData: {
            data: base64Data,
            mimeType: mimeType,
          },
        });
      } else {
        reject(new Error("读取数据失败"));
      }
    };
    reader.onerror = reject;
    reader.readAsDataURL(file);
  });
};

const mapToSupportedRatio = (ratio: AspectRatio, width?: number, height?: number): string => {
  if (ratio === AspectRatio.Custom && width && height) {
    const r = width / height;
    if (r >= 1.5) return "16:9";
    if (r >= 1.2) return "4:3";
    if (r > 0.8) return "1:1";
    if (r > 0.6) return "3:4";
    return "9:16";
  }
  const mapping: Record<string, string> = {
    [AspectRatio.Square]: "1:1",
    [AspectRatio.Landscape_4_3]: "4:3",
    [AspectRatio.Portrait_3_4]: "3:4",
    [AspectRatio.Landscape_16_9]: "16:9",
    [AspectRatio.Portrait_9_16]: "9:16",
    [AspectRatio.Portrait_4_5]: "3:4",
    [AspectRatio.Landscape_5_4]: "4:3",
  };
  return mapping[ratio] || "1:1";
};

/**
 * 将多张图片拼接为一张大图
 */
export const stitchImages = async (imageUrls: string[][], gridCount: number): Promise<string> => {
  return new Promise((resolve, reject) => {
    const canvas = document.createElement('canvas');
    const ctx = canvas.getContext('2d');
    if (!ctx) return reject("Canvas context error");

    const imgObjects: HTMLImageElement[][] = imageUrls.map(row => row.map(() => new Image()));
    let loadedCount = 0;
    const totalCount = gridCount * gridCount;

    const checkAllLoaded = () => {
      if (loadedCount === totalCount) {
        const singleW = imgObjects[0][0].width;
        const singleH = imgObjects[0][0].height;
        canvas.width = singleW * gridCount;
        canvas.height = singleH * gridCount;

        for (let r = 0; r < gridCount; r++) {
          for (let c = 0; c < gridCount; c++) {
            ctx.drawImage(imgObjects[r][c], c * singleW, r * singleH);
          }
        }
        resolve(canvas.toDataURL('image/png', 1.0));
      }
    };

    for (let r = 0; r < gridCount; r++) {
      for (let c = 0; c < gridCount; c++) {
        imgObjects[r][c].onload = () => {
          loadedCount++;
          checkAllLoaded();
        };
        imgObjects[r][c].onerror = () => reject("分块图片加载失败");
        imgObjects[r][c].src = imageUrls[r][c];
      }
    }
  });
};

export const analyzeAndName = async (prompt: string = "", files: File[], isSmartAnalysis: boolean) => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  const safePrompt = prompt || "";
  try {
    const parts: any[] = [];
    if (files.length > 0) {
      const imageParts = await Promise.all(files.map(fileToPart));
      parts.push(...imageParts);
    }
    const systemInstruction = "你是一个顶尖的AI绘画专家。分析并生成 refinedPrompt (英文) 和 fileName (中文)。如果只有图片，请根据图片内容构思。";
    parts.push({ text: `用户提示词: ${safePrompt || "（仅参考图）"}` });
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: { parts },
      config: { 
        systemInstruction, 
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            refinedPrompt: { type: Type.STRING },
            fileName: { type: Type.STRING }
          },
          required: ["refinedPrompt", "fileName"]
        }
      }
    });
    return JSON.parse(response.text);
  } catch (e) {
    return { 
      refinedPrompt: safePrompt || "Professional creative artwork", 
      fileName: safePrompt ? safePrompt.substring(0, 8) : "AI创意作品" 
    };
  }
};

export const generateSingleImage = async (
  prompt: string = "",
  inputFiles: (File | Blob)[],
  aspectRatio: AspectRatio,
  imageSize: ImageSize,
  model: AIModel,
  customWidth?: number,
  customHeight?: number,
  tileContext?: string 
): Promise<string[]> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  const parts: any[] = [];

  if (inputFiles.length > 0) {
    const imageParts = await Promise.all(inputFiles.map(fileToPart));
    parts.push(...imageParts);
  }

  // 修复：确保 prompt 不为 undefined 并处理 trim
  let finalPrompt = (prompt || "").trim();
  if (finalPrompt === "" && inputFiles.length === 0) {
    throw new Error("生成提示词不能为空");
  }

  if (tileContext) {
    finalPrompt = `This is the ${tileContext} of a large ultra-high resolution composition. Refine details for this specific area while maintaining coherence with the global reference: ${finalPrompt}`;
  }

  parts.push({ text: finalPrompt || "Masterpiece, high detail" });

  const config: any = {
    imageConfig: {
      aspectRatio: mapToSupportedRatio(aspectRatio, customWidth, customHeight),
      imageSize: (aspectRatio === AspectRatio.Custom) ? "4K" : imageSize
    }
  };

  const response = await ai.models.generateContent({
    model: model,
    contents: { parts },
    config
  });

  const urls: string[] = [];
  if (response.candidates?.[0]?.content?.parts) {
    for (const part of response.candidates[0].content.parts) {
      if (part.inlineData?.data) {
        urls.push(`data:${part.inlineData.mimeType || 'image/png'};base64,${part.inlineData.data}`);
      }
    }
  }
  return urls;
};

