import { GoogleGenAI, Type } from "@google/genai";
import { AspectRatio, ImageSize, AIModel } from "../types";

const fileToPart = async (file: File | Blob): Promise<{ inlineData: { data: string; mimeType: string } }> => {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onloadend = () => {
      if (typeof reader.result === 'string') {
        const base64Data = reader.result.split(',')[1];
        const mimeType = file.type || 'image/png';
        resolve({
          inlineData: {
            data: base64Data,
            mimeType: mimeType,
          },
        });
      } else {
        reject(new Error("读取数据失败"));
      }
    };
    reader.onerror = reject;
    reader.readAsDataURL(file);
  });
};

const mapToSupportedRatio = (ratio: AspectRatio, width?: number, height?: number): string => {
  if (ratio === AspectRatio.Custom && width && height) {
    const r = width / height;
    if (r >= 1.5) return "16:9";
    if (r >= 1.2) return "4:3";
    if (r > 0.8) return "1:1";
    if (r > 0.6) return "3:4";
    return "9:16";
  }
  const mapping: Record<string, string> = {
    [AspectRatio.Square]: "1:1",
    [AspectRatio.Landscape_4_3]: "4:3",
    [AspectRatio.Portrait_3_4]: "3:4",
    [AspectRatio.Landscape_16_9]: "16:9",
    [AspectRatio.Portrait_9_16]: "9:16",
    [AspectRatio.Portrait_4_5]: "3:4",
    [AspectRatio.Landscape_5_4]: "4:3",
  };
  return mapping[ratio] || "1:1";
};

/**
 * 精确拼接分块，并缩放到用户指定的自定义分辨率
 */
export const stitchImages = async (
  imageUrls: string[][], 
  gridCount: number, 
  targetWidth: number, 
  targetHeight: number
): Promise<string> => {
  return new Promise((resolve, reject) => {
    const canvas = document.createElement('canvas');
    const ctx = canvas.getContext('2d');
    if (!ctx) return reject("Canvas context error");

    const imgObjects: HTMLImageElement[][] = imageUrls.map(row => row.map(() => new Image()));
    let loadedCount = 0;
    const totalCount = gridCount * gridCount;

    const checkAllLoaded = () => {
      if (loadedCount === totalCount) {
        // 设置画布为用户指定的物理像素
        canvas.width = targetWidth;
        canvas.height = targetHeight;

        const tileW = targetWidth / gridCount;
        const tileH = targetHeight / gridCount;

        for (let r = 0; r < gridCount; r++) {
          for (let c = 0; c < gridCount; c++) {
            // 将每一个生成的 4K 分块精确绘制到画布对应的坐标区间
            ctx.drawImage(imgObjects[r][c], c * tileW, r * tileH, tileW, tileH);
          }
        }
        resolve(canvas.toDataURL('image/png', 1.0));
      }
    };

    for (let r = 0; r < gridCount; r++) {
      for (let c = 0; c < gridCount; c++) {
        imgObjects[r][c].onload = () => {
          loadedCount++;
          checkAllLoaded();
        };
        imgObjects[r][c].onerror = () => reject("分块图像加载失败");
        imgObjects[r][c].src = imageUrls[r][c];
      }
    }
  });
};

export const analyzeAndName = async (prompt: string = "", files: File[], isSmartAnalysis: boolean) => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  const safePrompt = prompt || "";
  try {
    const parts: any[] = [];
    if (files.length > 0) {
      const imageParts = await Promise.all(files.map(fileToPart));
      parts.push(...imageParts);
    }
    const systemInstruction = "你是一个AI绘画专家。分析并生成 refinedPrompt (英文) 和 fileName (中文)。";
    parts.push({ text: `用户需求: ${safePrompt || "（参考图生成）"}` });
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: { parts },
      config: { 
        systemInstruction, 
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            refinedPrompt: { type: Type.STRING },
            fileName: { type: Type.STRING }
          },
          required: ["refinedPrompt", "fileName"]
        }
      }
    });
    return JSON.parse(response.text);
  } catch (e) {
    return { refinedPrompt: safePrompt || "High resolution masterpiece", fileName: "AI超清作品" };
  }
};

export const generateSingleImage = async (
  prompt: string = "",
  inputFiles: (File | Blob)[],
  aspectRatio: AspectRatio,
  imageSize: ImageSize,
  model: AIModel,
  customWidth?: number,
  customHeight?: number,
  tileContext?: string 
): Promise<string[]> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  const parts: any[] = [];

  if (inputFiles.length > 0) {
    const imageParts = await Promise.all(inputFiles.map(fileToPart));
    parts.push(...imageParts);
  }

  let finalPrompt = (prompt || "").trim();

  // 核心改进：如果是分块渲染，提示词必须强调“基于局部放大”和“全局一致性”
  if (tileContext) {
    finalPrompt = `
      Reference Image: This is a low-resolution global blueprint.
      Task: Redraw the [${tileContext}] section of this exact reference.
      Requirements: 
      1. DO NOT change the composition, colors, or lighting. 
      2. Increase texture density, sharpness, and high-frequency details.
      3. This is part of a larger canvas, ensure the edges seamlessly match the reference.
      Original Prompt: ${finalPrompt}
    `;
  }

  parts.push({ text: finalPrompt || "Masterpiece, ultra-detailed" });

  const config: any = {
    imageConfig: {
      aspectRatio: mapToSupportedRatio(aspectRatio, customWidth, customHeight),
      // 分块渲染时，每个 Tile 强制使用 4K 以获得最高局部细节
      imageSize: tileContext ? "4K" : ((aspectRatio === AspectRatio.Custom) ? "4K" : imageSize)
    }
  };

  const response = await ai.models.generateContent({
    model: model,
    contents: { parts },
    config
  });

  const urls: string[] = [];
  if (response.candidates?.[0]?.content?.parts) {
    for (const part of response.candidates[0].content.parts) {
      if (part.inlineData?.data) {
        urls.push(`data:${part.inlineData.mimeType || 'image/png'};base64,${part.inlineData.data}`);
      }
    }
  }
  return urls;
};

import React, { useState, useEffect, useCallback, useRef } from 'react';
import { Sparkles, Download, Trash2, Loader2, Image as ImageIcon, Key, Copy, Check, Timer, Tag, BrainCircuit, Activity, Zap } from 'lucide-react';
import { generateSingleImage, analyzeAndName, stitchImages } from './services/geminiService';
import SettingsPanel from './components/SettingsPanel';
import ImageUploader from './components/ImageUploader';
import ImageViewer from './components/ImageViewer';
import { AspectRatio, ImageSize, GeneratedImage, AIModel, GenerationStep } from './types';

const App: React.FC = () => {
  const [prompt, setPrompt] = useState('');
  const [inputImages, setInputImages] = useState<File[]>([]);
  const [aspectRatio, setAspectRatio] = useState<AspectRatio>(AspectRatio.Square);
  const [imageSize, setImageSize] = useState<ImageSize>(ImageSize.Size_1K);
  const [batchSize, setBatchSize] = useState<number>(1);
  const [model, setModel] = useState<AIModel>(AIModel.Pro);
  const [isSmartAnalysis, setIsSmartAnalysis] = useState<boolean>(true);
  const [isUltraResMode, setIsUltraResMode] = useState<boolean>(false);
  const [ultraResGrid, setUltraResGrid] = useState<number>(2);
  const [customWidth, setCustomWidth] = useState(1024);
  const [customHeight, setCustomHeight] = useState(1024);

  const [isGenerating, setIsGenerating] = useState(false);
  const [progress, setProgress] = useState(0);
  const [elapsedTime, setElapsedTime] = useState(0);
  const [steps, setSteps] = useState<GenerationStep[]>([]);
  const [generatedImages, setGeneratedImages] = useState<GeneratedImage[]>([]);
  const [selectedImage, setSelectedImage] = useState<GeneratedImage | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [copyStatus, setCopyStatus] = useState<Record<string, boolean>>({});

  const startTimeRef = useRef<number>(0);

  const handleGenerate = async () => {
    const safePrompt = (prompt || "").trim();
    if (!safePrompt && inputImages.length === 0) return setError("请输入提示词或提供参考图");

    setIsGenerating(true);
    setError(null);
    setProgress(0);
    startTimeRef.current = performance.now();

    const timer = setInterval(() => setElapsedTime((performance.now() - startTimeRef.current) / 1000), 100);

    try {
      const { refinedPrompt, fileName } = await analyzeAndName(safePrompt, inputImages, isSmartAnalysis);

      const newGeneratedResults: GeneratedImage[] = [];

      for (let i = 0; i < batchSize; i++) {
        const batchProgressBase = (i / batchSize) * 100;
        const batchWeight = 100 / batchSize;

        const currentSteps: GenerationStep[] = [
          { id: 'prep', name: `[${i+1}/${batchSize}] 语义分析`, status: 'active', duration: null },
          { id: 'global', name: '生成全局样图', status: 'pending', duration: null },
          { id: 'tiles', name: isUltraResMode ? `高精分块细节渲染 (${ultraResGrid}x${ultraResGrid})` : '细节生成', status: 'pending', duration: null },
          { id: 'stitch', name: isUltraResMode ? '无缝像素拼接' : '导出结果', status: 'pending', duration: null },
        ];
        setSteps(currentSteps);

        // 1. 生成全局样图 (Blueprint)
        const stepStart = performance.now();
        const globalResults = await generateSingleImage(refinedPrompt, inputImages, aspectRatio, ImageSize.Size_2K, model, customWidth, customHeight);
        const globalRefUrl = globalResults[0];

        setSteps(s => s.map(x => x.id === 'prep' ? {...x, status: 'done', duration: (performance.now()-stepStart)/1000} : x.id === 'global' ? {...x, status: 'active'} : x));
        setProgress(batchProgressBase + (batchWeight * 0.15));

        let finalUrl = globalRefUrl;

        if (isUltraResMode) {
          // 2. 将全局样图转为 Blob 供后续分块重绘参考
          const globalBlob = await (await fetch(globalRefUrl)).blob();
          setSteps(s => s.map(x => x.id === 'global' ? {...x, status: 'done'} : x.id === 'tiles' ? {...x, status: 'active'} : x));

          // 3. 按照网格进行局部重绘
          const tileGrid: string[][] = [];
          const totalTiles = ultraResGrid * ultraResGrid;
          let completedTiles = 0;

          for (let r = 0; r < ultraResGrid; r++) {
            tileGrid[r] = [];
            for (let c = 0; c < ultraResGrid; c++) {
              // 构造坐标描述，引导模型关注特定区域
              const rowDesc = r === 0 ? "Top" : (r === ultraResGrid - 1 ? "Bottom" : "Middle-row");
              const colDesc = c === 0 ? "Left" : (c === ultraResGrid - 1 ? "Right" : "Middle-column");
              const context = `${rowDesc}-${colDesc} quadrant`;

              // 传入全局样图 + 提示词，要求模型在保持全局结构下重绘该局部
              const tileResults = await generateSingleImage(refinedPrompt, [globalBlob, ...inputImages], aspectRatio, ImageSize.Size_4K, model, customWidth, customHeight, context);
              tileGrid[r][c] = tileResults[0];
              completedTiles++;
              setProgress(batchProgressBase + (batchWeight * 0.15) + (completedTiles / totalTiles) * (batchWeight * 0.75));
            }
          }

          setSteps(s => s.map(x => x.id === 'tiles' ? {...x, status: 'done'} : x.id === 'stitch' ? {...x, status: 'active'} : x));

          // 4. 精确拼接并缩放到目标像素
          const targetW = aspectRatio === AspectRatio.Custom ? customWidth : (aspectRatio.includes('16:9') ? 3840 : 2048);
          const targetH = aspectRatio === AspectRatio.Custom ? customHeight : (aspectRatio.includes('16:9') ? 2160 : 2048);

          finalUrl = await stitchImages(tileGrid, ultraResGrid, targetW, targetH);
        } else {
          setProgress(batchProgressBase + (batchWeight * 0.95));
        }

        const totalTimeForOne = (performance.now() - stepStart) / 1000;
        newGeneratedResults.push({
          id: Date.now().toString() + "-" + i,
          url: finalUrl,
          prompt: safePrompt,
          refinedPrompt: isSmartAnalysis ? refinedPrompt : undefined,
          filename: batchSize > 1 ? `${fileName}-${i + 1}` : fileName,
          timestamp: Date.now(),
          totalDuration: totalTimeForOne,
          thoughtLog: currentSteps.map(s => ({...s, status: 'done'})),
          isUltraRes: isUltraResMode,
          gridConfig: isUltraResMode ? `${ultraResGrid}x${ultraResGrid}` : undefined
        });
      }

      setGeneratedImages(prev => [...newGeneratedResults, ...prev]);
      setSteps(s => s.map(x => ({...x, status: 'done'})));
      setProgress(100);

    } catch (err: any) {
      console.error(err);
      setError(err.message || "生成失败，请尝试减少分块数量或简化提示词");
    } finally {
      clearInterval(timer);
      setIsGenerating(false);
    }
  };

  const handleCopyPrompt = async (text: string, id: string) => {
    try {
      await navigator.clipboard.writeText(text);
      setCopyStatus({ ...copyStatus, [id]: true });
      setTimeout(() => setCopyStatus(prev => ({ ...prev, [id]: false })), 2000);
    } catch (e) { console.error(e); }
  };

  return (
    <div className="min-h-screen bg-slate-900 text-slate-100 flex flex-col lg:flex-row">
      {/* Sidebar Controls */}
      <div className="w-full lg:w-[400px] p-6 flex flex-col gap-5 border-r border-slate-800 bg-slate-900/95 sticky top-0 z-30 lg:h-screen overflow-y-auto">
        <div className="flex items-center gap-3 mb-2">
          <div className="p-2 bg-banana-500 rounded-xl text-slate-900 shadow-lg shadow-banana-500/20"><Sparkles size={24} /></div>
          <div>
            <h1 className="font-black text-lg leading-none">Nano Lab <span className="text-banana-400">Pro</span></h1>
            <p className="text-[10px] text-slate-500 mt-1 uppercase tracking-tighter">Ultra-HD Image Forge</p>
          </div>
        </div>

        <textarea
          value={prompt}
          onChange={(e) => setPrompt(e.target.value)}
          placeholder="输入您的创意描述，支持上传参考图..."
          className="w-full h-32 bg-slate-800 border border-slate-700 rounded-2xl p-4 text-sm focus:border-banana-400 focus:ring-1 focus:ring-banana-400 outline-none transition-all placeholder:text-slate-600 shadow-inner"
        />

        <ImageUploader files={inputImages} onFilesChange={setInputImages} disabled={isGenerating} />

        <SettingsPanel 
          {...{aspectRatio, imageSize, batchSize, model, isSmartAnalysis, isUltraResMode, ultraResGrid, customWidth, customHeight}}
          onAspectRatioChange={setAspectRatio}
          onImageSizeChange={setImageSize}
          onBatchSizeChange={setBatchSize}
          onModelChange={setModel}
          onSmartAnalysisChange={setIsSmartAnalysis}
          onUltraResModeChange={setIsUltraResMode}
          onUltraResGridChange={setUltraResGrid}
          onCustomPixelsChange={(w, h) => { setCustomWidth(w); setCustomHeight(h); }}
          disabled={isGenerating}
        />

        {error && <div className="text-red-400 text-[10px] bg-red-400/10 p-3 rounded-lg border border-red-400/20">{error}</div>}

        <button
          onClick={handleGenerate}
          disabled={isGenerating}
