import React, { useState, useEffect, useCallback, useRef } from 'react';
import { Sparkles, Download, Loader2, Image as ImageIcon, Check, Activity, Github } from 'lucide-react';
import { generateSingleImage, analyzeAndName } from './services/geminiService';
import SettingsPanel from './components/SettingsPanel';
import ImageUploader from './components/ImageUploader';
import ImageViewer from './components/ImageViewer';
import { AspectRatio, ImageSize, GeneratedImage, AIModel, GenerationStep } from './types';

const App: React.FC = () => {
  const [prompt, setPrompt] = useState('');
  const [inputImages, setInputImages] = useState<File[]>([]);
  const [aspectRatio, setAspectRatio] = useState<AspectRatio>(AspectRatio.Square);
  const [imageSize, setImageSize] = useState<ImageSize>(ImageSize.Size_1K);
  const [batchSize, setBatchSize] = useState<number>(1);
  const [model, setModel] = useState<AIModel>(AIModel.Pro);
  const [isSmartAnalysis, setIsSmartAnalysis] = useState<boolean>(true);
  const [customWidth, setCustomWidth] = useState(1024);
  const [customHeight, setCustomHeight] = useState(1024);

  const [isGenerating, setIsGenerating] = useState(false);
  const [progress, setProgress] = useState(0);
  const [elapsedTime, setElapsedTime] = useState(0);
  const [steps, setSteps] = useState<GenerationStep[]>([]);
  const [generatedImages, setGeneratedImages] = useState<GeneratedImage[]>([]);
  const [selectedImage, setSelectedImage] = useState<GeneratedImage | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [copyStatus, setCopyStatus] = useState<Record<string, boolean>>({});

  const startTimeRef = useRef<number>(0);

  const handleGenerate = async () => {
    const safePrompt = (prompt || "").trim();
    if (!safePrompt && inputImages.length === 0) return setError("描述和图片至少需要提供一个");

    setIsGenerating(true);
    setError(null);
    setProgress(0);
    startTimeRef.current = performance.now();

    const timer = setInterval(() => setElapsedTime((performance.now() - startTimeRef.current) / 1000), 100);

    try {
      const { refinedPrompt, fileName } = await analyzeAndName(safePrompt, inputImages, isSmartAnalysis);

      const newGeneratedResults: GeneratedImage[] = [];

      for (let i = 0; i < batchSize; i++) {
        const batchProgressBase = (i / batchSize) * 100;
        const batchWeight = 100 / batchSize;

        const currentSteps: GenerationStep[] = [
          { id: 'prep', name: `[${i+1}/${batchSize}] 环境锁定`, status: 'active', duration: null },
          { id: 'render', name: '高清渲染', status: 'pending', duration: null },
          { id: 'post', name: '画质归档', status: 'pending', duration: null },
        ];
        setSteps(currentSteps);

        const stepStart = performance.now();
        setProgress(batchProgressBase + (batchWeight * 0.2));

        setSteps(s => s.map(x => x.id === 'prep' ? {...x, status: 'done'} : x.id === 'render' ? {...x, status: 'active'} : x));
        const urls = await generateSingleImage(refinedPrompt, inputImages, aspectRatio, imageSize, model, customWidth, customHeight);

        setProgress(batchProgressBase + (batchWeight * 0.8));
        setSteps(s => s.map(x => x.id === 'render' ? {...x, status: 'done'} : x.id === 'post' ? {...x, status: 'active'} : x));

        const totalTimeForOne = (performance.now() - stepStart) / 1000;
        newGeneratedResults.push({
          id: Date.now().toString() + "-" + i,
          url: urls[0],
          prompt: safePrompt,
          refinedPrompt: isSmartAnalysis ? refinedPrompt : undefined,
          filename: batchSize > 1 ? `${fileName}-${i + 1}` : fileName,
          timestamp: Date.now(),
          totalDuration: totalTimeForOne,
          thoughtLog: currentSteps.map(s => ({...s, status: 'done'}))
        });
      }

      setGeneratedImages(prev => [...newGeneratedResults, ...prev]);
      setSteps(s => s.map(x => ({...x, status: 'done'})));
      setProgress(100);

    } catch (err: any) {
      console.error(err);
      setError(err.message || "生成失败，请检查网络或刷新重试");
    } finally {
      clearInterval(timer);
      setIsGenerating(false);
    }
  };

  const handleCopyPrompt = async (text: string, id: string) => {
    try {
      await navigator.clipboard.writeText(text);
      setCopyStatus({ ...copyStatus, [id]: true });
      setTimeout(() => setCopyStatus(prev => ({ ...prev, [id]: false })), 2000);
    } catch (e) { console.error(e); }
  };

  return (
    <div className="min-h-screen bg-[#0a0c10] text-slate-100 flex flex-col lg:flex-row font-sans">
      {/* Sidebar Controls */}
      <div className="w-full lg:w-[380px] p-6 flex flex-col gap-6 border-r border-slate-800/50 bg-[#0d1117]/80 backdrop-blur-xl sticky top-0 z-30 lg:h-screen overflow-y-auto no-scrollbar">
        <div className="flex items-center justify-between mb-2">
          <div className="flex items-center gap-3">
            <div className="w-10 h-10 bg-banana-500 rounded-2xl flex items-center justify-center text-slate-900 shadow-lg shadow-banana-500/20 rotate-3">
              <Sparkles size={22} />
            </div>
            <div>
              <h1 className="font-black text-lg tracking-tight leading-none text-white">NANO LAB</h1>
              <p className="text-[9px] text-slate-500 mt-1 font-bold uppercase tracking-[0.2em]">BANNAN PRO ENGINE</p>
            </div>
          </div>
        </div>

        <div className="space-y-4">
          <div className="relative group">
