interface ImageViewerProps {
  image: GeneratedImage;
  isCopied: boolean;
  onClose: () => void;
  onCopy: () => void;
}

const ImageViewer: React.FC<ImageViewerProps> = ({ image, isCopied, onClose, onCopy }) => {
  const [scale, setScale] = useState(1);
  const [position, setPosition] = useState({ x: 0, y: 0 });
  const [isDragging, setIsDragging] = useState(false);
  const [dragStart, setDragStart] = useState({ x: 0, y: 0 });
  const [showThinking, setShowThinking] = useState(false);

  useEffect(() => {
    document.body.style.overflow = 'hidden';
    return () => { document.body.style.overflow = 'unset'; };
  }, []);

  const handleWheel = (e: React.WheelEvent) => {
    e.stopPropagation();
    const delta = -e.deltaY * 0.001;
    setScale(prev => Math.min(Math.max(0.5, prev + delta), 8));
  };

  const handleMouseDown = (e: React.MouseEvent) => {
    if (scale > 1) {
      setIsDragging(true);
      setDragStart({ x: e.clientX - position.x, y: e.clientY - position.y });
    }
  };

  const handleMouseMove = (e: React.MouseEvent) => {
    if (isDragging && scale > 1) {
      setPosition({ x: e.clientX - dragStart.x, y: e.clientY - dragStart.y });
    }
  };

  return (
    <div className="fixed inset-0 z-[60] flex items-center justify-center bg-[#0a0c10]/98 backdrop-blur-3xl animate-in fade-in duration-300" onClick={onClose}>
      <div className="absolute top-0 left-0 right-0 p-8 flex justify-between items-center z-50 pointer-events-none">
        <div className="flex items-center gap-4 pointer-events-auto">
             <div className="bg-slate-900/60 backdrop-blur rounded-[2rem] border border-white/5 p-2 flex gap-1">
                <button onClick={(e) => { e.stopPropagation(); setScale(Math.min(scale + 0.5, 8)); }} className="p-3 hover:bg-white/5 rounded-2xl text-slate-200 transition-colors"><ZoomIn size={20} /></button>
                <button onClick={(e) => { e.stopPropagation(); setScale(Math.max(0.5, scale - 0.5)); }} className="p-3 hover:bg-white/5 rounded-2xl text-slate-200 transition-colors"><ZoomOut size={20} /></button>
                <button onClick={(e) => { e.stopPropagation(); setScale(1); setPosition({x:0,y:0}); }} className="p-3 hover:bg-white/5 rounded-2xl text-slate-200 transition-colors"><RotateCcw size={20} /></button>
             </div>
             <button 
                onClick={(e) => { e.stopPropagation(); setShowThinking(!showThinking); }}
                className={`flex items-center gap-2 text-[10px] font-black uppercase px-5 py-2.5 rounded-full border transition-all ${showThinking ? 'bg-banana-500 text-slate-950 border-banana-500 shadow-lg shadow-banana-500/20' : 'bg-white/5 text-slate-300 border-white/10 hover:bg-white/10'}`}
             >
                <BrainCircuit size={14} /> 模型溯源
             </button>
        </div>

        <div className="flex gap-4 pointer-events-auto">
          <button onClick={(e) => { e.stopPropagation(); onCopy(); }} className={`px-6 py-4 rounded-3xl transition-all shadow-2xl flex items-center gap-2 ${isCopied ? 'bg-green-500 text-white' : 'bg-slate-800/80 hover:bg-slate-700 text-white border border-white/5'}`}>
            {isCopied ? <Check size={20} /> : <Copy size={20} />}
            <span className="text-xs font-black uppercase tracking-widest">{isCopied ? '已复制' : '复制咒语'}</span>
          </button>
          <a href={image.url} download={`${image.filename}.png`} onClick={(e) => e.stopPropagation()} className="p-4 bg-banana-500 hover:bg-banana-400 text-slate-950 rounded-3xl transition-all shadow-2xl shadow-banana-500/20">
            <Download size={24} />
          </a>
          <button onClick={onClose} className="p-4 bg-slate-900/80 hover:bg-red-500/20 text-white hover:text-red-400 rounded-3xl transition-all border border-white/5">
            <X size={24} />
          </button>
        </div>
      </div>

      <div className="w-full h-full flex items-center justify-center overflow-hidden" onWheel={handleWheel} onMouseDown={handleMouseDown} onMouseMove={handleMouseMove} onMouseUp={() => setIsDragging(false)} onMouseLeave={() => setIsDragging(false)} onClick={(e) => e.stopPropagation()}>
        <img 
            src={image.url} 
            alt={image.prompt} 
            className="max-w-[90%] max-h-[90%] object-contain transition-transform duration-100 ease-out select-none shadow-[0_0_100px_rgba(0,0,0,0.5)] rounded-2xl" 
            style={{ transform: `translate(${position.x}px, ${position.y}px) scale(${scale})`, cursor: scale > 1 ? (isDragging ? 'grabbing' : 'grab') : 'default' }} 
            draggable={false} 
        />
      </div>

      {showThinking && (
          <div className="absolute top-28 left-8 w-80 bg-slate-900/90 backdrop-blur-3xl border border-white/10 rounded-[2.5rem] p-8 shadow-2xl animate-in slide-in-from-left-4 duration-300 pointer-events-auto" onClick={(e) => e.stopPropagation()}>
              <div className="flex items-center justify-between mb-6 pb-4 border-b border-white/5">
                  <div className="flex items-center gap-2 text-banana-400 font-black text-xs uppercase tracking-widest">
                      <BrainCircuit size={16} /> 艺术构建逻辑
                  </div>
                  <div className="text-[10px] font-mono text-slate-500 flex items-center gap-1.5">
                      <Timer size={12} /> {image.totalDuration.toFixed(2)}S
                  </div>
              </div>
              <div className="space-y-6">
                  {image.thoughtLog.map((step, idx) => (
                      <div key={idx} className="flex flex-col gap-2 group">
