                  <div className="pt-4 mt-4 border-t border-white/5">
                      <p className="text-[10px] text-slate-500 leading-relaxed font-medium italic">
                          Refined Prompt: {image.refinedPrompt || '使用了标准生成。'}
                      </p>
                  </div>
              </div>
          </div>
      )}

      <div className="absolute bottom-12 left-0 right-0 text-center pointer-events-none px-8">
        <div className="max-w-4xl mx-auto px-10 py-8 bg-slate-900/60 backdrop-blur-xl border border-white/5 rounded-[3rem] shadow-2xl flex flex-col items-center gap-3 animate-in fade-in slide-in-from-bottom-4 duration-500 delay-200">
            <div className="flex items-center gap-2 text-banana-400 font-black uppercase text-xs tracking-[0.2em]">
                <Tag size={16} /> <span>{image.filename}</span>
            </div>
            <p className="text-white/80 text-sm leading-relaxed font-medium line-clamp-2 max-w-2xl italic">
            "{image.prompt || '视觉引导模式生成'}"
            </p>
        </div>
      </div>
    </div>
  );
};

