        <div className={`w-8 h-4 rounded-full relative transition-colors ${isSmartAnalysis ? 'bg-banana-500' : 'bg-slate-400 dark:bg-slate-700'}`}>
          <div className={`absolute top-0.5 w-3 h-3 bg-white rounded-full transition-all ${isSmartAnalysis ? 'left-4.5' : 'left-0.5'}`} />
        </div>
      </button>

      {/* Aspect Ratio Selection with Orientation Toggle */}
      <div className="space-y-3">
        <div className="flex items-center justify-between">
           <label className="text-[10px] text-slate-500 dark:text-slate-400 font-black uppercase flex items-center gap-1.5">
             <Layout size={12} /> 画幅比例
           </label>
           <div className="flex items-center gap-2">
              <button 
                onClick={() => setOrientation('portrait')} 
                className={`p-1.5 rounded-lg transition-colors ${orientation === 'portrait' ? 'bg-banana-500/20 text-banana-600' : 'text-slate-400'}`}
                title="纵向"
              >
                <Smartphone size={14} />
              </button>
              <button 
                onClick={() => setOrientation('landscape')} 
                className={`p-1.5 rounded-lg transition-colors ${orientation === 'landscape' ? 'bg-banana-500/20 text-banana-600' : 'text-slate-400'}`}
                title="横向"
              >
                <MonitorIcon size={14} />
              </button>
              <div className="w-px h-3 bg-slate-300 dark:bg-slate-700 mx-1" />
              <button 
                onClick={() => onAspectRatioChange(aspectRatio === AspectRatio.Custom ? AspectRatio.Square : AspectRatio.Custom)}
                className={`px-3 py-1 rounded-full border text-[9px] font-black uppercase transition-all ${aspectRatio === AspectRatio.Custom ? 'bg-banana-500 text-slate-900 border-banana-500' : 'bg-slate-200 dark:bg-slate-900 border-slate-300 dark:border-slate-700 text-slate-500'}`}
              >
                {aspectRatio === AspectRatio.Custom ? '取消自定义' : '自定义'}
              </button>
           </div>
        </div>

        {aspectRatio === AspectRatio.Custom ? (
          <div className="grid grid-cols-2 gap-3 p-3 bg-slate-200 dark:bg-slate-900/50 rounded-2xl border border-slate-300 dark:border-slate-700/50 animate-in fade-in zoom-in-95 duration-200">
            <div className="space-y-1">
              <span className="text-[8px] text-slate-600 dark:text-slate-400 font-bold uppercase">宽度 Width</span>
              <input type="number" value={customWidth} onChange={(e) => onCustomPixelsChange(parseInt(e.target.value)||1024, customHeight)} className="w-full bg-slate-100 dark:bg-slate-800 border border-slate-300 dark:border-slate-700 rounded-xl p-2 text-xs text-banana-600 dark:text-banana-400 outline-none" />
            </div>
            <div className="space-y-1">
              <span className="text-[8px] text-slate-600 dark:text-slate-400 font-bold uppercase">高度 Height</span>
              <input type="number" value={customHeight} onChange={(e) => onCustomPixelsChange(customWidth, parseInt(e.target.value)||1024)} className="w-full bg-slate-100 dark:bg-slate-800 border border-slate-300 dark:border-slate-700 rounded-xl p-2 text-xs text-banana-600 dark:text-banana-400 outline-none" />
            </div>
          </div>
        ) : (
          <div className="space-y-2">
            <div className="grid grid-cols-2 gap-2">
               <button 
                 onClick={() => onAspectRatioChange(AspectRatio.Square)}
                 className={`py-2 px-3 rounded-xl border text-[9px] font-bold flex items-center gap-2 transition-all ${aspectRatio === AspectRatio.Square ? 'bg-banana-500/10 border-banana-500 text-banana-600' : 'bg-slate-200 dark:bg-slate-900/50 border-slate-300 dark:border-slate-800 text-slate-500 hover:border-slate-400 dark:hover:border-slate-700'}`}
               >
                 <Square size={12} /> 1:1 正方形
               </button>
               {presets.map(p => (
                 <button 
                  key={p.value} 
                  onClick={() => onAspectRatioChange(p.value)} 
                  className={`py-2 px-3 rounded-xl border text-[9px] font-bold text-left transition-all ${aspectRatio === p.value ? 'bg-banana-500/10 border-banana-500 text-banana-600' : 'bg-slate-200 dark:bg-slate-900/50 border-slate-300 dark:border-slate-800 text-slate-500 hover:border-slate-400 dark:hover:border-slate-700'}`}
                 >
                   {p.label}
                 </button>
               ))}
            </div>
          </div>
        )}
      </div>

      {/* Batch and Size */}
      <div className="space-y-5">
        <div className="space-y-2">
          <div className="flex justify-between items-center">
            <label className="text-[10px] text-slate-500 dark:text-slate-400 font-black uppercase flex items-center gap-1.5">
              <Layers size={12} /> 批量生成数量
            </label>
            <span className="text-banana-600 dark:text-banana-400 font-mono text-[10px] font-bold bg-banana-500/10 px-2 py-0.5 rounded-lg border border-banana-500/20">{batchSize} 张</span>
          </div>
          <input 
            type="range" min="1" max="10" step="1" value={batchSize}
            disabled={disabled}
            onChange={(e) => onBatchSizeChange(parseInt(e.target.value))}
            className="w-full h-1 bg-slate-300 dark:bg-slate-700 rounded-full appearance-none cursor-pointer accent-banana-500"
          />
        </div>

        <div className="space-y-2">
          <label className="text-[10px] text-slate-500 dark:text-slate-400 font-black uppercase flex items-center gap-1.5">
            <Monitor size={12} /> 分辨率质量上限 (Pro)
          </label>
          <div className="grid grid-cols-3 gap-2">
            {[ImageSize.Size_1K, ImageSize.Size_2K, ImageSize.Size_4K].map(s => (
              <button
                key={s}
                disabled={disabled || model === AIModel.Standard}
                onClick={() => onImageSizeChange(s)}
                className={`py-1.5 rounded-xl border text-[10px] font-bold transition-all ${
                  imageSize === s && model === AIModel.Pro ? 'bg-slate-900 dark:bg-white/10 border-slate-800 dark:border-white/30 text-white' : 'bg-slate-200 dark:bg-slate-900/50 border-slate-300 dark:border-slate-800 text-slate-500'
                } ${model === AIModel.Standard ? 'opacity-30 cursor-not-allowed' : ''}`}
              >
                {s}
              </button>
            ))}
          </div>
        </div>
      </div>
    </div>
  );
};

export default SettingsPanel;

import React, { useState, useEffect, useCallback, useRef } from 'react';
import { Sparkles, Download, Loader2, Image as ImageIcon, Check, Activity, Github, Sun, Moon } from 'lucide-react';
import { generateSingleImage, analyzeAndName } from './services/geminiService';
import SettingsPanel from './components/SettingsPanel';
import ImageUploader from './components/ImageUploader';
import ImageViewer from './components/ImageViewer';
import { AspectRatio, ImageSize, GeneratedImage, AIModel, GenerationStep } from './types';

const App: React.FC = () => {
  const [prompt, setPrompt] = useState('');
  const [inputImages, setInputImages] = useState<File[]>([]);
  const [aspectRatio, setAspectRatio] = useState<AspectRatio>(AspectRatio.Square);
  const [imageSize, setImageSize] = useState<ImageSize>(ImageSize.Size_1K);
  const [batchSize, setBatchSize] = useState<number>(1);
  const [model, setModel] = useState<AIModel>(AIModel.Pro);
  const [isSmartAnalysis, setIsSmartAnalysis] = useState<boolean>(true);
  const [customWidth, setCustomWidth] = useState(1024);
  const [customHeight, setCustomHeight] = useState(1024);
  const [isDarkMode, setIsDarkMode] = useState(true);

  const [isGenerating, setIsGenerating] = useState(false);
  const [progress, setProgress] = useState(0);
  const [elapsedTime, setElapsedTime] = useState(0);
  const [steps, setSteps] = useState<GenerationStep[]>([]);
  const [generatedImages, setGeneratedImages] = useState<GeneratedImage[]>([]);
  const [selectedImage, setSelectedImage] = useState<GeneratedImage | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [copyStatus, setCopyStatus] = useState<Record<string, boolean>>({});

  const startTimeRef = useRef<number>(0);

  // Sync dark mode class
  useEffect(() => {
    if (isDarkMode) {
      document.documentElement.classList.add('dark');
    } else {
      document.documentElement.classList.remove('dark');
    }
  }, [isDarkMode]);

  const handleGenerate = async () => {
    const safePrompt = (prompt || "").trim();
    if (!safePrompt && inputImages.length === 0) return setError("描述和图片至少需要提供一个才能生成");

    setIsGenerating(true);
    setError(null);
    setProgress(0);
    startTimeRef.current = performance.now();

    const timer = setInterval(() => setElapsedTime((performance.now() - startTimeRef.current) / 1000), 100);

    try {
      const { refinedPrompt, fileName } = await analyzeAndName(safePrompt, inputImages, isSmartAnalysis);

      const newGeneratedResults: GeneratedImage[] = [];

      for (let i = 0; i < batchSize; i++) {
        const batchProgressBase = (i / batchSize) * 100;
        const batchWeight = 100 / batchSize;

        const currentSteps: GenerationStep[] = [
          { id: 'prep', name: `第 ${i+1} 张：意图分析`, status: 'active', duration: null },
          { id: 'render', name: 'Nano 核心渲染', status: 'pending', duration: null },
          { id: 'post', name: '数据流收尾', status: 'pending', duration: null },
        ];
        setSteps(currentSteps);

        const stepStart = performance.now();
        setProgress(batchProgressBase + (batchWeight * 0.2));

        setSteps(s => s.map(x => x.id === 'prep' ? {...x, status: 'done'} : x.id === 'render' ? {...x, status: 'active'} : x));
        const urls = await generateSingleImage(refinedPrompt, inputImages, aspectRatio, imageSize, model, customWidth, customHeight);

        setProgress(batchProgressBase + (batchWeight * 0.8));
        setSteps(s => s.map(x => x.id === 'render' ? {...x, status: 'done'} : x.id === 'post' ? {...x, status: 'active'} : x));

        const totalTimeForOne = (performance.now() - stepStart) / 1000;
        newGeneratedResults.push({
          id: Date.now().toString() + "-" + i,
          url: urls[0],
          prompt: safePrompt,
          refinedPrompt: isSmartAnalysis ? refinedPrompt : undefined,
          filename: batchSize > 1 ? `${fileName}-${i + 1}` : fileName,
          timestamp: Date.now(),
          totalDuration: totalTimeForOne,
          thoughtLog: currentSteps.map(s => ({...s, status: 'done'}))
        });
      }

      setGeneratedImages(prev => [...newGeneratedResults, ...prev]);
      setSteps(s => s.map(x => ({...x, status: 'done'})));
      setProgress(100);

    } catch (err: any) {
      console.error(err);
      setError(err.message || "生成遇到了一点问题，请稍后重试。");
    } finally {
      clearInterval(timer);
      setIsGenerating(false);
    }
  };

  const handleCopyPrompt = async (text: string, id: string) => {
    try {
      await navigator.clipboard.writeText(text);
      setCopyStatus({ ...copyStatus, [id]: true });
      setTimeout(() => setCopyStatus(prev => ({ ...prev, [id]: false })), 2000);
    } catch (e) { console.error(e); }
  };

  return (
    <div className="min-h-screen bg-slate-50 dark:bg-[#0a0c10] text-slate-900 dark:text-slate-100 flex flex-col lg:flex-row font-sans transition-colors duration-300">
      {/* Sidebar Controls */}
      <div className="w-full lg:w-[380px] p-6 flex flex-col gap-6 border-b lg:border-r border-slate-200 dark:border-slate-800/50 bg-white/80 dark:bg-[#0d1117]/80 backdrop-blur-xl sticky top-0 z-30 lg:h-screen overflow-y-auto no-scrollbar transition-colors duration-300">
        <div className="flex items-center justify-between mb-2">
          <div className="flex items-center gap-3">
            <div className="w-10 h-10 bg-banana-500 rounded-2xl flex items-center justify-center text-slate-900 shadow-lg shadow-banana-500/20 rotate-3 transition-transform hover:rotate-0">
              <Sparkles size={22} />
            </div>
            <div>
              <h1 className="font-black text-base tracking-tight leading-none">NANO LAB <span className="text-banana-600 dark:text-banana-400">V2.0</span></h1>
              <p className="text-[8px] text-slate-500 mt-1 font-bold uppercase tracking-[0.2em]">Nano Banana Image Engine</p>
            </div>
          </div>
          <button 
            onClick={() => setIsDarkMode(!isDarkMode)}
            className="p-2 rounded-xl bg-slate-100 dark:bg-slate-800 text-slate-600 dark:text-slate-400 hover:bg-slate-200 dark:hover:bg-slate-700 transition-colors"
          >
            {isDarkMode ? <Sun size={18} /> : <Moon size={18} />}
          </button>
        </div>

        <div className="space-y-4">
          <div className="relative group">
            <textarea
              value={prompt}
              onChange={(e) => setPrompt(e.target.value)}
              placeholder="描述您的创意图景..."
              className="w-full h-36 bg-white dark:bg-slate-800/30 border border-slate-200 dark:border-slate-700/50 rounded-[2rem] p-5 text-sm focus:border-banana-500 focus:ring-1 focus:ring-banana-500 outline-none transition-all placeholder:text-slate-400 dark:placeholder:text-slate-600 resize-none shadow-sm dark:shadow-none"
            />
            <div className="absolute bottom-4 right-5 text-[9px] text-slate-400 font-mono select-none">
              {prompt.length} 字符
            </div>
          </div>

          <ImageUploader files={inputImages} onFilesChange={setInputImages} disabled={isGenerating} />

          <SettingsPanel 
            {...{aspectRatio, imageSize, batchSize, model, isSmartAnalysis, customWidth, customHeight}}
            onAspectRatioChange={setAspectRatio}
            onImageSizeChange={setImageSize}
            onBatchSizeChange={setBatchSize}
            onModelChange={setModel}
            onSmartAnalysisChange={setIsSmartAnalysis}
            onCustomPixelsChange={(w, h) => { setCustomWidth(w); setCustomHeight(h); }}
            disabled={isGenerating}
          />
        </div>

        {error && (
          <div className="text-red-600 dark:text-red-400 text-[11px] bg-red-100 dark:bg-red-400/5 p-4 rounded-2xl border border-red-200 dark:border-red-400/20 animate-in fade-in slide-in-from-top-2">
            {error}
          </div>
        )}

        <div className="mt-auto pt-4 flex flex-col gap-4">
          <button
            onClick={handleGenerate}
            disabled={isGenerating}
            className="w-full py-4.5 bg-gradient-to-br from-banana-400 to-banana-600 hover:from-banana-300 hover:to-banana-500 text-slate-950 font-black rounded-[2rem] shadow-xl shadow-banana-500/10 transition-all flex items-center justify-center gap-3 disabled:opacity-40 active:scale-95 group"
          >
            {isGenerating ? <Loader2 className="animate-spin" size={18} /> : <Sparkles size={18} className="group-hover:rotate-12 transition-transform" />}
            {isGenerating ? `${Math.round(progress)}% 正在注入灵感` : `启动 Nano 引擎 (${batchSize}张)`}
          </button>

          {isGenerating && (
            <div className="space-y-3 p-5 bg-white dark:bg-slate-900/40 rounded-[2rem] border border-slate-200 dark:border-slate-700/30 shadow-sm transition-colors duration-300">
               <div className="flex justify-between text-[10px] font-mono text-slate-500 dark:text-slate-400">
                  <span className="flex items-center gap-1.5"><Activity size={12} className="text-banana-600 dark:text-banana-400" /> GPU 任务流水线</span>
                  <span>{elapsedTime.toFixed(1)}S</span>
               </div>
               <div className="space-y-2">
                 {steps.map(s => (
                   <div key={s.id} className="flex items-center justify-between text-[10px] tracking-tight">
                     <span className={s.status === 'active' ? 'text-banana-600 dark:text-banana-300 font-bold' : s.status === 'done' ? 'text-slate-400 dark:text-slate-500' : 'text-slate-300 dark:text-slate-700'}>{s.name}</span>
                     {s.status === 'active' ? <Loader2 size={10} className="animate-spin text-banana-600 dark:text-banana-400" /> : s.status === 'done' ? <Check size={10} className="text-green-600 dark:text-green-500" /> : <div className="w-1.5 h-1.5 rounded-full bg-slate-200 dark:bg-slate-800" />}
                   </div>
                 ))}
               </div>
            </div>
          )}
        </div>
      </div>

      {/* Main Content Area */}
      <div className="flex-1 p-8 bg-slate-50 dark:bg-[#0a0c10] overflow-y-auto lg:h-screen scroll-smooth transition-colors duration-300">
        <div className="max-w-7xl mx-auto">
          <div className="flex items-end justify-between mb-12">
            <div>
              <h2 className="text-2xl font-black text-slate-900 dark:text-white tracking-tight flex items-center gap-3 transition-colors duration-300">
                <ImageIcon className="text-banana-500" size={24} /> 艺术档案库
              </h2>
              <p className="text-xs text-slate-500 mt-1 uppercase tracking-wider">Historical Creative Vault</p>
            </div>
            <div className="hidden md:flex items-center gap-6">
               <div className="text-center">
                  <div className="text-xl font-black text-slate-900 dark:text-white">{generatedImages.length}</div>
                  <div className="text-[9px] text-slate-400 dark:text-slate-500 font-bold uppercase tracking-widest">作品总额</div>
               </div>
               <div className="w-px h-8 bg-slate-200 dark:bg-slate-800/50" />
               <a href="https://github.com" className="text-slate-400 hover:text-slate-900 dark:hover:text-white transition-colors"><Github size={20}/></a>
            </div>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-2 2xl:grid-cols-3 gap-10">
            {generatedImages.map((img, idx) => (
              <div 
                key={img.id} 
                className="group relative bg-white dark:bg-[#0d1117] rounded-[3rem] overflow-hidden border border-slate-200 dark:border-slate-800/50 hover:border-banana-500 transition-all cursor-pointer shadow-xl hover:shadow-2xl hover:-translate-y-2 animate-in fade-in slide-in-from-bottom-6 duration-500"
                style={{ animationDelay: `${idx * 80}ms` }}
                onClick={() => setSelectedImage(img)}
              >
                <div className="aspect-[4/5] relative overflow-hidden">
                  <img src={img.url} className="w-full h-full object-cover transition-transform duration-1000 group-hover:scale-110" loading="lazy" />
                  <div className="absolute inset-0 bg-gradient-to-t from-slate-900/80 via-transparent to-transparent opacity-60 dark:opacity-40" />
                </div>

                <div className="absolute top-6 left-6 flex gap-2">
                  <span className="px-4 py-1.5 bg-white/40 dark:bg-black/40 backdrop-blur-xl rounded-full text-[9px] font-black text-slate-900 dark:text-banana-400 border border-white/20 shadow-xl uppercase tracking-[0.15em]">{img.filename}</span>
                </div>

                <div className="absolute inset-x-0 bottom-0 p-8 transform translate-y-4 group-hover:translate-y-0 transition-all duration-500 opacity-0 group-hover:opacity-100">
                   <p className="text-[10px] text-white/90 dark:text-slate-300 line-clamp-2 mb-6 leading-relaxed font-medium italic">"{img.prompt || '纳米模型重组生成'}"</p>
                   <div className="flex gap-3">
                      <button className="flex-1 py-3.5 bg-white/10 dark:bg-white/5 hover:bg-white/20 dark:hover:bg-white/10 backdrop-blur-xl rounded-2xl text-[10px] font-black text-white border border-white/10 transition-all">查阅档案</button>
                      <a 
                        href={img.url} 
                        download={`${img.filename}.png`} 
                        className="p-3.5 bg-banana-500 hover:bg-banana-400 text-slate-900 rounded-2xl shadow-xl shadow-banana-500/20 transition-colors" 
                        onClick={e => e.stopPropagation()}
                      >
                        <Download size={20} />
                      </a>
                   </div>
                </div>
              </div>
            ))}

            {generatedImages.length === 0 && !isGenerating && (
                <div className="col-span-full py-40 flex flex-col items-center justify-center text-slate-400 dark:text-slate-700 bg-white dark:bg-slate-900/5 border-2 border-dashed border-slate-200 dark:border-slate-800/30 rounded-[5rem] shadow-sm transition-colors duration-300">
                    <div className="w-24 h-24 bg-slate-100 dark:bg-slate-800/20 rounded-full flex items-center justify-center mb-8">
                      <Sparkles size={40} className="opacity-20 text-banana-600 dark:text-banana-400" />
                    </div>
                    <p className="text-xl font-black text-slate-400 dark:text-slate-500 tracking-tight">纳米视觉引擎已就绪</p>
                    <p className="text-[9px] text-slate-400 dark:text-slate-600 mt-4 uppercase tracking-[0.4em] font-bold">Waiting for your creativity to manifest</p>
                </div>
            )}
          </div>
        </div>
      </div>

      {selectedImage && <ImageViewer image={selectedImage} isCopied={!!copyStatus[selectedImage.id]} onCopy={() => handleCopyPrompt(selectedImage.prompt, selectedImage.id)} onClose={() => setSelectedImage(null)} />}
    </div>
  );
};

export default App;

import React, { useState } from 'react';
import { AspectRatio, ImageSize, AIModel } from '../types';
import { Settings2, Cpu, BrainCircuit, Layout, X, Layers, Monitor, SlidersHorizontal, Smartphone, Monitor as MonitorIcon, Square } from 'lucide-react';

interface SettingsPanelProps {
  aspectRatio: AspectRatio;
  imageSize: ImageSize;
  batchSize: number;
  model: AIModel;
  isSmartAnalysis: boolean;
  customWidth?: number;
  customHeight?: number;
  onAspectRatioChange: (ratio: AspectRatio) => void;
  onImageSizeChange: (size: ImageSize) => void;
  onBatchSizeChange: (size: number) => void;
  onModelChange: (model: AIModel) => void;
  onSmartAnalysisChange: (enabled: boolean) => void;
  onCustomPixelsChange: (width: number, height: number) => void;
  disabled: boolean;
}

const SettingsPanel: React.FC<SettingsPanelProps> = ({
  aspectRatio, imageSize, batchSize, model, isSmartAnalysis,
  customWidth = 1024, customHeight = 1024,
  onAspectRatioChange, onImageSizeChange, onBatchSizeChange, onModelChange,
  onSmartAnalysisChange, onCustomPixelsChange,
  disabled
}) => {
  const [orientation, setOrientation] = useState<'portrait' | 'landscape'>('landscape');

  const portraitPresets = [
    { label: "9:16 全屏", value: AspectRatio.Portrait_9_16 },
    { label: "3:4 经典", value: AspectRatio.Portrait_3_4 },
    { label: "4:5 社媒", value: AspectRatio.Portrait_4_5 },
  ];

  const landscapePresets = [
    { label: "16:9 电影", value: AspectRatio.Landscape_16_9 },
    { label: "4:3 经典", value: AspectRatio.Landscape_4_3 },
    // Removed Landscape_21_9 as it is not defined in AspectRatio enum and not supported by Gemini API
    { label: "5:4 传统", value: AspectRatio.Landscape_5_4 },
  ];

  const presets = orientation === 'landscape' ? landscapePresets : portraitPresets;

  return (
    <div className="bg-slate-100 dark:bg-slate-800/40 rounded-3xl p-5 border border-slate-200 dark:border-slate-700/50 space-y-6 backdrop-blur-sm transition-colors">
      <div className="flex items-center justify-between">
        <div className="flex items-center gap-2 text-banana-600 dark:text-banana-400 font-bold text-xs uppercase tracking-widest">
          <SlidersHorizontal size={14} />
          参数配置
        </div>
      </div>

      {/* Engine Selection */}
      <div className="space-y-3">
        <label className="text-[10px] text-slate-500 dark:text-slate-400 font-black uppercase flex items-center gap-1.5">
          <Cpu size={12} /> 核心引擎 (Model)
        </label>
        <div className="grid grid-cols-2 gap-2 bg-slate-200 dark:bg-slate-900/50 p-1 rounded-2xl border border-slate-300 dark:border-slate-700/30">
          {[AIModel.Standard, AIModel.Pro].map(m => (
            <button
              key={m}
              disabled={disabled}
