import { GoogleGenAI, Type } from "@google/genai";
import { AspectRatio, ImageSize, AIModel } from "../types";

const fileToPart = async (file: File | Blob): Promise<{ inlineData: { data: string; mimeType: string } }> => {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onloadend = () => {
      if (typeof reader.result === 'string') {
        const base64Data = reader.result.split(',')[1];
        const mimeType = file.type || 'image/png';
        resolve({
          inlineData: {
            data: base64Data,
            mimeType: mimeType,
          },
        });
      } else {
        reject(new Error("读取数据失败"));
      }
    };
    reader.onerror = reject;
    reader.readAsDataURL(file);
  });
};

const mapToSupportedRatio = (ratio: AspectRatio, width?: number, height?: number): string => {
  if (ratio === AspectRatio.Custom && width && height) {
    const r = width / height;
    if (r >= 1.5) return "16:9";
    if (r >= 1.2) return "4:3";
    if (r > 0.8) return "1:1";
    if (r > 0.6) return "3:4";
    return "9:16";
  }

  // Gemini API 仅支持: "1:1", "3:4", "4:3", "9:16", "16:9"
  const mapping: Record<string, string> = {
    [AspectRatio.Square]: "1:1",
    [AspectRatio.Ratio_3_2]: "4:3",
    [AspectRatio.Ratio_2_3]: "3:4",
    [AspectRatio.Ratio_4_3]: "4:3",
    [AspectRatio.Ratio_3_4]: "3:4",
    [AspectRatio.Ratio_4_5]: "3:4",
    [AspectRatio.Ratio_5_4]: "4:3",
    [AspectRatio.Ratio_16_9]: "16:9",
    [AspectRatio.Ratio_9_16]: "9:16",
    [AspectRatio.Ratio_16_10]: "16:9",
    [AspectRatio.Ratio_10_16]: "9:16",
    [AspectRatio.Ratio_21_9]: "16:9",
    [AspectRatio.Ratio_9_21]: "9:16",
  };
  return mapping[ratio] || "1:1";
};

export const analyzeAndName = async (prompt: string = "", files: File[], isSmartAnalysis: boolean) => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  const safePrompt = prompt || "";
  try {
    const parts: any[] = [];
    if (files.length > 0) {
      const imageParts = await Promise.all(files.map(fileToPart));
      parts.push(...imageParts);
    }
    const systemInstruction = "你是一个AI绘画专家。分析需求并生成 refinedPrompt (英文) 和 fileName (中文)。回复必须为JSON格式。";
    parts.push({ text: `用户需求: ${safePrompt || "（根据参考图生成）"}` });
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: { parts },
      config: { 
        systemInstruction, 
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            refinedPrompt: { type: Type.STRING },
            fileName: { type: Type.STRING }
          },
          required: ["refinedPrompt", "fileName"]
        }
      }
    });
    return JSON.parse(response.text);
  } catch (e) {
    return { 
      refinedPrompt: safePrompt || "High-end digital art masterpiece, extremely detailed, vibrant colors", 
      fileName: safePrompt.substring(0, 8) || "NanoArt" 
    };
  }
};

export const generateSingleImage = async (
  prompt: string = "",
  inputFiles: (File | Blob)[],
  aspectRatio: AspectRatio,
  imageSize: ImageSize,
  model: AIModel,
  customWidth?: number,
  customHeight?: number
): Promise<string[]> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  const parts: any[] = [];

  if (inputFiles.length > 0) {
    const imageParts = await Promise.all(inputFiles.map(fileToPart));
    parts.push(...imageParts);
  }

  let finalPrompt = (prompt || "").trim();
  parts.push({ text: finalPrompt || "Highly detailed masterpiece, cinematic lighting, professional composition" });

  const config: any = {
    imageConfig: {
      aspectRatio: mapToSupportedRatio(aspectRatio, customWidth, customHeight),
      imageSize: model === AIModel.Pro ? imageSize : undefined
    }
  };

  const response = await ai.models.generateContent({
    model: model,
    contents: { parts },
    config
  });

  const urls: string[] = [];
  if (response.candidates?.[0]?.content?.parts) {
    for (const part of response.candidates[0].content.parts) {
      if (part.inlineData?.data) {
        urls.push(`data:${part.inlineData.mimeType || 'image/png'};base64,${part.inlineData.data}`);
      }
    }
  }
  return urls;
};

