            {[ImageSize.Size_1K, ImageSize.Size_2K, ImageSize.Size_4K].map(s => (
              <button
                key={s}
                disabled={disabled || model === AIModel.Standard}
                onClick={() => onImageSizeChange(s)}
                className={`py-2 rounded-xl border text-[10px] font-bold transition-all ${
                  imageSize === s && model === AIModel.Pro ? 'bg-slate-800 dark:bg-white/10 border-slate-900 dark:border-white/30 text-white shadow-md' : 'bg-white dark:bg-slate-900/50 border-slate-200 dark:border-slate-800 text-slate-500'
                } ${model === AIModel.Standard ? 'opacity-30 cursor-not-allowed' : ''}`}
              >
                {s}
              </button>
            ))}
          </div>
        </div>
      </div>
    </div>
  );
};

