import React, { useState, useEffect, useCallback, useRef } from 'react';
import { Sparkles, Download, Loader2, Image as ImageIcon, Check, Activity, Sun, Moon } from 'lucide-react';
import { generateSingleImage, analyzeAndName } from './services/geminiService';
