            onImageSizeChange={setImageSize}
            onBatchSizeChange={setBatchSize}
            onModelChange={setModel}
            onSmartAnalysisChange={setIsSmartAnalysis}
            onCustomPixelsChange={(w, h) => { setCustomWidth(w); setCustomHeight(h); }}
            disabled={isGenerating}
          />
        </div>

        {error && (
          <div className="text-red-600 dark:text-red-400 text-[11px] font-bold bg-red-50 dark:bg-red-400/5 p-4 rounded-3xl border border-red-200 dark:border-red-400/20 animate-in fade-in slide-in-from-top-2">
            ⚠️ {error}
