          >
            {isGenerating ? <Loader2 className="animate-spin" size={24} /> : <Sparkles size={24} className="group-hover:rotate-45 transition-transform duration-500" />}
            <span>{isGenerating ? `正在构建场景 ${Math.round(progress)}%` : `立即生成图像 (${batchSize}张)`}</span>
            <div className="absolute inset-0 bg-white/10 translate-y-full group-hover:translate-y-0 transition-transform duration-300" />
