                  <img src={img.url} className="w-full h-full object-cover transition-transform duration-1000 group-hover:scale-110" loading="lazy" />
                  <div className="absolute inset-0 bg-gradient-to-t from-slate-950/90 via-slate-900/10 to-transparent opacity-60 dark:opacity-50" />
                </div>

                <div className="absolute top-8 left-8 flex gap-3">
                  <span className="px-5 py-2 bg-white/60 dark:bg-black/40 backdrop-blur-2xl rounded-full text-[10px] font-black text-slate-900 dark:text-banana-400 border border-white/30 dark:border-white/10 shadow-2xl uppercase tracking-widest">{img.filename}</span>
                </div>

                <div className="absolute inset-x-0 bottom-0 p-10 transform translate-y-6 group-hover:translate-y-0 transition-all duration-700 opacity-0 group-hover:opacity-100">
                   <p className="text-[11px] text-white dark:text-slate-300 line-clamp-2 mb-8 leading-relaxed font-bold italic tracking-wide">"{img.prompt || '基于视觉引擎的无缝构建'}"</p>
                   <div className="flex gap-4">
                      <button className="flex-1 py-4 bg-white/20 hover:bg-white/30 backdrop-blur-2xl rounded-[2rem] text-[10px] font-black text-white border border-white/20 transition-all shadow-xl">详细参数</button>
                      <a 
                        href={img.url} 
                        download={`${img.filename}.png`} 
                        className="p-4 bg-banana-500 hover:bg-banana-400 text-slate-950 rounded-[2rem] shadow-2xl shadow-banana-500/40 transition-all hover:scale-110 active:scale-95" 
                        onClick={e => e.stopPropagation()}
                      >
                        <Download size={24} />
                      </a>
                   </div>
                </div>
              </div>
            ))}

            {generatedImages.length === 0 && !isGenerating && (
                <div className="col-span-full py-48 flex flex-col items-center justify-center text-slate-400 dark:text-slate-800 bg-slate-50 dark:bg-slate-900/10 border-4 border-dashed border-slate-200 dark:border-slate-800/40 rounded-[6rem] transition-all">
                    <div className="w-32 h-32 bg-slate-200/50 dark:bg-slate-800/30 rounded-full flex items-center justify-center mb-10 animate-bounce transition-all">
                      <Sparkles size={56} className="opacity-20 text-banana-600 dark:text-banana-400" />
                    </div>
                    <p className="text-2xl font-black text-slate-400 dark:text-slate-500 tracking-tighter">创意引擎就绪，等待您的第一次捕捉</p>
                    <p className="text-[10px] text-slate-400 dark:text-slate-600 mt-6 uppercase tracking-[0.6em] font-black opacity-60">Unlock your imagination with Nano Banana</p>
                </div>
            )}
          </div>
        </div>
      </div>

      {selectedImage && <ImageViewer image={selectedImage} isCopied={!!copyStatus[selectedImage.id]} onCopy={() => handleCopyPrompt(selectedImage.prompt, selectedImage.id)} onClose={() => setSelectedImage(null)} />}
    </div>
  );
};

