    try {
      const { refinedPrompt, fileName } = await analyzeAndName(safePrompt, inputImages, isSmartAnalysis);
      const batchId = Date.now().toString();
      const currentBatchImages: GeneratedImage[] = [];

      for (let i = 0; i < batchSize; i++) {
        const batchProgressBase = (i / batchSize) * 100;
        const batchWeight = 100 / batchSize;

        const currentSteps: GenerationStep[] = [
          { id: 'prep', name: `任务 ${i+1}/${batchSize}：语义解析`, status: 'active', duration: null },
          { id: 'render', name: '纳米引擎渲染', status: 'pending', duration: null },
          { id: 'post', name: '画质归档', status: 'pending', duration: null },
        ];
        setSteps(currentSteps);

        const stepStart = performance.now();
        setProgress(batchProgressBase + (batchWeight * 0.2));

        setSteps(s => s.map(x => x.id === 'prep' ? {...x, status: 'done'} : x.id === 'render' ? {...x, status: 'active'} : x));
        const urls = await generateSingleImage(refinedPrompt, inputImages, aspectRatio, imageSize, model, customWidth, customHeight);

        setProgress(batchProgressBase + (batchWeight * 0.8));
        setSteps(s => s.map(x => x.id === 'render' ? {...x, status: 'done'} : x.id === 'post' ? {...x, status: 'active'} : x));

        const totalTimeForOne = (performance.now() - stepStart) / 1000;
        currentBatchImages.push({
          id: `${batchId}-${i}`,
          batchId,
          url: urls[0],
          prompt: safePrompt,
          refinedPrompt: isSmartAnalysis ? refinedPrompt : undefined,
          filename: batchSize > 1 ? `${fileName}-${i + 1}` : fileName,
          timestamp: Date.now(),
          totalDuration: totalTimeForOne,
          thoughtLog: currentSteps.map(s => ({...s, status: 'done'}))
        });
      }

      setBatches(prev => [{ id: batchId, images: currentBatchImages, timestamp: Date.now() }, ...prev]);
      setSteps(s => s.map(x => ({...x, status: 'done'})));
      setProgress(100);

    } catch (err: any) {
      setError(err.message || "生成失败，请确认您的网络连接或稍后再试。");
    } finally {
      clearInterval(timer);
      setIsGenerating(false);
    }
  };

