      await navigator.clipboard.writeText(text);
      setCopyStatus({ ...copyStatus, [id]: true });
      setTimeout(() => setCopyStatus(prev => ({ ...prev, [id]: false })), 2000);
    } catch (e) { console.error(e); }
  };

  return (
    <div className="min-h-screen bg-white dark:bg-slate-950 text-slate-900 dark:text-slate-100 flex flex-col lg:flex-row font-sans transition-colors duration-500 overflow-hidden">

      {/* Sidebar - Remains sharp */}
      <div className="w-full lg:w-[420px] p-8 flex flex-col gap-8 border-b lg:border-r border-slate-200 dark:border-slate-800/50 bg-white/90 dark:bg-[#0d1117]/95 backdrop-blur-3xl z-40 lg:h-screen overflow-y-auto no-scrollbar shadow-2xl">
        <div className="flex items-center justify-between">
          <div className="flex items-center gap-4">
