        <div className="mt-auto pt-6 flex flex-col gap-6">
          <button
            onClick={handleGenerate}
            disabled={isGenerating}
            className="w-full py-6 bg-gradient-to-br from-banana-400 to-banana-600 hover:from-banana-300 hover:to-banana-500 text-slate-950 font-black text-xl rounded-[2.5rem] shadow-2xl shadow-banana-500/30 transition-all flex items-center justify-center gap-4 disabled:opacity-40 active:scale-95 group relative overflow-hidden"
          >
            {isGenerating ? <Loader2 className="animate-spin" size={24} /> : <Sparkles size={24} className="group-hover:rotate-45 transition-transform duration-500" />}
            <span>{isGenerating ? `正在构建场景 ${Math.round(progress)}%` : `立即生成图像`}</span>
          </button>

          {isGenerating && (
            <div className="space-y-4 p-6 bg-white dark:bg-slate-900/40 rounded-[2.5rem] border border-slate-200 dark:border-slate-700/30 shadow-xl transition-all">
               <div className="flex justify-between text-[11px] font-mono text-slate-500 dark:text-slate-400">
                  <span className="flex items-center gap-2 tracking-tighter"><Activity size={14} className="text-banana-600 dark:text-banana-400 animate-pulse" /> AI 核心运算中...</span>
                  <span className="font-bold">{elapsedTime.toFixed(1)}s</span>
               </div>
               <div className="space-y-2.5">
                 {steps.map(s => (
                   <div key={s.id} className="flex items-center justify-between text-[11px]">
                     <span className={s.status === 'active' ? 'text-banana-600 dark:text-banana-300 font-black' : s.status === 'done' ? 'text-slate-400 dark:text-slate-500' : 'text-slate-300 dark:text-slate-700'}>{s.name}</span>
                     {s.status === 'active' ? <Loader2 size={12} className="animate-spin text-banana-600" /> : s.status === 'done' ? <Check size={12} className="text-green-600" /> : <div className="w-1 h-1 rounded-full bg-slate-300" />}
                   </div>
                 ))}
               </div>
            </div>
          )}
        </div>
      </div>

      {/* Main Gallery Area */}
      <div className={`flex-1 p-8 lg:p-12 overflow-y-auto lg:h-screen scroll-smooth transition-all duration-700 ${expandedBatchId || selectedImage ? 'blur-md grayscale-[0.2] brightness-50 pointer-events-none' : ''}`}>
        <div className="max-w-7xl mx-auto">
          <div className="flex items-end justify-between mb-16">
            <div>
              <h2 className="text-3xl font-black text-slate-900 dark:text-white tracking-tighter flex items-center gap-4">
                <div className="p-3 bg-banana-500/10 rounded-2xl"><ImageIcon className="text-banana-500" size={32} /></div>
                画廊
              </h2>
              <p className="text-sm text-slate-400 dark:text-slate-500 mt-2 uppercase tracking-[0.25em] font-medium opacity-60">Gallery Archive</p>
            </div>
            <div className="hidden md:flex items-center gap-10">
               <div className="text-center group">
                  <div className="text-3xl font-black text-slate-900 dark:text-white group-hover:text-banana-500 transition-colors">{batches.reduce((acc, b) => acc + b.images.length, 0)}</div>
                  <div className="text-[10px] text-slate-400 dark:text-slate-500 font-black uppercase tracking-widest mt-1">总计作品</div>
               </div>
            </div>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-16">
            {batches.map((batch, idx) => (
