export default App;

import React, { useState, useEffect } from 'react';
import { X, Download, ZoomIn, ZoomOut, RotateCcw, Copy, Check, Tag, BrainCircuit, Timer, ChevronLeft, ChevronRight } from 'lucide-react';
import { GeneratedImage } from '../types';

interface ImageViewerProps {
  image: GeneratedImage;
  isCopied: boolean;
  onClose: () => void;
  onCopy: () => void;
  onNext: () => void;
  onPrev: () => void;
}

const ImageViewer: React.FC<ImageViewerProps> = ({ image, isCopied, onClose, onCopy, onNext, onPrev }) => {
  const [scale, setScale] = useState(1);
  const [position, setPosition] = useState({ x: 0, y: 0 });
  const [isDragging, setIsDragging] = useState(false);
  const [dragStart, setDragStart] = useState({ x: 0, y: 0 });
  const [showThinking, setShowThinking] = useState(false);

  useEffect(() => {
    document.body.style.overflow = 'hidden';
    return () => { document.body.style.overflow = 'unset'; };
  }, []);

  const handleWheel = (e: React.WheelEvent) => {
    e.stopPropagation();
    const delta = -e.deltaY * 0.001;
    setScale(prev => Math.min(Math.max(0.5, prev + delta), 8));
  };

  const handleMouseDown = (e: React.MouseEvent) => {
    if (scale > 1) {
      setIsDragging(true);
      setDragStart({ x: e.clientX - position.x, y: e.clientY - position.y });
    }
  };

  const handleMouseMove = (e: React.MouseEvent) => {
    if (isDragging && scale > 1) {
      setPosition({ x: e.clientX - dragStart.x, y: e.clientY - dragStart.y });
    }
  };

  return (
    <div className="fixed inset-0 z-[100] flex items-center justify-center bg-[#0a0c10]/98 backdrop-blur-3xl animate-in fade-in duration-300" onClick={onClose}>
      {/* Top Bar Controls */}
      <div className="absolute top-0 left-0 right-0 p-8 flex justify-between items-center z-[110] pointer-events-none">
        <div className="flex items-center gap-4 pointer-events-auto">
             <div className="bg-slate-900/60 backdrop-blur rounded-[2rem] border border-white/5 p-2 flex gap-1 shadow-2xl">
                <button onClick={(e) => { e.stopPropagation(); setScale(Math.min(scale + 0.5, 8)); }} className="p-3 hover:bg-white/5 rounded-2xl text-slate-200 transition-colors"><ZoomIn size={20} /></button>
                <button onClick={(e) => { e.stopPropagation(); setScale(Math.max(0.5, scale - 0.5)); }} className="p-3 hover:bg-white/5 rounded-2xl text-slate-200 transition-colors"><ZoomOut size={20} /></button>
                <button onClick={(e) => { e.stopPropagation(); setScale(1); setPosition({x:0,y:0}); }} className="p-3 hover:bg-white/5 rounded-2xl text-slate-200 transition-colors"><RotateCcw size={20} /></button>
             </div>
             <button 
                onClick={(e) => { e.stopPropagation(); setShowThinking(!showThinking); }}
                className={`flex items-center gap-2 text-[10px] font-black uppercase px-6 py-3 rounded-full border transition-all ${showThinking ? 'bg-banana-500 text-slate-950 border-banana-500 shadow-xl' : 'bg-white/5 text-slate-300 border-white/10 hover:bg-white/10'}`}
             >
                <BrainCircuit size={14} /> 纳米溯源
             </button>
        </div>

        <div className="flex gap-4 pointer-events-auto">
          <button onClick={(e) => { e.stopPropagation(); onCopy(); }} className={`px-6 py-4 rounded-3xl transition-all shadow-2xl flex items-center gap-2 ${isCopied ? 'bg-green-500 text-white shadow-green-500/20' : 'bg-slate-800/80 hover:bg-slate-700 text-white border border-white/5'}`}>
            {isCopied ? <Check size={20} /> : <Copy size={20} />}
            <span className="text-xs font-black uppercase tracking-widest">{isCopied ? '咒语已存' : '复制咒语'}</span>
          </button>
          <a href={image.url} download={`${image.filename}.png`} onClick={(e) => e.stopPropagation()} className="p-4 bg-banana-500 hover:bg-banana-400 text-slate-950 rounded-3xl transition-all shadow-2xl shadow-banana-500/30">
            <Download size={24} />
          </a>
          <button onClick={onClose} className="p-4 bg-slate-900/80 hover:bg-red-500/20 text-white hover:text-red-400 rounded-3xl transition-all border border-white/5">
            <X size={24} />
          </button>
        </div>
      </div>

      {/* Navigation Controls */}
      <div className="absolute inset-x-8 top-1/2 -translate-y-1/2 flex justify-between pointer-events-none z-[105]">
          <button 
            onClick={(e) => { e.stopPropagation(); onPrev(); }}
            className="p-6 bg-white/5 hover:bg-white/10 backdrop-blur-xl rounded-full text-white border border-white/10 transition-all pointer-events-auto shadow-2xl group"
          >
            <ChevronLeft size={32} className="group-hover:-translate-x-1 transition-transform" />
          </button>
          <button 
            onClick={(e) => { e.stopPropagation(); onNext(); }}
            className="p-6 bg-white/5 hover:bg-white/10 backdrop-blur-xl rounded-full text-white border border-white/10 transition-all pointer-events-auto shadow-2xl group"
          >
            <ChevronRight size={32} className="group-hover:translate-x-1 transition-transform" />
          </button>
      </div>

      <div className="w-full h-full flex items-center justify-center overflow-hidden" onWheel={handleWheel} onMouseDown={handleMouseDown} onMouseMove={handleMouseMove} onMouseUp={() => setIsDragging(false)} onMouseLeave={() => setIsDragging(false)} onClick={(e) => e.stopPropagation()}>
        <img 
            src={image.url} 
            alt={image.prompt} 
            className="max-w-[90%] max-h-[90%] object-contain transition-transform duration-100 ease-out select-none shadow-[0_0_120px_rgba(0,0,0,0.8)] rounded-3xl" 
            style={{ transform: `translate(${position.x}px, ${position.y}px) scale(${scale})`, cursor: scale > 1 ? (isDragging ? 'grabbing' : 'grab') : 'default' }} 
            draggable={false} 
        />
      </div>

      {showThinking && (
          <div className="absolute top-32 left-8 w-80 bg-slate-950/90 backdrop-blur-3xl border border-white/10 rounded-[2.5rem] p-10 shadow-[0_40px_100px_rgba(0,0,0,0.8)] animate-in slide-in-from-left-4 duration-500 pointer-events-auto" onClick={(e) => e.stopPropagation()}>
              <div className="flex items-center justify-between mb-8 pb-4 border-b border-white/10">
                  <div className="flex items-center gap-2 text-banana-400 font-black text-xs uppercase tracking-widest">
                      <BrainCircuit size={18} /> 构建逻辑
                  </div>
                  <div className="text-[10px] font-mono text-slate-500 flex items-center gap-2">
                      <Timer size={14} /> {image.totalDuration.toFixed(2)}s
                  </div>
              </div>
              <div className="space-y-8">
                  {image.thoughtLog.map((step, idx) => (
                      <div key={idx} className="flex flex-col gap-3 group">
                          <div className="flex items-center justify-between">
                              <div className="flex items-center gap-4">
                                  <div className={`w-2.5 h-2.5 rounded-full ${step.status === 'done' ? 'bg-banana-400 shadow-[0_0_12px_rgba(234,179,8,0.6)]' : 'bg-slate-700'}`} />
                                  <span className="text-xs font-bold text-slate-200">{step.name}</span>
                              </div>
                          </div>
                          <div className="h-1.5 w-full bg-slate-800 rounded-full overflow-hidden">
                              <div className="h-full bg-banana-500 transition-all duration-1000" style={{ width: step.status === 'done' ? '100%' : '10%' }} />
                          </div>
                      </div>
                  ))}
                  {image.refinedPrompt && (
                    <div className="pt-6 border-t border-white/5">
                        <p className="text-[9px] text-slate-500 leading-relaxed font-bold uppercase tracking-widest mb-2">Refined Intent:</p>
                        <p className="text-[10px] text-slate-400 leading-relaxed font-medium italic">
                            "{image.refinedPrompt}"
                        </p>
                    </div>
                  )}
              </div>
          </div>
      )}

      {/* Info Overlay */}
      <div className="absolute bottom-12 left-0 right-0 text-center pointer-events-none px-8">
        <div className="max-w-4xl mx-auto px-12 py-10 bg-black/60 backdrop-blur-3xl border border-white/10 rounded-[4rem] shadow-[0_40px_100px_rgba(0,0,0,0.6)] flex flex-col items-center gap-4 animate-in fade-in slide-in-from-bottom-8 duration-700 delay-200">
            <div className="flex items-center gap-3 text-banana-400 font-black uppercase text-xs tracking-[0.3em]">
                <Tag size={18} /> <span>{image.filename}</span>
            </div>
            <p className="text-white text-base leading-relaxed font-bold line-clamp-2 max-w-2xl italic">
            "{image.prompt || '纳米视觉重组模式生成'}"
            </p>
            <p className="text-[9px] text-slate-500 uppercase font-black tracking-[0.4em] mt-2">← 左移 | 右移 →  | ESC 退出</p>
        </div>
      </div>
    </div>
  );
};

export default ImageViewer;

import React, { useState, useEffect, useCallback, useRef } from 'react';
import { Sparkles, Download, Loader2, Image as ImageIcon, Check, Activity, Sun, Moon, Layers, X, ChevronLeft, ChevronRight } from 'lucide-react';
import { generateSingleImage, analyzeAndName } from './services/geminiService';
import SettingsPanel from './components/SettingsPanel';
import ImageUploader from './components/ImageUploader';
import ImageViewer from './components/ImageViewer';
import { AspectRatio, ImageSize, GeneratedImage, AIModel, GenerationStep, GeneratedBatch } from './types';

const App: React.FC = () => {
  const [prompt, setPrompt] = useState('');
  const [inputImages, setInputImages] = useState<File[]>([]);
  const [aspectRatio, setAspectRatio] = useState<AspectRatio>(AspectRatio.Square);
  const [imageSize, setImageSize] = useState<ImageSize>(ImageSize.Size_1K);
  const [batchSize, setBatchSize] = useState<number>(1);
  const [model, setModel] = useState<AIModel>(AIModel.Pro);
  const [isSmartAnalysis, setIsSmartAnalysis] = useState<boolean>(true);
  const [customWidth, setCustomWidth] = useState(1024);
  const [customHeight, setCustomHeight] = useState(1024);
  const [isDarkMode, setIsDarkMode] = useState(true);

  const [isGenerating, setIsGenerating] = useState(false);
  const [progress, setProgress] = useState(0);
  const [elapsedTime, setElapsedTime] = useState(0);
  const [steps, setSteps] = useState<GenerationStep[]>([]);
  const [batches, setBatches] = useState<GeneratedBatch[]>([]);
  const [selectedImage, setSelectedImage] = useState<GeneratedImage | null>(null);
  const [expandedBatchId, setExpandedBatchId] = useState<string | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [copyStatus, setCopyStatus] = useState<Record<string, boolean>>({});

  const startTimeRef = useRef<number>(0);

  // 同步明暗模式
  useEffect(() => {
    if (isDarkMode) document.documentElement.classList.add('dark');
    else document.documentElement.classList.remove('dark');
  }, [isDarkMode]);

  // 全局快捷键处理
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      // Ctrl + Enter 触发生成
      if (e.ctrlKey && e.key === 'Enter') {
        if (!isGenerating) handleGenerate();
      }

      // 详情查看时的导航
      if (selectedImage) {
        if (e.key === 'ArrowLeft') navigateImage(-1);
        if (e.key === 'ArrowRight') navigateImage(1);
        if (e.key === 'Escape') setSelectedImage(null);
      } else if (expandedBatchId) {
        if (e.key === 'Escape') setExpandedBatchId(null);
      }
    };

    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [isGenerating, selectedImage, expandedBatchId, batches, prompt, inputImages]);

  const navigateImage = (direction: number) => {
    const allImages = batches.flatMap(b => b.images);
    if (allImages.length === 0 || !selectedImage) return;

    const currentIndex = allImages.findIndex(img => img.id === selectedImage.id);
    let nextIndex = currentIndex + direction;

    if (nextIndex < 0) nextIndex = allImages.length - 1;
    if (nextIndex >= allImages.length) nextIndex = 0;

    setSelectedImage(allImages[nextIndex]);
  };

  const handleGenerate = async () => {
    const safePrompt = (prompt || "").trim();
    if (!safePrompt && inputImages.length === 0) return setError("请至少输入一段描述文字或上传一张参考图片。");

    setIsGenerating(true);
    setError(null);
    setProgress(0);
    startTimeRef.current = performance.now();

    const timer = setInterval(() => setElapsedTime((performance.now() - startTimeRef.current) / 1000), 100);

    try {
      const batchId = Date.now().toString();
      const currentBatchImages: GeneratedImage[] = [];

      // 依次、独立生成每一张图片
      for (let i = 0; i < batchSize; i++) {
        const batchProgressBase = (i / batchSize) * 100;
        const batchWeight = 100 / batchSize;

        const currentSteps: GenerationStep[] = [
          { id: 'prep', name: `第 ${i+1} 张：解析与意图捕捉`, status: 'active', duration: null },
          { id: 'render', name: 'Nano 独立引擎渲染', status: 'pending', duration: null },
          { id: 'post', name: '数据归档', status: 'pending', duration: null },
        ];
        setSteps(currentSteps);

        // 每一张都进行独立的语义增强分析，确保图像的独立性与多样性
        const { refinedPrompt, fileName } = await analyzeAndName(safePrompt, inputImages, isSmartAnalysis);

        setProgress(batchProgressBase + (batchWeight * 0.2));
        setSteps(s => s.map(x => x.id === 'prep' ? {...x, status: 'done'} : x.id === 'render' ? {...x, status: 'active'} : x));

        const stepStart = performance.now();
        const urls = await generateSingleImage(refinedPrompt, inputImages, aspectRatio, imageSize, model, customWidth, customHeight);

        setProgress(batchProgressBase + (batchWeight * 0.8));
        setSteps(s => s.map(x => x.id === 'render' ? {...x, status: 'done'} : x.id === 'post' ? {...x, status: 'active'} : x));

        const totalTimeForOne = (performance.now() - stepStart) / 1000;
        currentBatchImages.push({
          id: `${batchId}-${i}`,
          batchId,
          url: urls[0],
          prompt: safePrompt,
          refinedPrompt: isSmartAnalysis ? refinedPrompt : undefined,
          filename: batchSize > 1 ? `${fileName}-${i + 1}` : fileName,
          timestamp: Date.now(),
          totalDuration: totalTimeForOne,
          thoughtLog: currentSteps.map(s => ({...s, status: 'done'}))
        });
      }

      setBatches(prev => [{ id: batchId, images: currentBatchImages, timestamp: Date.now() }, ...prev]);
      setSteps(s => s.map(x => ({...x, status: 'done'})));
      setProgress(100);

    } catch (err: any) {
      setError(err.message || "引擎任务中断，请尝试减少批量数量或刷新页面。");
    } finally {
      clearInterval(timer);
      setIsGenerating(false);
    }
  };

  const handleCopyPrompt = async (text: string, id: string) => {
    try {
      await navigator.clipboard.writeText(text);
      setCopyStatus({ ...copyStatus, [id]: true });
      setTimeout(() => setCopyStatus(prev => ({ ...prev, [id]: false })), 2000);
    } catch (e) { console.error(e); }
  };

  return (
    <div className="min-h-screen bg-white dark:bg-slate-950 text-slate-900 dark:text-slate-100 flex flex-col lg:flex-row font-sans transition-colors duration-500 overflow-hidden">

      {/* 操作区域：始终保持清晰，不受虚化影响 */}
      <div className="w-full lg:w-[440px] p-8 flex flex-col gap-8 border-b lg:border-r border-slate-200 dark:border-slate-800/50 bg-white/95 dark:bg-[#0d1117]/98 backdrop-blur-3xl z-40 lg:h-screen overflow-y-auto no-scrollbar shadow-2xl transition-all duration-300">
        <div className="flex items-center justify-between">
          <div className="flex items-center gap-4">
            <div className="w-14 h-14 bg-banana-500 rounded-3xl flex items-center justify-center text-slate-900 shadow-xl shadow-banana-500/30 rotate-6 transition-transform hover:rotate-0 duration-500">
              <Sparkles size={32} />
            </div>
            <div>
              <h1 className="font-black text-2xl tracking-tight leading-none text-slate-900 dark:text-white">NANO LAB <span className="text-banana-600 dark:text-banana-400">V2.0</span></h1>
              <p className="text-[10px] text-slate-500 mt-2 font-bold uppercase tracking-[0.2em] opacity-60">Visual Creation Engine</p>
            </div>
          </div>
          <button 
            onClick={() => setIsDarkMode(!isDarkMode)}
            className="p-3.5 rounded-2xl bg-slate-100 dark:bg-slate-800 text-slate-600 dark:text-slate-400 hover:bg-banana-500 hover:text-slate-950 transition-all shadow-sm"
          >
            {isDarkMode ? <Sun size={20} /> : <Moon size={20} />}
          </button>
        </div>

        <div className="space-y-6">
          <div className="relative group">
            <textarea
              value={prompt}
              onChange={(e) => setPrompt(e.target.value)}
              placeholder="在此输入您的灵感，Ctrl + Enter 立即生成..."
              className="w-full h-44 bg-slate-50 dark:bg-slate-800/40 border border-slate-200 dark:border-slate-700/50 rounded-[2.5rem] p-7 text-sm focus:border-banana-500 focus:ring-4 focus:ring-banana-500/10 outline-none transition-all placeholder:text-slate-400 dark:placeholder:text-slate-600 resize-none shadow-inner"
            />
          </div>

          <ImageUploader files={inputImages} onFilesChange={setInputImages} disabled={isGenerating} />

          <SettingsPanel 
            {...{aspectRatio, imageSize, batchSize, model, isSmartAnalysis, customWidth, customHeight}}
            onAspectRatioChange={setAspectRatio}
            onImageSizeChange={setImageSize}
            onBatchSizeChange={setBatchSize}
            onModelChange={setModel}
            onSmartAnalysisChange={setIsSmartAnalysis}
            onCustomPixelsChange={(w, h) => { setCustomWidth(w); setCustomHeight(h); }}
            disabled={isGenerating}
          />
        </div>

        {error && (
          <div className="text-red-600 dark:text-red-400 text-[11px] font-bold bg-red-50 dark:bg-red-400/5 p-5 rounded-3xl border border-red-200 dark:border-red-400/20">
            ⚠️ {error}
          </div>
        )}

        <div className="mt-auto pt-6 flex flex-col gap-6">
          <button
            onClick={handleGenerate}
            disabled={isGenerating}
            className="w-full py-7 bg-gradient-to-br from-banana-400 to-banana-600 hover:from-banana-300 hover:to-banana-500 text-slate-950 font-black text-xl rounded-[2.8rem] shadow-2xl shadow-banana-500/30 transition-all flex items-center justify-center gap-5 disabled:opacity-40 active:scale-95 group relative overflow-hidden"
          >
            {isGenerating ? <Loader2 className="animate-spin" size={28} /> : <Sparkles size={28} className="group-hover:rotate-45 transition-transform duration-700" />}
            <span className="tracking-tight">{isGenerating ? `任务执行中 ${Math.round(progress)}%` : `立即开启艺术渲染`}</span>
          </button>

          {isGenerating && (
            <div className="space-y-5 p-7 bg-white dark:bg-slate-900/50 rounded-[2.8rem] border border-slate-200 dark:border-slate-700/30 shadow-2xl transition-all scale-in">
               <div className="flex justify-between text-[11px] font-mono text-slate-500 dark:text-slate-400">
                  <span className="flex items-center gap-2"><Activity size={14} className="text-banana-600 dark:text-banana-400 animate-pulse" /> GPU 流水线运行中</span>
                  <span className="font-bold">{elapsedTime.toFixed(1)}s</span>
               </div>
               <div className="space-y-3">
                 {steps.map(s => (
                   <div key={s.id} className="flex items-center justify-between text-[11px]">
                     <span className={s.status === 'active' ? 'text-banana-600 dark:text-banana-300 font-black' : s.status === 'done' ? 'text-slate-400 dark:text-slate-500' : 'text-slate-300 dark:text-slate-700'}>{s.name}</span>
                     {s.status === 'active' ? <Loader2 size={14} className="animate-spin text-banana-600" /> : s.status === 'done' ? <Check size={14} className="text-green-600" /> : <div className="w-1.5 h-1.5 rounded-full bg-slate-300 dark:bg-slate-700" />}
                   </div>
                 ))}
               </div>
            </div>
          )}
        </div>
      </div>

      {/* 画廊展示区域：在展开合集或详情时会虚化 */}
      <div className={`flex-1 p-8 lg:p-14 overflow-y-auto lg:h-screen scroll-smooth transition-all duration-1000 ${expandedBatchId || selectedImage ? 'blur-xl grayscale-[0.3] brightness-50 pointer-events-none scale-[1.02]' : ''}`}>
        <div className="max-w-7xl mx-auto">
          <div className="flex items-end justify-between mb-20">
            <div>
              <h2 className="text-4xl font-black text-slate-900 dark:text-white tracking-tighter flex items-center gap-5">
                <div className="p-4 bg-banana-500/10 rounded-[2rem]"><ImageIcon className="text-banana-500" size={36} /></div>
                画廊
              </h2>
              <p className="text-sm text-slate-400 dark:text-slate-500 mt-3 uppercase tracking-[0.3em] font-bold opacity-50">Global Creative Gallery</p>
            </div>
            <div className="hidden md:flex items-center gap-12">
               <div className="text-center group">
                  <div className="text-4xl font-black text-slate-900 dark:text-white group-hover:text-banana-500 transition-colors duration-500">{batches.reduce((acc, b) => acc + b.images.length, 0)}</div>
                  <div className="text-[11px] text-slate-400 dark:text-slate-500 font-black uppercase tracking-[0.2em] mt-2">Captured Visuals</div>
               </div>
            </div>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-20">
            {batches.map((batch) => (
              <div 
                key={batch.id} 
                className="group relative cursor-pointer"
                onClick={() => setExpandedBatchId(batch.id)}
              >
                {/* 堆叠画框 UI */}
                <div className="aspect-[4/5] relative preserve-3d">
                   {batch.images.slice(0, 3).map((img, i) => (
                      <div 
                        key={img.id}
                        className={`absolute inset-0 bg-white dark:bg-slate-900 rounded-[3.5rem] overflow-hidden border border-slate-200 dark:border-slate-800/50 shadow-[0_30px_60px_-15px_rgba(0,0,0,0.3)] dark:shadow-[0_30px_60px_-15px_rgba(0,0,0,0.6)] transition-all duration-700 ease-out transform
                          ${i === 0 ? 'z-30 group-hover:rotate-1 group-hover:-translate-y-4' : ''}
                          ${i === 1 ? 'z-20 translate-x-4 translate-y-4 rotate-3 group-hover:translate-x-8 group-hover:translate-y-8 group-hover:rotate-6 opacity-80' : ''}
                          ${i === 2 ? 'z-10 translate-x-8 translate-y-8 rotate-6 group-hover:translate-x-16 group-hover:translate-y-16 group-hover:rotate-12 opacity-50' : ''}
                        `}
                      >
                         <img src={img.url} className="w-full h-full object-cover transition-transform duration-1000 group-hover:scale-110" loading="lazy" />
                         {i === 0 && (
                           <div className="absolute top-10 left-10 flex gap-4">
                              <span className="px-6 py-2.5 bg-white/60 dark:bg-black/40 backdrop-blur-3xl rounded-full text-[10px] font-black text-slate-900 dark:text-banana-400 border border-white/30 dark:border-white/10 shadow-2xl uppercase tracking-[0.15em]">
                                {batch.images.length > 1 ? <><Layers size={12} className="inline-block mr-2" /> 集合: {batch.images.length}P</> : batch.images[0].filename}
                              </span>
                           </div>
                         )}
                      </div>
                   ))}
                </div>

                <div className="mt-10 text-center opacity-0 group-hover:opacity-60 transition-all duration-500 translate-y-4 group-hover:translate-y-0">
                   <p className="text-[11px] text-slate-500 dark:text-slate-400 font-black uppercase tracking-[0.4em]">Tap to expand collection</p>
                </div>
              </div>
            ))}

            {batches.length === 0 && !isGenerating && (
                <div className="col-span-full py-56 flex flex-col items-center justify-center text-slate-400 dark:text-slate-800 bg-slate-50 dark:bg-slate-900/10 border-4 border-dashed border-slate-200 dark:border-slate-800/40 rounded-[7rem] transition-all">
                    <div className="w-40 h-40 bg-slate-100 dark:bg-slate-800/40 rounded-full flex items-center justify-center mb-12 animate-pulse shadow-inner">
                      <Sparkles size={64} className="opacity-20 text-banana-600 dark:text-banana-400" />
                    </div>
                    <p className="text-2xl font-black text-slate-400 dark:text-slate-500 tracking-tighter">画廊尚无创作记录</p>
                    <p className="text-[11px] text-slate-400 dark:text-slate-600 mt-6 uppercase tracking-[0.6em] font-black opacity-60">Manifest your thoughts now</p>
                </div>
            )}
          </div>
        </div>
      </div>

      {/* 合集展开层：此时背景（画廊）应已虚化 */}
      {expandedBatchId && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-transparent backdrop-blur-none animate-in fade-in duration-700 overflow-hidden">
           <div className="absolute inset-0 bg-black/60 dark:bg-black/80" onClick={() => setExpandedBatchId(null)} />
           <div className="relative w-full h-full flex flex-col items-center justify-center p-12 lg:p-24 overflow-visible">

              <button 
                onClick={() => setExpandedBatchId(null)}
                className="absolute top-16 right-16 p-5 bg-white/10 hover:bg-white/20 backdrop-blur-3xl rounded-full text-white border border-white/20 z-[60] transition-all shadow-2xl hover:rotate-90 duration-500"
              >
                <X size={32} />
              </button>

              <div className="flex flex-wrap items-center justify-center gap-16 lg:gap-24 w-full max-w-[1400px] animate-in zoom-in-[0.8] duration-1000 pointer-events-none">
                 {batches.find(b => b.id === expandedBatchId)?.images.map((img, idx) => (
                    <div 
                      key={img.id}
                      className="w-full max-w-[22rem] aspect-[4/5] bg-slate-900 rounded-[4rem] overflow-hidden border border-white/10 shadow-[0_50px_120px_-20px_rgba(0,0,0,0.8)] animate-float cursor-pointer hover:scale-110 hover:-rotate-2 transition-all duration-700 pointer-events-auto group/item"
                      style={{ 
                        animationDelay: `${idx * 0.3}s`, 
                        transitionDelay: `${idx * 0.08}s`,
                        zIndex: 100 - idx
                      }}
                      onClick={() => { setSelectedImage(img); }}
                    >
                       <img src={img.url} className="w-full h-full object-cover transition-transform duration-1000 group-hover/item:scale-110" />
                       <div className="absolute inset-0 bg-gradient-to-t from-black via-black/20 to-transparent opacity-0 group-hover/item:opacity-100 transition-opacity duration-500 p-10 flex flex-col justify-end">
                          <p className="text-[11px] text-white font-bold mb-6 line-clamp-3 leading-relaxed tracking-wide italic">"{img.prompt}"</p>
                          <button className="w-full py-4 bg-banana-500 hover:bg-banana-400 text-slate-950 rounded-[2rem] font-black text-[11px] uppercase shadow-2xl transition-all">查阅详细细节</button>
                       </div>
                    </div>
                 ))}
              </div>
           </div>
        </div>
      )}

      {selectedImage && (
        <ImageViewer 
          image={selectedImage} 
          isCopied={!!copyStatus[selectedImage.id]} 
          onCopy={() => handleCopyPrompt(selectedImage.prompt, selectedImage.id)} 
          onClose={() => setSelectedImage(null)} 
          onNext={() => navigateImage(1)}
          onPrev={() => navigateImage(-1)}
        />
      )}

      <style>{`
        @keyframes float {
          0%, 100% { transform: translateY(0px) rotate(0deg); }
          50% { transform: translateY(-30px) rotate(1.5deg); }
        }
        .animate-float {
          animation: float 6s ease-in-out infinite;
        }
        .preserve-3d {
          transform-style: preserve-3d;
        }
        .scale-in {
          animation: scaleIn 0.4s cubic-bezier(0.16, 1, 0.3, 1);
        }
        @keyframes scaleIn {
          from { transform: scale(0.95); opacity: 0; }
          to { transform: scale(1); opacity: 1; }
        }
      `}</style>
    </div>
  );
};

export default App;

export enum AspectRatio {
  Square = "1:1",
  Ratio_3_2 = "3:2",
  Ratio_2_3 = "2:3",
  Ratio_4_3 = "4:3",
  Ratio_3_4 = "3:4",
  Ratio_4_5 = "4:5",
  Ratio_5_4 = "5:4",
  Ratio_16_9 = "16:9",
  Ratio_9_16 = "9:16",
  Ratio_16_10 = "16:10",
  Ratio_10_16 = "10:16",
  Ratio_21_9 = "21:9",
  Ratio_9_21 = "9:21",
  Custom = "custom",
}

export enum ImageSize {
  Size_1K = "1K",
  Size_2K = "2K",
  Size_4K = "4K",
}

export enum AIModel {
  Standard = "gemini-2.5-flash-image",
  Pro = "gemini-3-pro-image-preview",
}

export interface GenerationStep {
  id: string;
  name: string;
  duration: number | null;
  status: 'pending' | 'active' | 'done';
}

export interface GeneratedImage {
  id: string;
  batchId: string;
  url: string;
  prompt: string;
  refinedPrompt?: string;
  filename: string;
  timestamp: number;
  totalDuration: number;
  thoughtLog: GenerationStep[];
}

export interface GeneratedBatch {
  id: string;
  images: GeneratedImage[];
  timestamp: number;
  cost: number; // 本次批次的预估费用 (RMB)
}

import React, { useState, useEffect, useCallback, useRef } from 'react';
import { Sparkles, Download, Loader2, Image as ImageIcon, Check, Activity, Sun, Moon, Layers, X, ChevronLeft, ChevronRight, Wallet, Info } from 'lucide-react';
import { generateSingleImage, analyzeAndName } from './services/geminiService';
import SettingsPanel from './components/SettingsPanel';
import ImageUploader from './components/ImageUploader';
import ImageViewer from './components/ImageViewer';
import { AspectRatio, ImageSize, GeneratedImage, AIModel, GenerationStep, GeneratedBatch } from './types';

// 计费标准 (RMB 预估)
// Nano Banana (2.5 Flash): 固定约 0.1 元/张
// Nano Banana Pro (3 Pro): 1K -> 0.25元, 2K -> 0.5元, 4K -> 1.0元
const getEstimatedPrice = (model: AIModel, size: ImageSize): number => {
  if (model === AIModel.Standard) return 0.10;
  switch (size) {
    case ImageSize.Size_2K: return 0.50;
    case ImageSize.Size_4K: return 1.00;
    case ImageSize.Size_1K:
    default: return 0.25;
  }
};

const App: React.FC = () => {
  const [prompt, setPrompt] = useState('');
  const [inputImages, setInputImages] = useState<File[]>([]);
  const [aspectRatio, setAspectRatio] = useState<AspectRatio>(AspectRatio.Square);
  const [imageSize, setImageSize] = useState<ImageSize>(ImageSize.Size_1K);
  const [batchSize, setBatchSize] = useState<number>(1);
  const [model, setModel] = useState<AIModel>(AIModel.Pro);
  const [isSmartAnalysis, setIsSmartAnalysis] = useState<boolean>(true);
  const [customWidth, setCustomWidth] = useState(1024);
  const [customHeight, setCustomHeight] = useState(1024);
  const [isDarkMode, setIsDarkMode] = useState(true);

  const [isGenerating, setIsGenerating] = useState(false);
  const [progress, setProgress] = useState(0);
  const [elapsedTime, setElapsedTime] = useState(0);
  const [steps, setSteps] = useState<GenerationStep[]>([]);
  const [batches, setBatches] = useState<GeneratedBatch[]>([]);
  const [selectedImage, setSelectedImage] = useState<GeneratedImage | null>(null);
  const [expandedBatchId, setExpandedBatchId] = useState<string | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [copyStatus, setCopyStatus] = useState<Record<string, boolean>>({});

  const startTimeRef = useRef<number>(0);

  // 同步明暗模式
  useEffect(() => {
    if (isDarkMode) {
      document.documentElement.classList.add('dark');
    } else {
      document.documentElement.classList.remove('dark');
    }
  }, [isDarkMode]);

  // 全局快捷键处理
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.ctrlKey && e.key === 'Enter') {
        if (!isGenerating) handleGenerate();
      }
      if (selectedImage) {
        if (e.key === 'ArrowLeft') navigateImage(-1);
        if (e.key === 'ArrowRight') navigateImage(1);
        if (e.key === 'Escape') setSelectedImage(null);
      } else if (expandedBatchId) {
        if (e.key === 'Escape') setExpandedBatchId(null);
      }
    };
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [isGenerating, selectedImage, expandedBatchId, batches, prompt, inputImages]);

  const navigateImage = (direction: number) => {
    const allImages = batches.flatMap(b => b.images);
    if (allImages.length === 0 || !selectedImage) return;
    const currentIndex = allImages.findIndex(img => img.id === selectedImage.id);
    let nextIndex = currentIndex + direction;
    if (nextIndex < 0) nextIndex = allImages.length - 1;
    if (nextIndex >= allImages.length) nextIndex = 0;
    setSelectedImage(allImages[nextIndex]);
  };

  const handleGenerate = async () => {
    const safePrompt = (prompt || "").trim();
    if (!safePrompt && inputImages.length === 0) return setError("请至少输入一段描述文字或上传一张参考图片。");

    setIsGenerating(true);
    setError(null);
    setProgress(0);
    startTimeRef.current = performance.now();
    const timer = setInterval(() => setElapsedTime((performance.now() - startTimeRef.current) / 1000), 100);

    try {
      const batchId = Date.now().toString();
      const currentBatchImages: GeneratedImage[] = [];
      const perImagePrice = getEstimatedPrice(model, imageSize);

      for (let i = 0; i < batchSize; i++) {
        const batchProgressBase = (i / batchSize) * 100;
        const batchWeight = 100 / batchSize;

        const currentSteps: GenerationStep[] = [
          { id: 'prep', name: `第 ${i+1} 张：解析与意图捕捉`, status: 'active', duration: null },
          { id: 'render', name: 'Nano 独立引擎渲染', status: 'pending', duration: null },
          { id: 'post', name: '数据归档', status: 'pending', duration: null },
        ];
        setSteps(currentSteps);

        const { refinedPrompt, fileName } = await analyzeAndName(safePrompt, inputImages, isSmartAnalysis);

        setProgress(batchProgressBase + (batchWeight * 0.2));
        setSteps(s => s.map(x => x.id === 'prep' ? {...x, status: 'done'} : x.id === 'render' ? {...x, status: 'active'} : x));

        const stepStart = performance.now();
        const urls = await generateSingleImage(refinedPrompt, inputImages, aspectRatio, imageSize, model, customWidth, customHeight);

        setProgress(batchProgressBase + (batchWeight * 0.8));
        setSteps(s => s.map(x => x.id === 'render' ? {...x, status: 'done'} : x.id === 'post' ? {...x, status: 'active'} : x));

        const totalTimeForOne = (performance.now() - stepStart) / 1000;
        currentBatchImages.push({
          id: `${batchId}-${i}`,
          batchId,
          url: urls[0],
          prompt: safePrompt,
          refinedPrompt: isSmartAnalysis ? refinedPrompt : undefined,
          filename: batchSize > 1 ? `${fileName}-${i + 1}` : fileName,
          timestamp: Date.now(),
          totalDuration: totalTimeForOne,
          thoughtLog: currentSteps.map(s => ({...s, status: 'done'}))
        });
      }

      setBatches(prev => [{ 
        id: batchId, 
        images: currentBatchImages, 
        timestamp: Date.now(),
        cost: perImagePrice * batchSize
      }, ...prev]);
      setSteps(s => s.map(x => ({...x, status: 'done'})));
      setProgress(100);

    } catch (err: any) {
      setError(err.message || "引擎任务中断，请尝试减少批量数量或刷新页面。");
    } finally {
      clearInterval(timer);
      setIsGenerating(false);
    }
  };

  const handleCopyPrompt = async (text: string, id: string) => {
    try {
      await navigator.clipboard.writeText(text);
      setCopyStatus({ ...copyStatus, [id]: true });
      setTimeout(() => setCopyStatus(prev => ({ ...prev, [id]: false })), 2000);
    } catch (e) { console.error(e); }
  };

  const totalGalleryCost = batches.reduce((sum, b) => sum + b.cost, 0);

  return (
    <div className="min-h-screen bg-slate-50 dark:bg-slate-950 text-slate-900 dark:text-slate-100 flex flex-col lg:flex-row font-sans transition-colors duration-500 overflow-hidden">

      {/* 操作区域 */}
      <div className="w-full lg:w-[440px] p-8 flex flex-col gap-8 border-b lg:border-r border-slate-200 dark:border-slate-800/50 bg-white/95 dark:bg-slate-900/95 backdrop-blur-3xl z-40 lg:h-screen overflow-y-auto no-scrollbar shadow-2xl transition-all duration-300">
        <div className="flex items-center justify-between">
          <div className="flex items-center gap-4">
            <div className="w-14 h-14 bg-banana-500 rounded-3xl flex items-center justify-center text-slate-900 shadow-xl shadow-banana-500/30 rotate-6 transition-transform hover:rotate-0 duration-500">
              <Sparkles size={32} />
            </div>
            <div>
              <h1 className="font-black text-2xl tracking-tight leading-none text-slate-900 dark:text-white">NANO LAB <span className="text-banana-600 dark:text-banana-400">V2.0</span></h1>
              <p className="text-[10px] text-slate-500 mt-2 font-bold uppercase tracking-[0.2em] opacity-60">Visual Creation Engine</p>
            </div>
          </div>
          <button 
            onClick={() => setIsDarkMode(!isDarkMode)}
            className="p-3.5 rounded-2xl bg-slate-100 dark:bg-slate-800 text-slate-600 dark:text-slate-400 hover:bg-banana-500 hover:text-slate-950 transition-all shadow-sm"
          >
            {isDarkMode ? <Sun size={20} /> : <Moon size={20} />}
          </button>
        </div>

        <div className="space-y-6">
          <div className="relative group">
            <textarea
              value={prompt}
              onChange={(e) => setPrompt(e.target.value)}
              placeholder="在此输入您的灵感，Ctrl + Enter 立即生成..."
              className="w-full h-44 bg-slate-100/50 dark:bg-slate-800/40 border border-slate-200 dark:border-slate-700/50 rounded-[2.5rem] p-7 text-sm focus:border-banana-500 focus:ring-4 focus:ring-banana-500/10 outline-none transition-all placeholder:text-slate-400 dark:placeholder:text-slate-600 resize-none shadow-inner"
            />
          </div>

          <ImageUploader files={inputImages} onFilesChange={setInputImages} disabled={isGenerating} />

          <SettingsPanel 
            {...{aspectRatio, imageSize, batchSize, model, isSmartAnalysis, customWidth, customHeight}}
            onAspectRatioChange={setAspectRatio}
            onImageSizeChange={setImageSize}
            onBatchSizeChange={setBatchSize}
            onModelChange={setModel}
            onSmartAnalysisChange={setIsSmartAnalysis}
            onCustomPixelsChange={(w, h) => { setCustomWidth(w); setCustomHeight(h); }}
            disabled={isGenerating}
          />

          <div className="p-4 bg-banana-500/5 dark:bg-banana-500/10 rounded-2xl border border-banana-500/20 flex items-center justify-between">
            <div className="flex items-center gap-2 text-xs font-bold text-banana-700 dark:text-banana-400">
              <Wallet size={16} /> 预估单价
            </div>
            <div className="text-sm font-black text-banana-600 dark:text-banana-300">
              ¥ {getEstimatedPrice(model, imageSize).toFixed(2)} / 张
            </div>
          </div>
        </div>

        {error && (
          <div className="text-red-600 dark:text-red-400 text-[11px] font-bold bg-red-50 dark:bg-red-400/5 p-5 rounded-3xl border border-red-200 dark:border-red-400/20">
            ⚠️ {error}
          </div>
        )}

        <div className="mt-auto pt-6 flex flex-col gap-6">
          <button
            onClick={handleGenerate}
            disabled={isGenerating}
            className="w-full py-7 bg-gradient-to-br from-banana-400 to-banana-600 hover:from-banana-300 hover:to-banana-500 text-slate-950 font-black text-xl rounded-[2.8rem] shadow-2xl shadow-banana-500/30 transition-all flex items-center justify-center gap-5 disabled:opacity-40 active:scale-95 group relative overflow-hidden"
          >
            {isGenerating ? <Loader2 className="animate-spin" size={28} /> : <Sparkles size={28} className="group-hover:rotate-45 transition-transform duration-700" />}
            <span className="tracking-tight">{isGenerating ? `任务执行中 ${Math.round(progress)}%` : `立即开启艺术渲染`}</span>
          </button>
        </div>
      </div>

      {/* 画廊展示区域 */}
      <div className={`flex-1 p-8 lg:p-14 overflow-y-auto lg:h-screen scroll-smooth transition-all duration-1000 bg-slate-50 dark:bg-slate-950 ${expandedBatchId || selectedImage ? 'blur-xl grayscale-[0.3] brightness-50 pointer-events-none scale-[1.02]' : ''}`}>
        <div className="max-w-7xl mx-auto">
          <div className="flex items-start justify-between mb-20">
            <div>
              <h2 className="text-4xl font-black text-slate-900 dark:text-white tracking-tighter flex items-center gap-5">
                <div className="p-4 bg-banana-500/10 rounded-[2rem]"><ImageIcon className="text-banana-500" size={36} /></div>
                画廊
              </h2>
              <p className="text-sm text-slate-400 dark:text-slate-500 mt-3 uppercase tracking-[0.3em] font-bold opacity-50">Global Creative Gallery</p>
            </div>

            {/* 自动计费显示框 */}
            <div className="flex items-center gap-6">
              <div className="flex flex-col items-end gap-1 p-5 bg-white dark:bg-slate-900 rounded-[2.5rem] shadow-xl border border-slate-200 dark:border-slate-800">
                <div className="flex items-center gap-2 text-[10px] font-black text-slate-400 uppercase tracking-widest">
                  <Wallet size={12} className="text-banana-500" /> 总计消费
                </div>
                <div className="text-3xl font-black text-slate-900 dark:text-white flex items-baseline gap-1">
                  <span className="text-sm text-banana-600 uppercase">RMB</span>
                  {totalGalleryCost.toFixed(2)}
                </div>
                <div className="text-[8px] text-slate-400 mt-1 flex items-center gap-1">
                  <Info size={10} /> 基于 Google API 实时计费预估
                </div>
              </div>
              <div className="hidden md:flex flex-col items-center group">
                  <div className="text-4xl font-black text-slate-900 dark:text-white group-hover:text-banana-500 transition-colors duration-500">{batches.reduce((acc, b) => acc + b.images.length, 0)}</div>
                  <div className="text-[11px] text-slate-400 dark:text-slate-500 font-black uppercase tracking-[0.2em] mt-2">Captured</div>
              </div>
            </div>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-24">
            {batches.map((batch) => (
              <div 
                key={batch.id} 
                className="group relative cursor-pointer"
                onClick={() => setExpandedBatchId(batch.id)}
              >
                {/* 扑克牌堆叠画框 UI */}
                <div className="aspect-[4/5] relative preserve-3d">
                   {[...batch.images].reverse().slice(-4).map((img, i, arr) => {
                      const totalVisible = arr.length;
                      const indexFromTop = totalVisible - 1 - i;
                      // 扑克牌展开效果：越往后的卡片旋转和位移越多
                      const rotate = indexFromTop * 6; 
                      const translateX = indexFromTop * 14;
                      const translateY = indexFromTop * 6;

                      return (
                        <div 
                          key={img.id}
                          className={`absolute inset-0 bg-white dark:bg-slate-900 rounded-[3.5rem] overflow-hidden border border-slate-200 dark:border-slate-800/50 shadow-[0_20px_50px_-15px_rgba(0,0,0,0.3)] transition-all duration-700 ease-out transform origin-bottom-right
                            ${indexFromTop === 0 ? 'z-30 group-hover:-translate-y-6 group-hover:-translate-x-2' : ''}
                            group-hover:rotate-[${rotate + 4}deg] group-hover:translate-x-[${translateX + 10}px] group-hover:translate-y-[${translateY + 10}px]
                          `}
                          style={{ 
                            transform: `rotate(${rotate}deg) translate(${translateX}px, ${translateY}px)`,
                            zIndex: 30 - indexFromTop,
                            opacity: 1 - (indexFromTop * 0.15)
                          }}
                        >
                           <img src={img.url} className="w-full h-full object-cover transition-transform duration-1000 group-hover:scale-110" loading="lazy" />
                           {indexFromTop === 0 && (
                             <>
                               <div className="absolute top-10 left-10 flex flex-col gap-2">
                                  <span className="px-5 py-2 bg-white/60 dark:bg-black/40 backdrop-blur-3xl rounded-full text-[9px] font-black text-slate-900 dark:text-banana-400 border border-white/30 dark:border-white/10 shadow-2xl uppercase tracking-widest w-fit">
                                    {batch.images.length > 1 ? `COLLECTION: ${batch.images.length}P` : `ID: ${img.filename.slice(0,8)}`}
                                  </span>
                                  <span className="px-4 py-1.5 bg-banana-500 text-slate-950 rounded-full text-[8px] font-black uppercase tracking-tighter w-fit shadow-lg">
                                    EST: ¥{batch.cost.toFixed(2)}
                                  </span>
                               </div>
                             </>
                           )}
                        </div>
                      );
                   })}
                </div>

                <div className="mt-14 text-center opacity-0 group-hover:opacity-60 transition-all duration-500 translate-y-4 group-hover:translate-y-0">
                   <p className="text-[10px] text-slate-500 dark:text-slate-400 font-black uppercase tracking-[0.5em]">Spread Collection</p>
                </div>
              </div>
            ))}

            {batches.length === 0 && !isGenerating && (
                <div className="col-span-full py-56 flex flex-col items-center justify-center text-slate-400 dark:text-slate-800 bg-white dark:bg-slate-900/10 border-4 border-dashed border-slate-200 dark:border-slate-800/40 rounded-[7rem] transition-all">
                    <div className="w-40 h-40 bg-slate-100 dark:bg-slate-800/40 rounded-full flex items-center justify-center mb-12 animate-pulse shadow-inner">
                      <Sparkles size={64} className="opacity-20 text-banana-600" />
                    </div>
                    <p className="text-2xl font-black text-slate-400 dark:text-slate-500 tracking-tighter">画廊尚无创作记录</p>
                    <p className="text-[11px] text-slate-400 dark:text-slate-600 mt-6 uppercase tracking-[0.6em] font-black opacity-60">Start Creating Artistic Value</p>
                </div>
            )}
          </div>
        </div>
      </div>

      {expandedBatchId && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-transparent backdrop-blur-none animate-in fade-in duration-700 overflow-hidden">
           <div className="absolute inset-0 bg-black/70 dark:bg-black/90" onClick={() => setExpandedBatchId(null)} />
           <div className="relative w-full h-full flex flex-col items-center justify-center p-12 lg:p-24 overflow-visible">
              <button 
                onClick={() => setExpandedBatchId(null)}
                className="absolute top-16 right-16 p-5 bg-white/10 hover:bg-white/20 backdrop-blur-3xl rounded-full text-white border border-white/20 z-[60] transition-all shadow-2xl hover:rotate-90 duration-500"
              >
                <X size={32} />
              </button>

              <div className="flex flex-wrap items-center justify-center gap-16 lg:gap-24 w-full max-w-[1400px] animate-in zoom-in-[0.8] duration-1000 pointer-events-none">
                 {batches.find(b => b.id === expandedBatchId)?.images.map((img, idx) => (
                    <div 
                      key={img.id}
                      className="w-full max-w-[22rem] aspect-[4/5] bg-slate-900 rounded-[4rem] overflow-hidden border border-white/10 shadow-[0_50px_120px_-20px_rgba(0,0,0,0.8)] animate-float cursor-pointer hover:scale-110 hover:-rotate-2 transition-all duration-700 pointer-events-auto group/item"
                      style={{ animationDelay: `${idx * 0.3}s`, zIndex: 100 - idx }}
                      onClick={() => { setSelectedImage(img); }}
                    >
                       <img src={img.url} className="w-full h-full object-cover transition-transform duration-1000 group-hover/item:scale-110" />
                       <div className="absolute inset-0 bg-gradient-to-t from-black via-black/20 to-transparent opacity-0 group-hover/item:opacity-100 transition-opacity duration-500 p-10 flex flex-col justify-end">
                          <p className="text-[11px] text-white font-bold mb-6 line-clamp-3 leading-relaxed tracking-wide italic">"{img.prompt}"</p>
                          <button className="w-full py-4 bg-banana-500 text-slate-950 rounded-[2rem] font-black text-[11px] uppercase shadow-2xl">预览详细</button>
                       </div>
                    </div>
                 ))}
              </div>
           </div>
        </div>
      )}

      {selectedImage && (
        <ImageViewer 
          image={selectedImage} 
          isCopied={!!copyStatus[selectedImage.id]} 
          onCopy={() => handleCopyPrompt(selectedImage.prompt, selectedImage.id)} 
          onClose={() => setSelectedImage(null)} 
          onNext={() => navigateImage(1)}
          onPrev={() => navigateImage(-1)}
        />
      )}

      <style>{`
        @keyframes float {
          0%, 100% { transform: translateY(0px) rotate(0deg); }
          50% { transform: translateY(-30px) rotate(1.5deg); }
        }
        .animate-float {
          animation: float 6s ease-in-out infinite;
        }
        .preserve-3d {
          transform-style: preserve-3d;
        }
      `}</style>
    </div>
  );
};

export default App;

export enum AspectRatio {
  Square = "1:1",
  Ratio_3_2 = "3:2",
  Ratio_2_3 = "2:3",
  Ratio_4_3 = "4:3",
  Ratio_3_4 = "3:4",
  Ratio_4_5 = "4:5",
  Ratio_5_4 = "5:4",
  Ratio_16_9 = "16:9",
  Ratio_9_16 = "9:16",
  Ratio_16_10 = "16:10",
  Ratio_10_16 = "10:16",
  Ratio_21_9 = "21:9",
  Ratio_9_21 = "9:21",
  Custom = "custom",
}

export enum ImageSize {
  Size_1K = "1K",
  Size_2K = "2K",
  Size_4K = "4K",
}

export enum AIModel {
  Standard = "gemini-2.5-flash-image",
  Pro = "gemini-3-pro-image-preview",
}

export interface GenerationStep {
  id: string;
  name: string;
  duration: number | null;
  status: 'pending' | 'active' | 'done';
}

export interface GeneratedImage {
  id: string;
  batchId: string;
  url: string;
  prompt: string;
  refinedPrompt?: string;
  filename: string;
  timestamp: number;
  totalDuration: number;
  thoughtLog: GenerationStep[];
  costRMB: number;
  costUSD: number;
}

export interface GeneratedBatch {
  id: string;
  images: GeneratedImage[];
  timestamp: number;
  totalCostRMB: number;
  totalCostUSD: number;
}

export type Currency = 'RMB' | 'USD';

import React, { useState, useEffect, useCallback, useRef } from 'react';
import { Sparkles, Download, Loader2, Image as ImageIcon, Check, Activity, Sun, Moon, Layers, X, ChevronLeft, ChevronRight, Wallet, Info, Coins } from 'lucide-react';
import { generateSingleImage, analyzeAndName } from './services/geminiService';
import SettingsPanel from './components/SettingsPanel';
import ImageUploader from './components/ImageUploader';
import ImageViewer from './components/ImageViewer';
import { AspectRatio, ImageSize, GeneratedImage, AIModel, GenerationStep, GeneratedBatch, Currency } from './types';

// 计费标准
// 汇率参考: 1 USD ≈ 7.2 RMB
const EXCHANGE_RATE = 7.2;

const getPriceInfo = (model: AIModel, size: ImageSize): { rmb: number, usd: number } => {
  let rmb = 0;
  if (model === AIModel.Standard) {
    rmb = 0.10;
  } else {
    switch (size) {
      case ImageSize.Size_2K: rmb = 0.50; break;
      case ImageSize.Size_4K: rmb = 1.00; break;
      case ImageSize.Size_1K:
      default: rmb = 0.25; break;
    }
  }
  return { rmb, usd: parseFloat((rmb / EXCHANGE_RATE).toFixed(4)) };
};

const App: React.FC = () => {
  const [prompt, setPrompt] = useState('');
  const [inputImages, setInputImages] = useState<File[]>([]);
  const [aspectRatio, setAspectRatio] = useState<AspectRatio>(AspectRatio.Square);
  const [imageSize, setImageSize] = useState<ImageSize>(ImageSize.Size_1K);
  const [batchSize, setBatchSize] = useState<number>(1);
  const [model, setModel] = useState<AIModel>(AIModel.Pro);
  const [isSmartAnalysis, setIsSmartAnalysis] = useState<boolean>(true);
  const [customWidth, setCustomWidth] = useState(1024);
  const [customHeight, setCustomHeight] = useState(1024);
  const [isDarkMode, setIsDarkMode] = useState(true);
  const [currency, setCurrency] = useState<Currency>('RMB');

  const [isGenerating, setIsGenerating] = useState(false);
  const [progress, setProgress] = useState(0);
  const [elapsedTime, setElapsedTime] = useState(0);
  const [steps, setSteps] = useState<GenerationStep[]>([]);
  const [batches, setBatches] = useState<GeneratedBatch[]>([]);
  const [selectedImage, setSelectedImage] = useState<GeneratedImage | null>(null);
  const [expandedBatchId, setExpandedBatchId] = useState<string | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [copyStatus, setCopyStatus] = useState<Record<string, boolean>>({});

  const startTimeRef = useRef<number>(0);

  useEffect(() => {
    if (isDarkMode) document.documentElement.classList.add('dark');
    else document.documentElement.classList.remove('dark');
  }, [isDarkMode]);

  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.ctrlKey && e.key === 'Enter' && !isGenerating) handleGenerate();
      if (selectedImage) {
        if (e.key === 'ArrowLeft') navigateImage(-1);
        if (e.key === 'ArrowRight') navigateImage(1);
        if (e.key === 'Escape') setSelectedImage(null);
      } else if (expandedBatchId && e.key === 'Escape') {
        setExpandedBatchId(null);
      }
    };
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [isGenerating, selectedImage, expandedBatchId, batches, prompt, inputImages]);

  const navigateImage = (direction: number) => {
    const allImages = batches.flatMap(b => b.images);
    if (allImages.length === 0 || !selectedImage) return;
    const currentIndex = allImages.findIndex(img => img.id === selectedImage.id);
    let nextIndex = (currentIndex + direction + allImages.length) % allImages.length;
    setSelectedImage(allImages[nextIndex]);
  };

  const handleGenerate = async () => {
    const safePrompt = (prompt || "").trim();
    if (!safePrompt && inputImages.length === 0) return setError("请至少输入一段描述文字或上传一张参考图片。");

    setIsGenerating(true);
    setError(null);
    setProgress(0);
    startTimeRef.current = performance.now();
    const timer = setInterval(() => setElapsedTime((performance.now() - startTimeRef.current) / 1000), 100);

    try {
      const batchId = Date.now().toString();
      const currentBatchImages: GeneratedImage[] = [];
      const price = getPriceInfo(model, imageSize);

      for (let i = 0; i < batchSize; i++) {
        const batchProgressBase = (i / batchSize) * 100;
        const batchWeight = 100 / batchSize;
        const currentSteps: GenerationStep[] = [
          { id: 'prep', name: `第 ${i+1} 张：解析意图`, status: 'active', duration: null },
          { id: 'render', name: 'Nano 引擎渲染', status: 'pending', duration: null },
          { id: 'post', name: '数据归档', status: 'pending', duration: null },
        ];
        setSteps(currentSteps);

        const { refinedPrompt, fileName } = await analyzeAndName(safePrompt, inputImages, isSmartAnalysis);
        setProgress(batchProgressBase + (batchWeight * 0.2));
        setSteps(s => s.map(x => x.id === 'prep' ? {...x, status: 'done'} : x.id === 'render' ? {...x, status: 'active'} : x));

        const stepStart = performance.now();
        const urls = await generateSingleImage(refinedPrompt, inputImages, aspectRatio, imageSize, model, customWidth, customHeight);
        setProgress(batchProgressBase + (batchWeight * 0.8));
        setSteps(s => s.map(x => x.id === 'render' ? {...x, status: 'done'} : x.id === 'post' ? {...x, status: 'active'} : x));

        const totalTimeForOne = (performance.now() - stepStart) / 1000;
        currentBatchImages.push({
          id: `${batchId}-${i}`, batchId, url: urls[0], prompt: safePrompt,
          refinedPrompt: isSmartAnalysis ? refinedPrompt : undefined,
          filename: batchSize > 1 ? `${fileName}-${i + 1}` : fileName,
          timestamp: Date.now(), totalDuration: totalTimeForOne,
          thoughtLog: currentSteps.map(s => ({...s, status: 'done'})),
          costRMB: price.rmb, costUSD: price.usd
        });
      }

      setBatches(prev => [{ 
        id: batchId, images: currentBatchImages, timestamp: Date.now(),
        totalCostRMB: price.rmb * batchSize, totalCostUSD: price.usd * batchSize
      }, ...prev]);
      setSteps(s => s.map(x => ({...x, status: 'done'})));
      setProgress(100);
    } catch (err: any) {
      setError(err.message || "任务生成异常。");
    } finally {
      clearInterval(timer);
      setIsGenerating(false);
    }
  };

  const handleCopyPrompt = async (text: string, id: string) => {
    try {
      await navigator.clipboard.writeText(text);
      setCopyStatus({ ...copyStatus, [id]: true });
      setTimeout(() => setCopyStatus(prev => ({ ...prev, [id]: false })), 2000);
    } catch (e) { console.error(e); }
  };

  const totalCost = batches.reduce((acc, b) => ({
    rmb: acc.rmb + b.totalCostRMB,
    usd: acc.usd + b.totalCostUSD
  }), { rmb: 0, usd: 0 });

  const currentPrice = getPriceInfo(model, imageSize);

  return (
    <div className="min-h-screen bg-slate-50 dark:bg-slate-950 text-slate-900 dark:text-slate-100 flex flex-col lg:flex-row font-sans transition-all duration-500 overflow-hidden">

      {/* 操作区域 */}
      <div className="w-full lg:w-[440px] p-8 flex flex-col gap-8 border-b lg:border-r border-slate-200 dark:border-slate-800 bg-white/95 dark:bg-slate-900/95 backdrop-blur-3xl z-40 lg:h-screen overflow-y-auto no-scrollbar shadow-2xl transition-all">
        <div className="flex items-center justify-between">
          <div className="flex items-center gap-4">
            <div className="w-14 h-14 bg-banana-500 rounded-3xl flex items-center justify-center text-slate-900 shadow-xl shadow-banana-500/30 rotate-6 transition-transform hover:rotate-0">
              <Sparkles size={32} />
            </div>
            <div>
              <h1 className="font-black text-2xl tracking-tight leading-none text-slate-900 dark:text-white">NANO LAB <span className="text-banana-600 dark:text-banana-400">V2.0</span></h1>
              <p className="text-[10px] text-slate-500 mt-2 font-bold uppercase tracking-[0.2em] opacity-60">Visual Creation Engine</p>
            </div>
          </div>
          <button onClick={() => setIsDarkMode(!isDarkMode)} className="p-3.5 rounded-2xl bg-slate-100 dark:bg-slate-800 text-slate-600 dark:text-slate-400 hover:bg-banana-500 hover:text-slate-950 transition-all shadow-sm">
            {isDarkMode ? <Sun size={20} /> : <Moon size={20} />}
          </button>
        </div>

        <div className="space-y-6">
          <textarea
            value={prompt}
            onChange={(e) => setPrompt(e.target.value)}
            placeholder="输入咒语灵感，Ctrl + Enter 生成..."
            className="w-full h-44 bg-slate-100/50 dark:bg-slate-800/60 border border-slate-200 dark:border-slate-700 rounded-[2.5rem] p-7 text-sm focus:border-banana-500 focus:ring-4 focus:ring-banana-500/10 outline-none transition-all placeholder:text-slate-400 dark:placeholder:text-slate-500 resize-none shadow-inner text-slate-900 dark:text-slate-100"
          />

          <ImageUploader files={inputImages} onFilesChange={setInputImages} disabled={isGenerating} />

          <SettingsPanel 
            {...{aspectRatio, imageSize, batchSize, model, isSmartAnalysis, customWidth, customHeight}}
            onAspectRatioChange={setAspectRatio} onImageSizeChange={setImageSize} onBatchSizeChange={setBatchSize}
