      {/* 画廊展示区域 */}
      <div className={`flex-1 p-8 lg:p-14 overflow-y-auto lg:h-screen scroll-smooth transition-all duration-1000 bg-slate-50 dark:bg-slate-950 ${expandedBatchId || selectedImage ? 'blur-2xl grayscale-[0.3] brightness-50 pointer-events-none' : ''}`}>
        <div className="max-w-7xl mx-auto">
          <div className="flex items-start justify-between mb-20">
            <div>
              <h2 className="text-4xl font-black text-slate-900 dark:text-white tracking-tighter flex items-center gap-5">
