                          style={{ 
                            transform: `rotate(${rotate}deg) translate(${translateX}px, ${translateY}px)`,
                            zIndex: 30 - indexFromTop,
                            opacity: 1 - (indexFromTop * 0.1)
                          }}
                        >
                           <img src={img.url} className="w-full h-full object-cover group-hover:scale-110 transition-transform duration-1000" loading="lazy" />
                           {indexFromTop === 0 && (
                             <div className="absolute top-10 left-10 flex flex-col gap-2">
                                <span className="px-5 py-2 bg-white/60 dark:bg-black/40 backdrop-blur-3xl rounded-full text-[9px] font-black text-slate-900 dark:text-banana-400 border border-white/30 dark:border-white/10 shadow-2xl uppercase tracking-widest w-fit">
                                  {batch.images.length > 1 ? `COLLECTION: ${batch.images.length}P` : `ID: ${img.filename.slice(0,8)}`}
                                </span>
                                <span className="px-4 py-1.5 bg-banana-500 text-slate-950 rounded-full text-[8px] font-black uppercase tracking-tighter w-fit shadow-lg">
                                  {currency === 'RMB' ? `¥ ${batch.totalCostRMB.toFixed(2)}` : `$ ${batch.totalCostUSD.toFixed(3)}`}
                                </span>
                             </div>
                           )}
                        </div>
                      );
                   })}
                </div>
                <div className="mt-14 text-center opacity-0 group-hover:opacity-60 transition-all duration-500 translate-y-4 group-hover:translate-y-0">
