            {batches.length === 0 && !isGenerating && (
                <div className="col-span-full py-56 flex flex-col items-center justify-center text-slate-400 dark:text-slate-800 bg-white/50 dark:bg-slate-900/20 border-4 border-dashed border-slate-200 dark:border-slate-800 rounded-[7rem] transition-all">
                    <div className="w-40 h-40 bg-slate-100 dark:bg-slate-800 rounded-full flex items-center justify-center mb-12 animate-pulse shadow-inner">
