           <div className="relative w-full h-full flex flex-wrap items-center justify-center p-12 lg:p-24 gap-16 lg:gap-24 animate-in zoom-in-[0.8] duration-1000 overflow-y-auto no-scrollbar">
              {batches.find(b => b.id === expandedBatchId)?.images.map((img, idx) => (
                <div key={img.id} className="w-full max-w-[22rem] aspect-[4/5] bg-slate-900 rounded-[4rem] overflow-hidden border border-white/10 shadow-[0_50px_120px_-20px_rgba(0,0,0,0.8)] animate-float cursor-pointer hover:scale-110 transition-all duration-700 pointer-events-auto group/item" onClick={() => setSelectedImage(img)}>
                    <img src={img.url} className="w-full h-full object-cover transition-transform duration-1000 group-hover/item:scale-110" />
                    <div className="absolute inset-0 bg-gradient-to-t from-black via-black/10 to-transparent opacity-0 group-hover/item:opacity-100 transition-opacity duration-500 p-10 flex flex-col justify-end">
                      <p className="text-[11px] text-white font-bold mb-6 line-clamp-3 italic">"{img.prompt}"</p>
