const AspectRatioIcon = ({ ratio, active }: { ratio: string, active: boolean }) => {
  const [w, h] = ratio.split(':').map(Number);
  const max = Math.max(w, h);
  const width = (w / max) * 100;
  const height = (h / max) * 100;
  return (
    <div className={`flex items-center justify-center w-6 h-6 mr-2`}>
      <div 
        className={`border-2 rounded-[2px] transition-all duration-300 ${active ? 'border-banana-600 bg-banana-500/20' : 'border-slate-400 dark:border-slate-600 bg-transparent'}`}
        style={{ width: `${width}%`, height: `${height}%` }}
      />
    </div>
  );
};

