        </div>
      </button>

      <div className="space-y-4">
        <div className="flex items-center justify-between">
           <label className="text-[10px] text-slate-500 dark:text-slate-400 font-black uppercase flex items-center gap-1.5">
             <Layout size={12} /> 画幅比例
           </label>
           <div className="flex items-center bg-slate-100 dark:bg-slate-900 p-1 rounded-xl border border-slate-200 dark:border-slate-800">
              <button onClick={() => setOrientation('landscape')} className={`flex items-center gap-1.5 px-3 py-1 rounded-lg text-[9px] font-bold transition-all ${orientation === 'landscape' ? 'bg-white dark:bg-slate-800 text-banana-600 dark:text-banana-400 shadow-sm' : 'text-slate-400'}`}><MonitorIcon size={12} /> 横屏</button>
              <button onClick={() => setOrientation('portrait')} className={`flex items-center gap-1.5 px-3 py-1 rounded-lg text-[9px] font-bold transition-all ${orientation === 'portrait' ? 'bg-white dark:bg-slate-800 text-banana-600 dark:text-banana-400 shadow-sm' : 'text-slate-400'}`}><Smartphone size={12} /> 竖屏</button>
           </div>
        </div>
        <div className="grid grid-cols-2 gap-2">
           {ratioGroups.map((g) => {
             const targetRatio = orientation === 'landscape' ? g.landscape : g.portrait;
             const isActive = aspectRatio === targetRatio;
             return (
               <button key={g.label} onClick={() => onAspectRatioChange(targetRatio)} className={`flex items-center p-2.5 rounded-2xl border text-[10px] font-bold transition-all ${isActive ? 'bg-banana-500/10 border-banana-500 text-banana-600 dark:text-banana-400' : 'bg-slate-50 dark:bg-slate-900/30 border-slate-200 dark:border-slate-800 text-slate-500 hover:border-slate-300 dark:hover:border-slate-700'}`}>
                 <AspectRatioIcon ratio={targetRatio} active={isActive} /> {g.label} {orientation === 'landscape' ? '横' : '竖'}
               </button>
             );
           })}
        </div>
      </div>

      <div className="space-y-5">
        <div className="space-y-2">
          <div className="flex justify-between items-center">
            <label className="text-[10px] text-slate-500 dark:text-slate-400 font-black uppercase flex items-center gap-1.5"><Layers size={12} /> 批量渲染</label>
            <span className="text-banana-600 dark:text-banana-400 font-mono text-[10px] font-bold bg-banana-500/10 px-2 py-0.5 rounded-lg">{batchSize} Pcs</span>
          </div>
          <input type="range" min="1" max="10" step="1" value={batchSize} disabled={disabled} onChange={(e) => onBatchSizeChange(parseInt(e.target.value))} className="w-full h-1 bg-slate-200 dark:bg-slate-700 rounded-full appearance-none cursor-pointer accent-banana-500" />
        </div>
        <div className="space-y-2">
          <label className="text-[10px] text-slate-500 dark:text-slate-400 font-black uppercase flex items-center gap-1.5"><Monitor size={12} /> 质量上限 (Pro)</label>
          <div className="grid grid-cols-3 gap-2">
            {[ImageSize.Size_1K, ImageSize.Size_2K, ImageSize.Size_4K].map(s => (
              <button key={s} disabled={disabled || model === AIModel.Standard} onClick={() => onImageSizeChange(s)} className={`py-2 rounded-xl border text-[10px] font-bold transition-all ${imageSize === s && model === AIModel.Pro ? 'bg-slate-800 dark:bg-white/10 border-slate-900 dark:border-white/30 text-white shadow-md' : 'bg-white dark:bg-slate-900/50 border-slate-200 dark:border-slate-800 text-slate-500'} ${model === AIModel.Standard ? 'opacity-30' : ''}`}>{s}</button>
            ))}
          </div>
        </div>
      </div>
    </div>
  );
};

export default SettingsPanel;

import React, { useCallback, useState } from 'react';
import { Upload, X, ImagePlus, ClipboardPaste } from 'lucide-react';

interface ImageUploaderProps {
  files: File[];
  onFilesChange: (files: File[]) => void;
  disabled: boolean;
}

const ImageUploader: React.FC<ImageUploaderProps> = ({ files, onFilesChange, disabled }) => {
  const [isDragging, setIsDragging] = useState(false);

  const handleDragOver = useCallback((e: React.DragEvent) => {
    e.preventDefault();
    if (!disabled) setIsDragging(true);
  }, [disabled]);

  const handleDragLeave = useCallback((e: React.DragEvent) => {
    e.preventDefault();
    setIsDragging(false);
  }, []);

  const handleDrop = useCallback((e: React.DragEvent) => {
    e.preventDefault();
    setIsDragging(false);
    if (disabled) return;
    if (e.dataTransfer.files && e.dataTransfer.files.length > 0) {
      const newFiles = (Array.from(e.dataTransfer.files) as File[]).filter(file => file.type.startsWith('image/'));
      onFilesChange([...files, ...newFiles]);
    }
  }, [files, onFilesChange, disabled]);

  const removeFile = (index: number) => {
    const newFiles = [...files];
    newFiles.splice(index, 1);
    onFilesChange(newFiles);
  };

  const handleFileInput = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files.length > 0) {
        const newFiles = (Array.from(e.target.files) as File[]).filter(file => file.type.startsWith('image/'));
        onFilesChange([...files, ...newFiles]);
    }
  };

  return (
    <div className="space-y-3">
      <div className="flex items-center justify-between text-sm text-slate-400 dark:text-slate-500">
        <span className="flex items-center gap-1.5 font-bold uppercase text-[10px] tracking-widest"><ImagePlus size={16}/> 参考图片 (可选)</span>
        <span className="text-[10px] opacity-60 font-medium">支持拖拽或粘贴</span>
      </div>

      <div
        onDragOver={handleDragOver}
        onDragLeave={handleDragLeave}
        onDrop={handleDrop}
        className={`relative border-2 border-dashed rounded-[2rem] transition-all duration-200 min-h-[140px] flex flex-col items-center justify-center p-6 group
          ${isDragging 
            ? 'border-banana-500 bg-banana-500/10' 
            : 'border-slate-200 dark:border-slate-700 bg-slate-50/50 dark:bg-slate-800/40 hover:border-banana-500/50 hover:bg-white dark:hover:bg-slate-800/60'
          } ${disabled ? 'opacity-50 cursor-not-allowed' : 'cursor-pointer'}`}
      >
         <input type="file" multiple accept="image/*" className="absolute inset-0 w-full h-full opacity-0 cursor-pointer disabled:cursor-not-allowed" onChange={handleFileInput} disabled={disabled} />

        {files.length === 0 ? (
          <div className="text-center pointer-events-none">
            <div className="w-12 h-12 rounded-2xl bg-white dark:bg-slate-900 shadow-sm flex items-center justify-center mx-auto mb-4 text-slate-400 group-hover:text-banana-500 transition-colors">
              <Upload size={24} />
            </div>
            <p className="text-xs text-slate-500 dark:text-slate-400 font-bold uppercase tracking-tight">点击或拖拽上传</p>
            <p className="text-[9px] text-slate-400 dark:text-slate-500 mt-2 flex items-center justify-center gap-1.5">
               <ClipboardPaste size={12}/> 支持 Ctrl+V 直接粘贴
            </p>
          </div>
        ) : (
            <div className="w-full relative z-10 pointer-events-none">
                <div className="flex flex-wrap gap-3 justify-center pointer-events-auto">
                    {files.map((file, idx) => (
                    <div key={idx} className="relative w-20 h-20 rounded-2xl overflow-hidden border border-white dark:border-slate-700 shadow-xl group/preview">
                        <img src={URL.createObjectURL(file)} alt="preview" className="w-full h-full object-cover" />
                        <button onClick={(e) => { e.stopPropagation(); removeFile(idx); }} className="absolute inset-0 bg-black/40 flex items-center justify-center opacity-0 group-hover/preview:opacity-100 transition-opacity">
                            <X size={20} className="text-white" />
                        </button>
                    </div>
                    ))}
                    <div className="flex items-center justify-center w-20 h-20 rounded-2xl border-2 border-dashed border-slate-300 dark:border-slate-600 bg-white/50 dark:bg-slate-900/50 text-slate-300 dark:text-slate-600">
                        <Upload size={20} />
                    </div>
                </div>
            </div>
        )}
      </div>
    </div>
  );
};

export default ImageUploader;

import React, { useState, useEffect, useCallback, useRef } from 'react';
import { Sparkles, Download, Loader2, Image as ImageIcon, Check, Activity, Sun, Moon, Layers, X, ChevronLeft, ChevronRight, Wallet, Info, Coins, Zap } from 'lucide-react';
import { generateSingleImage, analyzeAndName } from './services/geminiService';
import SettingsPanel from './components/SettingsPanel';
import ImageUploader from './components/ImageUploader';
import ImageViewer from './components/ImageViewer';
import { AspectRatio, ImageSize, GeneratedImage, AIModel, GenerationStep, GeneratedBatch, Currency } from './types';

// 计费标准参考最新定价图表
// 汇率参考: 1 USD ≈ 7.2 RMB
const EXCHANGE_RATE = 7.2;

const getPriceInfo = (model: AIModel, size: ImageSize): { rmb: number, usd: number } => {
  let usd = 0;
  if (model === AIModel.Standard) {
    // Nano Banana (gemini-2.5-flash-image) -> $0.02 - $0.04，取上限 $0.04
    usd = 0.04;
  } else {
    // Nano Banana Pro (gemini-3-pro-image)
    if (size === ImageSize.Size_4K) {
      // High Res (4K) -> $0.24
      usd = 0.24;
    } else {
      // Standard (2K 或 1K) -> $0.134
      usd = 0.134;
    }
  }
  return { usd, rmb: parseFloat((usd * EXCHANGE_RATE).toFixed(2)) };
};

const App: React.FC = () => {
  const [prompt, setPrompt] = useState('');
  const [inputImages, setInputImages] = useState<File[]>([]);
  const [aspectRatio, setAspectRatio] = useState<AspectRatio>(AspectRatio.Square);
  const [imageSize, setImageSize] = useState<ImageSize>(ImageSize.Size_1K);
  const [batchSize, setBatchSize] = useState<number>(1);
  const [model, setModel] = useState<AIModel>(AIModel.Pro);
  const [isSmartAnalysis, setIsSmartAnalysis] = useState<boolean>(true);
  const [customWidth, setCustomWidth] = useState(1024);
  const [customHeight, setCustomHeight] = useState(1024);
  const [isDarkMode, setIsDarkMode] = useState(true);
  const [currency, setCurrency] = useState<Currency>('RMB');

  const [isGenerating, setIsGenerating] = useState(false);
  const [progress, setProgress] = useState(0);
  const [elapsedTime, setElapsedTime] = useState(0);
  const [steps, setSteps] = useState<GenerationStep[]>([]);
  const [batches, setBatches] = useState<GeneratedBatch[]>([]);
  const [selectedImage, setSelectedImage] = useState<GeneratedImage | null>(null);
  const [expandedBatchId, setExpandedBatchId] = useState<string | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [copyStatus, setCopyStatus] = useState<Record<string, boolean>>({});

  const startTimeRef = useRef<number>(0);

  useEffect(() => {
    if (isDarkMode) document.documentElement.classList.add('dark');
    else document.documentElement.classList.remove('dark');
  }, [isDarkMode]);

  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.ctrlKey && e.key === 'Enter' && !isGenerating) handleGenerate();
      if (selectedImage) {
        if (e.key === 'ArrowLeft') navigateImage(-1);
        if (e.key === 'ArrowRight') navigateImage(1);
        if (e.key === 'Escape') setSelectedImage(null);
      } else if (expandedBatchId && e.key === 'Escape') {
        setExpandedBatchId(null);
      }
    };
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [isGenerating, selectedImage, expandedBatchId, batches, prompt, inputImages]);

  const navigateImage = (direction: number) => {
    const allImages = batches.flatMap(b => b.images);
    if (allImages.length === 0 || !selectedImage) return;
    const currentIndex = allImages.findIndex(img => img.id === selectedImage.id);
    let nextIndex = (currentIndex + direction + allImages.length) % allImages.length;
    setSelectedImage(allImages[nextIndex]);
  };

  const handleGenerate = async () => {
    const safePrompt = (prompt || "").trim();
    if (!safePrompt && inputImages.length === 0) return setError("请至少输入一段描述文字或上传一张参考图片。");

    setIsGenerating(true);
    setError(null);
    setProgress(0);
    startTimeRef.current = performance.now();
    const timer = setInterval(() => setElapsedTime((performance.now() - startTimeRef.current) / 1000), 100);

    try {
      const batchId = Date.now().toString();
      const currentBatchImages: GeneratedImage[] = [];
      const price = getPriceInfo(model, imageSize);

      for (let i = 0; i < batchSize; i++) {
        const batchProgressBase = (i / batchSize) * 100;
        const batchWeight = 100 / batchSize;
        const currentSteps: GenerationStep[] = [
          { id: 'prep', name: `第 ${i+1}/${batchSize} 张：意图捕捉与拓扑分析`, status: 'active', duration: null },
          { id: 'render', name: '纳米神经渲染器初始化', status: 'pending', duration: null },
          { id: 'pixel', name: '全画幅像素重构 (1K/2K/4K)', status: 'pending', duration: null },
          { id: 'post', name: '光学归档与元数据注入', status: 'pending', duration: null },
        ];
        setSteps(currentSteps);

        // 第一步：语义增强
        const { refinedPrompt, fileName } = await analyzeAndName(safePrompt, inputImages, isSmartAnalysis);
        setProgress(batchProgressBase + (batchWeight * 0.15));
        setSteps(s => s.map(x => x.id === 'prep' ? {...x, status: 'done'} : x.id === 'render' ? {...x, status: 'active'} : x));

        const stepStart = performance.now();

        // 第二步：开始渲染
        setProgress(batchProgressBase + (batchWeight * 0.35));
        setSteps(s => s.map(x => x.id === 'render' ? {...x, status: 'done'} : x.id === 'pixel' ? {...x, status: 'active'} : x));

        const urls = await generateSingleImage(refinedPrompt, inputImages, aspectRatio, imageSize, model, customWidth, customHeight);

        // 第三步：像素处理完成
        setProgress(batchProgressBase + (batchWeight * 0.85));
        setSteps(s => s.map(x => x.id === 'pixel' ? {...x, status: 'done'} : x.id === 'post' ? {...x, status: 'active'} : x));

        const totalTimeForOne = (performance.now() - stepStart) / 1000;
        currentBatchImages.push({
          id: `${batchId}-${i}`, batchId, url: urls[0], prompt: safePrompt,
          refinedPrompt: isSmartAnalysis ? refinedPrompt : undefined,
          filename: batchSize > 1 ? `${fileName}-${i + 1}` : fileName,
          timestamp: Date.now(), totalDuration: totalTimeForOne,
          thoughtLog: currentSteps.map(s => ({...s, status: 'done'})),
          costRMB: price.rmb, costUSD: price.usd
        });

        // 第四步：完成
        setSteps(s => s.map(x => x.id === 'post' ? {...x, status: 'done'} : x));
        setProgress(batchProgressBase + batchWeight);
      }

      setBatches(prev => [{ 
        id: batchId, images: currentBatchImages, timestamp: Date.now(),
        totalCostRMB: price.rmb * batchSize, totalCostUSD: price.usd * batchSize
      }, ...prev]);
      setProgress(100);
    } catch (err: any) {
      setError(err.message || "引擎渲染失败，请检查 API 配置。");
    } finally {
      clearInterval(timer);
      setIsGenerating(false);
    }
  };

  const handleCopyPrompt = async (text: string, id: string) => {
    try {
      await navigator.clipboard.writeText(text);
      setCopyStatus({ ...copyStatus, [id]: true });
      setTimeout(() => setCopyStatus(prev => ({ ...prev, [id]: false })), 2000);
    } catch (e) { console.error(e); }
  };

  const totalCost = batches.reduce((acc, b) => ({
    rmb: acc.rmb + b.totalCostRMB,
    usd: acc.usd + b.totalCostUSD
  }), { rmb: 0, usd: 0 });

  const currentPrice = getPriceInfo(model, imageSize);
  const estimatedTotal = {
    rmb: (currentPrice.rmb * batchSize).toFixed(2),
    usd: (currentPrice.usd * batchSize).toFixed(3)
  };

  return (
    <div className="min-h-screen bg-slate-50 dark:bg-slate-950 text-slate-900 dark:text-slate-100 flex flex-col lg:flex-row font-sans transition-all duration-500 overflow-hidden">

      {/* 操作区域 */}
      <div className="w-full lg:w-[460px] p-8 flex flex-col gap-8 border-b lg:border-r border-slate-200 dark:border-slate-800 bg-white/95 dark:bg-slate-900/95 backdrop-blur-3xl z-40 lg:h-screen overflow-y-auto no-scrollbar shadow-2xl">
        <div className="flex items-center justify-between">
          <div className="flex items-center gap-4">
            <div className="w-14 h-14 bg-banana-500 rounded-3xl flex items-center justify-center text-slate-900 shadow-xl shadow-banana-500/30 rotate-6 transition-transform hover:rotate-0">
              <Sparkles size={32} />
            </div>
            <div>
              <h1 className="font-black text-2xl tracking-tight leading-none text-slate-900 dark:text-white">NANO LAB <span className="text-banana-600 dark:text-banana-400">V2.0</span></h1>
              <p className="text-[10px] text-slate-500 mt-2 font-bold uppercase tracking-[0.2em] opacity-60">Visual Creation Engine</p>
            </div>
          </div>
          <button onClick={() => setIsDarkMode(!isDarkMode)} className="p-3.5 rounded-2xl bg-slate-100 dark:bg-slate-800 text-slate-600 dark:text-slate-400 hover:bg-banana-500 hover:text-slate-950 transition-all shadow-sm">
            {isDarkMode ? <Sun size={20} /> : <Moon size={20} />}
          </button>
        </div>

        <div className="space-y-6">
          <div className="relative group">
            <textarea
              value={prompt}
              onChange={(e) => setPrompt(e.target.value)}
              placeholder="输入咒语灵感，Ctrl + Enter 生成..."
              className="w-full h-40 bg-slate-100/50 dark:bg-slate-800/60 border border-slate-200 dark:border-slate-700 rounded-[2.5rem] p-7 text-sm focus:border-banana-500 focus:ring-4 focus:ring-banana-500/10 outline-none transition-all placeholder:text-slate-400 dark:placeholder:text-slate-500 resize-none shadow-inner text-slate-900 dark:text-slate-100"
            />
          </div>

          <ImageUploader files={inputImages} onFilesChange={setInputImages} disabled={isGenerating} />

          <SettingsPanel 
            {...{aspectRatio, imageSize, batchSize, model, isSmartAnalysis, customWidth, customHeight}}
            onAspectRatioChange={setAspectRatio} onImageSizeChange={setImageSize} onBatchSizeChange={setBatchSize}
            onModelChange={setModel} onSmartAnalysisChange={setIsSmartAnalysis} onCustomPixelsChange={(w, h) => { setCustomWidth(w); setCustomHeight(h); }}
            disabled={isGenerating}
          />

          <div 
            onClick={() => setCurrency(currency === 'RMB' ? 'USD' : 'RMB')}
            className="p-5 bg-banana-500/5 dark:bg-banana-500/10 rounded-[2rem] border border-banana-500/20 flex items-center justify-between cursor-pointer hover:bg-banana-500/10 dark:hover:bg-banana-500/20 transition-all group"
          >
            <div className="flex items-center gap-2 text-xs font-black text-banana-700 dark:text-banana-400 uppercase tracking-widest">
              <Coins size={18} className="group-hover:rotate-12 transition-transform" /> 引擎计价 (点击切换)
            </div>
            <div className="text-sm font-black text-banana-600 dark:text-banana-300">
              {currency === 'RMB' ? `¥ ${currentPrice.rmb.toFixed(2)}` : `$ ${currentPrice.usd.toFixed(3)}`} / 张
            </div>
          </div>
        </div>

        {error && (
          <div className="text-red-600 dark:text-red-400 text-[11px] font-bold bg-red-50 dark:bg-red-900/40 p-5 rounded-3xl border border-red-200 dark:border-red-900/50">
            ⚠️ {error}
          </div>
        )}

        <div className="mt-auto pt-6 flex flex-col gap-6">
          <button
            onClick={handleGenerate}
            disabled={isGenerating}
            className="w-full py-7 bg-gradient-to-br from-banana-400 to-banana-600 hover:from-banana-300 hover:to-banana-500 text-slate-950 font-black text-xl rounded-[2.8rem] shadow-2xl shadow-banana-500/30 transition-all flex flex-col items-center justify-center gap-1 disabled:opacity-40 active:scale-95 group relative overflow-hidden"
          >
            <div className="flex items-center gap-4">
               {isGenerating ? <Loader2 className="animate-spin" size={24} /> : <Zap size={24} className="group-hover:scale-125 transition-transform" />}
               <span className="tracking-tight">{isGenerating ? `核心渲染中...` : `开启艺术创作`}</span>
            </div>
            {!isGenerating && (
              <span className="text-[10px] font-black opacity-60 uppercase tracking-[0.2em]">
                预计消耗 {currency === 'RMB' ? `¥ ${estimatedTotal.rmb}` : `$ ${estimatedTotal.usd}`}
              </span>
            )}
          </button>

          {isGenerating && (
            <div className="space-y-6 p-7 bg-slate-50 dark:bg-slate-800/40 rounded-[2.8rem] border border-slate-200 dark:border-slate-700/50 shadow-xl animate-in slide-in-from-bottom-4">
               <div className="flex flex-col gap-2">
                 <div className="flex justify-between items-center text-[10px] font-black text-slate-500 uppercase tracking-widest">
                   <div className="flex items-center gap-2">
                      <Activity size={14} className="text-banana-500 animate-pulse" />
                      当前进度
                   </div>
                   <span>{Math.round(progress)}%</span>
                 </div>
                 <div className="h-2 w-full bg-slate-200 dark:bg-slate-700 rounded-full overflow-hidden p-[2px]">
                   <div 
                    className="h-full bg-gradient-to-r from-banana-400 to-banana-600 rounded-full transition-all duration-300 ease-out shadow-[0_0_10px_rgba(234,179,8,0.5)]" 
                    style={{ width: `${progress}%` }} 
                   />
                 </div>
               </div>

               <div className="space-y-3.5">
                 {steps.map(s => (
                   <div key={s.id} className="flex items-center justify-between text-[11px]">
                     <div className="flex items-center gap-3">
                       {s.status === 'done' ? (
                         <div className="w-5 h-5 rounded-full bg-green-500/10 flex items-center justify-center text-green-500">
                           <Check size={12} strokeWidth={4} />
                         </div>
                       ) : s.status === 'active' ? (
                         <div className="w-5 h-5 rounded-full bg-banana-500/10 flex items-center justify-center text-banana-500">
                           <Loader2 size={12} className="animate-spin" />
                         </div>
                       ) : (
                         <div className="w-5 h-5 rounded-full bg-slate-100 dark:bg-slate-800 border border-slate-200 dark:border-slate-700" />
                       )}
                       <span className={`font-bold transition-colors ${s.status === 'active' ? 'text-banana-600 dark:text-banana-400' : s.status === 'done' ? 'text-slate-400 dark:text-slate-600' : 'text-slate-300 dark:text-slate-700'}`}>
                         {s.name}
                       </span>
                     </div>
                     {s.status === 'active' && <span className="text-[9px] font-mono text-banana-500 animate-pulse">{elapsedTime.toFixed(1)}s</span>}
                   </div>
                 ))}
               </div>
            </div>
          )}
        </div>
      </div>

      {/* 画廊展示区域 */}
      <div className={`flex-1 p-8 lg:p-14 overflow-y-auto lg:h-screen scroll-smooth transition-all duration-1000 bg-slate-50 dark:bg-slate-950 ${expandedBatchId || selectedImage ? 'blur-2xl grayscale-[0.3] brightness-50 pointer-events-none' : ''}`}>
        <div className="max-w-7xl mx-auto">
          <div className="flex items-start justify-between mb-20">
            <div>
              <h2 className="text-4xl font-black text-slate-900 dark:text-white tracking-tighter flex items-center gap-5">
                <div className="p-4 bg-banana-500/10 rounded-[2rem]"><ImageIcon className="text-banana-500" size={36} /></div>
                画廊
              </h2>
              <p className="text-sm text-slate-400 dark:text-slate-500 mt-3 uppercase tracking-[0.3em] font-bold opacity-50">Global Creative Gallery</p>
            </div>

            <div className="flex items-center gap-6">
              <div 
                onClick={() => setCurrency(currency === 'RMB' ? 'USD' : 'RMB')}
                className="flex flex-col items-end gap-1 p-5 bg-white dark:bg-slate-900 rounded-[2.5rem] shadow-xl border border-slate-200 dark:border-slate-800 cursor-pointer hover:border-banana-500/50 transition-all group"
              >
                <div className="flex items-center gap-2 text-[10px] font-black text-slate-400 uppercase tracking-widest group-hover:text-banana-500 transition-colors">
                  <Wallet size={12} /> 总计消费 (点击切换)
                </div>
                <div className="text-3xl font-black text-slate-900 dark:text-white flex items-baseline gap-1">
                  <span className="text-sm text-banana-600 uppercase">{currency}</span>
                  {currency === 'RMB' ? totalCost.rmb.toFixed(2) : totalCost.usd.toFixed(2)}
                </div>
                <div className="text-[8px] text-slate-400 mt-1 flex items-center gap-1">
                  <Info size={10} /> 汇率 1:{EXCHANGE_RATE} | Google 计费预估
                </div>
              </div>
              <div className="hidden md:flex flex-col items-center">
                  <div className="text-4xl font-black text-slate-900 dark:text-white">{batches.reduce((acc, b) => acc + b.images.length, 0)}</div>
                  <div className="text-[11px] text-slate-400 dark:text-slate-500 font-black uppercase tracking-[0.2em] mt-2">Works</div>
              </div>
            </div>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-24">
            {batches.map((batch) => (
              <div key={batch.id} className="group relative cursor-pointer" onClick={() => setExpandedBatchId(batch.id)}>
                <div className="aspect-[4/5] relative preserve-3d h-full">
                   {[...batch.images].reverse().slice(-4).map((img, i, arr) => {
                      const totalVisible = arr.length;
                      const indexFromTop = totalVisible - 1 - i;
                      const rotate = indexFromTop * 4; 
                      const translateX = indexFromTop * 10;
                      const translateY = indexFromTop * 4;

                      return (
                        <div 
                          key={img.id}
                          className="absolute inset-0 bg-white dark:bg-slate-900 rounded-[3.5rem] overflow-hidden border border-slate-200 dark:border-slate-800 shadow-[0_20px_50px_-15px_rgba(0,0,0,0.3)] dark:shadow-[0_20px_50px_-15px_rgba(0,0,0,0.7)] transition-all duration-700 ease-out transform origin-bottom-right"
                          style={{ 
                            transform: `rotate(${rotate}deg) translate(${translateX}px, ${translateY}px)`,
                            zIndex: 30 - indexFromTop,
                            opacity: 1 - (indexFromTop * 0.1)
                          }}
                        >
                           <img src={img.url} className="w-full h-full object-cover group-hover:scale-110 transition-transform duration-1000" loading="lazy" />
                           {indexFromTop === 0 && (
                             <div className="absolute top-10 left-10 flex flex-col gap-2">
                                <span className="px-5 py-2 bg-white/60 dark:bg-black/40 backdrop-blur-3xl rounded-full text-[9px] font-black text-slate-900 dark:text-banana-400 border border-white/30 dark:border-white/10 shadow-2xl uppercase tracking-widest w-fit">
                                  {batch.images.length > 1 ? `COLLECTION: ${batch.images.length}P` : `ID: ${img.filename.slice(0,8)}`}
                                </span>
                                <span className="px-4 py-1.5 bg-banana-500 text-slate-950 rounded-full text-[8px] font-black uppercase tracking-tighter w-fit shadow-lg">
                                  {currency === 'RMB' ? `¥ ${batch.totalCostRMB.toFixed(2)}` : `$ ${batch.totalCostUSD.toFixed(3)}`}
                                </span>
                             </div>
                           )}
                        </div>
                      );
                   })}
                </div>
                <div className="mt-14 text-center opacity-0 group-hover:opacity-60 transition-all duration-500 translate-y-4 group-hover:translate-y-0">
                   <p className="text-[10px] text-slate-500 dark:text-slate-400 font-black uppercase tracking-[0.5em]">Spread Collection</p>
                </div>
              </div>
            ))}
            {batches.length === 0 && !isGenerating && (
                <div className="col-span-full py-56 flex flex-col items-center justify-center text-slate-400 dark:text-slate-800 bg-white/50 dark:bg-slate-900/20 border-4 border-dashed border-slate-200 dark:border-slate-800 rounded-[7rem] transition-all">
                    <div className="w-40 h-40 bg-slate-100 dark:bg-slate-800 rounded-full flex items-center justify-center mb-12 animate-pulse shadow-inner">
                      <Sparkles size={64} className="opacity-20 text-banana-600" />
                    </div>
                    <p className="text-2xl font-black tracking-tighter opacity-40">创作库尚无记录</p>
                </div>
            )}
          </div>
        </div>
      </div>

      {expandedBatchId && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-transparent backdrop-blur-none animate-in fade-in duration-700 overflow-hidden">
           <div className="absolute inset-0 bg-black/70 dark:bg-black/90" onClick={() => setExpandedBatchId(null)} />
           <div className="relative w-full h-full flex flex-wrap items-center justify-center p-12 lg:p-24 gap-16 lg:gap-24 animate-in zoom-in-[0.8] duration-1000 overflow-y-auto no-scrollbar">
              {batches.find(b => b.id === expandedBatchId)?.images.map((img, idx) => (
                <div key={img.id} className="w-full max-w-[22rem] aspect-[4/5] bg-slate-900 rounded-[4rem] overflow-hidden border border-white/10 shadow-[0_50px_120px_-20px_rgba(0,0,0,0.8)] animate-float cursor-pointer hover:scale-110 transition-all duration-700 pointer-events-auto group/item" onClick={() => setSelectedImage(img)}>
                    <img src={img.url} className="w-full h-full object-cover transition-transform duration-1000 group-hover/item:scale-110" />
                    <div className="absolute inset-0 bg-gradient-to-t from-black via-black/10 to-transparent opacity-0 group-hover/item:opacity-100 transition-opacity duration-500 p-10 flex flex-col justify-end">
                      <p className="text-[11px] text-white font-bold mb-6 line-clamp-3 italic">"{img.prompt}"</p>
                      <button className="w-full py-4 bg-banana-500 text-slate-950 rounded-[2rem] font-black text-[11px] uppercase">查看全屏</button>
                    </div>
                </div>
              ))}
              <button onClick={() => setExpandedBatchId(null)} className="fixed top-12 right-12 p-5 bg-white/10 hover:bg-white/20 backdrop-blur-3xl rounded-full text-white border border-white/20 shadow-2xl transition-all hover:rotate-90">
                <X size={32} />
              </button>
           </div>
        </div>
      )}

      {selectedImage && <ImageViewer image={selectedImage} isCopied={!!copyStatus[selectedImage.id]} onCopy={() => handleCopyPrompt(selectedImage.prompt, selectedImage.id)} onClose={() => setSelectedImage(null)} onNext={() => navigateImage(1)} onPrev={() => navigateImage(-1)} currency={currency} />}
      <style>{`.preserve-3d { transform-style: preserve-3d; } @keyframes float { 0%, 100% { transform: translateY(0px) rotate(0deg); } 50% { transform: translateY(-30px) rotate(1.5deg); } } .animate-float { animation: float 6s ease-in-out infinite; }`}</style>
    </div>
  );
};

export default App;

import React, { useState, useEffect, useCallback, useRef } from 'react';
import { Sparkles, Download, Loader2, Image as ImageIcon, Check, Activity, Sun, Moon, Layers, X, ChevronLeft, ChevronRight, Wallet, Info, Coins, Zap, Cpu } from 'lucide-react';
import { generateSingleImage, analyzeAndName } from './services/geminiService';
import SettingsPanel from './components/SettingsPanel';
import ImageUploader from './components/ImageUploader';
import ImageViewer from './components/ImageViewer';
import { AspectRatio, ImageSize, GeneratedImage, AIModel, GenerationStep, GeneratedBatch, Currency } from './types';

// 计费标准参考用户提供图表
// 汇率参考: 1 USD ≈ 7.2 RMB
const EXCHANGE_RATE = 7.2;

const getPriceInfo = (model: AIModel, size: ImageSize): { rmb: number, usd: number } => {
  let usd = 0;
  if (model === AIModel.Standard) {
    // Nano Banana (gemini-2.5-flash-image) -> $0.02 - $0.04，取上限
    usd = 0.04;
  } else {
    // Nano Banana Pro (gemini-3-pro-image)
    if (size === ImageSize.Size_4K) {
      // 4K (4096x4096) -> $0.24
      usd = 0.24;
    } else {
      // 1K (1024x1024) 和 2K (2048x2048) 同价 -> $0.134
      usd = 0.134;
    }
  }
  return { usd, rmb: parseFloat((usd * EXCHANGE_RATE).toFixed(2)) };
};

const App: React.FC = () => {
  const [prompt, setPrompt] = useState('');
  const [inputImages, setInputImages] = useState<File[]>([]);
  const [aspectRatio, setAspectRatio] = useState<AspectRatio>(AspectRatio.Square);
  const [imageSize, setImageSize] = useState<ImageSize>(ImageSize.Size_1K);
  const [batchSize, setBatchSize] = useState<number>(1);
  const [model, setModel] = useState<AIModel>(AIModel.Pro);
  const [isSmartAnalysis, setIsSmartAnalysis] = useState<boolean>(true);
  const [customWidth, setCustomWidth] = useState(1024);
  const [customHeight, setCustomHeight] = useState(1024);
  const [isDarkMode, setIsDarkMode] = useState(true);
  const [currency, setCurrency] = useState<Currency>('RMB');

  const [isGenerating, setIsGenerating] = useState(false);
  const [progress, setProgress] = useState(0);
  const [elapsedTime, setElapsedTime] = useState(0);
  const [steps, setSteps] = useState<GenerationStep[]>([]);
  const [batches, setBatches] = useState<GeneratedBatch[]>([]);
  const [selectedImage, setSelectedImage] = useState<GeneratedImage | null>(null);
  const [expandedBatchId, setExpandedBatchId] = useState<string | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [copyStatus, setCopyStatus] = useState<Record<string, boolean>>({});

  const startTimeRef = useRef<number>(0);

  useEffect(() => {
    if (isDarkMode) document.documentElement.classList.add('dark');
    else document.documentElement.classList.remove('dark');
  }, [isDarkMode]);

  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.ctrlKey && e.key === 'Enter' && !isGenerating) handleGenerate();
      if (selectedImage) {
        if (e.key === 'ArrowLeft') navigateImage(-1);
        if (e.key === 'ArrowRight') navigateImage(1);
        if (e.key === 'Escape') setSelectedImage(null);
      } else if (expandedBatchId && e.key === 'Escape') {
        setExpandedBatchId(null);
      }
    };
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [isGenerating, selectedImage, expandedBatchId, batches, prompt, inputImages]);

  const navigateImage = (direction: number) => {
    const allImages = batches.flatMap(b => b.images);
    if (allImages.length === 0 || !selectedImage) return;
    const currentIndex = allImages.findIndex(img => img.id === selectedImage.id);
    let nextIndex = (currentIndex + direction + allImages.length) % allImages.length;
    setSelectedImage(allImages[nextIndex]);
  };

  const handleGenerate = async () => {
    const safePrompt = (prompt || "").trim();
    if (!safePrompt && inputImages.length === 0) return setError("请输入描述或上传参考图片。");

    setIsGenerating(true);
    setError(null);
    setProgress(0);
    startTimeRef.current = performance.now();
    const timer = setInterval(() => setElapsedTime((performance.now() - startTimeRef.current) / 1000), 100);

    try {
      const batchId = Date.now().toString();
      const currentBatchImages: GeneratedImage[] = [];
      const price = getPriceInfo(model, imageSize);

      for (let i = 0; i < batchSize; i++) {
        const batchProgressBase = (i / batchSize) * 100;
        const batchWeight = 100 / batchSize;
        const currentSteps: GenerationStep[] = [
          { id: 'prep', name: `第 ${i+1}/${batchSize} 张：深度意图分析与重构`, status: 'active', duration: null },
          { id: 'env', name: 'Nano 视觉环境初始化', status: 'pending', duration: null },
          { id: 'render', name: `高阶神经渲染 (${model === AIModel.Pro ? imageSize : 'Standard'})`, status: 'pending', duration: null },
          { id: 'post', name: '色彩校准与元数据注入', status: 'pending', duration: null },
        ];
        setSteps(currentSteps);

        // 步骤1：分析
        const { refinedPrompt, fileName } = await analyzeAndName(safePrompt, inputImages, isSmartAnalysis);
        setProgress(batchProgressBase + (batchWeight * 0.15));
        setSteps(s => s.map(x => x.id === 'prep' ? {...x, status: 'done'} : x.id === 'env' ? {...x, status: 'active'} : x));

        const stepStart = performance.now();

        // 步骤2：环境初始化
        await new Promise(r => setTimeout(r, 400)); // 视觉反馈延迟
        setProgress(batchProgressBase + (batchWeight * 0.3));
        setSteps(s => s.map(x => x.id === 'env' ? {...x, status: 'done'} : x.id === 'render' ? {...x, status: 'active'} : x));

        // 步骤3：实际渲染
        const urls = await generateSingleImage(refinedPrompt, inputImages, aspectRatio, imageSize, model, customWidth, customHeight);

        setProgress(batchProgressBase + (batchWeight * 0.85));
        setSteps(s => s.map(x => x.id === 'render' ? {...x, status: 'done'} : x.id === 'post' ? {...x, status: 'active'} : x));

        // 步骤4：后处理
        const totalTimeForOne = (performance.now() - stepStart) / 1000;
        currentBatchImages.push({
          id: `${batchId}-${i}`, batchId, url: urls[0], prompt: safePrompt,
          refinedPrompt: isSmartAnalysis ? refinedPrompt : undefined,
          filename: batchSize > 1 ? `${fileName}-${i + 1}` : fileName,
          timestamp: Date.now(), totalDuration: totalTimeForOne,
          thoughtLog: currentSteps.map(s => ({...s, status: 'done'})),
          costRMB: price.rmb, costUSD: price.usd
        });

        setSteps(s => s.map(x => x.id === 'post' ? {...x, status: 'done'} : x));
        setProgress(batchProgressBase + batchWeight);
      }

      setBatches(prev => [{ 
        id: batchId, images: currentBatchImages, timestamp: Date.now(),
        totalCostRMB: price.rmb * batchSize, totalCostUSD: price.usd * batchSize
      }, ...prev]);
      setProgress(100);
    } catch (err: any) {
      setError(err.message || "渲染引擎响应异常，请核对 API 权限。");
    } finally {
      clearInterval(timer);
      setIsGenerating(false);
    }
  };

  const handleCopyPrompt = async (text: string, id: string) => {
    try {
      await navigator.clipboard.writeText(text);
      setCopyStatus({ ...copyStatus, [id]: true });
      setTimeout(() => setCopyStatus(prev => ({ ...prev, [id]: false })), 2000);
    } catch (e) { console.error(e); }
  };

  const totalCost = batches.reduce((acc, b) => ({
    rmb: acc.rmb + b.totalCostRMB,
    usd: acc.usd + b.totalCostUSD
  }), { rmb: 0, usd: 0 });

  const currentPrice = getPriceInfo(model, imageSize);
  const estimatedTotal = {
    rmb: (currentPrice.rmb * batchSize).toFixed(2),
    usd: (currentPrice.usd * batchSize).toFixed(3)
  };

  return (
    <div className="min-h-screen bg-slate-50 dark:bg-slate-950 text-slate-900 dark:text-slate-100 flex flex-col lg:flex-row font-sans transition-all duration-500 overflow-hidden">

      {/* 操作区域 */}
      <div className="w-full lg:w-[460px] p-8 flex flex-col gap-8 border-b lg:border-r border-slate-200 dark:border-slate-800 bg-white/95 dark:bg-slate-900/95 backdrop-blur-3xl z-40 lg:h-screen overflow-y-auto no-scrollbar shadow-2xl">
        <div className="flex items-center justify-between">
          <div className="flex items-center gap-4">
            <div className="w-14 h-14 bg-banana-500 rounded-3xl flex items-center justify-center text-slate-900 shadow-xl shadow-banana-500/30 rotate-6 transition-transform hover:rotate-0">
              <Sparkles size={32} />
            </div>
            <div>
              <h1 className="font-black text-2xl tracking-tight leading-none text-slate-900 dark:text-white">NANO LAB <span className="text-banana-600 dark:text-banana-400">V2.0</span></h1>
              <p className="text-[10px] text-slate-500 mt-2 font-bold uppercase tracking-[0.2em] opacity-60">Visual Creation Engine</p>
            </div>
          </div>
          <button onClick={() => setIsDarkMode(!isDarkMode)} className="p-3.5 rounded-2xl bg-slate-100 dark:bg-slate-800 text-slate-600 dark:text-slate-400 hover:bg-banana-500 hover:text-slate-950 transition-all shadow-sm">
            {isDarkMode ? <Sun size={20} /> : <Moon size={20} />}
          </button>
        </div>

        <div className="space-y-6">
          <textarea
            value={prompt}
            onChange={(e) => setPrompt(e.target.value)}
            placeholder="描述您的创意构想..."
            className="w-full h-40 bg-slate-100/50 dark:bg-slate-800/60 border border-slate-200 dark:border-slate-700 rounded-[2.5rem] p-7 text-sm focus:border-banana-500 focus:ring-4 focus:ring-banana-500/10 outline-none transition-all placeholder:text-slate-400 dark:placeholder:text-slate-500 resize-none shadow-inner text-slate-900 dark:text-slate-100"
          />

          <ImageUploader files={inputImages} onFilesChange={setInputImages} disabled={isGenerating} />

          <SettingsPanel 
            {...{aspectRatio, imageSize, batchSize, model, isSmartAnalysis, customWidth, customHeight}}
            onAspectRatioChange={setAspectRatio} onImageSizeChange={setImageSize} onBatchSizeChange={setBatchSize}
            onModelChange={setModel} onSmartAnalysisChange={setIsSmartAnalysis} onCustomPixelsChange={(w, h) => { setCustomWidth(w); setCustomHeight(h); }}
            disabled={isGenerating}
          />

          <div 
            onClick={() => setCurrency(currency === 'RMB' ? 'USD' : 'RMB')}
            className="p-5 bg-banana-500/5 dark:bg-banana-500/10 rounded-[2rem] border border-banana-500/20 flex items-center justify-between cursor-pointer hover:bg-banana-500/10 dark:hover:bg-banana-500/20 transition-all group"
          >
            <div className="flex items-center gap-2 text-xs font-black text-banana-700 dark:text-banana-400 uppercase tracking-widest">
              <Coins size={18} className="group-hover:rotate-12 transition-transform" /> 核心定价 (点击切换)
            </div>
            <div className="flex flex-col items-end">
              <div className="text-sm font-black text-banana-600 dark:text-banana-300">
                {currency === 'RMB' ? `¥ ${currentPrice.rmb.toFixed(2)}` : `$ ${currentPrice.usd.toFixed(3)}`} / 张
              </div>
              <div className="text-[9px] font-bold text-slate-400 uppercase tracking-tighter">
                {model === AIModel.Pro ? `${imageSize} 分辨率` : '标准画质'}
              </div>
            </div>
          </div>
        </div>

        {error && (
          <div className="text-red-600 dark:text-red-400 text-[11px] font-bold bg-red-50 dark:bg-red-900/40 p-5 rounded-3xl border border-red-200 dark:border-red-900/50">
            ⚠️ {error}
          </div>
        )}

        <div className="mt-auto pt-6 flex flex-col gap-6">
          <button
            onClick={handleGenerate}
            disabled={isGenerating}
            className="w-full py-7 bg-gradient-to-br from-banana-400 to-banana-600 hover:from-banana-300 hover:to-banana-500 text-slate-950 font-black text-xl rounded-[2.8rem] shadow-2xl shadow-banana-500/30 transition-all flex flex-col items-center justify-center gap-1 disabled:opacity-40 active:scale-95 group relative overflow-hidden"
          >
            <div className="flex items-center gap-4">
               {isGenerating ? <Loader2 className="animate-spin" size={24} /> : <Zap size={24} className="group-hover:scale-125 transition-transform" />}
               <span className="tracking-tight">{isGenerating ? `视觉构建中...` : `开启艺术创作`}</span>
            </div>
            {!isGenerating && (
              <span className="text-[10px] font-black opacity-70 uppercase tracking-[0.2em] border-t border-slate-900/10 w-2/3 mt-2 pt-1">
                预计消耗 {currency === 'RMB' ? `¥ ${estimatedTotal.rmb}` : `$ ${estimatedTotal.usd}`}
              </span>
            )}
          </button>

          {isGenerating && (
            <div className="space-y-6 p-7 bg-slate-50 dark:bg-slate-800/60 rounded-[2.8rem] border border-slate-200 dark:border-slate-700 shadow-xl animate-in slide-in-from-bottom-4">
               <div className="flex flex-col gap-2.5">
                 <div className="flex justify-between items-center text-[10px] font-black text-slate-500 uppercase tracking-widest">
                   <div className="flex items-center gap-2">
                      <Activity size={14} className="text-banana-500 animate-pulse" />
                      当前进度
                   </div>
                   <span className="font-mono text-banana-600">{Math.round(progress)}%</span>
                 </div>
                 <div className="h-2.5 w-full bg-slate-200 dark:bg-slate-900/80 rounded-full overflow-hidden p-[2px] shadow-inner">
                   <div 
                    className="h-full bg-gradient-to-r from-banana-400 via-banana-500 to-banana-600 rounded-full transition-all duration-300 ease-out shadow-[0_0_15px_rgba(234,179,8,0.4)]" 
                    style={{ width: `${progress}%` }} 
                   />
                 </div>
               </div>

               <div className="space-y-3.5">
                 {steps.map(s => (
                   <div key={s.id} className="flex items-center justify-between text-[11px]">
                     <div className="flex items-center gap-3">
                       {s.status === 'done' ? (
                         <div className="w-5 h-5 rounded-full bg-green-500 flex items-center justify-center text-white shadow-lg shadow-green-500/20 scale-100 transition-transform">
                           <Check size={12} strokeWidth={4} />
                         </div>
                       ) : s.status === 'active' ? (
                         <div className="w-5 h-5 rounded-full bg-banana-500 flex items-center justify-center text-slate-900 animate-pulse">
                           <Loader2 size={12} className="animate-spin" />
                         </div>
                       ) : (
                         <div className="w-5 h-5 rounded-full border-2 border-slate-200 dark:border-slate-700 bg-white dark:bg-slate-900" />
                       )}
                       <span className={`font-bold transition-all duration-300 ${s.status === 'active' ? 'text-banana-600 dark:text-banana-400 translate-x-1' : s.status === 'done' ? 'text-slate-400 dark:text-slate-600 opacity-60' : 'text-slate-300 dark:text-slate-800'}`}>
                         {s.name}
                       </span>
                     </div>
                     {s.status === 'active' && <span className="text-[10px] font-mono font-black text-banana-500 animate-pulse">{elapsedTime.toFixed(1)}s</span>}
                   </div>
                 ))}
               </div>
            </div>
          )}
        </div>
      </div>

      {/* 画廊展示区域 */}
      <div className={`flex-1 p-8 lg:p-14 overflow-y-auto lg:h-screen scroll-smooth transition-all duration-1000 bg-slate-50 dark:bg-slate-950 ${expandedBatchId || selectedImage ? 'blur-2xl grayscale-[0.3] brightness-50 pointer-events-none' : ''}`}>
        <div className="max-w-7xl mx-auto">
          <div className="flex items-start justify-between mb-20">
            <div>
              <h2 className="text-4xl font-black text-slate-900 dark:text-white tracking-tighter flex items-center gap-5">
                <div className="p-4 bg-banana-500/10 rounded-[2rem] shadow-sm"><ImageIcon className="text-banana-500" size={36} /></div>
                画廊
              </h2>
              <p className="text-sm text-slate-400 dark:text-slate-500 mt-3 uppercase tracking-[0.3em] font-bold opacity-50">Global Creative Gallery</p>
            </div>

            <div className="flex items-center gap-6">
              <div 
                onClick={() => setCurrency(currency === 'RMB' ? 'USD' : 'RMB')}
                className="flex flex-col items-end gap-1 p-5 bg-white dark:bg-slate-900 rounded-[2.5rem] shadow-xl border border-slate-200 dark:border-slate-800 cursor-pointer hover:border-banana-500/50 transition-all group"
              >
                <div className="flex items-center gap-2 text-[10px] font-black text-slate-400 uppercase tracking-widest group-hover:text-banana-500 transition-colors">
                  <Wallet size={12} /> 总计消费 (点击切换)
                </div>
                <div className="text-3xl font-black text-slate-900 dark:text-white flex items-baseline gap-1">
                  <span className="text-sm text-banana-600 uppercase">{currency}</span>
                  {currency === 'RMB' ? totalCost.rmb.toFixed(2) : totalCost.usd.toFixed(2)}
                </div>
                <div className="text-[8px] text-slate-400 mt-1 flex items-center gap-1">
                  <Info size={10} /> 汇率 1:{EXCHANGE_RATE} | Google 定价图表参考
                </div>
              </div>
              <div className="hidden md:flex flex-col items-center">
                  <div className="text-4xl font-black text-slate-900 dark:text-white">{batches.reduce((acc, b) => acc + b.images.length, 0)}</div>
                  <div className="text-[11px] text-slate-400 dark:text-slate-500 font-black uppercase tracking-[0.2em] mt-2">Works</div>
              </div>
            </div>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-24">
            {batches.map((batch) => (
              <div key={batch.id} className="group relative cursor-pointer" onClick={() => setExpandedBatchId(batch.id)}>
                <div className="aspect-[4/5] relative preserve-3d h-full">
                   {[...batch.images].reverse().slice(-4).map((img, i, arr) => {
                      const totalVisible = arr.length;
                      const indexFromTop = totalVisible - 1 - i;
                      const rotate = indexFromTop * 4; 
                      const translateX = indexFromTop * 10;
                      const translateY = indexFromTop * 4;

                      return (
                        <div 
                          key={img.id}
                          className="absolute inset-0 bg-white dark:bg-slate-900 rounded-[3.5rem] overflow-hidden border border-slate-200 dark:border-slate-800 shadow-[0_20px_50px_-15px_rgba(0,0,0,0.3)] dark:shadow-[0_20px_50px_-15px_rgba(0,0,0,0.7)] transition-all duration-700 ease-out transform origin-bottom-right"
                          style={{ 
                            transform: `rotate(${rotate}deg) translate(${translateX}px, ${translateY}px)`,
                            zIndex: 30 - indexFromTop,
                            opacity: 1 - (indexFromTop * 0.1)
                          }}
                        >
                           <img src={img.url} className="w-full h-full object-cover group-hover:scale-110 transition-transform duration-1000" loading="lazy" />
                           {indexFromTop === 0 && (
                             <div className="absolute top-10 left-10 flex flex-col gap-2">
                                <span className="px-5 py-2 bg-white/60 dark:bg-black/40 backdrop-blur-3xl rounded-full text-[9px] font-black text-slate-900 dark:text-banana-400 border border-white/30 dark:border-white/10 shadow-2xl uppercase tracking-widest w-fit">
                                  {batch.images.length > 1 ? `COLLECTION: ${batch.images.length}P` : `ID: ${img.filename.slice(0,8)}`}
                                </span>
                                <span className="px-4 py-1.5 bg-banana-500 text-slate-950 rounded-full text-[8px] font-black uppercase tracking-tighter w-fit shadow-lg">
                                  {currency === 'RMB' ? `¥ ${batch.totalCostRMB.toFixed(2)}` : `$ ${batch.totalCostUSD.toFixed(3)}`}
                                </span>
                             </div>
                           )}
                        </div>
                      );
                   })}
                </div>
                <div className="mt-14 text-center opacity-0 group-hover:opacity-60 transition-all duration-500 translate-y-4 group-hover:translate-y-0">
                   <p className="text-[10px] text-slate-500 dark:text-slate-400 font-black uppercase tracking-[0.5em]">Spread Collection</p>
                </div>
              </div>
            ))}
            {batches.length === 0 && !isGenerating && (
                <div className="col-span-full py-56 flex flex-col items-center justify-center text-slate-400 dark:text-slate-800 bg-white/50 dark:bg-slate-900/20 border-4 border-dashed border-slate-200 dark:border-slate-800 rounded-[7rem] transition-all">
                    <div className="w-40 h-40 bg-slate-100 dark:bg-slate-800 rounded-full flex items-center justify-center mb-12 animate-pulse shadow-inner">
                      <Sparkles size={64} className="opacity-20 text-banana-600" />
                    </div>
                    <p className="text-2xl font-black tracking-tighter opacity-40">创作库尚无记录</p>
                </div>
            )}
          </div>
        </div>
      </div>

      {expandedBatchId && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-transparent backdrop-blur-none animate-in fade-in duration-700 overflow-hidden">
           <div className="absolute inset-0 bg-black/70 dark:bg-black/90" onClick={() => setExpandedBatchId(null)} />
           <div className="relative w-full h-full flex flex-wrap items-center justify-center p-12 lg:p-24 gap-16 lg:gap-24 animate-in zoom-in-[0.8] duration-1000 overflow-y-auto no-scrollbar">
              {batches.find(b => b.id === expandedBatchId)?.images.map((img, idx) => (
                <div key={img.id} className="w-full max-w-[22rem] aspect-[4/5] bg-slate-900 rounded-[4rem] overflow-hidden border border-white/10 shadow-[0_50px_120px_-20px_rgba(0,0,0,0.8)] animate-float cursor-pointer hover:scale-110 transition-all duration-700 pointer-events-auto group/item" onClick={() => setSelectedImage(img)}>
                    <img src={img.url} className="w-full h-full object-cover transition-transform duration-1000 group-hover/item:scale-110" />
                    <div className="absolute inset-0 bg-gradient-to-t from-black via-black/10 to-transparent opacity-0 group-hover/item:opacity-100 transition-opacity duration-500 p-10 flex flex-col justify-end">
                      <p className="text-[11px] text-white font-bold mb-6 line-clamp-3 italic">"{img.prompt}"</p>
                      <button className="w-full py-4 bg-banana-500 text-slate-950 rounded-[2rem] font-black text-[11px] uppercase">查看全屏</button>
                    </div>
                </div>
              ))}
              <button onClick={() => setExpandedBatchId(null)} className="fixed top-12 right-12 p-5 bg-white/10 hover:bg-white/20 backdrop-blur-3xl rounded-full text-white border border-white/20 shadow-2xl transition-all hover:rotate-90">
                <X size={32} />
              </button>
           </div>
        </div>
      )}

      {selectedImage && <ImageViewer image={selectedImage} isCopied={!!copyStatus[selectedImage.id]} onCopy={() => handleCopyPrompt(selectedImage.prompt, selectedImage.id)} onClose={() => setSelectedImage(null)} onNext={() => navigateImage(1)} onPrev={() => navigateImage(-1)} currency={currency} />}
      <style>{`.preserve-3d { transform-style: preserve-3d; } @keyframes float { 0%, 100% { transform: translateY(0px) rotate(0deg); } 50% { transform: translateY(-30px) rotate(1.5deg); } } .animate-float { animation: float 6s ease-in-out infinite; }`}</style>
    </div>
  );
};

export default App;

import React, { useState, useEffect, useCallback, useRef } from 'react';
import { Sparkles, Download, Loader2, Image as ImageIcon, Check, Activity, Sun, Moon, Layers, X, ChevronLeft, ChevronRight, Wallet, Info, Coins, Zap, Cpu } from 'lucide-react';
import { generateSingleImage, analyzeAndName } from './services/geminiService';
import SettingsPanel from './components/SettingsPanel';
import ImageUploader from './components/ImageUploader';
import ImageViewer from './components/ImageViewer';
import { AspectRatio, ImageSize, GeneratedImage, AIModel, GenerationStep, GeneratedBatch, Currency } from './types';

// 计费标准参考用户提供图表
// 汇率参考: 1 USD ≈ 7.2 RMB
const EXCHANGE_RATE = 7.2;

const getPriceInfo = (model: AIModel, size: ImageSize): { rmb: number, usd: number } => {
  let usd = 0;
  if (model === AIModel.Standard) {
    // Nano Banana (gemini-2.5-flash-image) -> $0.02 - $0.04，按上限 $0.04 计费
    usd = 0.04;
  } else {
    // Nano Banana Pro (gemini-3-pro-image)
    if (size === ImageSize.Size_4K) {
      // 4K (4096x4096) -> $0.24 (2,000 Tokens)
      usd = 0.24;
    } else {
      // 1K (1024x1024) 和 2K (2048x2048) 定价一致 -> $0.134 (1,120 Tokens)
      // 2K 具有最高性价比
      usd = 0.134;
    }
  }
  return { usd, rmb: parseFloat((usd * EXCHANGE_RATE).toFixed(2)) };
};

const App: React.FC = () => {
  const [prompt, setPrompt] = useState('');
  const [inputImages, setInputImages] = useState<File[]>([]);
  const [aspectRatio, setAspectRatio] = useState<AspectRatio>(AspectRatio.Square);
  const [imageSize, setImageSize] = useState<ImageSize>(ImageSize.Size_1K);
  const [batchSize, setBatchSize] = useState<number>(1);
  const [model, setModel] = useState<AIModel>(AIModel.Pro);
  const [isSmartAnalysis, setIsSmartAnalysis] = useState<boolean>(true);
  const [customWidth, setCustomWidth] = useState(1024);
  const [customHeight, setCustomHeight] = useState(1024);
  const [isDarkMode, setIsDarkMode] = useState(true);
  const [currency, setCurrency] = useState<Currency>('RMB');

  const [isGenerating, setIsGenerating] = useState(false);
  const [progress, setProgress] = useState(0);
  const [elapsedTime, setElapsedTime] = useState(0);
  const [steps, setSteps] = useState<GenerationStep[]>([]);
  const [batches, setBatches] = useState<GeneratedBatch[]>([]);
  const [selectedImage, setSelectedImage] = useState<GeneratedImage | null>(null);
  const [expandedBatchId, setExpandedBatchId] = useState<string | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [copyStatus, setCopyStatus] = useState<Record<string, boolean>>({});

  const startTimeRef = useRef<number>(0);

  useEffect(() => {
    if (isDarkMode) document.documentElement.classList.add('dark');
    else document.documentElement.classList.remove('dark');
  }, [isDarkMode]);

  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.ctrlKey && e.key === 'Enter' && !isGenerating) handleGenerate();
      if (selectedImage) {
        if (e.key === 'ArrowLeft') navigateImage(-1);
        if (e.key === 'ArrowRight') navigateImage(1);
        if (e.key === 'Escape') setSelectedImage(null);
      } else if (expandedBatchId && e.key === 'Escape') {
        setExpandedBatchId(null);
      }
    };
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [isGenerating, selectedImage, expandedBatchId, batches, prompt, inputImages]);

  const navigateImage = (direction: number) => {
    const allImages = batches.flatMap(b => b.images);
    if (allImages.length === 0 || !selectedImage) return;
    const currentIndex = allImages.findIndex(img => img.id === selectedImage.id);
    let nextIndex = (currentIndex + direction + allImages.length) % allImages.length;
    setSelectedImage(allImages[nextIndex]);
  };

  const handleGenerate = async () => {
    const safePrompt = (prompt || "").trim();
    if (!safePrompt && inputImages.length === 0) return setError("请提供文本描述或参考图片以开始创作。");

    setIsGenerating(true);
    setError(null);
    setProgress(0);
    startTimeRef.current = performance.now();
    const timer = setInterval(() => setElapsedTime((performance.now() - startTimeRef.current) / 1000), 100);

    try {
      const batchId = Date.now().toString();
      const currentBatchImages: GeneratedImage[] = [];
      const price = getPriceInfo(model, imageSize);

      for (let i = 0; i < batchSize; i++) {
        const batchProgressBase = (i / batchSize) * 100;
        const batchWeight = 100 / batchSize;
        const currentSteps: GenerationStep[] = [
          { id: 'prep', name: `第 ${i+1}/${batchSize} 张：语义解析与意图重构`, status: 'active', duration: null },
          { id: 'env', name: '神经渲染引擎预加载', status: 'pending', duration: null },
          { id: 'render', name: `像素点阵计算 (${model === AIModel.Pro ? imageSize : 'Standard'})`, status: 'pending', duration: null },
          { id: 'post', name: '画质强化与数字归档', status: 'pending', duration: null },
        ];
        setSteps(currentSteps);

        // 步骤1：解析
        const { refinedPrompt, fileName } = await analyzeAndName(safePrompt, inputImages, isSmartAnalysis);
        setProgress(batchProgressBase + (batchWeight * 0.2));
        setSteps(s => s.map(x => x.id === 'prep' ? {...x, status: 'done'} : x.id === 'env' ? {...x, status: 'active'} : x));

        const stepStart = performance.now();

        // 步骤2：预加载反馈
        await new Promise(r => setTimeout(r, 600)); 
        setProgress(batchProgressBase + (batchWeight * 0.4));
        setSteps(s => s.map(x => x.id === 'env' ? {...x, status: 'done'} : x.id === 'render' ? {...x, status: 'active'} : x));

        // 步骤3：核心生成
        const urls = await generateSingleImage(refinedPrompt, inputImages, aspectRatio, imageSize, model, customWidth, customHeight);

        setProgress(batchProgressBase + (batchWeight * 0.9));
        setSteps(s => s.map(x => x.id === 'render' ? {...x, status: 'done'} : x.id === 'post' ? {...x, status: 'active'} : x));

        // 步骤4：收尾
        const totalTimeForOne = (performance.now() - stepStart) / 1000;
        currentBatchImages.push({
          id: `${batchId}-${i}`, batchId, url: urls[0], prompt: safePrompt,
          refinedPrompt: isSmartAnalysis ? refinedPrompt : undefined,
          filename: batchSize > 1 ? `${fileName}-${i + 1}` : fileName,
          timestamp: Date.now(), totalDuration: totalTimeForOne,
          thoughtLog: currentSteps.map(s => ({...s, status: 'done'})),
          costRMB: price.rmb, costUSD: price.usd
        });

        setSteps(s => s.map(x => x.id === 'post' ? {...x, status: 'done'} : x));
        setProgress(batchProgressBase + batchWeight);
      }

      setBatches(prev => [{ 
        id: batchId, images: currentBatchImages, timestamp: Date.now(),
        totalCostRMB: price.rmb * batchSize, totalCostUSD: price.usd * batchSize
      }, ...prev]);
      setProgress(100);
    } catch (err: any) {
      setError(err.message || "由于网络或 API 限制，渲染任务中断。");
    } finally {
      clearInterval(timer);
      setIsGenerating(false);
    }
  };

  const handleCopyPrompt = async (text: string, id: string) => {
    try {
      await navigator.clipboard.writeText(text);
      setCopyStatus({ ...copyStatus, [id]: true });
      setTimeout(() => setCopyStatus(prev => ({ ...prev, [id]: false })), 2000);
    } catch (e) { console.error(e); }
  };

  const totalCost = batches.reduce((acc, b) => ({
    rmb: acc.rmb + b.totalCostRMB,
    usd: acc.usd + b.totalCostUSD
  }), { rmb: 0, usd: 0 });

  const currentPrice = getPriceInfo(model, imageSize);
  const estimatedTotal = {
    rmb: (currentPrice.rmb * batchSize).toFixed(2),
    usd: (currentPrice.usd * batchSize).toFixed(3)
  };

  return (
    <div className="min-h-screen bg-slate-50 dark:bg-slate-950 text-slate-900 dark:text-slate-100 flex flex-col lg:flex-row font-sans transition-all duration-500 overflow-hidden">

      {/* 操作区域 */}
      <div className="w-full lg:w-[460px] p-8 flex flex-col gap-8 border-b lg:border-r border-slate-200 dark:border-slate-800 bg-white/95 dark:bg-slate-900/95 backdrop-blur-3xl z-40 lg:h-screen overflow-y-auto no-scrollbar shadow-2xl">
        <div className="flex items-center justify-between">
          <div className="flex items-center gap-4">
            <div className="w-14 h-14 bg-banana-500 rounded-3xl flex items-center justify-center text-slate-900 shadow-xl shadow-banana-500/30 rotate-6 transition-transform hover:rotate-0">
              <Sparkles size={32} />
            </div>
            <div>
              <h1 className="font-black text-2xl tracking-tight leading-none text-slate-900 dark:text-white">NANO LAB <span className="text-banana-600 dark:text-banana-400">V2.0</span></h1>
              <p className="text-[10px] text-slate-500 mt-2 font-bold uppercase tracking-[0.2em] opacity-60">Visual Creation Engine</p>
            </div>
          </div>
          <button onClick={() => setIsDarkMode(!isDarkMode)} className="p-3.5 rounded-2xl bg-slate-100 dark:bg-slate-800 text-slate-600 dark:text-slate-400 hover:bg-banana-500 hover:text-slate-950 transition-all shadow-sm">
            {isDarkMode ? <Sun size={20} /> : <Moon size={20} />}
          </button>
        </div>

        <div className="space-y-6">
          <textarea
            value={prompt}
            onChange={(e) => setPrompt(e.target.value)}
            placeholder="描述您想让 AI 渲染的画面细节..."
            className="w-full h-40 bg-slate-100/50 dark:bg-slate-800/60 border border-slate-200 dark:border-slate-700 rounded-[2.5rem] p-7 text-sm focus:border-banana-500 focus:ring-4 focus:ring-banana-500/10 outline-none transition-all placeholder:text-slate-400 dark:placeholder:text-slate-500 resize-none shadow-inner text-slate-900 dark:text-slate-100"
          />

          <ImageUploader files={inputImages} onFilesChange={setInputImages} disabled={isGenerating} />

          <SettingsPanel 
            {...{aspectRatio, imageSize, batchSize, model, isSmartAnalysis, customWidth, customHeight}}
            onAspectRatioChange={setAspectRatio} onImageSizeChange={setImageSize} onBatchSizeChange={setBatchSize}
            onModelChange={setModel} onSmartAnalysisChange={setIsSmartAnalysis} onCustomPixelsChange={(w, h) => { setCustomWidth(w); setCustomHeight(h); }}
            disabled={isGenerating}
          />

          <div 
            onClick={() => setCurrency(currency === 'RMB' ? 'USD' : 'RMB')}
            className="p-5 bg-banana-500/5 dark:bg-banana-500/10 rounded-[2.2rem] border border-banana-500/20 flex items-center justify-between cursor-pointer hover:bg-banana-500/10 dark:hover:bg-banana-500/20 transition-all group"
          >
            <div className="flex items-center gap-2 text-xs font-black text-banana-700 dark:text-banana-400 uppercase tracking-widest">
              <Coins size={18} className="group-hover:rotate-12 transition-transform" /> 核心定价 (点击切换)
            </div>
            <div className="flex flex-col items-end">
              <div className="text-sm font-black text-banana-600 dark:text-banana-300">
                {currency === 'RMB' ? `¥ ${currentPrice.rmb.toFixed(2)}` : `$ ${currentPrice.usd.toFixed(3)}`} / 张
              </div>
              <div className="text-[9px] font-bold text-slate-400 uppercase tracking-tighter">
                {model === AIModel.Pro ? `${imageSize} 分辨率` : 'Standard 画质'}
              </div>
            </div>
          </div>
        </div>

        {error && (
          <div className="text-red-600 dark:text-red-400 text-[11px] font-bold bg-red-50 dark:bg-red-900/40 p-5 rounded-3xl border border-red-200 dark:border-red-900/50">
            ⚠️ {error}
          </div>
        )}

        <div className="mt-auto pt-4 flex flex-col gap-6">
          <button
            onClick={handleGenerate}
            disabled={isGenerating}
            className="w-full py-7 bg-gradient-to-br from-banana-400 to-banana-600 hover:from-banana-300 hover:to-banana-500 text-slate-950 font-black text-xl rounded-[2.8rem] shadow-2xl shadow-banana-500/30 transition-all flex flex-col items-center justify-center gap-1 disabled:opacity-40 active:scale-95 group relative overflow-hidden"
          >
            <div className="flex items-center gap-4">
               {isGenerating ? <Loader2 className="animate-spin" size={24} /> : <Zap size={24} className="group-hover:scale-125 transition-transform" />}
               <span className="tracking-tight">{isGenerating ? `核心渲染器工作中...` : `开启艺术创作`}</span>
            </div>
            {!isGenerating && (
              <span className="text-[10px] font-black opacity-80 uppercase tracking-[0.2em] border-t border-slate-900/10 w-2/3 mt-2 pt-1.5">
                预估总消耗 {currency === 'RMB' ? `¥ ${estimatedTotal.rmb}` : `$ ${estimatedTotal.usd}`}
              </span>
            )}
          </button>

          {isGenerating && (
            <div className="space-y-6 p-7 bg-white dark:bg-slate-800/80 rounded-[3rem] border border-slate-200 dark:border-slate-700 shadow-2xl animate-in slide-in-from-bottom-4 transition-all">
               <div className="flex flex-col gap-3">
                 <div className="flex justify-between items-center text-[10px] font-black text-slate-500 dark:text-slate-400 uppercase tracking-widest">
                   <div className="flex items-center gap-2">
                      <Activity size={16} className="text-banana-500 animate-pulse" />
                      渲染进度
                   </div>
                   <span className="font-mono text-banana-600 text-xs">{Math.round(progress)}%</span>
                 </div>
                 <div className="h-3 w-full bg-slate-100 dark:bg-slate-900 rounded-full overflow-hidden p-[2px] shadow-inner border border-slate-200 dark:border-slate-800">
                   <div 
                    className="h-full bg-gradient-to-r from-banana-400 via-banana-500 to-banana-600 rounded-full transition-all duration-500 ease-out shadow-[0_0_15px_rgba(234,179,8,0.5)]" 
                    style={{ width: `${progress}%` }} 
                   />
                 </div>
               </div>

               <div className="space-y-4">
                 {steps.map(s => (
                   <div key={s.id} className="flex items-center justify-between text-[11px]">
                     <div className="flex items-center gap-3">
                       {s.status === 'done' ? (
                         <div className="w-5 h-5 rounded-full bg-green-500 flex items-center justify-center text-white shadow-lg shadow-green-500/20">
                           <Check size={12} strokeWidth={4} />
                         </div>
                       ) : s.status === 'active' ? (
                         <div className="w-5 h-5 rounded-full bg-banana-500 flex items-center justify-center text-slate-900">
                           <Loader2 size={12} className="animate-spin" />
                         </div>
                       ) : (
                         <div className="w-5 h-5 rounded-full border-2 border-slate-200 dark:border-slate-700 bg-white dark:bg-slate-900" />
                       )}
                       <span className={`font-bold transition-all duration-300 ${s.status === 'active' ? 'text-banana-600 dark:text-banana-400 translate-x-1 scale-105' : s.status === 'done' ? 'text-slate-400 dark:text-slate-600 opacity-60' : 'text-slate-300 dark:text-slate-800'}`}>
                         {s.name}
                       </span>
                     </div>
                     {s.status === 'active' && <span className="text-[10px] font-mono font-black text-banana-500 animate-pulse">{elapsedTime.toFixed(1)}s</span>}
                   </div>
                 ))}
               </div>
            </div>
          )}
        </div>
      </div>

      {/* 画廊展示区域 */}
      <div className={`flex-1 p-8 lg:p-14 overflow-y-auto lg:h-screen scroll-smooth transition-all duration-1000 bg-slate-50 dark:bg-slate-950 ${expandedBatchId || selectedImage ? 'blur-2xl grayscale-[0.3] brightness-50 pointer-events-none' : ''}`}>
        <div className="max-w-7xl mx-auto">
          <div className="flex items-start justify-between mb-20">
            <div>
              <h2 className="text-4xl font-black text-slate-900 dark:text-white tracking-tighter flex items-center gap-5">
                <div className="p-4 bg-banana-500/10 rounded-[2rem] shadow-sm"><ImageIcon className="text-banana-500" size={36} /></div>
                画廊
              </h2>
              <p className="text-sm text-slate-400 dark:text-slate-500 mt-3 uppercase tracking-[0.3em] font-bold opacity-50">Global Creative Gallery</p>
            </div>

            <div className="flex items-center gap-6">
              <div 
                onClick={() => setCurrency(currency === 'RMB' ? 'USD' : 'RMB')}
                className="flex flex-col items-end gap-1 p-5 bg-white dark:bg-slate-900 rounded-[2.5rem] shadow-xl border border-slate-200 dark:border-slate-800 cursor-pointer hover:border-banana-500/50 transition-all group"
              >
