           </div>
        </div>
      )}

      {selectedImage && <ImageViewer image={selectedImage} isCopied={!!copyStatus[selectedImage.id]} onCopy={() => handleCopyPrompt(selectedImage.prompt, selectedImage.id)} onClose={() => setSelectedImage(null)} onNext={() => navigateImage(1)} onPrev={() => navigateImage(-1)} currency={currency} />}
      <style>{`
        .preserve-3d { transform-style: preserve-3d; } 
        @keyframes float { 0%, 100% { transform: translateY(0px) rotate(0deg); } 50% { transform: translateY(-30px) rotate(1.5deg); } } 
        .animate-float { animation: float 6s ease-in-out infinite; }
        .animate-spin-slow { animation: spin 4s linear infinite; }
        @keyframes spin { from { transform: rotate(0deg); } to { transform: rotate(360deg); } }
      `}</style>
    </div>
  );
};

