        <div className="grid grid-cols-2 gap-1.5 bg-slate-100 dark:bg-slate-900/50 p-1.5 rounded-[1.8rem] border border-slate-200 dark:border-slate-700/30">
          {[AIModel.Standard, AIModel.Pro].map(m => (
            <button
              key={m} disabled={disabled} onClick={() => onModelChange(m)}
              className={`py-3 rounded-[1.5rem] text-[11px] font-black transition-all ${
                model === m ? 'bg-banana-500 text-slate-900 shadow-xl' : 'text-slate-500 hover:text-slate-700 dark:hover:text-slate-300'
              }`}
            >
              {m === AIModel.Pro ? 'Banana Pro' : 'Standard'}
            </button>
          ))}
        </div>
      </div>

      <button
        disabled={disabled} onClick={() => onSmartAnalysisChange(!isSmartAnalysis)}
        className={`w-full flex items-center justify-between py-4 px-5 rounded-[1.8rem] border transition-all ${isSmartAnalysis ? 'bg-banana-500/10 border-banana-500 text-banana-600 dark:text-banana-400 shadow-sm' : 'bg-slate-50 dark:bg-slate-900/50 border-slate-200 dark:border-slate-800 text-slate-500'}`}
      >
        <div className="flex items-center gap-3">
          <BrainCircuit size={16} />
          <span className="text-[11px] font-black uppercase tracking-tight">AI 语义强化分析</span>
        </div>
        <div className={`w-9 h-5 rounded-full relative transition-colors ${isSmartAnalysis ? 'bg-banana-500 shadow-[0_0_10px_rgba(234,179,8,0.5)]' : 'bg-slate-300 dark:bg-slate-700'}`}>
          <div className={`absolute top-0.5 w-4 h-4 bg-white rounded-full transition-all shadow-sm ${isSmartAnalysis ? 'left-4.5' : 'left-0.5'}`} />
        </div>
      </button>

      <div className="space-y-3">
        <div className="flex items-center justify-between px-1">
           <label className="text-[10px] text-slate-500 dark:text-slate-400 font-black uppercase flex items-center gap-2">
             <Layout size={14} /> 画幅比例
           </label>
           <div className="flex items-center bg-slate-100 dark:bg-slate-900 p-1 rounded-2xl border border-slate-200 dark:border-slate-800">
              <button onClick={() => setOrientation('landscape')} className={`flex items-center gap-1.5 px-4 py-1.5 rounded-xl text-[10px] font-black transition-all ${orientation === 'landscape' ? 'bg-white dark:bg-slate-800 text-banana-600 dark:text-banana-400 shadow-sm' : 'text-slate-400'}`}><MonitorIcon size={12} /> 横</button>
              <button onClick={() => setOrientation('portrait')} className={`flex items-center gap-1.5 px-4 py-1.5 rounded-xl text-[10px] font-black transition-all ${orientation === 'portrait' ? 'bg-white dark:bg-slate-800 text-banana-600 dark:text-banana-400 shadow-sm' : 'text-slate-400'}`}><Smartphone size={12} /> 竖</button>
           </div>
        </div>
        <div className="grid grid-cols-2 gap-2">
           {ratioGroups.map((g) => {
             const targetRatio = orientation === 'landscape' ? g.landscape : g.portrait;
             const isActive = aspectRatio === targetRatio;
             return (
               <button key={g.label} onClick={() => onAspectRatioChange(targetRatio)} className={`flex items-center py-3.5 px-4 rounded-[1.6rem] border text-[11px] font-black transition-all ${isActive ? 'bg-banana-500/10 border-banana-500 text-banana-600 dark:text-banana-400 shadow-sm' : 'bg-slate-50 dark:bg-slate-900/30 border-slate-200 dark:border-slate-800 text-slate-500 hover:border-slate-300 dark:hover:border-slate-700'}`}>
                 <AspectRatioIcon ratio={targetRatio} active={isActive} /> {g.label}
               </button>
             );
           })}
        </div>
      </div>

      <div className="space-y-5 px-1">
        <div className="space-y-3">
          <div className="flex justify-between items-center">
            <label className="text-[10px] text-slate-500 dark:text-slate-400 font-black uppercase flex items-center gap-2"><Layers size={14} /> 批量数</label>
            <span className="text-banana-600 dark:text-banana-400 font-black text-[11px] bg-banana-500/10 px-3 py-1 rounded-xl">{batchSize} 张</span>
          </div>
          <input type="range" min="1" max="10" step="1" value={batchSize} disabled={disabled} onChange={(e) => onBatchSizeChange(parseInt(e.target.value))} className="w-full h-2 bg-slate-200 dark:bg-slate-700 rounded-full appearance-none cursor-pointer accent-banana-500" />
        </div>
        <div className="space-y-3">
          <label className="text-[10px] text-slate-500 dark:text-slate-400 font-black uppercase flex items-center gap-2"><Monitor size={14} /> 渲染质量 (仅 Pro 可选)</label>
          <div className="grid grid-cols-3 gap-1.5">
            {[ImageSize.Size_1K, ImageSize.Size_2K, ImageSize.Size_4K].map(s => (
              <button key={s} disabled={disabled || model === AIModel.Standard} onClick={() => onImageSizeChange(s)} className={`py-3.5 rounded-[1.4rem] border text-[11px] font-black transition-all ${imageSize === s && model === AIModel.Pro ? 'bg-slate-800 dark:bg-white text-white dark:text-slate-950 border-slate-900 dark:border-white shadow-lg' : 'bg-white dark:bg-slate-900/50 border-slate-200 dark:border-slate-800 text-slate-500'} ${model === AIModel.Standard ? 'opacity-30' : ''}`}>{s}</button>
            ))}
          </div>
        </div>
      </div>
    </div>
  );
};

