import { AspectRatio, ImageSize, GeneratedImage, AIModel, GenerationStep, GeneratedBatch, Currency, EditingImage } from './types';

const EXCHANGE_RATE = 7.2;

const getPriceInfo = (model: AIModel, size: ImageSize): { rmb: number, usd: number } => {
  let usd = 0;
  if (model === AIModel.Standard) {
    usd = 0.04;
  } else {
    if (size === ImageSize.Size_4K) {
      usd = 0.24;
    } else {
      usd = 0.134;
    }
  }
  return { usd, rmb: parseFloat((usd * EXCHANGE_RATE).toFixed(2)) };
};

const App: React.FC = () => {
  const [prompt, setPrompt] = useState('');
  const [inputImages, setInputImages] = useState<File[]>([]);
  const [aspectRatio, setAspectRatio] = useState<AspectRatio>(AspectRatio.Square);
  const [imageSize, setImageSize] = useState<ImageSize>(ImageSize.Size_1K);
  const [batchSize, setBatchSize] = useState<number>(1);
  const [model, setModel] = useState<AIModel>(AIModel.Pro);
  const [isSmartAnalysis, setIsSmartAnalysis] = useState<boolean>(true);
  const [customWidth, setCustomWidth] = useState(1024);
  const [customHeight, setCustomHeight] = useState(1024);
  const [isDarkMode, setIsDarkMode] = useState(true);
  const [currency, setCurrency] = useState<Currency>('RMB');
  const [uiScale, setUiScale] = useState(1.0);
  const [showUISettings, setShowUISettings] = useState(false);

  const [isGenerating, setIsGenerating] = useState(false);
  const [progress, setProgress] = useState(0);
  const [elapsedTime, setElapsedTime] = useState(0);
  const [steps, setSteps] = useState<GenerationStep[]>([]);
  const [batches, setBatches] = useState<GeneratedBatch[]>([]);
  const [selectedImage, setSelectedImage] = useState<GeneratedImage | null>(null);
  const [expandedBatchId, setExpandedBatchId] = useState<string | null>(null);
  const [editingImage, setEditingImage] = useState<EditingImage | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [copyStatus, setCopyStatus] = useState<Record<string, boolean>>({});

  const startTimeRef = useRef<number>(0);

  useEffect(() => {
    if (isDarkMode) document.documentElement.classList.add('dark');
    else document.documentElement.classList.remove('dark');
  }, [isDarkMode]);

  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.ctrlKey && e.key === 'Enter' && !isGenerating) handleGenerate();
      if (selectedImage) {
        if (e.key === 'ArrowLeft') navigateImage(-1);
        if (e.key === 'ArrowRight') navigateImage(1);
        if (e.key === 'Escape') setSelectedImage(null);
      } else if (expandedBatchId && e.key === 'Escape') {
        setExpandedBatchId(null);
      } else if (editingImage && e.key === 'Escape') {
        setEditingImage(null);
      }
    };
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [isGenerating, selectedImage, expandedBatchId, batches, prompt, inputImages, editingImage]);

  const navigateImage = (direction: number) => {
    const allImages = batches.flatMap(b => b.images);
    if (allImages.length === 0 || !selectedImage) return;
    const currentIndex = allImages.findIndex(img => img.id === selectedImage.id);
    let nextIndex = (currentIndex + direction + allImages.length) % allImages.length;
    setSelectedImage(allImages[nextIndex]);
  };

  const handleGenerate = async () => {
    const safePrompt = (prompt || "").trim();
    if (!safePrompt && inputImages.length === 0) return setError("请提供文本描述或参考图片以开始创作。");

    setIsGenerating(true);
    setError(null);
    setProgress(0);
    startTimeRef.current = performance.now();
    const timer = setInterval(() => setElapsedTime((performance.now() - startTimeRef.current) / 1000), 100);

    try {
      const batchId = Date.now().toString();
      const currentBatchImages: GeneratedImage[] = [];
      const price = getPriceInfo(model, imageSize);

      for (let i = 0; i < batchSize; i++) {
        const batchProgressBase = (i / batchSize) * 100;
        const batchWeight = 100 / batchSize;
        const currentSteps: GenerationStep[] = [
          { id: 'prep', name: `第 ${i+1}/${batchSize} 张：语义解析与意图重构`, status: 'active', duration: null },
          { id: 'env', name: '神经渲染引擎预加载', status: 'pending', duration: null },
          { id: 'render', name: `像素点阵计算 (${model === AIModel.Pro ? imageSize : 'Standard'})`, status: 'pending', duration: null },
          { id: 'post', name: '画质强化与数字归档', status: 'pending', duration: null },
        ];
        setSteps(currentSteps);

        const { refinedPrompt, fileName } = await analyzeAndName(safePrompt, inputImages, isSmartAnalysis);
        setProgress(batchProgressBase + (batchWeight * 0.2));
        setSteps(s => s.map(x => x.id === 'prep' ? {...x, status: 'done'} : x.id === 'env' ? {...x, status: 'active'} : x));

        const stepStart = performance.now();
        await new Promise(r => setTimeout(r, 600)); 
        setProgress(batchProgressBase + (batchWeight * 0.4));
        setSteps(s => s.map(x => x.id === 'env' ? {...x, status: 'done'} : x.id === 'render' ? {...x, status: 'active'} : x));

        const urls = await generateSingleImage(refinedPrompt, inputImages, aspectRatio, imageSize, model, customWidth, customHeight);
        setProgress(batchProgressBase + (batchWeight * 0.9));
        setSteps(s => s.map(x => x.id === 'render' ? {...x, status: 'done'} : x.id === 'post' ? {...x, status: 'active'} : x));

        const totalTimeForOne = (performance.now() - stepStart) / 1000;
        currentBatchImages.push({
          id: `${batchId}-${i}`, batchId, url: urls[0], prompt: safePrompt,
          refinedPrompt: isSmartAnalysis ? refinedPrompt : undefined,
          filename: batchSize > 1 ? `${fileName}-${i + 1}` : fileName,
          timestamp: Date.now(), totalDuration: totalTimeForOne,
          thoughtLog: currentSteps.map(s => ({...s, status: 'done'})),
          costRMB: price.rmb, costUSD: price.usd
        });

        setSteps(s => s.map(x => x.id === 'post' ? {...x, status: 'done'} : x));
        setProgress(batchProgressBase + batchWeight);
      }

      setBatches(prev => [{ 
        id: batchId, images: currentBatchImages, timestamp: Date.now(),
        totalCostRMB: price.rmb * batchSize, totalCostUSD: price.usd * batchSize
      }, ...prev]);
      setProgress(100);
    } catch (err: any) {
      setError(err.message || "由于网络或 API 限制，渲染任务中断。");
    } finally {
      clearInterval(timer);
      setIsGenerating(false);
    }
  };

  const handleCopyPrompt = async (text: string, id: string) => {
    try {
      await navigator.clipboard.writeText(text);
      setCopyStatus({ ...copyStatus, [id]: true });
      setTimeout(() => setCopyStatus(prev => ({ ...prev, [id]: false })), 2000);
    } catch (e) { console.error(e); }
  };

  const handleEditorDone = (blob: Blob) => {
    const file = new File([blob], "edited-nano.png", { type: "image/png" });
    setInputImages(prev => [file, ...prev]);
    setEditingImage(null);
  };

  const totalCost = batches.reduce((acc, b) => ({
    rmb: acc.rmb + b.totalCostRMB,
    usd: acc.usd + b.totalCostUSD
  }), { rmb: 0, usd: 0 });

  const currentPrice = getPriceInfo(model, imageSize);
  const estimatedTotal = {
    rmb: (currentPrice.rmb * batchSize).toFixed(2),
    usd: (currentPrice.usd * batchSize).toFixed(3)
  };

  return (
    <div className="min-h-screen bg-slate-50 dark:bg-slate-950 text-slate-900 dark:text-slate-100 flex flex-col lg:flex-row font-sans transition-all duration-500 overflow-hidden">

      {/* 操作区域 */}
      <div 
        style={{ fontSize: `${uiScale * 100}%` }}
        className="w-full lg:w-[480px] p-6 flex flex-col gap-5 border-b lg:border-r border-slate-200 dark:border-slate-800 bg-white/95 dark:bg-slate-900/95 backdrop-blur-3xl z-40 lg:h-screen overflow-y-auto no-scrollbar shadow-2xl relative"
      >
        <div className="flex items-center justify-between sticky top-0 bg-inherit z-50 py-2">
          <div className="flex items-center gap-3">
            <div className="w-12 h-12 bg-banana-500 rounded-2xl flex items-center justify-center text-slate-900 shadow-xl shadow-banana-500/30 transition-transform hover:scale-110">
              <Sparkles size={28} />
            </div>
            <div>
              <h1 className="font-black text-xl tracking-tight leading-none text-slate-900 dark:text-white uppercase">Nano Lab <span className="text-banana-600 dark:text-banana-400">V2</span></h1>
              <p className="text-[9px] text-slate-500 mt-1 font-black uppercase tracking-widest opacity-60">Visual Engine</p>
            </div>
          </div>
          <div className="flex items-center gap-2">
             <button 
                onClick={() => setShowUISettings(!showUISettings)} 
                className={`p-2.5 rounded-xl transition-all ${showUISettings ? 'bg-banana-500 text-slate-900 shadow-lg' : 'bg-slate-100 dark:bg-slate-800 text-slate-500 hover:text-slate-900 dark:hover:text-white'}`}
                title="UI 设置"
              >
                <Settings size={18} className={showUISettings ? 'animate-spin-slow' : ''} />
              </button>
              <button onClick={() => setIsDarkMode(!isDarkMode)} className="p-2.5 rounded-xl bg-slate-100 dark:bg-slate-800 text-slate-600 dark:text-slate-400 hover:bg-banana-500 hover:text-slate-950 transition-all">
                {isDarkMode ? <Sun size={18} /> : <Moon size={18} />}
              </button>
          </div>
        </div>

        {showUISettings && (
          <div className="p-5 bg-slate-100 dark:bg-slate-800 rounded-3xl border border-slate-200 dark:border-slate-700 animate-in slide-in-from-top-2 duration-300">
             <div className="flex items-center justify-between mb-4">
                <span className="text-[10px] font-black uppercase text-slate-500 tracking-widest">UI 缩放比例</span>
                <span className="text-[10px] font-black text-banana-500">{Math.round(uiScale * 100)}%</span>
             </div>
             <input 
                type="range" min="0.8" max="1.3" step="0.05" 
                value={uiScale} 
                onChange={(e) => setUiScale(parseFloat(e.target.value))}
                className="w-full h-1.5 bg-slate-200 dark:bg-slate-700 rounded-full appearance-none cursor-pointer accent-banana-500" 
              />
          </div>
        )}

        <div className="space-y-4 flex-1">
          <div className="relative">
            <textarea
              value={prompt}
              onChange={(e) => setPrompt(e.target.value)}
              placeholder="输入灵感画面描述..."
              className="w-full h-32 bg-slate-100/50 dark:bg-slate-800/60 border border-slate-200 dark:border-slate-700 rounded-[2rem] p-6 text-sm focus:border-banana-500 focus:ring-4 focus:ring-banana-500/10 outline-none transition-all placeholder:text-slate-400 dark:placeholder:text-slate-500 resize-none shadow-inner text-slate-900 dark:text-slate-100 font-medium"
            />
          </div>

          <ImageUploader 
            files={inputImages} 
            onFilesChange={setInputImages} 
            disabled={isGenerating} 
            onEdit={(file) => setEditingImage({ url: URL.createObjectURL(file), name: file.name, type: 'local' })}
          />

          <SettingsPanel 
            {...{aspectRatio, imageSize, batchSize, model, isSmartAnalysis, customWidth, customHeight}}
            onAspectRatioChange={setAspectRatio} onImageSizeChange={setImageSize} onBatchSizeChange={setBatchSize}
            onModelChange={setModel} onSmartAnalysisChange={setIsSmartAnalysis} onCustomPixelsChange={(w, h) => { setCustomWidth(w); setCustomHeight(h); }}
            disabled={isGenerating}
          />

          <div 
            onClick={() => setCurrency(currency === 'RMB' ? 'USD' : 'RMB')}
            className="p-4 bg-banana-500/5 dark:bg-banana-500/10 rounded-3xl border border-banana-500/20 flex items-center justify-between cursor-pointer hover:bg-banana-500/10 dark:hover:bg-banana-500/20 transition-all group"
          >
            <div className="flex items-center gap-2 text-xs font-black text-banana-700 dark:text-banana-400 uppercase tracking-widest">
              <Coins size={16} className="group-hover:rotate-12 transition-transform" /> 引擎计费
            </div>
            <div className="flex flex-col items-end">
              <div className="text-sm font-black text-banana-600 dark:text-banana-300">
                {currency === 'RMB' ? `¥ ${currentPrice.rmb.toFixed(2)}` : `$ ${currentPrice.usd.toFixed(3)}`} <span className="text-[10px] font-bold opacity-60">/ 张</span>
              </div>
            </div>
          </div>
        </div>

        {error && (
          <div className="text-red-600 dark:text-red-400 text-[11px] font-bold bg-red-50 dark:bg-red-900/40 p-4 rounded-2xl border border-red-200 dark:border-red-900/50">
            ⚠️ {error}
          </div>
        )}

        <div className="pt-2 flex flex-col gap-4">
          <button
            onClick={handleGenerate}
            disabled={isGenerating}
            className="w-full py-6 bg-gradient-to-br from-banana-400 to-banana-600 hover:from-banana-300 hover:to-banana-500 text-slate-950 font-black text-lg rounded-[2.2rem] shadow-2xl shadow-banana-500/30 transition-all flex flex-col items-center justify-center gap-1 disabled:opacity-40 active:scale-95 group relative overflow-hidden"
          >
            <div className="flex items-center gap-3">
               {isGenerating ? <Loader2 className="animate-spin" size={20} /> : <Zap size={20} className="group-hover:scale-125 transition-transform" />}
               <span className="tracking-tight">{isGenerating ? `视觉神经渲染中...` : `开启艺术创作`}</span>
            </div>
            {!isGenerating && (
              <span className="text-[9px] font-black opacity-80 uppercase tracking-widest border-t border-slate-900/10 w-1/2 mt-1.5 pt-1">
                预计消耗 {currency === 'RMB' ? `¥ ${estimatedTotal.rmb}` : `$ ${estimatedTotal.usd}`}
              </span>
            )}
          </button>

          {isGenerating && (
            <div className="space-y-4 p-5 bg-white dark:bg-slate-800/80 rounded-[2.5rem] border border-slate-200 dark:border-slate-700 shadow-2xl animate-in slide-in-from-bottom-4 transition-all">
               <div className="flex flex-col gap-2">
                 <div className="flex justify-between items-center text-[10px] font-black text-slate-500 dark:text-slate-400 uppercase tracking-widest">
                   <div className="flex items-center gap-2">
                      <Activity size={14} className="text-banana-500 animate-pulse" />
                      当前进度
                   </div>
                   <span className="font-mono text-banana-600">{Math.round(progress)}%</span>
                 </div>
                 <div className="h-2 w-full bg-slate-100 dark:bg-slate-900 rounded-full overflow-hidden p-[1px] border border-slate-200 dark:border-slate-800 shadow-inner">
                   <div 
                    className="h-full bg-gradient-to-r from-banana-400 to-banana-600 rounded-full transition-all duration-500 ease-out shadow-[0_0_10px_rgba(234,179,8,0.5)]" 
                    style={{ width: `${progress}%` }} 
                   />
                 </div>
               </div>

               <div className="space-y-2.5">
                 {steps.map(s => (
                   <div key={s.id} className="flex items-center justify-between text-[10px]">
                     <div className="flex items-center gap-2.5">
                       {s.status === 'done' ? (
                         <div className="w-4 h-4 rounded-full bg-green-500 flex items-center justify-center text-white shadow shadow-green-500/20">
                           <Check size={10} strokeWidth={4} />
                         </div>
                       ) : s.status === 'active' ? (
                         <div className="w-4 h-4 rounded-full bg-banana-500 flex items-center justify-center text-slate-900">
                           <Loader2 size={10} className="animate-spin" />
                         </div>
                       ) : (
                         <div className="w-4 h-4 rounded-full border border-slate-200 dark:border-slate-700 bg-white dark:bg-slate-900" />
                       )}
                       <span className={`font-bold transition-all duration-300 ${s.status === 'active' ? 'text-banana-600 dark:text-banana-400 translate-x-1' : s.status === 'done' ? 'text-slate-400 dark:text-slate-600 opacity-60' : 'text-slate-300 dark:text-slate-800'}`}>
                         {s.name}
                       </span>
                     </div>
                     {s.status === 'active' && <span className="text-[9px] font-mono font-black text-banana-500 animate-pulse">{elapsedTime.toFixed(1)}s</span>}
                   </div>
                 ))}
               </div>
            </div>
          )}
        </div>
      </div>

      {/* 画廊展示区域 */}
      <div className={`flex-1 p-8 lg:p-14 overflow-y-auto lg:h-screen scroll-smooth transition-all duration-1000 bg-slate-50 dark:bg-slate-950 ${expandedBatchId || selectedImage || editingImage ? 'blur-2xl grayscale-[0.3] brightness-50 pointer-events-none' : ''}`}>
        <div className="max-w-7xl mx-auto">
          <div className="flex items-start justify-between mb-20">
            <div>
              <h2 className="text-4xl font-black text-slate-900 dark:text-white tracking-tighter flex items-center gap-5">
                <div className="p-4 bg-banana-500/10 rounded-[2rem] shadow-sm"><ImageIcon className="text-banana-500" size={36} /></div>
                画廊
              </h2>
              <p className="text-sm text-slate-400 dark:text-slate-500 mt-3 uppercase tracking-[0.3em] font-bold opacity-50">Global Creative Gallery</p>
            </div>

            <div className="flex items-center gap-6">
              <div 
                onClick={() => setCurrency(currency === 'RMB' ? 'USD' : 'RMB')}
                className="flex flex-col items-end gap-1 p-5 bg-white dark:bg-slate-900 rounded-[2.5rem] shadow-xl border border-slate-200 dark:border-slate-800 cursor-pointer hover:border-banana-500/50 transition-all group"
              >
                <div className="flex items-center gap-2 text-[10px] font-black text-slate-400 uppercase tracking-widest group-hover:text-banana-500 transition-colors">
                  <Wallet size={12} /> 总计消费
                </div>
                <div className="text-3xl font-black text-slate-900 dark:text-white flex items-baseline gap-1">
                  <span className="text-sm text-banana-600 uppercase">{currency}</span>
                  {currency === 'RMB' ? totalCost.rmb.toFixed(2) : totalCost.usd.toFixed(2)}
                </div>
                <div className="text-[8px] text-slate-400 mt-1 flex items-center gap-1 font-bold">
                  <Info size={10} /> 官方定价图表参考 | 汇率 1:{EXCHANGE_RATE}
                </div>
              </div>
              <div className="hidden md:flex flex-col items-center">
                  <div className="text-4xl font-black text-slate-900 dark:text-white">{batches.reduce((acc, b) => acc + b.images.length, 0)}</div>
                  <div className="text-[11px] text-slate-400 dark:text-slate-500 font-black uppercase tracking-[0.2em] mt-2">Captured</div>
              </div>
            </div>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-24">
            {batches.map((batch) => (
              <div key={batch.id} className="group relative cursor-pointer" onClick={() => setExpandedBatchId(batch.id)}>
                <div className="aspect-[4/5] relative preserve-3d h-full">
                   {[...batch.images].reverse().slice(-4).map((img, i, arr) => {
                      const totalVisible = arr.length;
                      const indexFromTop = totalVisible - 1 - i;
                      const rotate = indexFromTop * 4; 
                      const translateX = indexFromTop * 10;
                      const translateY = indexFromTop * 4;

                      return (
                        <div 
                          key={img.id}
                          className="absolute inset-0 bg-white dark:bg-slate-900 rounded-[3.5rem] overflow-hidden border border-slate-200 dark:border-slate-800 shadow-[0_20px_50px_-15px_rgba(0,0,0,0.3)] dark:shadow-[0_20px_50px_-15px_rgba(0,0,0,0.7)] transition-all duration-700 ease-out transform origin-bottom-right"
                          style={{ 
                            transform: `rotate(${rotate}deg) translate(${translateX}px, ${translateY}px)`,
                            zIndex: 30 - indexFromTop,
                            opacity: 1 - (indexFromTop * 0.1)
                          }}
                        >
                           <img src={img.url} className="w-full h-full object-cover group-hover:scale-110 transition-transform duration-1000" loading="lazy" />
                           {indexFromTop === 0 && (
                             <div className="absolute top-10 left-10 flex flex-col gap-2">
                                <span className="px-5 py-2 bg-white/60 dark:bg-black/40 backdrop-blur-3xl rounded-full text-[9px] font-black text-slate-900 dark:text-banana-400 border border-white/30 dark:border-white/10 shadow-2xl uppercase tracking-widest w-fit">
                                  {batch.images.length > 1 ? `COLLECTION: ${batch.images.length}P` : `ID: ${img.filename.slice(0,8)}`}
                                </span>
                                <span className="px-4 py-1.5 bg-banana-500 text-slate-950 rounded-full text-[8px] font-black uppercase tracking-tighter w-fit shadow-lg">
                                  {currency === 'RMB' ? `¥ ${batch.totalCostRMB.toFixed(2)}` : `$ ${batch.totalCostUSD.toFixed(3)}`}
                                </span>
                             </div>
                           )}
                        </div>
                      );
                   })}
                </div>
                <div className="mt-14 text-center opacity-0 group-hover:opacity-60 transition-all duration-500 translate-y-4 group-hover:translate-y-0">
                   <p className="text-[10px] text-slate-500 dark:text-slate-400 font-black uppercase tracking-[0.5em]">Spread Collection</p>
                </div>
              </div>
            ))}
            {batches.length === 0 && !isGenerating && (
                <div className="col-span-full py-56 flex flex-col items-center justify-center text-slate-400 dark:text-slate-800 bg-white/50 dark:bg-slate-900/20 border-4 border-dashed border-slate-200 dark:border-slate-800 rounded-[7rem] transition-all">
                    <div className="w-40 h-40 bg-slate-100 dark:bg-slate-800 rounded-full flex items-center justify-center mb-12 animate-pulse shadow-inner">
                      <Sparkles size={64} className="opacity-20 text-banana-600" />
                    </div>
                    <p className="text-2xl font-black tracking-tighter opacity-40">创作库尚无记录</p>
                </div>
            )}
          </div>
        </div>
      </div>

      {expandedBatchId && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-transparent backdrop-blur-none animate-in fade-in duration-700 overflow-hidden">
           <div className="absolute inset-0 bg-black/70 dark:bg-black/90" onClick={() => setExpandedBatchId(null)} />
           <div className="relative w-full h-full flex flex-wrap items-center justify-center p-12 lg:p-24 gap-16 lg:gap-24 animate-in zoom-in-[0.8] duration-1000 overflow-y-auto no-scrollbar">
              {batches.find(b => b.id === expandedBatchId)?.images.map((img, idx) => (
                <div key={img.id} className="w-full max-w-[22rem] aspect-[4/5] bg-slate-900 rounded-[4rem] overflow-hidden border border-white/10 shadow-[0_50px_120px_-20px_rgba(0,0,0,0.8)] animate-float cursor-pointer hover:scale-110 transition-all duration-700 pointer-events-auto group/item" onClick={() => setSelectedImage(img)}>
                    <img src={img.url} className="w-full h-full object-cover transition-transform duration-1000 group-hover/item:scale-110" />
                    <div className="absolute inset-0 bg-gradient-to-t from-black via-black/10 to-transparent opacity-0 group-hover/item:opacity-100 transition-opacity duration-500 p-10 flex flex-col justify-end">
                      <p className="text-[11px] text-white font-bold mb-6 line-clamp-3 italic">"{img.prompt}"</p>
                      <button className="w-full py-4 bg-banana-500 text-slate-950 rounded-[2rem] font-black text-[11px] uppercase">查看全屏</button>
                    </div>
                </div>
              ))}
              <button onClick={() => setExpandedBatchId(null)} className="fixed top-12 right-12 p-5 bg-white/10 hover:bg-white/20 backdrop-blur-3xl rounded-full text-white border border-white/20 shadow-2xl transition-all hover:rotate-90">
                <X size={32} />
              </button>
           </div>
        </div>
      )}

      {selectedImage && (
        <ImageViewer 
          image={selectedImage} 
          isCopied={!!copyStatus[selectedImage.id]} 
          onCopy={() => handleCopyPrompt(selectedImage.prompt, selectedImage.id)} 
          onClose={() => setSelectedImage(null)} 
          onNext={() => navigateImage(1)} 
          onPrev={() => navigateImage(-1)} 
          onEdit={() => { setEditingImage({ url: selectedImage.url, name: selectedImage.filename, type: 'generated' }); setSelectedImage(null); }}
          currency={currency} 
        />
      )}

      {editingImage && (
        <ImageEditor 
          image={editingImage} 
          onClose={() => setEditingImage(null)} 
          onDone={handleEditorDone}
        />
      )}

      <style>{`
        .preserve-3d { transform-style: preserve-3d; } 
        @keyframes float { 0%, 100% { transform: translateY(0px) rotate(0deg); } 50% { transform: translateY(-30px) rotate(1.5deg); } } 
        .animate-float { animation: float 6s ease-in-out infinite; }
        .animate-spin-slow { animation: spin 4s linear infinite; }
        @keyframes spin { from { transform: rotate(0deg); } to { transform: rotate(360deg); } }
      `}</style>
    </div>
  );
};

export default App;

import React, { useCallback, useState } from 'react';
import { Upload, X, ImagePlus, ClipboardPaste, AlertCircle, Edit3 } from 'lucide-react';

interface ImageUploaderProps {
  files: File[];
  onFilesChange: (files: File[]) => void;
  disabled: boolean;
  onEdit: (file: File) => void;
}

const ImageUploader: React.FC<ImageUploaderProps> = ({ files, onFilesChange, disabled, onEdit }) => {
  const [isDragging, setIsDragging] = useState(false);
  const [confirmingIdx, setConfirmingIdx] = useState<number | null>(null);

  const handleDragOver = useCallback((e: React.DragEvent) => {
    e.preventDefault();
    if (!disabled) setIsDragging(true);
  }, [disabled]);

  const handleDragLeave = useCallback((e: React.DragEvent) => {
    e.preventDefault();
    setIsDragging(false);
  }, []);

  const handleDrop = useCallback((e: React.DragEvent) => {
    e.preventDefault();
    setIsDragging(false);
    if (disabled) return;
    if (e.dataTransfer.files && e.dataTransfer.files.length > 0) {
      const newFiles = (Array.from(e.dataTransfer.files) as File[]).filter(file => file.type.startsWith('image/'));
      onFilesChange([...files, ...newFiles]);
    }
  }, [files, onFilesChange, disabled]);

  const handleRemoveClick = (e: React.MouseEvent, index: number) => {
    e.stopPropagation();
    if (confirmingIdx === index) {
      const newFiles = [...files];
      newFiles.splice(index, 1);
      onFilesChange(newFiles);
      setConfirmingIdx(null);
    } else {
      setConfirmingIdx(index);
      setTimeout(() => {
        setConfirmingIdx(current => current === index ? null : current);
      }, 3000);
    }
  };

  const handleFileInput = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files.length > 0) {
        const newFiles = (Array.from(e.target.files) as File[]).filter(file => file.type.startsWith('image/'));
        onFilesChange([...files, ...newFiles]);
    }
  };

  return (
    <div className="space-y-3" onClick={() => setConfirmingIdx(null)}>
      <div className="flex items-center justify-between text-sm text-slate-400 dark:text-slate-500">
        <span className="flex items-center gap-1.5 font-bold uppercase text-[10px] tracking-widest"><ImagePlus size={16}/> 参考图片 (可选)</span>
        <span className="text-[10px] opacity-60 font-medium">支持拖拽或粘贴</span>
      </div>

      <div
        onDragOver={handleDragOver}
        onDragLeave={handleDragLeave}
        onDrop={handleDrop}
        className={`relative border-2 border-dashed rounded-[2rem] transition-all duration-200 min-h-[140px] flex flex-col items-center justify-center p-6 group
          ${isDragging 
            ? 'border-banana-500 bg-banana-500/10' 
            : 'border-slate-200 dark:border-slate-700 bg-slate-50/50 dark:bg-slate-800/40 hover:border-banana-500/50 hover:bg-white dark:hover:bg-slate-800/60'
          } ${disabled ? 'opacity-50 cursor-not-allowed' : 'cursor-pointer'}`}
      >
         <input type="file" multiple accept="image/*" className="absolute inset-0 w-full h-full opacity-0 cursor-pointer disabled:cursor-not-allowed" onChange={handleFileInput} disabled={disabled} />

        {files.length === 0 ? (
          <div className="text-center pointer-events-none">
            <div className="w-12 h-12 rounded-2xl bg-white dark:bg-slate-900 shadow-sm flex items-center justify-center mx-auto mb-4 text-slate-400 group-hover:text-banana-500 transition-colors">
              <Upload size={24} />
            </div>
            <p className="text-xs text-slate-500 dark:text-slate-400 font-bold uppercase tracking-tight">点击或拖拽上传</p>
            <p className="text-[9px] text-slate-400 dark:text-slate-500 mt-2 flex items-center justify-center gap-1.5">
               <ClipboardPaste size={12}/> 支持 Ctrl+V 直接粘贴
            </p>
          </div>
        ) : (
            <div className="w-full relative z-10 pointer-events-none">
                <div className="flex flex-wrap gap-3 justify-center pointer-events-auto">
                    {files.map((file, idx) => (
                    <div key={idx} className={`relative w-24 h-24 rounded-2xl overflow-hidden border shadow-xl transition-all duration-300 ${confirmingIdx === idx ? 'ring-2 ring-red-500 scale-95' : 'border-white dark:border-slate-700 group/img'}`}>
                        <img src={URL.createObjectURL(file)} alt="preview" className={`w-full h-full object-cover transition-all ${confirmingIdx === idx ? 'blur-[2px] brightness-50' : ''}`} />

                        <div className="absolute inset-0 bg-black/20 opacity-0 group-hover/img:opacity-100 transition-opacity flex flex-col gap-1 p-1">
                          <button 
                            onClick={(e) => { e.stopPropagation(); onEdit(file); }}
                            className="w-full flex-1 bg-banana-500/90 hover:bg-banana-500 text-slate-900 rounded-xl flex items-center justify-center transition-colors"
                            title="编辑图片"
                          >
                            <Edit3 size={16} strokeWidth={3} />
                          </button>
                          <button 
                            onClick={(e) => handleRemoveClick(e, idx)} 
                            className={`w-full flex-1 rounded-xl flex items-center justify-center transition-all ${
                              confirmingIdx === idx 
                                ? 'bg-red-500 text-white animate-pulse' 
                                : 'bg-slate-900/80 text-white hover:bg-red-500'
                            }`}
                            title={confirmingIdx === idx ? "确认删除？" : "移除图片"}
                          >
                              {confirmingIdx === idx ? <AlertCircle size={16} strokeWidth={3} /> : <X size={16} strokeWidth={3} />}
                          </button>
                        </div>

                        {confirmingIdx === idx && (
                          <div className="absolute bottom-1 inset-x-1 flex items-center justify-center pointer-events-none">
                             <span className="text-[7px] font-black text-white uppercase tracking-tighter bg-red-500/80 px-1 py-0.5 rounded-full">再次点击</span>
                          </div>
                        )}
                    </div>
                    ))}
                    <div className="flex items-center justify-center w-24 h-24 rounded-2xl border-2 border-dashed border-slate-300 dark:border-slate-600 bg-white/50 dark:bg-slate-900/50 text-slate-300 dark:text-slate-600">
                        <Upload size={24} />
                    </div>
                </div>
            </div>
        )}
      </div>
    </div>
  );
};

