import React, { useState, useEffect } from 'react';
import { X, Download, ZoomIn, ZoomOut, RotateCcw, Copy, Check, Tag, BrainCircuit, Timer, ChevronLeft, ChevronRight, Wallet, Edit3 } from 'lucide-react';
