        <div className="flex items-center gap-4 pointer-events-auto">
             <div className="bg-slate-900/80 backdrop-blur rounded-[2.5rem] border border-white/5 p-2 flex gap-1 shadow-2xl">
                <button onClick={(e) => { e.stopPropagation(); setScale(Math.min(scale + 0.5, 8)); }} className="p-3.5 hover:bg-white/10 rounded-2xl text-slate-200 transition-colors"><ZoomIn size={20} /></button>
                <button onClick={(e) => { e.stopPropagation(); setScale(Math.max(0.5, scale - 0.5)); }} className="p-3.5 hover:bg-white/10 rounded-2xl text-slate-200 transition-colors"><ZoomOut size={20} /></button>
                <button onClick={(e) => { e.stopPropagation(); setScale(1); setPosition({x:0,y:0}); }} className="p-3.5 hover:bg-white/10 rounded-2xl text-slate-200 transition-colors"><RotateCcw size={20} /></button>
             </div>
             <button 
                onClick={(e) => { e.stopPropagation(); onEdit(); }}
                className="flex items-center gap-2 bg-banana-500 hover:bg-banana-400 text-slate-950 px-6 py-4 rounded-full border border-banana-500 shadow-xl font-black text-[10px] uppercase tracking-widest transition-all hover:scale-105"
             >
                <Edit3 size={16} /> 重绘编辑
             </button>
             <button 
                onClick={(e) => { e.stopPropagation(); setShowThinking(!showThinking); }}
                className={`flex items-center gap-2 text-[10px] font-black uppercase px-6 py-4 rounded-full border transition-all ${showThinking ? 'bg-white text-slate-950 border-white shadow-xl' : 'bg-white/5 text-slate-300 border-white/10 hover:bg-white/10'}`}
             >
                <BrainCircuit size={14} /> 纳米溯源
             </button>
             <div className="bg-white/5 backdrop-blur-xl rounded-full px-6 py-4 border border-white/10 flex items-center gap-2 text-banana-400 font-black text-[10px] uppercase tracking-widest shadow-2xl">
                <Wallet size={14} />
                <span>费用: {currency === 'RMB' ? `¥${image.costRMB.toFixed(2)}` : `$${image.costUSD.toFixed(3)}`}</span>
             </div>
        </div>

        <div className="flex gap-4 pointer-events-auto">
          <button onClick={(e) => { e.stopPropagation(); onCopy(); }} className={`px-6 py-4 rounded-3xl transition-all shadow-2xl flex items-center gap-2 ${isCopied ? 'bg-green-500 text-white shadow-green-500/20' : 'bg-slate-800/80 hover:bg-slate-700 text-white border border-white/5'}`}>
            {isCopied ? <Check size={20} /> : <Copy size={20} />}
            <span className="text-xs font-black uppercase tracking-widest">{isCopied ? '咒语已存' : '复制咒语'}</span>
          </button>
          <a href={image.url} download={`${image.filename}.png`} onClick={(e) => e.stopPropagation()} className="p-4 bg-banana-500 hover:bg-banana-400 text-slate-950 rounded-3xl transition-all shadow-2xl shadow-banana-500/30">
            <Download size={24} />
          </a>
          <button onClick={onClose} className="p-4 bg-slate-900/80 hover:bg-red-500/20 text-white hover:text-red-400 rounded-3xl transition-all border border-white/5">
            <X size={24} />
          </button>
        </div>
      </div>

      {/* Navigation Controls */}
      <div className="absolute inset-x-8 top-1/2 -translate-y-1/2 flex justify-between pointer-events-none z-[105]">
          <button onClick={(e) => { e.stopPropagation(); onPrev(); }} className="p-7 bg-white/5 hover:bg-white/10 backdrop-blur-2xl rounded-full text-white border border-white/10 transition-all pointer-events-auto shadow-2xl group"><ChevronLeft size={36} className="group-hover:-translate-x-1 transition-transform" /></button>
          <button onClick={(e) => { e.stopPropagation(); onNext(); }} className="p-7 bg-white/5 hover:bg-white/10 backdrop-blur-2xl rounded-full text-white border border-white/10 transition-all pointer-events-auto shadow-2xl group"><ChevronRight size={36} className="group-hover:translate-x-1 transition-transform" /></button>
      </div>

      <div className="w-full h-full flex items-center justify-center overflow-hidden" onWheel={handleWheel} onMouseDown={handleMouseDown} onMouseMove={handleMouseMove} onMouseUp={() => setIsDragging(false)} onMouseLeave={() => setIsDragging(false)} onClick={(e) => e.stopPropagation()}>
        <img src={image.url} alt={image.prompt} className="max-w-[85%] max-h-[85%] object-contain transition-transform duration-100 select-none shadow-[0_0_120px_rgba(0,0,0,0.9)] rounded-[3rem]" style={{ transform: `translate(${position.x}px, ${position.y}px) scale(${scale})`, cursor: scale > 1 ? (isDragging ? 'grabbing' : 'grab') : 'default' }} draggable={false} />
      </div>

      {showThinking && (
          <div className="absolute top-36 left-8 w-80 bg-slate-950/90 backdrop-blur-3xl border border-white/10 rounded-[3rem] p-10 shadow-2xl animate-in slide-in-from-left-4 duration-500 pointer-events-auto" onClick={(e) => e.stopPropagation()}>
              <div className="flex items-center justify-between mb-8 pb-4 border-b border-white/10">
                  <div className="flex items-center gap-2 text-banana-400 font-black text-xs uppercase tracking-widest"><BrainCircuit size={18} /> 构建逻辑</div>
                  <div className="text-[10px] font-mono text-slate-500 flex items-center gap-2"><Timer size={14} /> {image.totalDuration.toFixed(2)}s</div>
              </div>
              <div className="space-y-8">
                  {image.thoughtLog.map((step, idx) => (
                      <div key={idx} className="flex flex-col gap-3 group">
                          <div className="flex items-center gap-4">
                              <div className={`w-2.5 h-2.5 rounded-full ${step.status === 'done' ? 'bg-banana-400 shadow-[0_0_12px_rgba(234,179,8,0.6)]' : 'bg-slate-700'}`} />
                              <span className="text-xs font-bold text-slate-200">{step.name}</span>
