        <div className="max-w-4xl mx-auto px-12 py-10 bg-black/60 backdrop-blur-3xl border border-white/10 rounded-[4rem] shadow-2xl flex flex-col items-center gap-4 animate-in fade-in slide-in-from-bottom-8 duration-700">
            <div className="flex items-center gap-3 text-banana-400 font-black uppercase text-xs tracking-[0.3em]"><Tag size={18} /> <span>{image.filename}</span></div>
            <p className="text-white text-base font-bold line-clamp-2 italic max-w-2xl leading-relaxed">"{image.prompt || '纳米意图重构渲染'}"</p>
