  '#000000', '#ffffff', '#ef4444', '#f97316', '#facc15', 
  '#22c55e', '#06b6d4', '#3b82f6', '#8b5cf6', '#d946ef'
];

const TOOLS = [
  { id: 'select', icon: MousePointer2, name: '选择' },
  { id: 'pencil', icon: Pencil, name: '画笔' },
  { id: 'text', icon: TypeIcon, name: '文字' },
  { id: 'rect', icon: Square, name: '方框' }
];

const ImageEditor: React.FC<ImageEditorProps> = ({ image, onClose, onDone }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const fabricRef = useRef<fabric.Canvas | null>(null);
  const [activeTool, setActiveTool] = useState('pencil');
  const [activeColor, setActiveColor] = useState('#facc15');
  const [isCopied, setIsCopied] = useState(false);
  const [historyCount, setHistoryCount] = useState(0);

  useEffect(() => {
    if (!canvasRef.current) return;

    const canvas = new fabric.Canvas(canvasRef.current, {
      width: window.innerWidth * 0.8,
      height: window.innerHeight * 0.8,
      backgroundColor: '#0a0c10',
      preserveObjectStacking: true
    });
    fabricRef.current = canvas;

    fabric.Image.fromURL(image.url, (img) => {
      const containerW = canvas.width!;
      const containerH = canvas.height!;
      const imgW = img.width!;
      const imgH = img.height!;

      const scale = Math.min(containerW / imgW, containerH / imgH) * 0.9;

      img.set({
        selectable: false,
        evented: false,
        scaleX: scale,
        scaleY: scale,
        left: (containerW - imgW * scale) / 2,
        top: (containerH - imgH * scale) / 2
      });

      canvas.add(img);
      canvas.sendToBack(img);
      canvas.renderAll();
    }, { crossOrigin: 'anonymous' });

    canvas.on('object:added', () => setHistoryCount(prev => prev + 1));
    canvas.on('object:removed', () => setHistoryCount(prev => prev + 1));

    updateTool(canvas, activeTool);

    const handleResize = () => {
      canvas.setDimensions({
        width: window.innerWidth * 0.8,
        height: window.innerHeight * 0.8
      });
      canvas.renderAll();
    };
    window.addEventListener('resize', handleResize);

    return () => {
      window.removeEventListener('resize', handleResize);
      canvas.dispose();
    };
  }, [image.url]);

  useEffect(() => {
    if (fabricRef.current) {
      updateTool(fabricRef.current, activeTool);
    }
  }, [activeTool, activeColor]);

  const updateTool = (canvas: fabric.Canvas, tool: string) => {
    canvas.isDrawingMode = tool === 'pencil';
    if (canvas.isDrawingMode) {
      canvas.freeDrawingBrush = new fabric.PencilBrush(canvas);
      canvas.freeDrawingBrush.color = activeColor;
      canvas.freeDrawingBrush.width = 5;
    }

    // Handle other tools via mouse events
    canvas.off('mouse:down');
    if (tool === 'rect') {
      canvas.on('mouse:down', (options) => {
        if (options.target) return;
        const pointer = canvas.getPointer(options.e);
        const rect = new fabric.Rect({
          left: pointer.x,
          top: pointer.y,
          fill: 'transparent',
          stroke: activeColor,
          strokeWidth: 4,
          width: 50,
          height: 50,
          rx: 8,
          ry: 8
        });
        canvas.add(rect);
        canvas.setActiveObject(rect);
        setActiveTool('select');
      });
    } else if (tool === 'text') {
      canvas.on('mouse:down', (options) => {
        if (options.target) return;
        const pointer = canvas.getPointer(options.e);
        const text = new fabric.IText('输入文字', {
          left: pointer.x,
          top: pointer.y,
          fill: activeColor,
          fontSize: 32,
          fontFamily: 'system-ui',
          fontWeight: 'black'
        });
        canvas.add(text);
        canvas.setActiveObject(text);
        text.enterEditing();
        setActiveTool('select');
      });
    }
  };

  const handleExport = (action: 'done' | 'download' | 'copy') => {
    if (!fabricRef.current) return;

    // Hide selection borders for export
    fabricRef.current.discardActiveObject();
    fabricRef.current.renderAll();

    const dataUrl = fabricRef.current.toDataURL({
      format: 'png',
      quality: 1
    });

    if (action === 'download') {
      const link = document.createElement('a');
      link.download = `nano-edit-${Date.now()}.png`;
      link.href = dataUrl;
      link.click();
    } else if (action === 'copy') {
      fetch(dataUrl).then(res => res.blob()).then(blob => {
        const item = new ClipboardItem({ 'image/png': blob });
        navigator.clipboard.write([item]);
        setIsCopied(true);
        setTimeout(() => setIsCopied(false), 2000);
      });
    } else {
      fetch(dataUrl).then(res => res.blob()).then(blob => {
        onDone(blob);
      });
    }
  };

  const deleteSelected = () => {
    const active = fabricRef.current?.getActiveObject();
    if (active) {
      fabricRef.current?.remove(active);
    }
  };

  const clearCanvas = () => {
    if (confirm('确定要清除所有修改吗？')) {
      const objects = fabricRef.current?.getObjects();
      objects?.forEach((obj, idx) => {
        if (idx > 0) fabricRef.current?.remove(obj); // Keep index 0 which is the background image
      });
    }
  };

  return (
    <div className="fixed inset-0 z-[120] flex items-center justify-center bg-black/95 backdrop-blur-3xl animate-in zoom-in-95 duration-300">
      {/* Top Header */}
      <div className="absolute top-0 inset-x-0 p-6 flex justify-between items-center bg-gradient-to-b from-black/80 to-transparent">
        <div className="flex items-center gap-4">
          <div className="w-10 h-10 bg-banana-500 rounded-xl flex items-center justify-center text-slate-950 shadow-lg">
            <Edit3 size={20} />
          </div>
          <div>
            <h2 className="text-white font-black text-sm uppercase tracking-widest">Nano Canvas Studio</h2>
            <p className="text-slate-400 text-[9px] uppercase tracking-tighter">Editing: {image.name}</p>
          </div>
        </div>
        <div className="flex items-center gap-3">
          <button onClick={onClose} className="p-3 bg-white/5 hover:bg-white/10 rounded-2xl text-white transition-all">
            <X size={20} />
          </button>
        </div>
      </div>

      {/* Main Workspace */}
      <div className="relative shadow-[0_0_100px_rgba(0,0,0,0.8)] rounded-3xl overflow-hidden border border-white/5">
        <canvas ref={canvasRef} />
      </div>

      {/* Right Tools - Floating like Procreate */}
      <div className="absolute right-8 top-1/2 -translate-y-1/2 flex flex-col gap-6">
        <div className="bg-slate-900/90 backdrop-blur-2xl p-3 rounded-[2.5rem] border border-white/5 shadow-2xl flex flex-col gap-4">
          {TOOLS.map(t => (
            <button
              key={t.id}
              onClick={() => setActiveTool(t.id)}
              className={`p-4 rounded-2xl transition-all ${activeTool === t.id ? 'bg-banana-500 text-slate-950 shadow-xl scale-110' : 'text-slate-400 hover:text-white hover:bg-white/5'}`}
              title={t.name}
            >
              <t.icon size={22} strokeWidth={2.5} />
            </button>
          ))}
          <div className="h-px bg-white/5 mx-2" />
          <button onClick={deleteSelected} className="p-4 rounded-2xl text-red-400 hover:bg-red-400/10 transition-all" title="删除选中">
