            <Edit3 size={24} />
          </div>
          <div>
            <h2 className="text-white font-black text-sm uppercase tracking-[0.2em]">Nano Canvas Studio <span className="text-banana-500 ml-2">PRO</span></h2>
            <p className="text-slate-400 text-[9px] uppercase tracking-tighter opacity-60">Source: {image.name}</p>
          </div>
        </div>
        <div className="flex items-center gap-4">
          <div className="bg-slate-900/80 backdrop-blur rounded-2xl p-1.5 flex gap-1 border border-white/5">
            <button onClick={undo} disabled={history.length <= 1} className="p-2.5 text-slate-400 hover:text-white hover:bg-white/5 rounded-xl transition-all disabled:opacity-20" title="撤销 (Ctrl+Z)"><Undo2 size={20} /></button>
            <button onClick={() => { if(confirm('重置画板？')) fabricRef.current?.clear(); }} className="p-2.5 text-slate-400 hover:text-red-400 hover:bg-red-400/5 rounded-xl transition-all" title="重置"><RotateCcw size={20} /></button>
          </div>
          <button onClick={onClose} className="p-3 bg-white/5 hover:bg-white/10 rounded-2xl text-white transition-all border border-white/5 shadow-xl"><X size={24} /></button>
        </div>
      </div>

      {/* 左侧属性调节器 */}
