            <span className="text-[8px] font-black text-slate-500 uppercase vertical-text">Size</span>
            <div className="flex flex-col gap-4 items-center h-48 py-2">
               <button onClick={() => setStrokeWidth(prev => Math.min(prev + 2, 50))} className="p-1 text-slate-400 hover:text-white"><Plus size={14}/></button>
               <div className="flex-1 w-1 bg-slate-800 rounded-full relative overflow-hidden group">
                  <div className="absolute bottom-0 inset-x-0 bg-banana-500 transition-all duration-300" style={{ height: `${(strokeWidth / 50) * 100}%` }} />
                  <input 
                    type="range" min="1" max="50" vertical="" 
                    value={strokeWidth} 
                    onChange={(e) => setStrokeWidth(parseInt(e.target.value))}
                    className="absolute inset-0 w-full h-full opacity-0 cursor-pointer"
                  />
               </div>
               <button onClick={() => setStrokeWidth(prev => Math.max(prev - 2, 1))} className="p-1 text-slate-400 hover:text-white"><Minus size={14}/></button>
            </div>
            <div className="w-8 h-8 rounded-full bg-white/5 flex items-center justify-center text-[10px] font-mono text-banana-500 font-bold">{strokeWidth}</div>
         </div>

         <div className="flex flex-col items-center gap-4 bg-slate-900/90 backdrop-blur-2xl p-3 rounded-[2rem] border border-white/5 shadow-2xl">
            <span className="text-[8px] font-black text-slate-500 uppercase vertical-text">Text</span>
            <div className="flex flex-col gap-4 items-center h-48 py-2">
               <button onClick={() => setFontSize(prev => Math.min(prev + 5, 200))} className="p-1 text-slate-400 hover:text-white"><Plus size={14}/></button>
               <div className="flex-1 w-1 bg-slate-800 rounded-full relative">
                  <div className="absolute bottom-0 inset-x-0 bg-banana-500 transition-all" style={{ height: `${(fontSize / 200) * 100}%` }} />
                  <input type="range" min="10" max="200" value={fontSize} onChange={(e) => setFontSize(parseInt(e.target.value))} className="absolute inset-0 w-full h-full opacity-0 cursor-pointer" />
               </div>
               <button onClick={() => setFontSize(prev => Math.max(prev - 5, 10))} className="p-1 text-slate-400 hover:text-white"><Minus size={14}/></button>
            </div>
            <div className="w-8 h-8 rounded-full bg-white/5 flex items-center justify-center text-[10px] font-mono text-banana-500 font-bold">{fontSize}</div>
         </div>
      </div>

      {/* 主画布 */}
      <div className="relative group cursor-crosshair">
        <canvas ref={canvasRef} />
      </div>

      {/* 右侧工具栏 - 悬浮式 */}
      <div className="absolute right-8 top-1/2 -translate-y-1/2 flex flex-col gap-6 z-50">
        <div className="bg-slate-900/90 backdrop-blur-2xl p-3 rounded-[2.5rem] border border-white/5 shadow-2xl flex flex-col gap-4">
          {TOOLS.map(t => (
            <button
              key={t.id}
              onClick={() => setActiveTool(t.id)}
              className={`p-4 rounded-2xl transition-all ${activeTool === t.id ? 'bg-banana-500 text-slate-950 shadow-xl scale-110' : 'text-slate-400 hover:text-white hover:bg-white/5'}`}
              title={t.name}
            >
              <t.icon size={24} strokeWidth={2.5} />
            </button>
          ))}
          <div className="h-px bg-white/5 mx-2" />
          <button onClick={deleteSelected} className="p-4 rounded-2xl text-red-400 hover:bg-red-400/10 transition-all" title="删除选中 (Delete)">
            <Trash2 size={24} />
          </button>
        </div>

        <div className="bg-slate-900/90 backdrop-blur-2xl p-4 rounded-[2.5rem] border border-white/5 shadow-2xl flex flex-col gap-3 items-center">
          <div className="grid grid-cols-2 gap-2.5">
            {COLORS.map(c => (
              <button
                key={c}
                onClick={() => setActiveColor(c)}
                className={`w-9 h-9 rounded-full border-2 transition-all shadow-sm ${activeColor === c ? 'border-white scale-125 shadow-lg' : 'border-white/10'}`}
                style={{ backgroundColor: c }}
              />
            ))}
          </div>
          <div className="mt-2 text-[8px] font-black text-slate-500 uppercase tracking-widest">Palette</div>
        </div>
