            {isCopied ? <Check size={18} /> : <Copy size={18} />} {isCopied ? '已复制到剪贴板' : '复制合并图层'}
          </button>
          <button onClick={() => handleExport('download')} className="px-10 py-5 rounded-full flex items-center gap-3 text-slate-300 hover:bg-white/10 font-black text-[11px] uppercase tracking-widest transition-all duration-300">
            <Download size={18} /> 下载 PNG
          </button>
        </div>

        <button 
          onClick={() => handleExport('done')}
          className="bg-banana-500 hover:bg-banana-400 text-slate-950 px-14 py-6 rounded-full shadow-[0_25px_60px_-15px_rgba(234,179,8,0.5)] font-black text-sm uppercase tracking-[0.25em] flex items-center gap-5 transition-all duration-300 hover:scale-105 active:scale-95 group"
        >
          <Send size={22} className="group-hover:translate-x-1 group-hover:-translate-y-1 transition-transform" /> 
          确认编辑并同步库
