          box-shadow: 0 60px 120px -30px rgba(0,0,0,0.9); 
          border-radius: 2.5rem; 
          overflow: hidden; 
          border: 1px solid rgba(255,255,255,0.08); 
          background: #000;
        }
        input[type="range"] { -webkit-appearance: none; background: transparent; }
