};

export default ImageEditor;

import React, { useEffect, useRef, useState, useCallback } from 'react';
import { fabric } from 'https://esm.sh/fabric@5.3.0';
import { X, Pencil, Type as TypeIcon, Square, MousePointer2, Download, Copy, Check, Send, Undo2, RotateCcw, Trash2, Edit3, Minus, Plus, Maximize } from 'lucide-react';
import { EditingImage } from '../types';

interface ImageEditorProps {
  image: EditingImage;
  onClose: () => void;
  onDone: (blob: Blob) => void;
}

const COLORS = [
  '#000000', '#ffffff', '#ef4444', '#f97316', '#facc15', 
  '#22c55e', '#06b6d4', '#3b82f6', '#8b5cf6', '#d946ef'
];

const TOOLS = [
  { id: 'select', icon: MousePointer2, name: '选择' },
  { id: 'pencil', icon: Pencil, name: '画笔' },
  { id: 'text', icon: TypeIcon, name: '文字' },
  { id: 'rect', icon: Square, name: '方框' }
];

const ImageEditor: React.FC<ImageEditorProps> = ({ image, onClose, onDone }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const fabricRef = useRef<fabric.Canvas | null>(null);
  const [activeTool, setActiveTool] = useState('pencil');
  const [activeColor, setActiveColor] = useState('#facc15');
  const [strokeWidth, setStrokeWidth] = useState(5);
  const [fontSize, setFontSize] = useState(40);
  const [isCopied, setIsCopied] = useState(false);
  const [history, setHistory] = useState<string[]>([]);

  const isRectDrawing = useRef(false);
  const rectStart = useRef<{ x: number, y: number } | null>(null);
  const currentRect = useRef<fabric.Rect | null>(null);
  const isPanning = useRef(false);

  // 记录历史记录
  const saveHistory = useCallback(() => {
    if (!fabricRef.current) return;
    const json = JSON.stringify(fabricRef.current.toDatalessJSON());
    setHistory(prev => {
      if (prev.length > 0 && prev[prev.length - 1] === json) return prev;
      const newHistory = [...prev, json];
      return newHistory.slice(-30);
    });
  }, []);

  const undo = useCallback(() => {
    if (history.length <= 1 || !fabricRef.current) return;
    const newHistory = [...history];
    newHistory.pop();
    const lastState = newHistory[newHistory.length - 1];

    fabricRef.current.loadFromJSON(lastState, () => {
      fabricRef.current?.renderAll();
      setHistory(newHistory);
    });
  }, [history]);

  // Fix: Added missing deleteSelected function to handle removal of active canvas objects
  const deleteSelected = useCallback(() => {
    const canvas = fabricRef.current;
    if (!canvas) return;
    const active = canvas.getActiveObjects();
    if (active.length > 0 && active.every(o => o.type !== 'image')) {
      canvas.remove(...active);
      canvas.discardActiveObject().renderAll();
    }
  }, []);

  const resetZoom = () => {
    if (!fabricRef.current) return;
    fabricRef.current.setZoom(1);
    fabricRef.current.absolutePan({ x: 0, y: 0 });
  };

  useEffect(() => {
    if (!canvasRef.current) return;

    const canvas = new fabric.Canvas(canvasRef.current, {
      width: window.innerWidth * 0.85,
      height: window.innerHeight * 0.85,
      backgroundColor: '#0a0c10',
      preserveObjectStacking: true,
      stopContextMenu: true
    });
    fabricRef.current = canvas;

    fabric.Image.fromURL(image.url, (img) => {
      const containerW = canvas.width!;
      const containerH = canvas.height!;
      const imgW = img.width!;
      const imgH = img.height!;
      const scale = Math.min(containerW / imgW, containerH / imgH) * 0.95;

      img.set({
        selectable: false,
        evented: false,
        scaleX: scale,
        scaleY: scale,
        left: (containerW - imgW * scale) / 2,
        top: (containerH - imgH * scale) / 2
      });

      canvas.add(img);
      canvas.sendToBack(img);
      canvas.renderAll();
      saveHistory();
    }, { crossOrigin: 'anonymous' });

    // 缩放逻辑
    canvas.on('mouse:wheel', (opt) => {
      const delta = opt.e.deltaY;
      let zoom = canvas.getZoom();
      zoom *= 0.999 ** delta;
      if (zoom > 20) zoom = 20;
      if (zoom < 0.05) zoom = 0.05;
      canvas.zoomToPoint({ x: opt.e.offsetX, y: opt.e.offsetY }, zoom);
      opt.e.preventDefault();
      opt.e.stopPropagation();
    });

    // 平移逻辑 (Alt + 拖动)
    canvas.on('mouse:down', (opt) => {
      const evt = opt.e as MouseEvent;
      if (evt.altKey || evt.button === 1) {
        isPanning.current = true;
        canvas.selection = false;
        canvas.setCursor('grabbing');
      }
    });

    canvas.on('mouse:move', (opt) => {
      if (isPanning.current) {
        const e = opt.e as MouseEvent;
        const vpt = canvas.viewportTransform;
        if (vpt) {
          vpt[4] += e.movementX;
          vpt[5] += e.movementY;
          canvas.requestRenderAll();
        }
      }
    });

    canvas.on('mouse:up', () => {
      isPanning.current = false;
      canvas.selection = true;
    });

    canvas.on('object:added', (e) => {
      if (!isRectDrawing.current) saveHistory();
    });
    canvas.on('object:modified', saveHistory);
    canvas.on('object:removed', () => saveHistory());

    const handleKeyDown = (e: KeyboardEvent) => {
      if ((e.key === 'Delete' || e.key === 'Backspace') && !canvas.isDrawingMode) {
        // Fix: Use deleteSelected function instead of inline logic
        deleteSelected();
      } else if (e.ctrlKey && e.key === 'z') {
        e.preventDefault();
        undo();
      }
    };
    window.addEventListener('keydown', handleKeyDown);

    return () => {
      window.removeEventListener('keydown', handleKeyDown);
      canvas.dispose();
    };
  }, [image.url, saveHistory, undo, deleteSelected]);

  // 工具属性同步
  useEffect(() => {
    const canvas = fabricRef.current;
    if (!canvas) return;

    canvas.isDrawingMode = activeTool === 'pencil';
    if (canvas.isDrawingMode) {
      canvas.freeDrawingBrush = new fabric.PencilBrush(canvas);
      canvas.freeDrawingBrush.color = activeColor;
      canvas.freeDrawingBrush.width = strokeWidth;
      canvas.discardActiveObject().renderAll();
    }

    canvas.off('mouse:down:before');
    canvas.off('mouse:move:before');
    canvas.off('mouse:up:before');

    if (activeTool === 'rect') {
      canvas.on('mouse:down:before', (options) => {
        const pointer = canvas.getPointer(options.e);
        isRectDrawing.current = true;
        rectStart.current = { x: pointer.x, y: pointer.y };
        currentRect.current = new fabric.Rect({
          left: pointer.x,
          top: pointer.y,
          width: 0,
          height: 0,
          fill: 'transparent',
          stroke: activeColor,
          strokeWidth: strokeWidth,
          rx: 4, ry: 4,
          selectable: true
        });
        canvas.add(currentRect.current);
      });

      canvas.on('mouse:move:before', (options) => {
        if (!isRectDrawing.current || !currentRect.current || !rectStart.current) return;
        const pointer = canvas.getPointer(options.e);
        const width = Math.abs(rectStart.current.x - pointer.x);
        const height = Math.abs(rectStart.current.y - pointer.y);
        currentRect.current.set({
          width,
          height,
          left: Math.min(rectStart.current.x, pointer.x),
          top: Math.min(rectStart.current.y, pointer.y)
        });
        canvas.renderAll();
      });

      canvas.on('mouse:up:before', () => {
        isRectDrawing.current = false;
        if (currentRect.current && currentRect.current.width! < 2 && currentRect.current.height! < 2) {
          canvas.remove(currentRect.current);
        } else {
          saveHistory();
        }
        currentRect.current = null;
      });
    } else if (activeTool === 'text') {
      canvas.on('mouse:down:before', (options) => {
        if (options.target) return;
        const pointer = canvas.getPointer(options.e);
        const text = new fabric.IText('输入内容...', {
          left: pointer.x,
          top: pointer.y,
          fill: activeColor,
          fontSize: fontSize,
          fontFamily: 'Inter, system-ui',
          fontWeight: 'bold',
          editable: true
        });
        canvas.add(text);
        canvas.setActiveObject(text);
        setTimeout(() => {
          text.enterEditing();
          text.selectAll();
        }, 10);
      });
    }
  }, [activeTool, activeColor, strokeWidth, fontSize, saveHistory]);

  // 当属性（颜色、粗细等）改变时，同步到选中的对象
  useEffect(() => {
    const canvas = fabricRef.current;
    if (!canvas) return;
    const activeObjects = canvas.getActiveObjects();
    if (activeObjects.length > 0) {
      activeObjects.forEach(obj => {
        if (obj.type === 'i-text') {
          obj.set({ fill: activeColor, fontSize: fontSize });
        } else if (obj.type === 'rect') {
          obj.set({ stroke: activeColor, strokeWidth: strokeWidth });
        } else if (obj.type === 'path') {
          obj.set({ stroke: activeColor, strokeWidth: strokeWidth });
        }
      });
      canvas.renderAll();
    }
  }, [activeColor, strokeWidth, fontSize]);

  const handleExport = async (action: 'done' | 'download' | 'copy') => {
    if (!fabricRef.current) return;

    // 导出前重置缩放以确保质量
    const originalZoom = fabricRef.current.getZoom();
    const originalVpt = [...fabricRef.current.viewportTransform!];
    fabricRef.current.setZoom(1);
    fabricRef.current.absolutePan({ x: 0, y: 0 });

    fabricRef.current.discardActiveObject();
    fabricRef.current.renderAll();

    const dataUrl = fabricRef.current.toDataURL({ format: 'png', quality: 1 });

    // 恢复缩放
    fabricRef.current.viewportTransform = originalVpt;
    fabricRef.current.setZoom(originalZoom);
    fabricRef.current.renderAll();

    if (action === 'download') {
      const link = document.createElement('a');
      link.download = `nano-export-${Date.now()}.png`;
      link.href = dataUrl;
      link.click();
    } else if (action === 'copy') {
      const blob = await (await fetch(dataUrl)).blob();
      const item = new ClipboardItem({ 'image/png': blob });
      await navigator.clipboard.write([item]);
      setIsCopied(true);
      setTimeout(() => setIsCopied(false), 2000);
    } else {
      const blob = await (await fetch(dataUrl)).blob();
      onDone(blob);
    }
  };

  return (
    <div className="fixed inset-0 z-[120] flex items-center justify-center bg-[#050608] backdrop-blur-3xl animate-in fade-in duration-300 overflow-hidden select-none">
      {/* 顶部工具栏 */}
      <div className="absolute top-0 inset-x-0 p-6 flex justify-between items-center bg-gradient-to-b from-black/80 to-transparent z-50">
        <div className="flex items-center gap-5">
          <div className="w-12 h-12 bg-banana-500 rounded-2xl flex items-center justify-center text-slate-950 shadow-[0_0_30px_rgba(234,179,8,0.2)]">
            <Edit3 size={24} />
          </div>
          <div className="hidden sm:block">
            <h2 className="text-white font-black text-sm uppercase tracking-[0.25em]">Nano Canvas Studio <span className="text-banana-500 ml-2">PRO V2</span></h2>
            <div className="flex items-center gap-2 mt-0.5">
              <span className="text-slate-500 text-[8px] uppercase font-bold tracking-widest">Alt+Drag to Pan</span>
              <span className="text-slate-700">•</span>
              <span className="text-slate-500 text-[8px] uppercase font-bold tracking-widest">Wheel to Zoom</span>
            </div>
          </div>
        </div>
        <div className="flex items-center gap-4">
          <div className="bg-slate-900/90 backdrop-blur-xl rounded-2xl p-1.5 flex gap-1 border border-white/5 shadow-2xl">
            <button onClick={undo} disabled={history.length <= 1} className="p-3 text-slate-400 hover:text-white hover:bg-white/5 rounded-xl transition-all disabled:opacity-10" title="撤销 (Ctrl+Z)"><Undo2 size={20} /></button>
            <button onClick={resetZoom} className="p-3 text-slate-400 hover:text-white hover:bg-white/5 rounded-xl transition-all" title="重置视角"><Maximize size={20} /></button>
            <button onClick={() => { if(confirm('重置画板？')) fabricRef.current?.clear(); }} className="p-3 text-slate-400 hover:text-red-400 hover:bg-red-400/5 rounded-xl transition-all" title="重置画板"><RotateCcw size={20} /></button>
          </div>
          <button onClick={onClose} className="p-4 bg-white/5 hover:bg-red-500/20 rounded-2xl text-white transition-all border border-white/5 shadow-xl group">
            <X size={24} className="group-hover:rotate-90 transition-transform duration-300" />
          </button>
        </div>
      </div>

      {/* 左侧调节器 */}
      <div className="absolute left-8 top-1/2 -translate-y-1/2 z-50 flex flex-col gap-8 w-14 items-center">
         <div className="flex flex-col items-center gap-4 bg-slate-900/90 backdrop-blur-3xl p-4 rounded-[2.5rem] border border-white/5 shadow-2xl">
            <span className="text-[9px] font-black text-slate-500 uppercase vertical-text tracking-widest">Brush</span>
            <div className="flex flex-col gap-4 items-center h-48 py-2">
               <button onClick={() => setStrokeWidth(prev => Math.min(prev + 2, 80))} className="p-1 text-slate-500 hover:text-white transition-colors"><Plus size={16}/></button>
               <div className="flex-1 w-1.5 bg-slate-800/50 rounded-full relative overflow-hidden">
                  <div className="absolute bottom-0 inset-x-0 bg-banana-500 transition-all duration-300" style={{ height: `${(strokeWidth / 80) * 100}%` }} />
                  <input 
                    type="range" min="1" max="80" 
                    value={strokeWidth} 
                    onChange={(e) => setStrokeWidth(parseInt(e.target.value))}
                    className="absolute inset-0 w-full h-full opacity-0 cursor-ns-resize"
                  />
               </div>
               <button onClick={() => setStrokeWidth(prev => Math.max(prev - 2, 1))} className="p-1 text-slate-500 hover:text-white transition-colors"><Minus size={16}/></button>
            </div>
            <div className="w-10 h-10 rounded-full bg-white/5 flex items-center justify-center text-[11px] font-mono text-banana-400 font-black shadow-inner">{strokeWidth}</div>
         </div>

         <div className="flex flex-col items-center gap-4 bg-slate-900/90 backdrop-blur-3xl p-4 rounded-[2.5rem] border border-white/5 shadow-2xl">
            <span className="text-[9px] font-black text-slate-500 uppercase vertical-text tracking-widest">Type</span>
            <div className="flex flex-col gap-4 items-center h-48 py-2">
               <button onClick={() => setFontSize(prev => Math.min(prev + 5, 300))} className="p-1 text-slate-500 hover:text-white transition-colors"><Plus size={16}/></button>
               <div className="flex-1 w-1.5 bg-slate-800/50 rounded-full relative">
                  <div className="absolute bottom-0 inset-x-0 bg-banana-500 transition-all" style={{ height: `${(fontSize / 300) * 100}%` }} />
                  <input type="range" min="10" max="300" value={fontSize} onChange={(e) => setFontSize(parseInt(e.target.value))} className="absolute inset-0 w-full h-full opacity-0 cursor-ns-resize" />
               </div>
               <button onClick={() => setFontSize(prev => Math.max(prev - 5, 10))} className="p-1 text-slate-500 hover:text-white transition-colors"><Minus size={16}/></button>
            </div>
            <div className="w-10 h-10 rounded-full bg-white/5 flex items-center justify-center text-[11px] font-mono text-banana-400 font-black shadow-inner">{fontSize}</div>
         </div>
      </div>

      {/* 主画布容器 */}
      <div className="relative group cursor-crosshair">
        <canvas ref={canvasRef} />
      </div>

      {/* 右侧工具栏 */}
      <div className="absolute right-8 top-1/2 -translate-y-1/2 flex flex-col gap-6 z-50">
        <div className="bg-slate-900/90 backdrop-blur-3xl p-3.5 rounded-[3rem] border border-white/5 shadow-2xl flex flex-col gap-4">
          {TOOLS.map(t => (
            <button
              key={t.id}
              onClick={() => setActiveTool(t.id)}
              className={`p-4.5 rounded-[1.8rem] transition-all duration-300 ${activeTool === t.id ? 'bg-banana-500 text-slate-950 shadow-[0_10px_30px_rgba(234,179,8,0.4)] scale-110' : 'text-slate-500 hover:text-white hover:bg-white/5'}`}
              title={t.name}
            >
              <t.icon size={26} strokeWidth={2.5} />
            </button>
          ))}
          <div className="h-px bg-white/10 mx-3" />
          <button onClick={deleteSelected} className="p-4.5 rounded-[1.8rem] text-red-500/60 hover:text-red-400 hover:bg-red-400/10 transition-all" title="删除选中 (Delete)">
            <Trash2 size={26} />
          </button>
        </div>

        <div className="bg-slate-900/90 backdrop-blur-3xl p-5 rounded-[3rem] border border-white/5 shadow-2xl flex flex-col gap-4 items-center">
          <div className="grid grid-cols-2 gap-3">
            {COLORS.map(c => (
              <button
                key={c}
                onClick={() => setActiveColor(c)}
                className={`w-10 h-10 rounded-full border-2 transition-all duration-300 shadow-sm ${activeColor === c ? 'border-white scale-125 shadow-[0_0_15px_rgba(255,255,255,0.3)]' : 'border-white/5 hover:border-white/20'}`}
                style={{ backgroundColor: c }}
              />
            ))}
          </div>
          <div className="text-[10px] font-black text-slate-600 uppercase tracking-widest mt-1">Palette</div>
        </div>
      </div>

      {/* 底部功能条 */}
      <div className="absolute bottom-10 flex gap-8 items-center animate-in slide-in-from-bottom-6 z-50">
        <div className="bg-slate-900/90 backdrop-blur-3xl p-3 rounded-[3.5rem] border border-white/5 shadow-2xl flex gap-3">
          <button onClick={() => handleExport('copy')} className={`px-10 py-5 rounded-full flex items-center gap-3 font-black text-[11px] uppercase tracking-widest transition-all duration-300 ${isCopied ? 'bg-green-500 text-white' : 'text-slate-300 hover:bg-white/10'}`}>
            {isCopied ? <Check size={18} /> : <Copy size={18} />} {isCopied ? '已复制到剪贴板' : '复制合并图层'}
          </button>
          <button onClick={() => handleExport('download')} className="px-10 py-5 rounded-full flex items-center gap-3 text-slate-300 hover:bg-white/10 font-black text-[11px] uppercase tracking-widest transition-all duration-300">
