const fileToPart = async (file: File | Blob): Promise<{ inlineData: { data: string; mimeType: string } }> => {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onloadend = () => {
      if (typeof reader.result === 'string') {
        const base64Data = reader.result.split(',')[1];
        const mimeType = file.type || 'image/png';
        resolve({
          inlineData: {
            data: base64Data,
            mimeType: mimeType,
          },
        });
      } else {
        reject(new Error("读取数据失败"));
      }
    };
    reader.onerror = reject;
    reader.readAsDataURL(file);
  });
};

const mapToSupportedRatio = (ratio: AspectRatio, width?: number, height?: number): string => {
  if (ratio === AspectRatio.Custom && width && height) {
    const r = width / height;
    if (r >= 1.5) return "16:9";
    if (r >= 1.2) return "4:3";
    if (r > 0.8) return "1:1";
    if (r > 0.6) return "3:4";
    return "9:16";
  }

  // Gemini API 仅支持: "1:1", "4:3", "3:4", "9:16", "16:9"
  switch (ratio) {
    case AspectRatio.Square:
      return "1:1";
    case AspectRatio.Ratio_3_2:
    case AspectRatio.Ratio_4_3:
    case AspectRatio.Ratio_5_4:
      return "4:3";
    case AspectRatio.Ratio_2_3:
    case AspectRatio.Ratio_3_4:
    case AspectRatio.Ratio_4_5:
      return "3:4";
    case AspectRatio.Ratio_16_9:
    case AspectRatio.Ratio_16_10:
    case AspectRatio.Ratio_21_9:
      return "16:9";
    case AspectRatio.Ratio_9_16:
    case AspectRatio.Ratio_10_16:
    case AspectRatio.Ratio_9_21:
      return "9:16";
    default:
      return "1:1";
  }
};

export const analyzeAndName = async (prompt: string = "", files: File[], isSmartAnalysis: boolean) => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  const safePrompt = prompt || "";
  try {
    const parts: any[] = [];
    if (files.length > 0) {
      const imageParts = await Promise.all(files.map(fileToPart));
      parts.push(...imageParts);
    }
    const systemInstruction = "你是一个AI绘画专家。分析需求并生成 refinedPrompt (英文) 和 fileName (中文)。分析时请注意构图建议。回复必须为JSON格式。";
    parts.push({ text: `用户需求: ${safePrompt || "（根据参考图生成）"}` });
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: { parts },
      config: { 
        systemInstruction, 
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            refinedPrompt: { type: Type.STRING },
            fileName: { type: Type.STRING }
          },
          required: ["refinedPrompt", "fileName"]
        }
      }
    });
    return JSON.parse(response.text);
  } catch (e) {
    return { 
      refinedPrompt: safePrompt || "High-end digital art masterpiece, extremely detailed, vibrant colors", 
      fileName: safePrompt.substring(0, 8) || "NanoArt" 
    };
  }
};

export const generateSingleImage = async (
  prompt: string = "",
  inputFiles: (File | Blob)[],
  aspectRatio: AspectRatio,
  imageSize: ImageSize,
  model: AIModel,
  customWidth?: number,
  customHeight?: number
): Promise<string[]> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  const parts: any[] = [];

  if (inputFiles.length > 0) {
    const imageParts = await Promise.all(inputFiles.map(fileToPart));
    parts.push(...imageParts);
  }

  // 增加强制构图指令，确保输出更符合用户选择的比例感
  const compositionGuide = aspectRatio !== AspectRatio.Square ? `, ${aspectRatio} widescreen cinematic composition` : "";
  let finalPrompt = `${(prompt || "").trim()}${compositionGuide}`;

  parts.push({ text: finalPrompt || "Highly detailed masterpiece, cinematic lighting, professional composition" });

  const config: any = {
    imageConfig: {
      aspectRatio: mapToSupportedRatio(aspectRatio, customWidth, customHeight),
      imageSize: model === AIModel.Pro ? imageSize : undefined
    }
  };

  const response = await ai.models.generateContent({
    model: model,
    contents: { parts },
    config
  });

  const urls: string[] = [];
  if (response.candidates?.[0]?.content?.parts) {
    for (const part of response.candidates[0].content.parts) {
      if (part.inlineData?.data) {
        urls.push(`data:${part.inlineData.mimeType || 'image/png'};base64,${part.inlineData.data}`);
      }
    }
  }
  return urls;
};

import { GoogleGenAI, Type } from "@google/genai";
import { AspectRatio, ImageSize, AIModel } from "../types";

const fileToPart = async (file: File | Blob): Promise<{ inlineData: { data: string; mimeType: string } }> => {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onloadend = () => {
      if (typeof reader.result === 'string') {
        const base64Data = reader.result.split(',')[1];
        const mimeType = file.type || 'image/png';
        resolve({
          inlineData: {
            data: base64Data,
            mimeType: mimeType,
          },
        });
      } else {
        reject(new Error("读取数据失败"));
      }
    };
    reader.onerror = reject;
    reader.readAsDataURL(file);
  });
};

/**
 * 将 base64 图像裁剪为指定的宽高比
 */
const cropImageToStrictRatio = async (base64: string, targetRatioStr: string): Promise<string> => {
  if (targetRatioStr === "custom") return base64;

  const [tw, th] = targetRatioStr.split(':').map(Number);
  const targetRatio = tw / th;

  return new Promise((resolve) => {
    const img = new Image();
    img.onload = () => {
      const canvas = document.createElement('canvas');
      const currentRatio = img.width / img.height;

      let finalW, finalH, offsetX = 0, offsetY = 0;

      if (currentRatio > targetRatio) {
        // 当前图太宽，裁剪左右
        finalH = img.height;
        finalW = img.height * targetRatio;
        offsetX = (img.width - finalW) / 2;
      } else {
        // 当前图太高，裁剪上下
        finalW = img.width;
        finalH = img.width / targetRatio;
        offsetY = (img.height - finalH) / 2;
      }

      canvas.width = finalW;
      canvas.height = finalH;
      const ctx = canvas.getContext('2d');
      if (ctx) {
        ctx.drawImage(img, offsetX, offsetY, finalW, finalH, 0, 0, finalW, finalH);
        resolve(canvas.toDataURL('image/png', 1.0));
      } else {
        resolve(base64);
      }
    };
    img.src = base64;
  });
};

const mapToSupportedRatio = (ratio: AspectRatio, width?: number, height?: number): string => {
  if (ratio === AspectRatio.Custom && width && height) {
    const r = width / height;
    if (r >= 1.5) return "16:9";
    if (r >= 1.2) return "4:3";
    if (r > 0.8) return "1:1";
    if (r > 0.6) return "3:4";
    return "9:16";
  }

  // Gemini API 官方仅支持: "1:1", "4:3", "3:4", "9:16", "16:9"
  switch (ratio) {
    case AspectRatio.Square:
      return "1:1";
    case AspectRatio.Ratio_3_2:
    case AspectRatio.Ratio_4_3:
    case AspectRatio.Ratio_5_4:
      return "4:3";
    case AspectRatio.Ratio_2_3:
    case AspectRatio.Ratio_3_4:
    case AspectRatio.Ratio_4_5:
      return "3:4";
    case AspectRatio.Ratio_16_9:
    case AspectRatio.Ratio_16_10:
    case AspectRatio.Ratio_21_9:
      return "16:9";
    case AspectRatio.Ratio_9_16:
    case AspectRatio.Ratio_10_16:
    case AspectRatio.Ratio_9_21:
      return "9:16";
    default:
      return "1:1";
  }
};

export const analyzeAndName = async (prompt: string = "", files: File[], isSmartAnalysis: boolean) => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  const safePrompt = prompt || "";
  try {
    const parts: any[] = [];
    if (files.length > 0) {
      const imageParts = await Promise.all(files.map(fileToPart));
      parts.push(...imageParts);
    }
    const systemInstruction = "你是一个AI绘画专家。分析需求并生成 refinedPrompt (英文) 和 fileName (中文)。回复必须为JSON格式。";
    parts.push({ text: `用户需求: ${safePrompt || "（根据参考图生成）"}` });
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: { parts },
      config: { 
        systemInstruction, 
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            refinedPrompt: { type: Type.STRING },
            fileName: { type: Type.STRING }
          },
          required: ["refinedPrompt", "fileName"]
        }
      }
    });
    return JSON.parse(response.text);
  } catch (e) {
    return { 
      refinedPrompt: safePrompt || "High-end digital art masterpiece", 
      fileName: safePrompt.substring(0, 8) || "NanoArt" 
    };
  }
};

export const generateSingleImage = async (
  prompt: string = "",
  inputFiles: (File | Blob)[],
  aspectRatio: AspectRatio,
  imageSize: ImageSize,
  model: AIModel,
  customWidth?: number,
  customHeight?: number
): Promise<string[]> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  const parts: any[] = [];

  if (inputFiles.length > 0) {
    const imageParts = await Promise.all(inputFiles.map(fileToPart));
    parts.push(...imageParts);
  }

  // 在 Prompt 中强制指定构图比例，帮助 AI 更好适应非标比例
  const ratioInstruction = aspectRatio !== AspectRatio.Square ? `, strictly composed for ${aspectRatio} aspect ratio, wide angle cinematic framing` : "";
  parts.push({ text: `${(prompt || "").trim()}${ratioInstruction}` });

  const apiRatio = mapToSupportedRatio(aspectRatio, customWidth, customHeight);

  const config: any = {
    imageConfig: {
      aspectRatio: apiRatio,
      imageSize: model === AIModel.Pro ? imageSize : undefined
    }
  };

  const response = await ai.models.generateContent({
    model: model,
    contents: { parts },
    config
  });

  const urls: string[] = [];
  if (response.candidates?.[0]?.content?.parts) {
    for (const part of response.candidates[0].content.parts) {
      if (part.inlineData?.data) {
        const base64 = `data:${part.inlineData.mimeType || 'image/png'};base64,${part.inlineData.data}`;

        // 如果请求的比例不是 API 原生支持的（例如 21:9 或 9:21），进行物理裁剪
        if (aspectRatio !== AspectRatio.Custom && aspectRatio.toString() !== apiRatio) {
          const croppedBase64 = await cropImageToStrictRatio(base64, aspectRatio.toString());
          urls.push(croppedBase64);
        } else {
          urls.push(base64);
        }
      }
    }
  }
  return urls;
};

