  aspectRatio, imageSize, batchSize, model, isSmartAnalysis,
  onAspectRatioChange, onImageSizeChange, onBatchSizeChange, onModelChange,
  onSmartAnalysisChange,
  disabled
}) => {
  // 根据传入的 aspectRatio 初始判断方向
  const [orientation, setOrientation] = useState<'portrait' | 'landscape'>(() => {
    const isPortrait = ratioGroups.some(g => g.portrait === aspectRatio && g.portrait !== g.landscape);
    return isPortrait ? 'portrait' : 'landscape';
  });

  const handleOrientationSwitch = (newOrientation: 'portrait' | 'landscape') => {
    if (newOrientation === orientation) return;
    setOrientation(newOrientation);

    // 查找当前比例对应的标签，并在切换方向后更新父组件的 aspectRatio
    const currentGroup = ratioGroups.find(g => g.landscape === aspectRatio || g.portrait === aspectRatio);
    if (currentGroup) {
      onAspectRatioChange(newOrientation === 'landscape' ? currentGroup.landscape : currentGroup.portrait);
    }
  };

  return (
    <div className="bg-white dark:bg-slate-800/40 rounded-[2.5rem] p-5 border border-slate-200 dark:border-slate-700/50 space-y-6 backdrop-blur-sm shadow-sm">
