                       title="下载原图"
                     >
                        <Download size={18} />
                     </a>
                  </div>

                  <div className="absolute inset-0 bg-gradient-to-t from-black/80 via-transparent to-transparent opacity-0 group-hover:opacity-100 transition-all duration-300 p-8 flex flex-col justify-end">
                    <p className="text-white text-xs font-bold line-clamp-2 mb-4">"{img.prompt}"</p>
                    <div className="flex gap-2">
                       <button onClick={(e) => { e.stopPropagation(); setSelectedImage(img); }} className="flex-1 py-3 bg-white/20 backdrop-blur-xl hover:bg-white/30 text-white rounded-2xl text-[10px] font-black uppercase tracking-widest transition-all">查看详情</button>
                       <a href={img.url} download={`${img.filename}.png`} onClick={(e) => e.stopPropagation()} className="p-3 bg-banana-500 hover:bg-banana-400 text-slate-950 rounded-2xl transition-all shadow-lg"><Download size={18} /></a>
                    </div>
                  </div>
                  <div className="absolute top-6 left-6 flex flex-col gap-2">
                     <span className="px-4 py-1.5 bg-black/40 backdrop-blur-md rounded-full text-[8px] font-black text-white border border-white/10 uppercase tracking-widest">{img.filename.slice(0,10)}</span>
                  </div>
                </div>
              </div>
            ))}

            {allImages.length === 0 && !isGenerating && (
                <div className="col-span-full py-40 flex flex-col items-center justify-center text-slate-400 bg-white/50 dark:bg-slate-900/20 border-4 border-dashed border-slate-200 dark:border-slate-800 rounded-[5rem]">
                    <Sparkles size={64} className="opacity-20 text-banana-600 mb-8" />
                    <p className="text-xl font-black opacity-40">创作库尚无记录</p>
                </div>
            )}
          </div>
        </div>
      </div>

      {selectedImage && (
        <ImageViewer 
          image={selectedImage} 
          isCopied={!!copyStatus[selectedImage.id]} 
          onCopy={() => handleCopyPrompt(selectedImage.prompt, selectedImage.id)} 
          onClose={() => setSelectedImage(null)} 
          onNext={() => navigateImage(1)} 
          onPrev={() => navigateImage(-1)} 
          onEdit={() => { setEditingImage({ url: selectedImage.url, name: selectedImage.filename, type: 'generated' }); setSelectedImage(null); }}
          currency={currency} 
        />
      )}

      {editingImage && (
        <ImageEditor image={editingImage} onClose={() => setEditingImage(null)} onDone={handleEditorDone} />
      )}
    </div>
  );
};

