import { GoogleGenAI, Type, Schema } from "@google/genai";
import { AspectRatio, ImageSize, AIModel, StructuraData } from "../types";

const fileToPart = async (file: File | Blob): Promise<{ inlineData: { data: string; mimeType: string } }> => {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onloadend = () => {
      if (typeof reader.result === 'string') {
        const base64Data = reader.result.split(',')[1];
        const mimeType = file.type || 'image/png';
        resolve({
          inlineData: {
            data: base64Data,
            mimeType: mimeType,
          },
        });
      } else {
        reject(new Error("读取数据失败"));
      }
    };
    reader.onerror = reject;
    reader.readAsDataURL(file);
  });
};

const mapToSupportedRatio = (ratio: AspectRatio, width?: number, height?: number): string => {
  if (ratio === AspectRatio.Custom && width && height) {
    const r = width / height;
    if (r >= 1.5) return "16:9";
    if (r >= 1.2) return "4:3";
    if (r > 0.8) return "1:1";
    if (r > 0.6) return "3:4";
    return "9:16";
  }

  // Gemini API 原生支持: "1:1", "4:3", "3:4", "9:16", "16:9"
  switch (ratio) {
    case AspectRatio.Square:
      return "1:1";
    case AspectRatio.Ratio_3_2:
    case AspectRatio.Ratio_4_3:
    case AspectRatio.Ratio_5_4:
      return "4:3";
    case AspectRatio.Ratio_2_3:
    case AspectRatio.Ratio_3_4:
    case AspectRatio.Ratio_4_5:
      return "3:4";
    case AspectRatio.Ratio_16_9:
    case AspectRatio.Ratio_16_10:
    case AspectRatio.Ratio_21_9:
      return "16:9";
    case AspectRatio.Ratio_9_16:
    case AspectRatio.Ratio_10_16:
    case AspectRatio.Ratio_9_21:
      return "9:16";
    default:
      return "1:1";
  }
};

// Structura System Definition
const STRUCTURA_SYSTEM_PROMPT = `
=== STRUCTURA PROMPTER SYSTEM DOCUMENTATION ===

[1. CORE GENERATION LOGIC]
Structura uses a "Smart Inference" engine to bridge the gap between vague natural language and technical specifications.

- Contextual Inference: Interpret the "intent" of a style. If "Photo" is requested, inject lens data. If "Anime", inject rendering data.
- Multi-Style Fusion: Prioritize Medium for texture/rendering while keeping the Subject's identity intact.
- Dynamic Filling: Never output null values. Infer best fits based on Art Direction.

[2. OUTPUT REQUIREMENT]
Analyze the user request and user provided images (if any). Output a strict JSON object.
Additionally, generate a short, creative Chinese filename in the "file_name_cn" field.
`;

const structuraSchema: Schema = {
  type: Type.OBJECT,
  properties: {
    meta: {
      type: Type.OBJECT,
      properties: {
        version: { type: Type.STRING },
        prompt_complexity: { type: Type.STRING },
