      }
    },
    subject: {
      type: Type.OBJECT,
      properties: {
        description: { type: Type.STRING },
        pose: { type: Type.STRING },
        expression: { type: Type.STRING },
        clothing_and_accessories: { type: Type.STRING },
      }
    },
    art_direction: {
      type: Type.OBJECT,
      properties: {
        medium: { type: Type.STRING },
        visual_style: { type: Type.STRING },
        color_palette: { type: Type.STRING },
        artist_references: { type: Type.ARRAY, items: { type: Type.STRING } }
      }
    },
    technical_specs: {
      type: Type.OBJECT,
      properties: {
        lighting: { type: Type.STRING },
        camera: { type: Type.STRING },
        renderer_settings: { type: Type.STRING },
      }
    },
    environment: {
      type: Type.OBJECT,
      properties: {
        location: { type: Type.STRING },
        details: { type: Type.STRING },
        time_of_day: { type: Type.STRING },
        atmosphere: { type: Type.STRING },
      }
    },
    negative_constraints: {
      type: Type.OBJECT,
      properties: {
        forbidden_elements: { type: Type.ARRAY, items: { type: Type.STRING } }
      }
    },
    file_name_cn: { type: Type.STRING, description: "A creative filename in Chinese, max 10 chars" }
  },
  required: ["meta", "subject", "art_direction", "technical_specs", "environment", "negative_constraints", "file_name_cn"]
};

// Flatten JSON to Image Gen Prompt
const flattenStructuraPrompt = (data: StructuraData): string => {
  const { subject, art_direction, technical_specs, environment } = data;

  // Construct a dense, high-quality prompt string
  const stylePart = `${art_direction.medium}, ${art_direction.visual_style}.`;
  const subjectPart = `${subject.description}, ${subject.pose}, ${subject.expression}, ${subject.clothing_and_accessories}.`;
  const envPart = `${environment.location}, ${environment.atmosphere}, ${environment.time_of_day}, ${environment.details}.`;
  const techPart = `${technical_specs.lighting}, ${technical_specs.camera}, ${technical_specs.renderer_settings}.`;
  const colorPart = `Color Palette: ${art_direction.color_palette}.`;

  return `${stylePart} ${subjectPart} ${envPart} ${techPart} ${colorPart}`;
};

export const analyzeAndName = async (prompt: string = "", files: File[], isSmartAnalysis: boolean): Promise<{ structuraData: StructuraData | null, refinedPrompt: string, fileName: string }> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  const safePrompt = prompt || "";

  if (!isSmartAnalysis) {
    return {
      structuraData: null,
      refinedPrompt: safePrompt,
      fileName: `Direct-${Date.now()}`
    };
  }

  try {
    const parts: any[] = [];
    if (files.length > 0) {
      const imageParts = await Promise.all(files.map(fileToPart));
      parts.push(...imageParts);
    }

    parts.push({ text: `User Request: ${safePrompt || "（Create an artistic image based on visual inputs）"}` });

    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: { parts },
      config: { 
        systemInstruction: STRUCTURA_SYSTEM_PROMPT, 
        responseMimeType: "application/json",
        responseSchema: structuraSchema
      }
    });

    const jsonText = response.text || "{}";
    const data = JSON.parse(jsonText) as StructuraData;
    const refinedPrompt = flattenStructuraPrompt(data);

    return { 
      structuraData: data,
      refinedPrompt: refinedPrompt, 
      fileName: data.file_name_cn || "NanoArt" 
    };

  } catch (e) {
    console.error("Structura Analysis Failed:", e);
    // Fallback
    return { 
      structuraData: null,
      refinedPrompt: safePrompt || "High-end digital art masterpiece", 
      fileName: safePrompt.substring(0, 8) || "NanoError" 
    };
  }
};

export const generateSingleImage = async (
  prompt: string = "",
  inputFiles: (File | Blob)[],
  aspectRatio: AspectRatio,
  imageSize: ImageSize,
  model: AIModel,
  customWidth?: number,
  customHeight?: number
): Promise<string[]> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  const parts: any[] = [];

  if (inputFiles.length > 0) {
    const imageParts = await Promise.all(inputFiles.map(fileToPart));
    parts.push(...imageParts);
  }

  // 通过 Prompt 增强对长宽比的感知。由于 API 限制 9:16，Prompt 引导 AI 将主体放在极窄区域。
  const compositionPrompt = aspectRatio.includes("21") || aspectRatio.includes("10") 
    ? `, extreme ${aspectRatio} cinematic composition, fill the entire frame, panoramic view`
    : `, ${aspectRatio} aspect ratio`;

  parts.push({ text: `${(prompt || "").trim()}${compositionPrompt}` });

  const apiRatio = mapToSupportedRatio(aspectRatio, customWidth, customHeight);

  const config: any = {
    imageConfig: {
      aspectRatio: apiRatio,
      imageSize: model === AIModel.Pro ? imageSize : undefined
    }
  };

  const response = await ai.models.generateContent({
    model: model,
    contents: { parts },
    config
  });

  const urls: string[] = [];
  if (response.candidates?.[0]?.content?.parts) {
    for (const part of response.candidates[0].content.parts) {
      if (part.inlineData?.data) {
        // 直接返回原生像素数据，不再进行客户端裁切
        urls.push(`data:${part.inlineData.mimeType || 'image/png'};base64,${part.inlineData.data}`);
      }
    }
  }
  return urls;
};

import React, { useState, useEffect, useRef } from 'react';
