const fileToPart = async (file: File | Blob): Promise<{ inlineData: { data: string; mimeType: string } }> => {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onloadend = () => {
      if (typeof reader.result === 'string') {
        const base64Data = reader.result.split(',')[1];
        const mimeType = file.type || 'image/png';
        resolve({
          inlineData: {
            data: base64Data,
            mimeType: mimeType,
          },
        });
      } else {
        reject(new Error("读取数据失败"));
      }
    };
    reader.onerror = reject;
    reader.readAsDataURL(file);
  });
};

const mapToSupportedRatio = (ratio: AspectRatio, width?: number, height?: number): string => {
  if (ratio === AspectRatio.Custom && width && height) {
    const r = width / height;
    if (r >= 1.5) return "16:9";
    if (r >= 1.2) return "4:3";
    if (r > 0.8) return "1:1";
    if (r > 0.6) return "3:4";
    return "9:16";
  }

  switch (ratio) {
    case AspectRatio.Square: return "1:1";
    case AspectRatio.Ratio_3_2:
    case AspectRatio.Ratio_4_3:
    case AspectRatio.Ratio_5_4: return "4:3";
    case AspectRatio.Ratio_2_3:
    case AspectRatio.Ratio_3_4:
    case AspectRatio.Ratio_4_5: return "3:4";
    case AspectRatio.Ratio_16_9:
    case AspectRatio.Ratio_16_10:
    case AspectRatio.Ratio_21_9: return "16:9";
    case AspectRatio.Ratio_9_16:
    case AspectRatio.Ratio_10_16:
    case AspectRatio.Ratio_9_21: return "9:16";
    default: return "1:1";
  }
};

// JsonPromptMaker System Definition
const JSON_PROMPT_MAKER_SYS = `
ROLE & OBJECTIVE
You are JsonPromptMaker, a deterministic Prompt-to-JSON Engine.
Your task is to convert a user’s text prompt — optionally containing instructions
to extract specific attributes from a reference image that will be provided later
to the image generation model — into a precise, production-ready JSON prompt.

CORE RULES
1. Determinism: Given the same input, you must always produce the same JSON output.
2. No Inference: Never invent, hallucinate, infer, guess, optimize, or assume any attribute.
3. Image Source Priority: If an attribute allows "image" as a source AND the user does NOT explicitly provide a value, it MUST be resolved from the reference image.
4. Defaults: Only allowed if "image" is NOT an allowed source and text is missing.
5. Value Declaration: Never output null.
6. Image Locking: If user requests attribute from image, mark as image_locked.
7. Output Discipline: Only output valid JSON.

ADDITIONAL REQUIREMENT:
You must also provide a "file_name_cn" (a short creative Chinese filename) and a "prompt_translation_cn" (a Chinese translation/explanation of the generated JSON prompt intent).
`;

