export const analyzeAndName = async (prompt: string = "", files: File[], isSmartAnalysis: boolean): Promise<{ structuraData: JsonPromptData | null, refinedPrompt: string, fileName: string, promptTranslation: string }> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  const safePrompt = prompt || "";

  if (!isSmartAnalysis) {
    return {
      structuraData: null,
      refinedPrompt: safePrompt,
      fileName: `Direct-${Date.now()}`,
      promptTranslation: "无智能分析（直接模式）"
    };
  }

  try {
    const parts: any[] = [];
    if (files.length > 0) {
      const imageParts = await Promise.all(files.map(fileToPart));
      parts.push(...imageParts);
    }

    parts.push({ text: `User Request: ${safePrompt || "（Create an artistic image based on visual inputs）"}` });

    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: { parts },
      config: { 
        systemInstruction: JSON_PROMPT_MAKER_SYS, 
        responseMimeType: "application/json",
        responseSchema: jsonPromptSchema
      }
    });

    const jsonText = response.text || "{}";
    const data = JSON.parse(jsonText) as JsonPromptData;

    // The refined prompt is the JSON string itself for the model
    const refinedPrompt = JSON.stringify(data.prompt_payload);

    return { 
      structuraData: data,
      refinedPrompt: refinedPrompt, 
      fileName: data.file_name_cn || "NanoArt",
      promptTranslation: data.prompt_translation_cn || "解析完成"
    };

  } catch (e) {
    console.error("JsonPromptMaker Failed:", e);
    return { 
      structuraData: null,
      refinedPrompt: safePrompt || "High-end digital art masterpiece", 
      fileName: safePrompt.substring(0, 8) || "NanoError",
      promptTranslation: "解析失败，已回退到基础模式"
    };
  }
};

export const generateSingleImage = async (
  prompt: string = "",
  inputFiles: (File | Blob)[],
  aspectRatio: AspectRatio,
  imageSize: ImageSize,
  model: AIModel,
  customWidth?: number,
  customHeight?: number
): Promise<string[]> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  const parts: any[] = [];

  if (inputFiles.length > 0) {
    const imageParts = await Promise.all(inputFiles.map(fileToPart));
    parts.push(...imageParts);
  }

  // Handle aspect ratio prompt injection if strict JSON is not used, 
  // BUT if prompt is JSON, appending text might break valid JSON structure if not careful.
  // Nano Banana Pro can handle text appended to JSON, but it's cleaner to keep it separate.
  // For safety with JSON prompts, we rely heavily on the JSON content itself, 
  // but we can append a composition hint if it's extreme.

  let finalPrompt = prompt;

  // Only append ratio text if it's NOT a JSON string (simple heuristic) or if we want to force it.
  // Since we are sending JSON, let's trust the model or the JSON config. 
  // However, `compositionPrompt` helps with canvas filling.
  const compositionPrompt = aspectRatio.includes("21") || aspectRatio.includes("10") 
    ? ` (Extreme ${aspectRatio} aspect ratio, panoramic)`
    : ``;

  finalPrompt = finalPrompt + compositionPrompt;

  parts.push({ text: finalPrompt });

  const apiRatio = mapToSupportedRatio(aspectRatio, customWidth, customHeight);

  const config: any = {
    imageConfig: {
      aspectRatio: apiRatio,
      imageSize: model === AIModel.Pro ? imageSize : undefined
    }
  };

  const response = await ai.models.generateContent({
    model: model,
    contents: { parts },
    config
  });

  const urls: string[] = [];
  if (response.candidates?.[0]?.content?.parts) {
    for (const part of response.candidates[0].content.parts) {
      if (part.inlineData?.data) {
        urls.push(`data:${part.inlineData.mimeType || 'image/png'};base64,${part.inlineData.data}`);
      }
    }
  }
  return urls;
};

import React, { useState, useEffect, useRef } from 'react';
import { Sparkles, Download, Loader2, Image as ImageIcon, Check, Activity, Sun, Moon, Layers, X, ChevronLeft, ChevronRight, Wallet, Info, Coins, Zap, Cpu, Settings, Edit3 } from 'lucide-react';
import { generateSingleImage, analyzeAndName } from './services/geminiService';
