import { GoogleGenAI, Type, Schema } from "@google/genai";
import { AspectRatio, ImageSize, AIModel, JsonPromptData } from "../types";

const fileToPart = async (file: File | Blob): Promise<{ inlineData: { data: string; mimeType: string } }> => {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onloadend = () => {
      if (typeof reader.result === 'string') {
        const base64Data = reader.result.split(',')[1];
        const mimeType = file.type || 'image/png';
        resolve({
          inlineData: {
            data: base64Data,
            mimeType: mimeType,
          },
        });
      } else {
        reject(new Error("读取数据失败"));
      }
    };
    reader.onerror = reject;
    reader.readAsDataURL(file);
  });
};

const mapToSupportedRatio = (ratio: AspectRatio, width?: number, height?: number): string => {
  if (ratio === AspectRatio.Custom && width && height) {
    const r = width / height;
    if (r >= 1.5) return "16:9";
    if (r >= 1.2) return "4:3";
    if (r > 0.8) return "1:1";
    if (r > 0.6) return "3:4";
    return "9:16";
  }

  switch (ratio) {
    case AspectRatio.Square: return "1:1";
    case AspectRatio.Ratio_3_2:
    case AspectRatio.Ratio_4_3:
    case AspectRatio.Ratio_5_4: return "4:3";
    case AspectRatio.Ratio_2_3:
    case AspectRatio.Ratio_3_4:
    case AspectRatio.Ratio_4_5: return "3:4";
    case AspectRatio.Ratio_16_9:
    case AspectRatio.Ratio_16_10:
    case AspectRatio.Ratio_21_9: return "16:9";
    case AspectRatio.Ratio_9_16:
    case AspectRatio.Ratio_10_16:
    case AspectRatio.Ratio_9_21: return "9:16";
    default: return "1:1";
  }
};

// JsonPromptMaker System Definition
const JSON_PROMPT_MAKER_SYS = `
ROLE & OBJECTIVE
You are JsonPromptMaker, a deterministic Prompt-to-JSON Engine.
Your task is to convert a user’s text prompt — optionally containing instructions
to extract specific attributes from a reference image that will be provided later
to the image generation model — into a precise, production-ready JSON prompt.

CORE RULES
1. Determinism: Given the same input, you must always produce the same JSON output.
2. No Inference: Never invent, hallucinate, infer, guess, optimize, or assume any attribute.
3. Image Source Priority: If an attribute allows "image" as a source AND the user does NOT explicitly provide a value, it MUST be resolved from the reference image.
4. Defaults: Only allowed if "image" is NOT an allowed source and text is missing.
5. Value Declaration: Never output null.
6. Image Locking: If user requests attribute from image, mark as image_locked.
7. Output Discipline: Only output valid JSON.

ADDITIONAL REQUIREMENT:
You must also provide a "file_name_cn" (a short creative Chinese filename) and a "prompt_translation_cn" (a Chinese translation/explanation of the generated JSON prompt intent).
`;

// Helper for repetitive PromptSource schema
const promptSourceSchema = {
  type: Type.OBJECT,
  nullable: true,
  properties: {
    value: { type: Type.STRING },
    allowed_sources: { type: Type.ARRAY, items: { type: Type.STRING } },
    source_policy: { type: Type.STRING }
  }
};

const jsonPromptSchema: Schema = {
  type: Type.OBJECT,
  properties: {
    prompt_payload: {
      type: Type.OBJECT,
      description: "The strict JSON prompt for the image generation model.",
      properties: {
        task: { type: Type.STRING },
        reference_image_policy: {
          type: Type.OBJECT,
          properties: {
            used: { type: Type.BOOLEAN },
            represents: { type: Type.STRING },
            instructions: { type: Type.ARRAY, items: { type: Type.STRING } }
          }
        },
        subject: {
          type: Type.OBJECT,
          properties: {
            type: { type: Type.STRING },
            identity_lock: { 
               type: Type.OBJECT,
               nullable: true,
               properties: {
                 face: { type: Type.STRING },
                 age: { type: Type.STRING },
                 skin_tone: { type: Type.STRING },
                 facial_features: { type: Type.STRING },
                 body_proportions: { type: Type.STRING },
                 hair_style: { type: Type.STRING },
                 hair_color: { type: Type.STRING },
                 eye_color: { type: Type.STRING },
               }
            },
            pose: promptSourceSchema,
            expression: promptSourceSchema,
            gaze: promptSourceSchema
          }
        },
        appearance: { 
          type: Type.OBJECT, 
          nullable: true,
          properties: {
            clothing: promptSourceSchema,
            colors: {
              type: Type.OBJECT,
              nullable: true,
              properties: {
                primary_palette: promptSourceSchema
              }
            }
          } 
        },
        environment: {
          type: Type.OBJECT,
          properties: {
            location: promptSourceSchema,
            details: promptSourceSchema,
            time_of_day: promptSourceSchema,
            weather: promptSourceSchema
          }
        },
        camera: {
          type: Type.OBJECT,
          properties: {
            framing: promptSourceSchema,
            angle: promptSourceSchema,
            lens_feel: promptSourceSchema
          }
        },
        lighting: {
          type: Type.OBJECT,
          properties: {
            type: promptSourceSchema,
            direction: promptSourceSchema,
            intensity: promptSourceSchema
          }
        },
        style: {
           type: Type.OBJECT,
           properties: {
             render_type: promptSourceSchema
           }
        },
        quality_controls: {
          type: Type.OBJECT,
          properties: {
            forbidden_changes: { type: Type.ARRAY, items: { type: Type.STRING } }
          }
        }
      },
      required: ["task", "reference_image_policy", "subject", "environment", "camera", "lighting", "style", "quality_controls"]
    },
    file_name_cn: { type: Type.STRING, description: "Short creative Chinese filename" },
    prompt_translation_cn: { type: Type.STRING, description: "Chinese translation and explanation of the intent." }
  },
  required: ["prompt_payload", "file_name_cn", "prompt_translation_cn"]
};

export const analyzeAndName = async (prompt: string = "", files: File[], isSmartAnalysis: boolean): Promise<{ structuraData: JsonPromptData | null, refinedPrompt: string, fileName: string, promptTranslation: string }> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  const safePrompt = prompt || "";

  if (!isSmartAnalysis) {
    return {
      structuraData: null,
      refinedPrompt: safePrompt,
      fileName: `Direct-${Date.now()}`,
      promptTranslation: "无智能分析（直接模式）"
    };
  }

  try {
    const parts: any[] = [];
    if (files.length > 0) {
      const imageParts = await Promise.all(files.map(fileToPart));
      parts.push(...imageParts);
    }

    parts.push({ text: `User Request: ${safePrompt || "（Create an artistic image based on visual inputs）"}` });

    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: { parts },
      config: { 
        systemInstruction: JSON_PROMPT_MAKER_SYS, 
        responseMimeType: "application/json",
        responseSchema: jsonPromptSchema
      }
    });

    const jsonText = response.text || "{}";
    const data = JSON.parse(jsonText) as JsonPromptData;

    // The refined prompt is the JSON string itself for the model
    const refinedPrompt = JSON.stringify(data.prompt_payload);

    return { 
      structuraData: data,
      refinedPrompt: refinedPrompt, 
      fileName: data.file_name_cn || "NanoArt",
      promptTranslation: data.prompt_translation_cn || "解析完成"
    };

  } catch (e) {
    console.error("JsonPromptMaker Failed:", e);
    // Return fallback to ensure app doesn't crash, but log error
    return { 
      structuraData: null,
      refinedPrompt: safePrompt || "High-end digital art masterpiece", 
      fileName: safePrompt.substring(0, 8) || "NanoError",
      promptTranslation: "解析失败，已回退到基础模式"
    };
  }
};

export const generateSingleImage = async (
  prompt: string = "",
  inputFiles: (File | Blob)[],
  aspectRatio: AspectRatio,
  imageSize: ImageSize,
  model: AIModel,
  customWidth?: number,
  customHeight?: number
): Promise<string[]> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  const parts: any[] = [];

  if (inputFiles.length > 0) {
    const imageParts = await Promise.all(inputFiles.map(fileToPart));
    parts.push(...imageParts);
  }

  // Handle aspect ratio prompt injection if strict JSON is not used, 
  // BUT if prompt is JSON, appending text might break valid JSON structure if not careful.
  // Nano Banana Pro can handle text appended to JSON, but it's cleaner to keep it separate.
  // For safety with JSON prompts, we rely heavily on the JSON content itself, 
  // but we can append a composition hint if it's extreme.

  let finalPrompt = prompt;

  // Only append ratio text if it's NOT a JSON string (simple heuristic) or if we want to force it.
  // Since we are sending JSON, let's trust the model or the JSON config. 
  // However, `compositionPrompt` helps with canvas filling.
  const compositionPrompt = aspectRatio.includes("21") || aspectRatio.includes("10") 
    ? ` (Extreme ${aspectRatio} aspect ratio, panoramic)`
    : ``;

  // We check if it looks like JSON. If so, don't break it. 
  // But wait, the model can take {parts: [{text: json}, {text: prompt}]}.
  // For simplicity, we just append to text if it's not JSON, or leave it if it is.
  if (!finalPrompt.trim().startsWith('{')) {
      finalPrompt = finalPrompt + compositionPrompt;
  }

  parts.push({ text: finalPrompt });

  const apiRatio = mapToSupportedRatio(aspectRatio, customWidth, customHeight);

  const config: any = {
    imageConfig: {
      aspectRatio: apiRatio,
      imageSize: model === AIModel.Pro ? imageSize : undefined
    }
  };

  const response = await ai.models.generateContent({
    model: model,
    contents: { parts },
    config
  });

  const urls: string[] = [];
  if (response.candidates?.[0]?.content?.parts) {
    for (const part of response.candidates[0].content.parts) {
      if (part.inlineData?.data) {
        urls.push(`data:${part.inlineData.mimeType || 'image/png'};base64,${part.inlineData.data}`);
      }
    }
  }
  return urls;
};

