                  <button onClick={() => setShowCode(true)} className={`flex-1 py-1.5 rounded-lg text-[10px] font-bold transition-all flex items-center justify-center gap-1.5 ${showCode ? 'bg-banana-500 text-slate-900' : 'text-slate-400 hover:text-white'}`}><Code2 size={12}/> 结构化代码</button>
