                className="group relative bg-white dark:bg-slate-900 rounded-[2.5rem] lg:rounded-[3rem] overflow-hidden border border-slate-200 dark:border-slate-800 shadow-xl transition-all duration-500 hover:scale-[1.02] hover:shadow-2xl cursor-pointer"
                onClick={() => setSelectedImage(img)}
              >
                <div className="aspect-[4/5] relative">
                  <img src={img.url} className="w-full h-full object-cover" loading="lazy" />

                  {/* 右上角快速下载按钮 - 移动端始终可见以优化体验 */}
                  <div className="absolute top-4 right-4 lg:top-5 lg:right-5 z-20 opacity-100 lg:opacity-0 lg:group-hover:opacity-100 transition-all duration-300 transform lg:-translate-y-2 lg:group-hover:translate-y-0">
                     <a 
                       href={img.url} 
                       download={`${img.filename}.png`} 
                       onClick={(e) => e.stopPropagation()} 
                       className="w-10 h-10 lg:w-11 lg:h-11 flex items-center justify-center bg-black/40 lg:bg-black/30 hover:bg-banana-500 backdrop-blur-md rounded-full text-white hover:text-slate-900 border border-white/10 transition-all shadow-lg"
                       title="下载原图"
                     >
                        <Download size={18} />
                     </a>
                  </div>

                  <div className="absolute inset-0 bg-gradient-to-t from-black/80 via-transparent to-transparent opacity-0 group-hover:opacity-100 transition-all duration-300 p-6 lg:p-8 flex flex-col justify-end">
                    <p className="text-white text-xs font-bold line-clamp-2 mb-4">"{img.prompt}"</p>
                    <div className="flex gap-2">
                       <button onClick={(e) => { e.stopPropagation(); setSelectedImage(img); }} className="flex-1 py-3 bg-white/20 backdrop-blur-xl hover:bg-white/30 text-white rounded-2xl text-[10px] font-black uppercase tracking-widest transition-all">查看详情</button>
                       <a href={img.url} download={`${img.filename}.png`} onClick={(e) => e.stopPropagation()} className="p-3 bg-banana-500 hover:bg-banana-400 text-slate-950 rounded-2xl transition-all shadow-lg"><Download size={18} /></a>
                    </div>
                  </div>
                  <div className="absolute top-4 left-4 lg:top-6 lg:left-6 flex flex-col gap-2">
                     <span className="px-3 py-1 lg:px-4 lg:py-1.5 bg-black/40 backdrop-blur-md rounded-full text-[8px] font-black text-white border border-white/10 uppercase tracking-widest">{img.filename.slice(0,10)}</span>
                  </div>
                </div>
              </div>
            ))}

            {allImages.length === 0 && !isGenerating && (
                <div className="col-span-full py-20 lg:py-40 flex flex-col items-center justify-center text-slate-400 bg-white/50 dark:bg-slate-900/20 border-4 border-dashed border-slate-200 dark:border-slate-800 rounded-[3rem] lg:rounded-[5rem]">
                    <Sparkles size={48} className="opacity-20 text-banana-600 mb-6 lg:mb-8" />
                    <p className="text-lg lg:text-xl font-black opacity-40">创作库尚无记录</p>
                </div>
            )}
          </div>
        </div>
      </div>

      {selectedImage && (
        <ImageViewer 
          image={selectedImage} 
          isCopied={!!copyStatus[selectedImage.id]} 
          onCopy={() => handleCopyPrompt(selectedImage.prompt, selectedImage.id)} 
          onClose={() => setSelectedImage(null)} 
          onNext={() => navigateImage(1)} 
          onPrev={() => navigateImage(-1)} 
          onEdit={() => { setEditingImage({ url: selectedImage.url, name: selectedImage.filename, type: 'generated' }); setSelectedImage(null); }}
          currency={currency} 
        />
      )}

      {editingImage && (
        <ImageEditor image={editingImage} onClose={() => setEditingImage(null)} onDone={handleEditorDone} />
      )}
    </div>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
import { AspectRatio, ImageSize, AIModel } from '../types';
import { Settings2, Cpu, BrainCircuit, Layout, X, Layers, Monitor, SlidersHorizontal, Smartphone, Monitor as MonitorIcon, Square } from 'lucide-react';

interface SettingsPanelProps {
  aspectRatio: AspectRatio;
  imageSize: ImageSize;
  batchSize: number;
  model: AIModel;
  isSmartAnalysis: boolean;
  customWidth?: number;
  customHeight?: number;
  onAspectRatioChange: (ratio: AspectRatio) => void;
  onImageSizeChange: (size: ImageSize) => void;
  onBatchSizeChange: (size: number) => void;
  onModelChange: (model: AIModel) => void;
  onSmartAnalysisChange: (enabled: boolean) => void;
  onCustomPixelsChange: (width: number, height: number) => void;
  disabled: boolean;
}

const ratioGroups = [
  { label: "1:1", landscape: AspectRatio.Square, portrait: AspectRatio.Square },
  { label: "3:2", landscape: AspectRatio.Ratio_3_2, portrait: AspectRatio.Ratio_2_3 },
  { label: "4:3", landscape: AspectRatio.Ratio_4_3, portrait: AspectRatio.Ratio_3_4 },
  { label: "4:5", landscape: AspectRatio.Ratio_5_4, portrait: AspectRatio.Ratio_4_5 },
  { label: "16:9", landscape: AspectRatio.Ratio_16_9, portrait: AspectRatio.Ratio_9_16 },
  { label: "16:10", landscape: AspectRatio.Ratio_16_10, portrait: AspectRatio.Ratio_10_16 },
  { label: "21:9", landscape: AspectRatio.Ratio_21_9, portrait: AspectRatio.Ratio_9_21 },
];

const AspectRatioIcon = ({ ratio, active }: { ratio: string, active: boolean }) => {
  const [w, h] = ratio.split(':').map(Number);
  const max = Math.max(w, h);
  const width = (w / max) * 100;
  const height = (h / max) * 100;
  return (
    <div className={`flex items-center justify-center w-6 h-6 mr-3`}>
      <div 
        className={`border-2 rounded-[3px] transition-all duration-300 ${active ? 'border-banana-600 bg-banana-500/20 shadow-[0_0_8px_rgba(234,179,8,0.4)]' : 'border-slate-400 dark:border-slate-600 bg-transparent'}`}
        style={{ width: `${width}%`, height: `${height}%` }}
      />
    </div>
  );
};

const SettingsPanel: React.FC<SettingsPanelProps> = ({
  aspectRatio, imageSize, batchSize, model, isSmartAnalysis,
  onAspectRatioChange, onImageSizeChange, onBatchSizeChange, onModelChange,
  onSmartAnalysisChange,
  disabled
}) => {
  // 根据传入的 aspectRatio 初始判断方向
  const [orientation, setOrientation] = useState<'portrait' | 'landscape'>(() => {
    const isPortrait = ratioGroups.some(g => g.portrait === aspectRatio && g.portrait !== g.landscape);
    return isPortrait ? 'portrait' : 'landscape';
  });

  const handleOrientationSwitch = (newOrientation: 'portrait' | 'landscape') => {
    if (newOrientation === orientation) return;
    setOrientation(newOrientation);

    // 查找当前比例对应的标签，并在切换方向后更新父组件的 aspectRatio
    const currentGroup = ratioGroups.find(g => g.landscape === aspectRatio || g.portrait === aspectRatio);
    if (currentGroup) {
      onAspectRatioChange(newOrientation === 'landscape' ? currentGroup.landscape : currentGroup.portrait);
    }
  };

  return (
    <div className="bg-white dark:bg-slate-800/40 rounded-[2.5rem] p-5 border border-slate-200 dark:border-slate-700/50 space-y-6 backdrop-blur-sm shadow-sm">
      <div className="space-y-2">
        <label className="text-[10px] text-slate-500 dark:text-slate-400 font-black uppercase flex items-center gap-2 px-1">
          <Cpu size={14} /> 核心引擎
        </label>
        <div className="grid grid-cols-2 gap-1.5 bg-slate-100 dark:bg-slate-900/50 p-1.5 rounded-[1.8rem] border border-slate-200 dark:border-slate-700/30">
          {[AIModel.Standard, AIModel.Pro].map(m => (
            <button
              key={m} disabled={disabled} onClick={() => onModelChange(m)}
              className={`py-3 rounded-[1.5rem] text-[11px] font-black transition-all ${
                model === m ? 'bg-banana-500 text-slate-900 shadow-xl' : 'text-slate-500 hover:text-slate-700 dark:hover:text-slate-300'
              }`}
            >
              {m === AIModel.Pro ? 'Banana Pro' : 'Standard'}
            </button>
          ))}
        </div>
      </div>

      <button
        disabled={disabled} onClick={() => onSmartAnalysisChange(!isSmartAnalysis)}
        className={`w-full flex items-center justify-between py-4 px-5 rounded-[1.8rem] border transition-all duration-300 ${isSmartAnalysis ? 'bg-banana-500/10 border-banana-500 text-banana-600 dark:text-banana-400 shadow-sm' : 'bg-slate-50 dark:bg-slate-900/50 border-slate-200 dark:border-slate-800 text-slate-500'}`}
      >
        <div className="flex items-center gap-3">
          <BrainCircuit size={16} />
          <span className="text-[11px] font-black uppercase tracking-tight">AI 语义强化分析</span>
        </div>
        <div className={`w-9 h-5 rounded-full relative transition-colors duration-300 ${isSmartAnalysis ? 'bg-banana-500 shadow-[0_0_10px_rgba(234,179,8,0.5)]' : 'bg-slate-300 dark:bg-slate-700'}`}>
          <div className={`absolute top-0.5 left-0.5 w-4 h-4 bg-white rounded-full transition-transform duration-300 shadow-sm ${isSmartAnalysis ? 'translate-x-4' : 'translate-x-0'}`} />
        </div>
      </button>

      <div className="space-y-3">
        <div className="flex items-center justify-between px-1">
           <label className="text-[10px] text-slate-500 dark:text-slate-400 font-black uppercase flex items-center gap-2">
             <Layout size={14} /> 画幅比例
           </label>
           <div className="flex items-center bg-slate-100 dark:bg-slate-900 p-1 rounded-2xl border border-slate-200 dark:border-slate-800">
              <button onClick={() => handleOrientationSwitch('landscape')} className={`flex items-center gap-1.5 px-4 py-1.5 rounded-xl text-[10px] font-black transition-all ${orientation === 'landscape' ? 'bg-white dark:bg-slate-800 text-banana-600 dark:text-banana-400 shadow-sm' : 'text-slate-400'}`}><MonitorIcon size={12} /> 横</button>
              <button onClick={() => handleOrientationSwitch('portrait')} className={`flex items-center gap-1.5 px-4 py-1.5 rounded-xl text-[10px] font-black transition-all ${orientation === 'portrait' ? 'bg-white dark:bg-slate-800 text-banana-600 dark:text-banana-400 shadow-sm' : 'text-slate-400'}`}><Smartphone size={12} /> 竖</button>
           </div>
        </div>
        <div className="grid grid-cols-2 gap-2">
           {ratioGroups.map((g) => {
             const targetRatio = orientation === 'landscape' ? g.landscape : g.portrait;
             // 必须使用全等判断 AspectRatio 枚举值，确保唯一高亮
             const isActive = aspectRatio === targetRatio;

             return (
               <button 
                key={`${g.label}-${orientation}`} 
                onClick={() => onAspectRatioChange(targetRatio)} 
                className={`flex items-center py-3.5 px-4 rounded-[1.6rem] border text-[11px] font-black transition-all ${isActive ? 'bg-banana-500/10 border-banana-500 text-banana-600 dark:text-banana-400 shadow-sm' : 'bg-slate-50 dark:bg-slate-900/30 border-slate-200 dark:border-slate-800 text-slate-500 hover:border-slate-300 dark:hover:border-slate-700'}`}
               >
                 <AspectRatioIcon ratio={targetRatio} active={isActive} /> {g.label}
               </button>
             );
           })}
        </div>
      </div>

      <div className="space-y-5 px-1">
        <div className="space-y-3">
          <div className="flex justify-between items-center">
            <label className="text-[10px] text-slate-500 dark:text-slate-400 font-black uppercase flex items-center gap-2"><Layers size={14} /> 批量数</label>
            <span className="text-banana-600 dark:text-banana-400 font-black text-[11px] bg-banana-500/10 px-3 py-1 rounded-xl">{batchSize} 张</span>
          </div>
          <input type="range" min="1" max="10" step="1" value={batchSize} disabled={disabled} onChange={(e) => onBatchSizeChange(parseInt(e.target.value))} className="w-full h-2 bg-slate-200 dark:bg-slate-700 rounded-full appearance-none cursor-pointer accent-banana-500" />
        </div>
        <div className="space-y-3">
          <label className="text-[10px] text-slate-500 dark:text-slate-400 font-black uppercase flex items-center gap-2"><Monitor size={14} /> 渲染质量 (仅 Pro 可选)</label>
          <div className="grid grid-cols-3 gap-1.5">
            {[ImageSize.Size_1K, ImageSize.Size_2K, ImageSize.Size_4K].map(s => (
              <button key={s} disabled={disabled || model === AIModel.Standard} onClick={() => onImageSizeChange(s)} className={`py-3.5 rounded-[1.4rem] border text-[11px] font-black transition-all ${imageSize === s && model === AIModel.Pro ? 'bg-slate-800 dark:bg-white text-white dark:text-slate-950 border-slate-900 dark:border-white shadow-lg' : 'bg-white dark:bg-slate-900/50 border-slate-200 dark:border-slate-800 text-slate-500'} ${model === AIModel.Standard ? 'opacity-30' : ''}`}>{s}</button>
            ))}
          </div>
        </div>
      </div>
    </div>
  );
};

export default SettingsPanel;

import React, { useState, useEffect } from 'react';
import { X, Download, ZoomIn, ZoomOut, RotateCcw, Copy, Check, Tag, BrainCircuit, Timer, ChevronLeft, ChevronRight, Wallet, Edit3, Maximize2, Share2, Code2, MessageSquareText, FileJson, ListOrdered } from 'lucide-react';
import { GeneratedImage, Currency } from '../types';

interface ImageViewerProps {
  image: GeneratedImage;
  isCopied: boolean;
  onClose: () => void;
  onCopy: () => void;
  onNext: () => void;
  onPrev: () => void;
  onEdit: () => void;
  currency: Currency;
}

const ImageViewer: React.FC<ImageViewerProps> = ({ image, isCopied, onClose, onCopy, onNext, onPrev, onEdit, currency }) => {
  const [scale, setScale] = useState(1);
  const [position, setPosition] = useState({ x: 0, y: 0 });
  const [isDragging, setIsDragging] = useState(false);
  const [dragStart, setDragStart] = useState({ x: 0, y: 0 });
  const [showThinking, setShowThinking] = useState(false);
  const [showCode, setShowCode] = useState(false);

  useEffect(() => {
    document.body.style.overflow = 'hidden';
    return () => { document.body.style.overflow = 'unset'; };
  }, []);

  const handleWheel = (e: React.WheelEvent) => {
    e.stopPropagation();
    const delta = -e.deltaY * 0.0015;
    setScale(prev => Math.min(Math.max(0.5, prev + delta), 10));
  };

  const handleMouseDown = (e: React.MouseEvent) => {
    if (scale > 1) {
      setIsDragging(true);
      setDragStart({ x: e.clientX - position.x, y: e.clientY - position.y });
    }
  };

  const handleMouseMove = (e: React.MouseEvent) => {
    if (isDragging && scale > 1) {
      setPosition({ x: e.clientX - dragStart.x, y: e.clientY - dragStart.y });
    }
  };

  const handleShare = async () => {
    if (navigator.share) {
      try {
        await navigator.share({
          title: `Nano Art: ${image.filename}`,
          text: image.prompt,
          url: window.location.href,
        });
      } catch (err) {
        console.error("分享失败:", err);
      }
    } else {
        onCopy();
        alert("浏览器不支持原生分享，已为您复制咒语内容。");
    }
  };

  const renderCodeContent = () => {
    if (image.structuraData) {
        return JSON.stringify(image.structuraData.prompt_payload, null, 2);
    }
    // Try parse refinedPrompt if it looks like JSON
    const text = image.refinedPrompt || "";
    if (text.trim().startsWith('{')) {
        try {
            return JSON.stringify(JSON.parse(text), null, 2);
        } catch (e) {
            return text;
        }
    }
    return text || "No Data";
  };

  return (
    <div className="fixed inset-0 z-[100] flex items-center justify-center bg-black/95 backdrop-blur-2xl animate-in fade-in duration-500" onClick={onClose}>

      {/* 顶部控制栏 - 响应式调整 */}
      <div className="absolute top-0 inset-x-0 p-4 lg:p-6 flex justify-between items-start z-[110] pointer-events-none">
        <div className="flex flex-wrap items-center gap-2 lg:gap-3 pointer-events-auto">
             <div className="bg-slate-900/90 backdrop-blur-xl rounded-2xl border border-white/10 p-1 flex gap-0.5 shadow-2xl overflow-hidden">
                <button onClick={(e) => { e.stopPropagation(); setScale(Math.min(scale + 0.5, 10)); }} className="p-2 lg:p-3 hover:bg-white/10 rounded-xl text-slate-300 transition-colors"><ZoomIn size={18} /></button>
                <button onClick={(e) => { e.stopPropagation(); setScale(Math.max(0.5, scale - 0.5)); }} className="p-2 lg:p-3 hover:bg-white/10 rounded-xl text-slate-300 transition-colors"><ZoomOut size={18} /></button>
                <button onClick={(e) => { e.stopPropagation(); setScale(1); setPosition({x:0,y:0}); }} className="p-2 lg:p-3 hover:bg-white/10 rounded-xl text-slate-300 transition-colors"><RotateCcw size={18} /></button>
             </div>

             <div className="hidden sm:flex bg-slate-900/90 backdrop-blur-xl rounded-2xl border border-white/10 p-1 shadow-2xl">
               <button onClick={(e) => { e.stopPropagation(); onEdit(); }} className="flex items-center gap-2 bg-banana-500 hover:bg-banana-400 text-slate-950 px-4 lg:px-5 py-2.5 lg:py-3 rounded-xl font-black text-[9px] lg:text-[10px] uppercase tracking-widest transition-all"><Edit3 size={14} /> 编辑</button>
               <button onClick={(e) => { e.stopPropagation(); setShowThinking(!showThinking); }} className={`flex items-center gap-2 text-[9px] lg:text-[10px] font-black uppercase px-4 lg:px-5 py-2.5 lg:py-3 rounded-xl transition-all ${showThinking ? 'bg-white text-slate-950 shadow-xl' : 'text-slate-300 hover:bg-white/5'}`}><BrainCircuit size={14} /> 核心数据</button>
             </div>

             <div className="bg-slate-900/90 backdrop-blur-xl rounded-2xl px-4 py-2.5 lg:px-5 lg:py-3.5 border border-white/10 flex items-center gap-2 text-banana-500 font-black text-[9px] lg:text-[10px] uppercase tracking-widest shadow-2xl">
                <Wallet size={12} /> <span>{currency === 'RMB' ? `¥${image.costRMB.toFixed(2)}` : `$${image.costUSD.toFixed(3)}`}</span>
             </div>
        </div>

        <div className="flex gap-2 lg:gap-3 pointer-events-auto">
          <button onClick={(e) => { e.stopPropagation(); onCopy(); }} className={`hidden md:flex px-6 py-3.5 rounded-2xl transition-all shadow-2xl items-center gap-2 border ${isCopied ? 'bg-green-500 border-green-400 text-white' : 'bg-slate-900/90 border-white/10 hover:bg-slate-800 text-white'}`}>
            {isCopied ? <Check size={18} /> : <Copy size={18} />}
            <span className="text-[10px] font-black uppercase tracking-widest">{isCopied ? '已复制' : '复制咒语'}</span>
          </button>
          <a href={image.url} download={`${image.filename}.png`} onClick={(e) => e.stopPropagation()} className="p-3 lg:p-4 bg-banana-500 hover:bg-banana-400 text-slate-950 rounded-2xl transition-all shadow-xl" title="下载原图"><Download size={20} /></a>
          <button onClick={onClose} className="p-3 lg:p-4 bg-slate-900/90 hover:bg-red-500/20 text-white hover:text-red-400 rounded-2xl transition-all border border-white/10"><X size={20} /></button>
        </div>
      </div>

      {/* 左右翻页 - 手机端缩小以防误触 */}
      <div className="absolute inset-x-4 lg:inset-x-6 top-1/2 -translate-y-1/2 flex justify-between pointer-events-none z-[105]">
          <button onClick={(e) => { e.stopPropagation(); onPrev(); }} className="p-4 lg:p-6 bg-white/5 hover:bg-white/10 backdrop-blur-3xl rounded-full text-white border border-white/10 transition-all pointer-events-auto shadow-2xl group"><ChevronLeft size={24} /></button>
          <button onClick={(e) => { e.stopPropagation(); onNext(); }} className="p-4 lg:p-6 bg-white/5 hover:bg-white/10 backdrop-blur-3xl rounded-full text-white border border-white/10 transition-all pointer-events-auto shadow-2xl group"><ChevronRight size={24} /></button>
      </div>

      {/* 主图片显示 */}
      <div className="w-full h-full flex items-center justify-center overflow-hidden" onWheel={handleWheel} onMouseDown={handleMouseDown} onMouseMove={handleMouseMove} onMouseUp={() => setIsDragging(false)} onMouseLeave={() => setIsDragging(false)} onClick={(e) => e.stopPropagation()}>
        <img src={image.url} alt={image.prompt} className="max-w-[95%] max-h-[85%] object-contain transition-transform duration-150 select-none shadow-[0_40px_100px_rgba(0,0,0,0.8)] rounded-3xl lg:rounded-[3rem]" style={{ transform: `translate(${position.x}px, ${position.y}px) scale(${scale})`, cursor: scale > 1 ? (isDragging ? 'grabbing' : 'grab') : 'default' }} draggable={false} />
      </div>

      {/* 溯源面板 - 核心数据展示 */}
      {showThinking && (
          <div className="absolute top-24 lg:top-32 left-4 lg:left-8 w-80 lg:w-96 bg-slate-900/95 backdrop-blur-3xl border border-white/10 rounded-[2rem] lg:rounded-[2.5rem] p-6 lg:p-8 shadow-2xl animate-in slide-in-from-left-4 duration-500 pointer-events-auto z-[120] flex flex-col gap-5 max-h-[60vh] overflow-hidden" onClick={(e) => e.stopPropagation()}>
              <div className="flex items-center justify-between border-b border-white/10 pb-3">
                  <div className="flex items-center gap-2 text-banana-500 font-black text-[10px] uppercase tracking-widest"><BrainCircuit size={16} /> 核心数据</div>
                  <div className="text-[9px] font-mono text-slate-500">{image.totalDuration.toFixed(2)}s</div>
              </div>

              {/* 顶部常驻：中文意图翻译 */}
              {image.promptTranslation && (
                <div className="bg-white/5 p-4 rounded-2xl border border-white/5 shrink-0">
                    <div className="flex items-center gap-2 mb-2 text-[10px] font-black uppercase tracking-widest text-slate-400">
                        <MessageSquareText size={12} className="text-banana-500" /> 
                        中文构建意图
                    </div>
                    <p className="text-[11px] text-slate-300 leading-relaxed font-medium">{image.promptTranslation}</p>
                </div>
              )}

              {/* 切换开关 */}
              <div className="flex bg-slate-800/50 p-1 rounded-xl shrink-0">
                  <button onClick={() => setShowCode(false)} className={`flex-1 py-1.5 rounded-lg text-[10px] font-bold transition-all flex items-center justify-center gap-1.5 ${!showCode ? 'bg-banana-500 text-slate-900' : 'text-slate-400 hover:text-white'}`}><ListOrdered size={12}/> 执行流</button>
                  <button onClick={() => setShowCode(true)} className={`flex-1 py-1.5 rounded-lg text-[10px] font-bold transition-all flex items-center justify-center gap-1.5 ${showCode ? 'bg-banana-500 text-slate-900' : 'text-slate-400 hover:text-white'}`}><FileJson size={12}/> 结构化 JSON</button>
              </div>

              {/* 可滚动内容区域 */}
              <div className="flex-1 overflow-y-auto no-scrollbar">
                {!showCode ? (
                    <div className="space-y-3 pt-1">
                       {image.thoughtLog.map((step, idx) => (
                           <div key={idx} className="flex items-center gap-3 bg-white/5 p-3 rounded-xl border border-white/5">
                               <div className={`w-2 h-2 rounded-full ${step.status === 'done' ? 'bg-banana-500 shadow-[0_0_8px_rgba(234,179,8,0.5)]' : 'bg-slate-700'}`} />
                               <span className="text-[10px] font-bold text-slate-300">{step.name}</span>
                           </div>
                       ))}
                    </div>
