import React, { useState, useRef, Suspense } from 'react';
import { Canvas, useThree } from '@react-three/fiber';
import { OrbitControls, PerspectiveCamera, Environment } from '@react-three/drei';
import { Box, ChevronDown, ChevronUp, Copy, RefreshCw, BoxSelect } from 'lucide-react';
import * as THREE from 'three';

interface Cube3DWidgetProps {
  onExtract: (text: string) => void;
}

// 场景控制器，用于获取相机数据
const SceneController = ({ getCameraDataRef }: { getCameraDataRef: React.MutableRefObject<any> }) => {
  const { camera, gl } = useThree();
  const controlsRef = useRef<any>(null);

  // 将获取数据的函数暴露给父组件
  getCameraDataRef.current = () => {
    const cam = camera as THREE.PerspectiveCamera;
    const target = controlsRef.current?.target || new THREE.Vector3(0, 0, 0);

    return {
      position: {
        x: cam.position.x,
        y: cam.position.y,
        z: cam.position.z
      },
      target: {
        x: target.x,
        y: target.y,
        z: target.z
      },
      zoom: cam.zoom,
      cameraType: "perspective"
    };
  };

  return (
    <>
      <OrbitControls 
        ref={controlsRef}
        makeDefault 
        enableDamping={false} // 关闭阻尼，实现即停
        autoRotate={false}    // 默认静止
        enablePan={true}
        enableZoom={true}
      />
      <ambientLight intensity={0.5} />
      <directionalLight position={[10, 10, 5]} intensity={1} />
    </>
  );
};

const CubeMesh = () => {
  return (
    <mesh>
      <boxGeometry args={[2.5, 2.5, 2.5]} />
      {/* 使用 NormalMaterial 让每个面颜色不同，看起来多彩且有方位感 */}
      <meshNormalMaterial /> 
      <lineSegments>
        <edgesGeometry args={[new THREE.BoxGeometry(2.5, 2.5, 2.5)]} />
        <lineBasicMaterial color="white" linewidth={2} />
      </lineSegments>
    </mesh>
  );
};

const Cube3DWidget: React.FC<Cube3DWidgetProps> = ({ onExtract }) => {
  const [isOpen, setIsOpen] = useState(false);
  const [output, setOutput] = useState('');
  const getCameraDataRef = useRef<(() => any) | null>(null);

  const handleGetCoordinates = () => {
    if (getCameraDataRef.current) {
      const data = getCameraDataRef.current();

      const jsonString = JSON.stringify(data);
      // 构造符合用户要求的特定格式
      const formattedText = `Simulate spatial rendering based on 3D spatial coordinate information, including position, scaling, and camera type: ${jsonString}\nChange the shooting angle of the image`;

      setOutput(formattedText);
    }
  };

  const handleCopy = () => {
    if (output) {
      navigator.clipboard.writeText(output);
      // 可以在这里加个简单的 Toast 提示，但为了保持简洁暂时省略
    }
  };

  const handleApplyToPrompt = () => {
    if (output) {
        onExtract(output);
    }
  }

  return (
    <div className="bg-white dark:bg-slate-900 rounded-[2rem] border border-slate-200 dark:border-slate-800 overflow-hidden shadow-sm transition-all duration-300">
      <button 
        onClick={() => setIsOpen(!isOpen)}
        className="w-full flex items-center justify-between p-4 hover:bg-slate-50 dark:hover:bg-slate-800/50 transition-colors"
      >
        <div className="flex items-center gap-2">
          <div className="p-1.5 bg-indigo-500/10 rounded-lg">
             <BoxSelect size={16} className="text-indigo-500" />
          </div>
          <span className="text-[11px] font-black uppercase tracking-widest text-slate-600 dark:text-slate-300">3D 空间构图模拟</span>
        </div>
        {isOpen ? <ChevronUp size={16} className="text-slate-400" /> : <ChevronDown size={16} className="text-slate-400" />}
      </button>

      {isOpen && (
        <div className="p-4 pt-0 space-y-4 animate-in slide-in-from-top-2">
          {/* 3D Canvas 区域 */}
          <div className="relative w-full h-48 bg-slate-100 dark:bg-slate-950 rounded-2xl overflow-hidden border border-slate-200 dark:border-slate-800 cursor-move">
            <Canvas camera={{ position: [5, 5, 5], fov: 50 }}>
              <Suspense fallback={null}>
                <SceneController getCameraDataRef={getCameraDataRef} />
                <CubeMesh />
                <gridHelper args={[20, 20, 0x444444, 0x222222]} />
                <axesHelper args={[5]} />
              </Suspense>
            </Canvas>
            <div className="absolute bottom-2 right-2 text-[9px] text-slate-400 font-mono bg-black/50 px-2 py-0.5 rounded-full pointer-events-none">
                拖拽旋转 / 滚轮缩放
            </div>
          </div>

          {/* 操作按钮 */}
          <button 
            onClick={handleGetCoordinates}
            className="w-full py-2.5 bg-indigo-500 hover:bg-indigo-400 text-white rounded-xl text-[10px] font-black uppercase tracking-widest transition-all flex items-center justify-center gap-2 shadow-lg shadow-indigo-500/20 active:scale-95"
          >
            <RefreshCw size={14} /> 获取空间坐标 (Get Coordinates)
          </button>

          {/* 输出文本框 */}
          {output && (
            <div className="space-y-2">
                <div className="relative group">
                    <textarea 
                        readOnly
                        value={output}
                        className="w-full h-24 bg-slate-50 dark:bg-black/20 border border-slate-200 dark:border-slate-800 rounded-xl p-3 text-[9px] font-mono text-slate-600 dark:text-slate-400 resize-none outline-none focus:border-indigo-500 transition-colors leading-relaxed"
                    />
                    <button 
                        onClick={handleCopy}
                        className="absolute top-2 right-2 p-1.5 bg-white dark:bg-slate-800 hover:bg-slate-100 dark:hover:bg-slate-700 rounded-lg text-slate-400 hover:text-indigo-500 transition-colors shadow-sm"
                        title="复制"
                    >
                        <Copy size={12} />
                    </button>
                </div>

                <button 
                    onClick={handleApplyToPrompt}
                    className="w-full py-2 border border-slate-200 dark:border-slate-700 hover:border-indigo-500 text-slate-500 hover:text-indigo-500 dark:text-slate-400 rounded-xl text-[10px] font-bold transition-all"
                >
                    插入到提示词输入框
                </button>
            </div>
          )}
        </div>
      )}
    </div>
  );
};

