// 场景控制器
const SceneController = ({ getCameraDataRef }: { getCameraDataRef: React.MutableRefObject<any> }) => {
  const { camera } = useThree();
  const controlsRef = useRef<any>(null);

  getCameraDataRef.current = () => {
    const cam = camera as THREE.PerspectiveCamera;
    const target = controlsRef.current?.target || new THREE.Vector3(0, 0, 0);

    return {
      position: {
        x: cam.position.x,
        y: cam.position.y,
        z: cam.position.z
      },
      target: {
        x: target.x,
        y: target.y,
        z: target.z
      },
      zoom: cam.zoom,
      cameraType: "perspective"
    };
  };

  return (
    <>
      <OrbitControls 
        ref={controlsRef}
        makeDefault 
        enableDamping={true}
        dampingFactor={0.05}
        autoRotate={false}
        enablePan={false} // 禁止平移，保证方块居中
        enableZoom={true}
        minDistance={3}
        maxDistance={15}
      />
      <ambientLight intensity={0.8} />
      <directionalLight position={[5, 5, 5]} intensity={1} />
      <directionalLight position={[-5, -5, -5]} intensity={0.5} />
    </>
  );
};

// 辅助函数：生成带文字的纹理
function createLabelTexture(text: string, color: string, bg: string = '#f8fafc') {
  const canvas = document.createElement('canvas');
  const size = 512;
  canvas.width = size;
  canvas.height = size;
  const ctx = canvas.getContext('2d');
  if (!ctx) return new THREE.CanvasTexture(canvas);

  // 背景
  ctx.fillStyle = bg;
  ctx.fillRect(0, 0, size, size);

  // 边框
  ctx.lineWidth = 20;
  ctx.strokeStyle = color;
  ctx.strokeRect(0, 0, size, size);

  // 文字
  ctx.fillStyle = color;
  ctx.font = 'bold 80px "Microsoft YaHei", "Inter", sans-serif';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';

  const lines = text.split('/');
  const lineHeight = 100;
  const startY = size/2 - ((lines.length - 1) * lineHeight) / 2;

  lines.forEach((line, i) => {
    ctx.fillText(line, size/2, startY + i * lineHeight);
  });

  const texture = new THREE.CanvasTexture(canvas);
  texture.colorSpace = THREE.SRGBColorSpace;
  return texture;
}

const CubeMesh = () => {
  const materials = useMemo(() => {
      // 顺序: Right(x+), Left(x-), Top(y+), Bottom(y-), Front(z+), Back(z-)
      const configs = [
          { text: "Right/右侧", color: "#3b82f6" }, 
          { text: "Left/左侧", color: "#3b82f6" },  
          { text: "Top/顶部", color: "#22c55e" },   
          { text: "Bottom/底部", color: "#22c55e" },
          { text: "Front/正面", color: "#ef4444" },  
          { text: "Back/背面", color: "#ef4444" },   
      ];
      return configs.map(c => new THREE.MeshStandardMaterial({ 
          map: createLabelTexture(c.text, c.color),
          roughness: 0.2,
          metalness: 0.1
      }));
  }, []);

  return (
    <mesh material={materials}>
      <boxGeometry args={[2.5, 2.5, 2.5]} />
    </mesh>
  );
};

