// 场景控制器：处理相机数据获取和轨道控制
const SceneController = ({ getCameraDataRef }: { getCameraDataRef: React.MutableRefObject<any> }) => {
  const { camera } = useThree();
  const controlsRef = useRef<any>(null);

  // 将获取数据的函数绑定到父组件传来的 ref 上
  useEffect(() => {
    getCameraDataRef.current = () => {
      const cam = camera as THREE.PerspectiveCamera;
      const target = controlsRef.current?.target || new THREE.Vector3(0, 0, 0);

      // 简单的角度计算逻辑用于生成自然语言描述
      let angleDesc = "Front View";
      const x = cam.position.x;
      const y = cam.position.y;
      const z = cam.position.z;
      const absX = Math.abs(x);
      const absZ = Math.abs(z);

      if (y > 2.5) angleDesc = "High Angle / Top-down View";
      else if (y < -2.5) angleDesc = "Low Angle / Worm's-eye View";
      else if (absX > absZ) angleDesc = x > 0 ? "Right Side View" : "Left Side View";
      else if (z < 0) angleDesc = "Back View";
      else angleDesc = "Front Eye-level View";

      return {
        json: {
            position: { x: Number(x.toFixed(2)), y: Number(y.toFixed(2)), z: Number(z.toFixed(2)) },
            target: { x: Number(target.x.toFixed(2)), y: Number(target.y.toFixed(2)), z: Number(target.z.toFixed(2)) },
            fov: cam.fov
        },
        desc: angleDesc
      };
    };
  }, [camera, getCameraDataRef]);

  return (
    <>
      <OrbitControls 
        ref={controlsRef}
        makeDefault 
        enableDamping={true}
        dampingFactor={0.05}
        autoRotate={false}
        enablePan={false} // 核心需求：禁止平移，确保方块居中
        enableZoom={true}
        minDistance={3}
        maxDistance={15}
      />
      <ambientLight intensity={0.8} />
      <directionalLight position={[5, 5, 5]} intensity={1} />
      <directionalLight position={[-5, -5, -5]} intensity={0.5} />
    </>
  );
};

// 辅助函数：生成带文字和背景色的纹理
function createLabelTexture(text: string, bgColor: string) {
  const canvas = document.createElement('canvas');
  const size = 512;
  canvas.width = size;
  canvas.height = size;
  const ctx = canvas.getContext('2d');
  if (!ctx) return new THREE.CanvasTexture(canvas);

  // 背景
  ctx.fillStyle = bgColor;
  ctx.fillRect(0, 0, size, size);

  // 边框
  ctx.lineWidth = 40;
  ctx.strokeStyle = '#ffffff';
  ctx.strokeRect(0, 0, size, size);

  // 文字
  ctx.fillStyle = '#ffffff';
  ctx.font = 'bold 100px "Inter", sans-serif';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';

  // 处理多行文本 (例如 "Right/右侧")
  const lines = text.split('/');
  const lineHeight = 120;
  const startY = size/2 - ((lines.length - 1) * lineHeight) / 2;

  lines.forEach((line, i) => {
    ctx.fillText(line, size/2, startY + i * lineHeight);
  });

  const texture = new THREE.CanvasTexture(canvas);
  texture.colorSpace = THREE.SRGBColorSpace;
  return texture;
}

const CubeMesh = () => {
  const materials = useMemo(() => {
      // 材质顺序: Right(x+), Left(x-), Top(y+), Bottom(y-), Front(z+), Back(z-)
      // 颜色配置: X轴(蓝), Y轴(绿), Z轴(红)
      const configs = [
          { text: "RIGHT/右", color: "#3b82f6" },   // Right
          { text: "LEFT/左", color: "#2563eb" },    // Left
          { text: "TOP/顶", color: "#22c55e" },     // Top
          { text: "BOTTOM/底", color: "#16a34a" },  // Bottom
          { text: "FRONT/正", color: "#ef4444" },   // Front
          { text: "BACK/背", color: "#b91c1c" },    // Back
      ];
      return configs.map(c => new THREE.MeshStandardMaterial({ 
          map: createLabelTexture(c.text, c.color),
          roughness: 0.3,
          metalness: 0.1
      }));
  }, []);

  return (
    <mesh material={materials}>
      <boxGeometry args={[2.5, 2.5, 2.5]} />
    </mesh>
  );
};

