          thoughtLog: currentSteps.map(s => ({...s, status: 'done'})),
          costRMB: price.rmb, costUSD: price.usd
        });

        setSteps(s => s.map(x => x.id === 'post' ? {...x, status: 'done'} : x));
        setProgress(batchProgressBase + batchWeight);
      }

      setBatches(prev => [{ 
        id: batchId, images: currentBatchImages, timestamp: Date.now(),
        totalCostRMB: price.rmb * batchSize, totalCostUSD: price.usd * batchSize
      }, ...prev]);
      setProgress(100);
    } catch (err: any) {
      setError(err.message || "由于网络或 API 限制，渲染任务中断。");
    } finally {
      clearInterval(timer);
      setIsGenerating(false);
    }
  };

  const handleCopyPrompt = async (text: string, id: string) => {
    try {
      await navigator.clipboard.writeText(text);
      setCopyStatus({ ...copyStatus, [id]: true });
      setTimeout(() => setCopyStatus(prev => ({ ...prev, [id]: false })), 2000);
    } catch (e) { console.error(e); }
  };

  const handleEditorDone = (blob: Blob) => {
    const file = new File([blob], "edited-nano.png", { type: "image/png" });
    setInputImages(prev => [file, ...prev]);
    setEditingImage(null);
