              onChange={(e) => setPrompt(e.target.value)}
              placeholder="输入灵感画面描述..."
              className="w-full h-36 bg-slate-100/50 dark:bg-slate-800/60 border border-slate-200 dark:border-slate-700 rounded-[2rem] p-6 text-sm focus:border-banana-500 focus:ring-4 focus:ring-banana-500/10 outline-none transition-all placeholder:text-slate-400 dark:placeholder:text-slate-500 resize-none shadow-inner text-slate-900 dark:text-slate-100 font-medium pb-12"
            />
            {/* 提示词优化/智能分析 开关按钮 - 嵌入文本框 */}
            <div className="absolute bottom-3 left-3 right-3 flex justify-end">
               <button 
                 onClick={() => setIsSmartAnalysis(!isSmartAnalysis)}
                 className={`flex items-center gap-2 px-3 py-1.5 rounded-xl border transition-all text-[10px] font-black uppercase tracking-wider ${isSmartAnalysis ? 'bg-banana-500 text-slate-950 border-banana-400 shadow-lg shadow-banana-500/20' : 'bg-white dark:bg-slate-900 text-slate-500 border-slate-200 dark:border-slate-700 hover:text-slate-900 dark:hover:text-slate-300'}`}
               >
                 <Wand2 size={12} className={isSmartAnalysis ? "fill-current" : ""} />
                 {isSmartAnalysis ? "智能构思: ON" : "智能构思: OFF"}
               </button>
            </div>
          </div>

          <ImageUploader files={inputImages} onFilesChange={setInputImages} disabled={isGenerating} onEdit={(file) => setEditingImage({ url: URL.createObjectURL(file), name: file.name, type: 'local' })} />

          <SettingsPanel {...{aspectRatio, imageSize, batchSize, model, isSmartAnalysis, customWidth, customHeight}} onAspectRatioChange={setAspectRatio} onImageSizeChange={setImageSize} onBatchSizeChange={setBatchSize} onModelChange={setModel} onSmartAnalysisChange={setIsSmartAnalysis} onCustomPixelsChange={(w, h) => { setCustomWidth(w); setCustomHeight(h); }} disabled={isGenerating} />

          <div onClick={() => setCurrency(currency === 'RMB' ? 'USD' : 'RMB')} className="p-4 bg-banana-500/5 dark:bg-banana-500/10 rounded-3xl border border-banana-500/20 flex items-center justify-between cursor-pointer hover:bg-banana-500/10 dark:hover:bg-banana-500/20 transition-all group">
            <div className="flex items-center gap-2 text-xs font-black text-banana-700 dark:text-banana-400 uppercase tracking-widest"><Coins size={16}/> 引擎计费</div>
            <div className="text-sm font-black text-banana-600 dark:text-banana-300">
                {currency === 'RMB' ? `¥ ${currentPrice.rmb.toFixed(2)}` : `$ ${currentPrice.usd.toFixed(3)}`} <span className="text-[10px] font-bold opacity-60">/ 张</span>
            </div>
          </div>
        </div>

        {error && <div className="text-red-600 dark:text-red-400 text-[11px] font-bold bg-red-50 dark:bg-red-900/40 p-4 rounded-2xl border border-red-200">⚠️ {error}</div>}

        <div className="pt-2 flex flex-col gap-4">
          <button onClick={handleGenerate} disabled={isGenerating} className="w-full py-6 bg-gradient-to-br from-banana-400 to-banana-600 text-slate-950 font-black text-lg rounded-[2.2rem] shadow-2xl transition-all flex flex-col items-center justify-center gap-1 disabled:opacity-40 active:scale-95 group overflow-hidden">
            <div className="flex items-center gap-3">
               {isGenerating ? <Loader2 className="animate-spin" size={20} /> : <Zap size={20} />}
               <span className="tracking-tight">{isGenerating ? `渲染中...` : `开启艺术创作`}</span>
            </div>
            {!isGenerating && <span className="text-[9px] font-black opacity-80 uppercase tracking-widest mt-1">预计 {currency === 'RMB' ? `¥ ${estimatedTotal.rmb}` : `$ ${estimatedTotal.usd}`}</span>}
          </button>

          {isGenerating && (
            <div className="space-y-4 p-5 bg-white dark:bg-slate-800/80 rounded-[2.5rem] border border-slate-200 dark:border-slate-700 shadow-2xl">
               <div className="flex flex-col gap-2">
                 <div className="flex justify-between items-center text-[10px] font-black text-slate-500 uppercase tracking-widest">
                   <span>进度 {Math.round(progress)}%</span>
                   <span className="font-mono text-banana-600">{elapsedTime.toFixed(1)}s</span>
                 </div>
                 <div className="h-2 w-full bg-slate-100 dark:bg-slate-900 rounded-full overflow-hidden p-[1px]">
                   <div className="h-full bg-banana-500 rounded-full transition-all duration-500 shadow-[0_0_10px_rgba(234,179,8,0.5)]" style={{ width: `${progress}%` }} />
                 </div>
               </div>
               <div className="space-y-2">
                 {steps.map(s => (
                   <div key={s.id} className={`flex items-center gap-2 text-[10px] font-bold ${s.status === 'active' ? 'text-banana-500' : s.status === 'done' ? 'text-slate-400' : 'text-slate-600'}`}>
                     {s.status === 'done' ? <Check size={12} strokeWidth={4} /> : s.status === 'active' ? <Loader2 size={12} className="animate-spin" /> : <div className="w-3 h-3 rounded-full border border-current opacity-20" />}
                     {s.name}
                   </div>
                 ))}
               </div>
            </div>
          )}
        </div>
      </div>

      {/* 画廊区域 - 扁平化布局 */}
      <div className={`flex-1 p-5 lg:p-14 overflow-y-auto lg:h-screen scroll-smooth bg-slate-50 dark:bg-slate-950 transition-all duration-700 ${selectedImage || editingImage ? 'blur-xl brightness-50 pointer-events-none scale-105' : ''}`}>
        <div className="max-w-7xl mx-auto">
          <div className="flex flex-col sm:flex-row items-start justify-between mb-8 lg:mb-16 gap-4">
            <div>
              <h2 className="text-3xl lg:text-4xl font-black text-slate-900 dark:text-white tracking-tighter flex items-center gap-3 lg:gap-5">
                <div className="p-3 lg:p-4 bg-banana-500/10 rounded-[1.5rem] lg:rounded-[2rem]"><ImageIcon className="text-banana-500" size={28} /></div>
                艺术馆
              </h2>
              <p className="text-[10px] lg:text-sm text-slate-500 mt-2 lg:mt-3 uppercase tracking-[0.2em] lg:tracking-[0.3em] font-bold opacity-50">Global Creative Gallery</p>
            </div>

            <div onClick={() => setCurrency(currency === 'RMB' ? 'USD' : 'RMB')} className="w-full sm:w-auto flex flex-col items-end gap-1 p-4 lg:p-5 bg-white dark:bg-slate-900 rounded-[2rem] lg:rounded-[2.5rem] shadow-xl border border-slate-200 dark:border-slate-800 cursor-pointer hover:border-banana-500 transition-all">
               <div className="flex items-center gap-2 text-[10px] font-black text-slate-400 uppercase tracking-widest">总计消费</div>
               <div className="text-2xl lg:text-3xl font-black text-slate-900 dark:text-white">{currency === 'RMB' ? `¥${totalCost.rmb.toFixed(2)}` : `$${totalCost.usd.toFixed(2)}`}</div>
            </div>
          </div>

          <div className="grid grid-cols-1 sm:grid-cols-2 xl:grid-cols-3 2xl:grid-cols-4 gap-6 lg:gap-10">
            {allImages.map((img) => (
              <div 
                key={img.id} 
                className="group relative bg-white dark:bg-slate-900 rounded-[2.5rem] lg:rounded-[3rem] overflow-hidden border border-slate-200 dark:border-slate-800 shadow-xl transition-all duration-500 hover:scale-[1.02] hover:shadow-2xl cursor-pointer"
                onClick={() => setSelectedImage(img)}
              >
                <div className="aspect-[4/5] relative">
                  <img src={img.url} className="w-full h-full object-cover" loading="lazy" />

                  {/* 右上角快速下载按钮 - 移动端始终可见以优化体验 */}
                  <div className="absolute top-4 right-4 lg:top-5 lg:right-5 z-20 opacity-100 lg:opacity-0 lg:group-hover:opacity-100 transition-all duration-300 transform lg:-translate-y-2 lg:group-hover:translate-y-0">
                     <a 
                       href={img.url} 
                       download={`${img.filename}.png`} 
                       onClick={(e) => e.stopPropagation()} 
                       className="w-10 h-10 lg:w-11 lg:h-11 flex items-center justify-center bg-black/40 lg:bg-black/30 hover:bg-banana-500 backdrop-blur-md rounded-full text-white hover:text-slate-900 border border-white/10 transition-all shadow-lg"
                       title="下载原图"
                     >
                        <Download size={18} />
                     </a>
                  </div>

                  <div className="absolute inset-0 bg-gradient-to-t from-black/80 via-transparent to-transparent opacity-0 group-hover:opacity-100 transition-all duration-300 p-6 lg:p-8 flex flex-col justify-end">
                    <p className="text-white text-xs font-bold line-clamp-2 mb-4">"{img.prompt}"</p>
                    <div className="flex gap-2">
                       <button onClick={(e) => { e.stopPropagation(); setSelectedImage(img); }} className="flex-1 py-3 bg-white/20 backdrop-blur-xl hover:bg-white/30 text-white rounded-2xl text-[10px] font-black uppercase tracking-widest transition-all">查看详情</button>
                       <a href={img.url} download={`${img.filename}.png`} onClick={(e) => e.stopPropagation()} className="p-3 bg-banana-500 hover:bg-banana-400 text-slate-950 rounded-2xl transition-all shadow-lg"><Download size={18} /></a>
                    </div>
                  </div>
                  <div className="absolute top-4 left-4 lg:top-6 lg:left-6 flex flex-col gap-2">
                     <span className="px-3 py-1 lg:px-4 lg:py-1.5 bg-black/40 backdrop-blur-md rounded-full text-[8px] font-black text-white border border-white/10 uppercase tracking-widest">{img.filename.slice(0,10)}</span>
                  </div>
                </div>
              </div>
            ))}

            {allImages.length === 0 && !isGenerating && (
                <div className="col-span-full py-20 lg:py-40 flex flex-col items-center justify-center text-slate-400 bg-white/50 dark:bg-slate-900/20 border-4 border-dashed border-slate-200 dark:border-slate-800 rounded-[3rem] lg:rounded-[5rem]">
                    <Sparkles size={48} className="opacity-20 text-banana-600 mb-6 lg:mb-8" />
                    <p className="text-lg lg:text-xl font-black opacity-40">创作库尚无记录</p>
                </div>
            )}
          </div>
        </div>
      </div>

      {selectedImage && (
        <ImageViewer 
          image={selectedImage} 
          isCopied={!!copyStatus[selectedImage.id]} 
          onCopy={() => handleCopyPrompt(selectedImage.prompt, selectedImage.id)} 
          onClose={() => setSelectedImage(null)} 
          onNext={() => navigateImage(1)} 
          onPrev={() => navigateImage(-1)} 
          onEdit={() => { setEditingImage({ url: selectedImage.url, name: selectedImage.filename, type: 'generated' }); setSelectedImage(null); }}
          currency={currency} 
        />
      )}

      {editingImage && (
        <ImageEditor image={editingImage} onClose={() => setEditingImage(null)} onDone={handleEditorDone} />
      )}
    </div>
  );
};

export default App;
